fn truncate_to_i32(value: u64) -> i32 {
    if value > i32::MAX as u64 {
        i32::MAX
    } else {
        value as i32
    }
}

fn invert_rgba_alpha(color: u32) -> u32 {
    let alpha = (color >> 24) & 0xff;
    let rgb = color & 0x00ff_ffff;
    ((255 - alpha) << 24) | rgb
}

fn ensure_single_flag(flags: u32, mask: u32, error: &str) -> Result<(), RuntimeError> {
    let masked = flags & mask;
    if masked != 0 && (masked & (masked - 1)) != 0 {
        return Err(RuntimeError::new(error));
    }
    Ok(())
}

pub fn object_reference_value(id: ObjectId) -> Value {
    Value::Object(id.as_u64())
}

fn object_id_from_value(value: &Value) -> Option<ObjectId> {
    match value {
        Value::Object(id) if *id != 0 => Some(ObjectId::new(*id)),
        Value::Proplist(map) => match map.get("id") {
            Some(Value::Int(id)) if *id > 0 => Some(ObjectId::new(*id as u64)),
            _ => None,
        },
        _ => None,
    }
}

fn parse_object_reference_argument(
    value: &Value,
    function: &str,
    parameter: &str,
) -> Result<Option<ObjectId>, RuntimeError> {
    match value {
        Value::Object(_) | Value::Proplist(_) => Ok(object_id_from_value(value)),
        Value::Nil => Ok(None),
        Value::Int(id) if *id == 0 => Ok(None),
        other => Err(RuntimeError::new(format!(
            "{}: expected object, proplist, nil, or 0 for {}, got {}",
            function,
            parameter,
            other.type_name()
        ))),
    }
}

fn consume_optional_object_reference_argument(
    args: &[Value],
    index: &mut usize,
    function: &str,
    parameter: &str,
) -> Result<Option<ObjectId>, RuntimeError> {
    let Some(value) = args.get(*index) else {
        return Ok(None);
    };
    if !matches!(
        value,
        Value::Object(_) | Value::Proplist(_) | Value::Nil | Value::Int(0)
    ) {
        return Ok(None);
    }
    let object_id = parse_object_reference_argument(value, function, parameter)?;
    *index += 1;
    Ok(object_id)
}

fn value_to_i32(value: &Value, function: &str, parameter: &str) -> Result<i32, RuntimeError> {
    match value {
        Value::Int(int) => Ok(*int),
        // Unfilled parameter slots are nil and convert to 0; bools convert
        // directly (C4AulExec.cpp:1364-1396 CheckConvertFunctionParameters,
        // C4Value.cpp FnCnvGuess / Bool->Int CnvOK).
        Value::Nil => Ok(0),
        Value::Bool(flag) => Ok(i32::from(*flag)),
        other => Err(RuntimeError::new(format!(
            "{}: expected integer for {}, got {}",
            function,
            parameter,
            other.type_name()
        ))),
    }
}

/// Which post-name script argument layout a command function uses.
#[derive(Clone, Copy)]
enum CommandArgLayout {
    /// FnSetCommand: (name, target, Tx, Ty, target2, data, retries) — no
    /// update-interval slot, and the resulting command is always pushed
    /// with C4CMD_Mode_Base (C4Script.cpp:840-867, C4Object.cpp:3949).
    Set,
    /// FnAddCommand/FnAppendCommand: (name, target, Tx, Ty, target2,
    /// interval, data, retries, base_mode); an unfilled base_mode is int 0
    /// = C4CMD_Mode_SilentSub (C4Script.cpp:870-916, C4Command.h:62).
    Add,
}

fn parse_command_request(
    id: CommandId,
    args: &[Value],
    layout: CommandArgLayout,
    function: &str,
) -> Result<CommandRequest, RuntimeError> {
    let target = if args.len() > 1 {
        parse_object_reference_argument(&args[1], function, "target")?
    } else {
        None
    };

    let (tx, tx_definition) = if args.len() > 2 {
        match &args[2] {
            Value::Nil => (None, None),
            // Tx is a C4Value rather than C4ValueInt in all three C++
            // wrappers. In legacy syntax ConvertTo(C4V_Int) leaves a C4ID's
            // type tag intact, and C4CMD_Call forwards that tagged value to
            // its script callback (C4Script.cpp:840-916).
            Value::C4Id(id) => (
                definition_id_to_c4id(id),
                (!id.is_empty()).then(|| id.clone()),
            ),
            other => (Some(value_to_i32(other, function, "Tx")?), None),
        }
    } else {
        (None, None)
    };

    let ty = if args.len() > 3 {
        match &args[3] {
            Value::Nil => None,
            other => Some(value_to_i32(other, function, "Ty")?),
        }
    } else {
        None
    };

    let target2 = if args.len() > 4 {
        parse_object_reference_argument(&args[4], function, "target2")?
    } else {
        None
    };

    let (interval_slot, data_slot, retries_slot, mode_slot) = match layout {
        CommandArgLayout::Set => (None, 5usize, 6usize, None),
        CommandArgLayout::Add => (Some(5usize), 6, 7, Some(8usize)),
    };

    let update_interval = interval_slot
        .and_then(|slot| args.get(slot))
        .map(|value| value_to_i32(value, function, "update_interval"))
        .transpose()?
        .unwrap_or(0);
    if update_interval < 0 {
        return Err(RuntimeError::new(format!(
            "{}: update interval must be >= 0",
            function
        )));
    }
    let update_interval = update_interval as u32;

    let data_value = args.get(data_slot).unwrap_or(&Value::Nil);
    let data = match (id, data_value) {
        (CommandId::Call, Value::String(text)) => CommandData::Text(text.clone()),
        (CommandId::Call, Value::Nil) => CommandData::Text(String::new()),
        (CommandId::Call, other) => {
            return Err(RuntimeError::new(format!(
                "{}: expected string for data when command is Call, got {}",
                function,
                other.type_name()
            )))
        }
        (_, Value::Nil) => CommandData::Integer(0),
        (_, Value::C4Id(id)) => {
            CommandData::Integer(definition_id_to_c4id(id).unwrap_or_default())
        }
        (_, other) => CommandData::Integer(value_to_i32(other, function, "data")?),
    };

    let retries = args
        .get(retries_slot)
        .map(|value| value_to_i32(value, function, "retries"))
        .transpose()?
        .unwrap_or(0);

    let mode = mode_slot
        .and_then(|slot| args.get(slot))
        .map(|value| value_to_i32(value, function, "mode"))
        .transpose()?
        .map(|raw| CommandMode::from_i32(raw).unwrap_or(CommandMode::Base))
        .unwrap_or(match layout {
            CommandArgLayout::Set => CommandMode::Base,
            CommandArgLayout::Add => CommandMode::SilentSub,
        });

    let request = CommandRequest::new(id)
        .with_target(target)
        .with_target2(target2)
        .with_tx(tx)
        .with_ty(ty)
        .with_data(data)
        .with_update_interval(update_interval)
        .with_retries(retries)
        .with_mode(mode);
    Ok(tx_definition
        .map(|definition| request.clone().with_tx_definition(definition))
        .unwrap_or(request))
}

fn parse_player_type_filter(value: Option<&Value>, function: &str) -> Result<i32, RuntimeError> {
    match value {
        Some(Value::Int(filter)) => Ok(*filter),
        Some(Value::Nil) | None => Ok(0),
        Some(other) => Err(RuntimeError::new(format!(
            "{}: expected int or nil for type filter, got {}",
            function,
            other.type_name()
        ))),
    }
}

fn player_type(player: &PlayerState) -> i32 {
    i32::from(if player.script_player {
        crate::PLAYER_INFO_TYPE_SCRIPT
    } else {
        crate::PLAYER_INFO_TYPE_USER
    })
}

fn player_type_matches(player: &PlayerState, filter: i32) -> bool {
    filter == 0 || filter == player_type(player)
}

fn script_player_extra_data(value: Option<&Value>) -> Result<[u8; 4], RuntimeError> {
    let text = match value {
        None | Some(Value::Nil) | Some(Value::Int(0)) | Some(Value::Bool(false)) => None,
        Some(Value::C4Id(id)) => Some(id.clone()),
        Some(Value::Int(raw @ 1..=9999)) => Some(format!("{raw:04}")),
        Some(Value::Int(raw)) => c4id_to_definition(*raw),
        Some(other) => {
            return Err(RuntimeError::new(format!(
                "CreateScriptPlayer: expected C4ID or nil for extra data, got {}",
                other.type_name()
            )))
        }
    };
    let Some(text) = text.filter(|text| text != "NONE" && text != "0000") else {
        return Ok(*b"NONE");
    };
    let bytes = text.as_bytes();
    if bytes.len() < 4 {
        return Ok(*b"NONE");
    }
    let mut extra = [0; 4];
    extra.copy_from_slice(&bytes[..4]);
    Ok(extra)
}

/// FnCreateScriptPlayer (C4Script.cpp:2877-2903): validate the name on
/// every peer, but only the control host emits the additive PlayerInfo
/// request. The actual join remains delayed in the control pipeline.
fn create_script_player(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 5 {
        return Err(RuntimeError::new(
            "CreateScriptPlayer expects at most 5 arguments: name, color, team, flags and extra data",
        ));
    }
    let name = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) if !name.is_empty() => name,
        Value::String(_) | Value::Nil => return Ok(Value::Bool(false)),
        other => {
            return Err(RuntimeError::new(format!(
                "CreateScriptPlayer: expected string for name, got {}",
                other.type_name()
            )))
        }
    };
    let color = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "CreateScriptPlayer",
        "color",
    )? as u32
        & 0x00ff_ffff;
    let team = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "CreateScriptPlayer",
        "team",
    )?;
    let source_flags = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "CreateScriptPlayer",
        "flags",
    )?;
    let extra_data = script_player_extra_data(args.get(4))?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Bool(true));
        };
        if !context.world.control_host {
            return Ok(Value::Bool(true));
        }
        let mut flags = 0;
        if source_flags & 1 != 0 {
            flags |= crate::PLAYER_INFO_FLAG_ATTRIBUTES_FIXED;
        }
        if source_flags & 2 != 0 {
            flags |= crate::PLAYER_INFO_FLAG_NO_SCENARIO_INIT;
        }
        if source_flags & 4 != 0 {
            flags |= crate::PLAYER_INFO_FLAG_NO_ELIMINATION_CHECK;
        }
        if source_flags & 8 != 0 {
            flags |= crate::PLAYER_INFO_FLAG_INVISIBLE;
        }
        let name = crate::LegacyCString::from_bytes(name.as_bytes().to_vec()).ok_or_else(|| {
            RuntimeError::new("CreateScriptPlayer: name contains an interior NUL")
        })?;
        context
            .world
            .player_info_updates
            .borrow_mut()
            .push(crate::PlayerInfoUpdateRequest {
                client_id: 0,
                flags: crate::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS,
                players: vec![crate::ControlPlayerInfoEntry {
                    name,
                    flags,
                    player_type: crate::PLAYER_INFO_TYPE_SCRIPT,
                    color,
                    original_color: color,
                    team,
                    extra_data,
                    ..Default::default()
                }],
            });
        Ok(Value::Bool(true))
    })
}

fn get_player_count(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetPlayerCount expects at most 1 argument: type",
        ));
    }
    let filter = parse_player_type_filter(args.first(), "GetPlayerCount")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Int(0));
        };
        let count = context
            .player_ids()
            .iter()
            .filter(|id| {
                context
                    .player_state(**id)
                    .map(|player| player_type_matches(player, filter))
                    .unwrap_or(false)
            })
            .count();
        Ok(Value::Int(truncate_to_i32(count as u64)))
    })
}

/// `FnIsNetwork` reads `Game.Parameters.IsNetworkGame`
/// (C4Script.cpp:3554). Parameter setup copies that flag from the active
/// `Game.NetworkActive` session (C4GameParameters.cpp:429-434).
fn is_network(_args: &[Value]) -> Result<Value, RuntimeError> {
    HOST_CONTEXT.with(|cell| {
        Ok(Value::Bool(
            cell.borrow()
                .as_ref()
                .is_some_and(|context| context.world.network_game()),
        ))
    })
}

/// `FnSetMaxPlayer` (C4Script.cpp:3698-3706): nonnegative values directly
/// replace `Game.Parameters.MaxPlayers`; negative values fail without a
/// write. The C++ host function returns `C4ValueInt`, not a script bool.
fn set_max_player(args: &[Value]) -> Result<Value, RuntimeError> {
    let max_players = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetMaxPlayer",
        "maximum player count",
    )?;
    if max_players < 0 {
        return Ok(Value::Int(0));
    }

    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            context.record_player_command(PlayerCommand::SetMaxPlayer { max_players });
        }
    });
    Ok(Value::Int(1))
}

/// `FnCallMessageBoard` (C4Script.cpp:3575-3585): register one player query,
/// replacing the first query for the same callback object and appending the
/// replacement at the list tail.
fn call_message_board(args: &[Value]) -> Result<Value, RuntimeError> {
    let explicit_target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "CallMessageBoard",
        "callback object",
    )?;
    let uppercase = value_to_bool(
        args.get(1).unwrap_or(&Value::Nil),
        "CallMessageBoard",
        "uppercase",
    )?;
    let prompt = parse_optional_string(args.get(2), "CallMessageBoard", "query")?
        .unwrap_or_default();
    let player_id = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "CallMessageBoard",
        "player",
    )?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let target = explicit_target.or(context.script_object_context);
        if target.is_some_and(|target| !context.object_status_present(target)) {
            return Ok(Value::Bool(false));
        }
        let query = crate::MessageBoardQuery::new(target, prompt, uppercase);
        let Some(player) = context.player_state_mut(player_id) else {
            return Ok(Value::Bool(false));
        };
        player.call_message_board(query.clone());
        context.record_player_command(PlayerCommand::CallMessageBoard { player_id, query });
        Ok(Value::Bool(true))
    })
}

/// `FnAbortMessageBoard` (C4Script.cpp:3587-3597). Local non-network
/// cancellation synchronously executes an empty answer before the outer
/// Remove call, so an active query closes/removes but the builtin returns
/// false; network cancellation defers that answer and returns the Remove
/// result.
fn abort_message_board(args: &[Value]) -> Result<Value, RuntimeError> {
    let explicit_target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "AbortMessageBoard",
        "callback object",
    )?;
    let player_id = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "AbortMessageBoard",
        "player",
    )?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let target = explicit_target.or(context.script_object_context);
        if context.player_state(player_id).is_none() {
            return Ok(Value::Bool(false));
        }
        let active_local_cancel = !context.world.network_game()
            && context
                .world
                .active_message_board_input()
                .is_some_and(|input| input.player == player_id && input.target == target);
        let removed = context
            .player_state_mut(player_id)
            .is_some_and(|player| player.remove_message_board_query(target));
        context.record_player_command(PlayerCommand::AbortMessageBoard { player_id, target });
        Ok(Value::Bool(removed && !active_local_cancel))
    })
}

/// `FnOnMessageBoardAnswer` (C4Script.cpp:3599-3613): consume exactly one
/// query before dispatching `InputCallback(answer, player)`.
fn on_message_board_answer(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "OnMessageBoardAnswer",
        "callback object",
    )?;
    let player_id = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "OnMessageBoardAnswer",
        "player",
    )?;
    let answer = parse_optional_string(args.get(2), "OnMessageBoardAnswer", "answer")?
        .unwrap_or_default();

    let removed = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let removed = context
            .player_state_mut(player_id)
            .is_some_and(|player| player.remove_message_board_query(target));
        if removed {
            context.record_player_command(PlayerCommand::RemoveMessageBoardQuery {
                player_id,
                target,
            });
        }
        removed
    });
    if !removed {
        return Ok(Value::Bool(false));
    }
    if answer.is_empty() {
        return Ok(Value::Bool(true));
    }

    let callback_args = [Value::String(answer), Value::Int(player_id)];
    let callback = match target {
        Some(target) => call_world_object_script_function(target, "InputCallback", &callback_args),
        None => {
            let script = HOST_CONTEXT.with(|cell| {
                cell.borrow()
                    .as_ref()
                    .and_then(|context| context.world.scenario_script().cloned())
            });
            script.and_then(|script| {
                call_scoped_script_function(script, "InputCallback", &callback_args)
            })
        }
    };
    match callback {
        Some(Ok(value)) => Ok(Value::Bool(value_raw_truthy(&value))),
        Some(Err(error)) => Err(error),
        None => Ok(Value::Bool(false)),
    }
}

fn get_player_by_index(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "GetPlayerByIndex expects at most 2 arguments: index and type",
        ));
    }
    // C++ pads missing script args with zero: GetPlayerByIndex() is the
    // first player (GoldRush Script1's intro camera).
    let index = match args.first() {
        None | Some(Value::Nil) => 0,
        Some(value) => value_to_i32(value, "GetPlayerByIndex", "index")?,
    };
    let filter = parse_player_type_filter(args.get(1), "GetPlayerByIndex")?;
    if index < 0 {
        return Ok(Value::Int(OWNER_NONE));
    }
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Int(OWNER_NONE));
        };
        let matching: Vec<i32> = context
            .player_ids()
            .iter()
            .filter_map(|id| {
                context
                    .player_state(*id)
                    .filter(|player| player_type_matches(player, filter))
                    .map(|_| *id)
            })
            .collect();
        let idx = index as usize;
        if idx >= matching.len() {
            Ok(Value::Int(OWNER_NONE))
        } else {
            Ok(Value::Int(matching[idx]))
        }
    })
}

/// FnEliminatePlayer (C4Script.cpp:2823-2842): missing players and already
/// eliminated regular players fail; the direct flag removes through the
/// player-control path, while regular elimination starts the retire delay.
fn eliminate_player(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "EliminatePlayer expects at most 2 arguments: player and direct removal flag",
        ));
    }
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "EliminatePlayer",
        "player",
    )?;
    let remove_direct = value_to_bool(
        args.get(1).unwrap_or(&Value::Nil),
        "EliminatePlayer",
        "direct removal flag",
    )?;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Int(0));
        };
        let Some(player) = context.player_state(player_id) else {
            return Ok(Value::Int(0));
        };
        if remove_direct {
            context.record_player_command(PlayerCommand::Remove { player_id });
            return Ok(Value::Int(1));
        }
        if player.status == crate::PlayerStatus::Eliminated {
            return Ok(Value::Int(0));
        }
        if let Some(player) = context.player_state_mut(player_id) {
            player.status = crate::PlayerStatus::Eliminated;
            player.surrendered = false;
        }
        context.record_player_command(PlayerCommand::Eliminate { player_id });
        Ok(Value::Int(1))
    })
}

