/// FnSetClrModulation (C4Script.cpp:3880-3901): set either the object's
/// `ColorMod` or one existing overlay's modulation. A null object defaults
/// to the calling object; an unknown overlay fails without creating it.
fn set_clr_modulation(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 3 {
        return Err(RuntimeError::new(
            "SetClrModulation expects at most 3 arguments: color, object and overlay id",
        ));
    }
    let color = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetClrModulation",
        "clr",
    )? as u32;
    let target = args
        .get(1)
        .map(|value| parse_object_reference_argument(value, "SetClrModulation", "object"))
        .transpose()?
        .flatten();
    let overlay_id = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "SetClrModulation",
        "overlay id",
    )?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let Some(target) = target.or_else(|| context.object_context().map(|object| object.id()))
        else {
            return Ok(Value::Bool(false));
        };
        let changed = if overlay_id == 0 {
            context.set_object_color_modulation(target, color)
        } else {
            context.set_object_overlay_color_modulation(target, overlay_id, color)
        };
        Ok(Value::Bool(changed))
    })
}

/// FnGetClrModulation (C4Script.cpp:3904-3921): return the raw object or
/// overlay modulation; a missing object/overlay is nil.
fn get_clr_modulation(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "GetClrModulation expects at most 2 arguments: object and overlay id",
        ));
    }
    let target = args
        .first()
        .map(|value| parse_object_reference_argument(value, "GetClrModulation", "object"))
        .transpose()?
        .flatten();
    let overlay_id = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "GetClrModulation",
        "overlay id",
    )?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(target) = target.or_else(|| context.object_context().map(|object| object.id()))
        else {
            return Ok(Value::Nil);
        };
        let color = if overlay_id == 0 {
            context.object_color_modulation(target)
        } else {
            context.object_overlay_color_modulation(target, overlay_id)
        };
        Ok(color
            .map(|color| Value::Int(color as i32))
            .unwrap_or(Value::Nil))
    })
}

/// FnModulateColor (C4Script.cpp:5597-5612): multiply packed RGB channels
/// with the engine's `/ 256` rule and combine inverted alpha upwards.
fn modulate_color(args: &[Value]) -> Result<Value, RuntimeError> {
    let color1 = parse_native_optional_i32(args.first(), "ModulateColor", "color 1")?
        .unwrap_or(0x00ff_ffff) as u32;
    let color2 = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "ModulateColor",
        "color 2",
    )? as u32;
    let channel = |shift: u32| -> u32 {
        ((((color1 >> shift) & 0xff_u32) * ((color2 >> shift) & 0xff_u32)) >> 8) << shift
    };
    let alpha1 = color1 >> 24;
    let alpha2 = color2 >> 24;
    let alpha = (alpha1 + alpha2 - ((alpha1 * alpha2) >> 8)).min(0xff);
    Ok(Value::Int(
        (channel(0) | channel(8) | channel(16) | (alpha << 24)) as i32,
    ))
}

fn call_object_own_fail_safe(target: ObjectId, function: &str, args: &[Value]) -> Value {
    match call_world_object_own_function(target, function, args) {
        Some(Ok(value)) => value,
        Some(Err(error)) => {
            tracing::warn!(
                %error,
                object = target.as_u64(),
                callback = function,
                "script error in object callback; continuing like C++ fail-safe Call"
            );
            Value::Nil
        }
        None => Value::Nil,
    }
}

/// Fail-safe own-script call that also accepts an already-active object
/// scope which has not joined the world list yet. Plain Engine spawns run
/// Construction/Initialize in exactly that pre-insertion state.
fn call_inflight_object_own_fail_safe(
    target: ObjectId,
    function: &str,
    args: &[Value],
) -> Value {
    match call_world_object_own_function_inflight(target, function, args) {
        Some(Ok(value)) => value,
        Some(Err(error)) => {
            tracing::warn!(
                %error,
                object = target.as_u64(),
                callback = function,
                "script error in object callback; continuing like C++ fail-safe Call"
            );
            Value::Nil
        }
        None => Value::Nil,
    }
}

fn object_is_present(target: ObjectId) -> bool {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        match context.object_scope(target) {
            Some(scope) => !scope.destroy && scope.status().is_active(),
            None => context
                .get_world_object(target)
                .is_some_and(|object| object.is_present()),
        }
    })
}

/// C++ truthiness of a raw object Status. Inactive objects still receive
/// callbacks; only Deleted/status-zero objects are suppressed.
fn object_has_status(target: ObjectId) -> bool {
    HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .is_some_and(|context| context.object_status_present(target))
    })
}

fn live_collection_eligible(
    context: &EffectHostContext,
    target: ObjectId,
    ignore_no_collect_delay: bool,
) -> bool {
    let Some(scope) = context.object_scope(target) else {
        return false;
    };
    let Some(definition_id) = context.object_effective_definition_id(target) else {
        return false;
    };
    let Some(metadata) = context.definition_metadata(&definition_id) else {
        return false;
    };
    let construction_ready = scope.construction() >= FULL_CON
        || metadata.fire.incomplete_activity;
    let positive_rect = metadata
        .fire
        .collection_rect
        .is_some_and(|rect| rect.width > 0 && rect.height > 0);
    let below_limit = metadata.collection_limit <= 0
        || context
            .get_world_object(target)
            .is_some_and(|object| object.contents().len() < metadata.collection_limit as usize);
    construction_ready
        && positive_rect
        && below_limit
        && !scope
            .action_library
            .disables_object(scope.effective_action_name())
        && (ignore_no_collect_delay || scope.no_collect_delay() == 0)
}

/// Presence check for ordered command previews: once a same-call scope
/// exists, its removal state supersedes the immutable frame snapshot.
fn preview_object_is_present(target: ObjectId) -> bool {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        match context.object_scope(target) {
            Some(scope) => !scope.destroy && scope.status() != ObjectStatus::Deleted,
            None => context
                .get_world_object(target)
                .is_some_and(|object| object.is_present()),
        }
    })
}

/// Synchronous host-side portion of C4Object::SetOCF that depends on live
/// motion/containment/terrain. Definition-static bits remain in the cached
/// seed; every field this helper rebuilds is cleared first like C++.
fn refresh_live_object_ocf(context: &mut EffectHostContext, target: ObjectId) -> bool {
    if !context.ensure_object_scope(target) {
        return false;
    }
    let Some(definition_id) = context.object_effective_definition_id(target) else {
        return false;
    };
    let Some(metadata) = context.definition_metadata(&definition_id).cloned() else {
        return false;
    };
    let Some((
        position,
        container,
        construction,
        rotation,
        energy,
        on_fire,
        alive,
        category,
        action_disabled,
    )) = context
        .object_scope(target)
        .map(|scope| {
            (
                scope.effective_position(),
                scope.container(),
                scope.construction(),
                scope.rotation(),
                scope.energy(),
                scope.ocf() & ocf::ON_FIRE != 0,
                scope.alive(),
                scope.category(),
                scope
                    .action_library
                    .disables_object(scope.effective_action_name()),
            )
        })
    else {
        return false;
    };
    let collection = live_collection_eligible(context, target, false);
    let solid_center = context
        .landscape_ref()
        .is_some_and(|landscape| landscape.is_solid_at(position.x, position.y));
    let semi_above = context.landscape_ref().is_some_and(|landscape| {
        landscape.is_semi_solid_at(position.x, position.y.saturating_sub(1))
    });
    let solid_above = context.landscape_ref().is_some_and(|landscape| {
        landscape.is_solid_at(position.x, position.y.saturating_sub(1))
    });
    let semi_high = context.landscape_ref().is_some_and(|landscape| {
        landscape.is_semi_solid_at(position.x, position.y.saturating_sub(8))
    });
    let container_allows_get = container.is_some_and(|container| {
        let grab_get = context
            .object_effective_definition_id(container)
            .and_then(|id| context.definition_metadata(&id))
            .is_some_and(|metadata| metadata.grab_put_get & 2 != 0);
        let entrance = context
            .object_scope(container)
            .map(ObjectScopeContext::ocf)
            .or_else(|| context.get_world_object(container).map(|object| object.ocf()))
            .is_some_and(|mask| mask & ocf::ENTRANCE != 0);
        grab_get || entrance
    });

    let Some(scope) = context.object_scope_mut(target) else {
        return false;
    };
    scope.refresh_cached_ocf();
    let mut mask = scope.cached_ocf.unwrap_or(ocf::NORMAL);
    // Every bit whose SetOCF predicate depends directly or indirectly on
    // Con is rebuilt from the live definition/scope. DoCon calls SetOCF
    // before UpdateFace and before any lifecycle callback.
    mask &= !(ocf::CONSTRUCT
        | ocf::FULL_CON
        | ocf::ROTATE
        | ocf::ENTRANCE
        | ocf::COLLECTION
        | ocf::LINE_CONSTRUCT
        | ocf::ATTRACT_LIGHTNING
        | ocf::POWER_CONSUMER
        | ocf::POWER_SUPPLY
        | ocf::CONTAINER
        | ocf::FIGHT_READY);
    if metadata.constructable && construction < FULL_CON && rotation == 0 && !on_fire {
        mask |= ocf::CONSTRUCT;
    }
    if construction >= FULL_CON {
        mask |= ocf::FULL_CON;
    }
    if metadata.rotateable > 0 && construction > 100 {
        mask |= ocf::ROTATE;
    }
    if metadata
        .fire
        .entrance_rect
        .is_some_and(|rect| rect.width > 0 && rect.height > 0)
        && mask & ocf::FULL_CON != 0
        && (metadata.fire.rotated_entrance == 1 || rotation <= metadata.fire.rotated_entrance)
    {
        mask |= ocf::ENTRANCE;
    }
    if collection {
        mask |= ocf::COLLECTION;
    }
    if mask & ocf::FULL_CON != 0
        && metadata.line_connect & !crate::LINE_CONNECT_ENERGY_HOLDER != 0
    {
        mask |= ocf::LINE_CONSTRUCT;
    }
    if metadata.fire.attract_lightning && mask & ocf::FULL_CON != 0 {
        mask |= ocf::ATTRACT_LIGHTNING;
    }
    if metadata.line_connect & crate::LINE_CONNECT_POWER_CONSUMER != 0
        && mask & ocf::FULL_CON != 0
    {
        mask |= ocf::POWER_CONSUMER;
    }
    if (metadata.line_connect & crate::LINE_CONNECT_POWER_GENERATOR != 0
        || (metadata.line_connect & crate::LINE_CONNECT_POWER_OUTPUT != 0 && energy > 0))
        && mask & ocf::FULL_CON != 0
    {
        mask |= ocf::POWER_SUPPLY;
    }
    if metadata.grab_put_get & 3 != 0 || mask & ocf::ENTRANCE != 0 {
        mask |= ocf::CONTAINER;
    }
    if alive
        && category & crate::CATEGORY_LIVING != 0
        && !action_disabled
        && !metadata.fire.no_fight
    {
        mask |= ocf::FIGHT_READY;
    }
    mask &= !(ocf::IN_SOLID | ocf::IN_FREE | ocf::AVAILABLE);
    if container.is_none() {
        if solid_center {
            mask |= ocf::IN_SOLID;
        }
        if !semi_above {
            mask |= ocf::IN_FREE;
        }
    }
    if (container.is_none() || container_allows_get)
        && (!semi_above || (!solid_above && !semi_high))
    {
        mask |= ocf::AVAILABLE;
    }
    scope.cached_ocf = Some(mask);
    true
}

fn refresh_container_collection_ocf(context: &mut EffectHostContext, container: ObjectId) {
    let _ = refresh_live_object_ocf(context, container);
}

/// Direct `C4Object::Exit(x, y)` with absolute coordinates. Unlike the
/// script `Exit` wrapper, these receive no caller-relative or Shape.y
/// adjustment.
fn exit_object_at_position(target: ObjectId, position: Vector2) -> Result<bool, RuntimeError> {
    exit_object_at_position_with_calls(target, position, true)
}

fn live_object_bounds_shape(
    context: &EffectHostContext,
    target: ObjectId,
) -> Option<DefinitionRect> {
    if let Some(shape) = live_object_shape(context, target) {
        return Some(shape);
    }
    let object = context.get_world_object(target)?;
    let vertices = context
        .object_scope(target)
        .map(|scope| scope.vertices().to_vec())
        .unwrap_or_else(|| object.vertices.clone());
    host_vertex_bounds_rect(Vector2::ZERO, &vertices)
}

fn live_exit_layer_bounds(
    context: &EffectHostContext,
    target: ObjectId,
    horizontal: bool,
) -> Option<(i32, i32)> {
    let object = context.get_world_object(target)?;
    let definition_id = context.object_effective_definition_id(target)?;
    let metadata = context.definition_metadata(&definition_id)?;
    let action_name = context
        .object_scope(target)
        .map(ObjectScopeContext::effective_action_name)
        .unwrap_or(object.action_name.as_str());
    let procedure = metadata.action_library.procedure_for_action(action_name);
    if !action_name.is_empty()
        && action_name != "Idle"
        && matches!(procedure, ActionProcedure::Attach)
    {
        return None;
    }

    let layer_id = context.object_layer(target)?;
    let layer = context.get_world_object(layer_id)?;
    let layer_definition_id = context.object_effective_definition_id(layer_id)?;
    let layer_metadata = context.definition_metadata(&layer_definition_id)?;
    if layer_metadata.border_bound & C4D_BORDER_LAYER == 0 {
        return None;
    }
    let object_shape = live_object_bounds_shape(context, target).unwrap_or_default();
    let layer_shape = live_object_bounds_shape(context, layer_id).unwrap_or_default();
    let is_static = object.category & crate::CATEGORY_STATIC_BACK != 0;
    let (layer_origin, layer_size, shape_offset) = if horizontal {
        (
            layer.position.x.saturating_add(layer_shape.x),
            layer_shape.width,
            object_shape.x,
        )
    } else {
        (
            layer.position.y.saturating_add(layer_shape.y),
            layer_shape.height,
            object_shape.y,
        )
    };
    let low = if is_static {
        layer_origin
    } else {
        layer_origin.saturating_sub(shape_offset)
    };
    let high = if is_static {
        layer_origin.saturating_add(layer_size)
    } else {
        layer_origin
            .saturating_add(layer_size)
            .saturating_add(shape_offset)
    };
    Some((low, high))
}

fn run_live_exit_bound_contact(target: ObjectId, cnat: u32) {
    let calls_enabled = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let definition_id = context.object_effective_definition_id(target);
        let calls_enabled = definition_id
            .as_deref()
            .and_then(|id| context.definition_metadata(id))
            .is_some_and(|metadata| metadata.contact_function_calls);
        if !context.ensure_object_scope(target) {
            return false;
        }
        if let Some(scope) = context.object_scope_mut(target) {
            let component = if cnat == CNAT_LEFT || cnat == CNAT_RIGHT {
                VelocityComponent::X
            } else {
                VelocityComponent::Y
            };
            scope.set_fixed_velocity_component(component, C4Fixed::ZERO);
            return calls_enabled && scope.status() != ObjectStatus::Deleted;
        }
        false
    });
    if calls_enabled {
        if let Some(function) = crate::contact_callback_name(cnat) {
            let _ = call_object_own_fail_safe(target, function, &[]);
        }
    }
}

fn apply_live_exit_target_bounds(
    target: ObjectId,
    coordinate: &mut i32,
    low: i32,
    high: i32,
    low_cnat: u32,
    high_cnat: u32,
) {
    // These are deliberately independent, matching C4Object::TargetBounds.
    if *coordinate < low {
        *coordinate = low;
        run_live_exit_bound_contact(target, low_cnat);
    }
    if *coordinate > high {
        *coordinate = high;
        run_live_exit_bound_contact(target, high_cnat);
    }
}

fn bounds_check_live_exit(target: ObjectId, position: &mut Vector2) {
    let layer_side = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| live_exit_layer_bounds(context, target, true))
    });
    if let Some((low, high)) = layer_side {
        apply_live_exit_target_bounds(
            target,
            &mut position.x,
            low,
            high,
            CNAT_LEFT,
            CNAT_RIGHT,
        );
    }

    let landscape_side = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let definition_id = context.object_effective_definition_id(target)?;
        let metadata = context.definition_metadata(&definition_id)?;
        if metadata.border_bound & C4D_BORDER_SIDES == 0 {
            return None;
        }
        let shape_x = live_object_bounds_shape(context, target)
            .map(|shape| shape.x)
            .unwrap_or(0);
        let width = i32::try_from(context.landscape_ref()?.width()).ok()?;
        Some((-shape_x, width.saturating_add(shape_x)))
    });
    if let Some((low, high)) = landscape_side {
        apply_live_exit_target_bounds(
            target,
            &mut position.x,
            low,
            high,
            CNAT_LEFT,
            CNAT_RIGHT,
        );
    }

    let layer_vertical = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| live_exit_layer_bounds(context, target, false))
    });
    if let Some((low, high)) = layer_vertical {
        apply_live_exit_target_bounds(
            target,
            &mut position.y,
            low,
            high,
            CNAT_TOP,
            CNAT_BOTTOM,
        );
    }

    let top = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let definition_id = context.object_effective_definition_id(target)?;
        let metadata = context.definition_metadata(&definition_id)?;
        if metadata.border_bound & C4D_BORDER_TOP == 0 {
            return None;
        }
        let shape_y = live_object_bounds_shape(context, target)
            .map(|shape| shape.y)
            .unwrap_or(0);
        Some((-shape_y, 1_000_000))
    });
    if let Some((low, high)) = top {
        apply_live_exit_target_bounds(
            target,
            &mut position.y,
            low,
            high,
            CNAT_TOP,
            CNAT_BOTTOM,
        );
    }

    let bottom = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let definition_id = context.object_effective_definition_id(target)?;
        let metadata = context.definition_metadata(&definition_id)?;
        if metadata.border_bound & C4D_BORDER_BOTTOM == 0 {
            return None;
        }
        let shape_y = live_object_bounds_shape(context, target)
            .map(|shape| shape.y)
            .unwrap_or(0);
        let height = context.landscape_ref()?.estimated_height();
        Some((-1_000_000, height.saturating_add(shape_y)))
    });
    if let Some((low, high)) = bottom {
        apply_live_exit_target_bounds(
            target,
            &mut position.y,
            low,
            high,
            CNAT_TOP,
            CNAT_BOTTOM,
        );
    }
}

fn exit_object_at_position_with_calls(
    target: ObjectId,
    position: Vector2,
    f_calls: bool,
) -> Result<bool, RuntimeError> {
    exit_object_at_position_with_motion_and_calls(
        target,
        position,
        FixedVec2::ZERO,
        C4Fixed::ZERO,
        f_calls,
    )
}

fn exit_object_at_position_with_motion_and_calls(
    target: ObjectId,
    mut position: Vector2,
    velocity: FixedVec2,
    rotation_velocity: C4Fixed,
    f_calls: bool,
) -> Result<bool, RuntimeError> {
    let previous = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return None;
        };
        if !context.ensure_object_scope(target) {
            return None;
        }
        let scope = context.object_scope_mut(target)?;
        let previous = scope.container()?;
        // Raw unlink first. Contained is null for BoundsCheck, but C++ does
        // not close the menu or refresh this object's OCF until afterward.
        scope.current_container = None;
        scope.pending_update.container = Some(None);
        scope.pending_update.construction_preserves_fixed_position = false;
        scope.exit_bounds_in_progress = true;
        refresh_container_collection_ocf(context, previous);
        Some(previous)
    });
    let Some(previous) = previous else {
        return Ok(false);
    };

    bounds_check_live_exit(target, &mut position);

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        let definition_metadata = context
            .object_effective_definition_id(target)
            .and_then(|id| context.definition_metadata(&id).cloned())
            .unwrap_or_default();
        let Some(scope) = context.object_scope_mut(target) else {
            return;
        };
        scope.exit_bounds_in_progress = false;
        // Exit assigns x/y even when unchanged and thereby snaps fix_x/y.
        scope.current_position = position;
        scope.current_fixed_position = FixedVec2::from_ints(position.x, position.y);
        scope.pending_update.position = Some(position);
        scope.pending_update.construction_preserves_fixed_position = false;
        scope.current_rotation = 0;
        scope.current_fixed_rotation = C4Fixed::ZERO;
        scope.pending_update.rotation = Some(0);
        scope.set_fixed_velocity(velocity);
        scope.set_rotation_velocity(rotation_velocity);
        scope.set_mobile(true);
        scope.current_in_liquid = false;
        // Bounds callbacks may have opened a menu; Exit closes it afterward.
        scope.pending_update.menu = Some(None);
        // UpdateFace(true) rebuilds an ordinary C4Shape from Def after the
        // BoundsCheck callbacks consumed the old live SetShape rectangle.
        // Line shapes keep their independent geometry.
        if definition_metadata.line == 0 {
            scope.pending_update.shape_override = Some(None);
        }
        scope.refresh_shape_preview(&definition_metadata);
    });
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            let _ = refresh_live_object_ocf(context, target);
        }
    });

    if f_calls && object_has_status(previous) {
        call_object_own_fail_safe(
            previous,
            "Ejection",
            &[object_reference_value(target)],
        );
    }
    if f_calls && object_has_status(target) {
        call_object_own_fail_safe(
            target,
            "Departure",
            &[object_reference_value(previous)],
        );
    }
    Ok(HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .is_some_and(|object| object.container().is_none())
    }))
}

/// Engine-internal exits normally retain the object's current coordinates.
fn exit_object_at_current_position(target: ObjectId) -> Result<bool, RuntimeError> {
    let position = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .map(|object| object.position)
    });
    let Some(position) = position else {
        return Ok(false);
    };
    exit_object_at_position(target, position)
}

/// Live `C4Object::Enter(target)` without Collect's RejectCollect,
/// Collection and Hit tail. This is the path used by CreateContents and
/// Split2Components and must finish its callbacks before their next step.
fn enter_object_live(target: ObjectId, container: ObjectId) -> Result<bool, RuntimeError> {
    enter_object_live_with_calls(target, container, true)
}

/// C4Object::Enter's `fCalls` controls only Collection2/Entrance. The
/// RejectEntrance query, a transfer's ordinary callback-enabled Exit,
/// CopyMotion and base auto-sale all run in both modes.
fn enter_object_live_with_calls(
    target: ObjectId,
    container: ObjectId,
    f_calls: bool,
) -> Result<bool, RuntimeError> {
    if target == container || !object_is_present(target) || !object_is_present(container) {
        return Ok(false);
    }
    if call_object_own_fail_safe(
        target,
        "RejectEntrance",
        &[object_reference_value(container)],
    )
    .as_bool()
    {
        return Ok(false);
    }

    let would_cycle = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return true;
        };
        let mut cursor = Some(container);
        let mut seen = HashSet::new();
        while let Some(current) = cursor {
            if current == target || !seen.insert(current) {
                return true;
            }
            cursor = context
                .get_world_object(current)
                .and_then(|object| object.container());
        }
        false
    });
    if would_cycle {
        return Ok(false);
    }

    let contained = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .and_then(|object| object.container())
            .is_some()
    });
    if contained && !exit_object_at_current_position(target)? {
        return Ok(false);
    }

    let entered = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let target_ready = context
            .object_scope(target)
            .is_some_and(|scope| {
                !scope.destroy && scope.status().is_active() && scope.container().is_none()
            })
            || context.get_world_object(target).is_some_and(|object| {
                object.is_present() && object.container().is_none()
            });
        let container_motion = context
            .object_scope(container)
            .filter(|scope| !scope.destroy && scope.status().is_active())
            .map(|scope| {
                (
                    scope.effective_position(),
                    scope.fixed_velocity(),
                    scope.controller(),
                )
            })
            .or_else(|| {
                context
                    .get_world_object(container)
                    .filter(|object| object.is_present())
                    .map(|object| (object.position, object.fixed_velocity, object.controller()))
            });
        let Some((position, velocity, controller)) = container_motion else {
            return false;
        };
        if !target_ready || !context.ensure_object_scope(target) {
            return false;
        }
        let Some(scope) = context.object_scope_mut(target) else {
            return false;
        };
        let was_mobile = scope.mobile();
        scope.set_container(Some(container));
        if !(scope.alive() && scope.category() & crate::CATEGORY_LIVING != 0) {
            scope.set_controller(controller);
        }
        // CopyMotion writes integer position/fix position and x/y dirs; it
        // intentionally leaves r/rdir untouched.
        scope.current_position = position;
        scope.current_fixed_position = FixedVec2::from_ints(position.x, position.y);
        scope.pending_update.position = Some(position);
        scope.pending_update.construction_preserves_fixed_position = false;
        scope.set_fixed_velocity(velocity);
        // CopyMotion does not mobilize; the generic fixed-dir update does,
        // so carry the pre-Enter native flag explicitly over that fold.
        scope.set_mobile(was_mobile);
        let nonliving = !(scope.alive() && scope.category() & crate::CATEGORY_LIVING != 0);
        if let Some(spawn) = context
            .pending_spawns
            .iter_mut()
            .find(|spawn| spawn.id == Some(target))
        {
            spawn.container = Some(container);
            spawn.position = position;
            spawn.fixed_position = None;
            spawn.fixed_velocity = Some(velocity);
            if nonliving {
                spawn.controller = Some(controller);
            }
        }
        let _ = refresh_live_object_ocf(context, target);
        refresh_container_collection_ocf(context, container);
        true
    });
    if !entered {
        return Ok(false);
    }

    if f_calls {
        call_object_own_fail_safe(
            container,
            "Collection2",
            &[object_reference_value(target)],
        );
        let entrance_container = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow.as_ref()?;
            let current = context.get_world_object(target)?.container()?;
            let current_live = context
                .get_world_object(current)
                .is_some_and(|object| object.is_present());
            let original_live = context
                .get_world_object(container)
                .is_some_and(|object| object.is_present());
            (current_live && original_live).then_some(current)
        });
        if let Some(current) = entrance_container {
            call_object_own_fail_safe(target, "Entrance", &[object_reference_value(current)]);
        }
    }
    auto_sell_after_enter(target, container)?;
    Ok(true)
}

/// `C4Effect::ClearAll(..., C4FxCall_RemoveClear)` for AssignRemoval.
/// Stop callbacks run from the tail of the effect list while the object is
/// still live; effects added by those callbacks are deleted afterwards
/// without receiving a Stop callback (C4Effect.cpp:407-425).
fn clear_effects_for_assign_removal(target: ObjectId) -> Result<bool, RuntimeError> {
    let effects = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Vec::new();
        };
        if !context.ensure_object_scope(target) {
            return Vec::new();
        }
        context
            .object_scope(target)
            .map(|scope| {
                scope
                    .effects
                    .snapshot()
                    .into_iter()
                    .filter(|effect| effect.priority != 0)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default()
    });
    for effect in effects.into_iter().rev() {
        let marked_dead = HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(scope) = borrow
                .as_mut()
                .and_then(|context| context.object_scope_mut(target))
            else {
                return false;
            };
            let Some(live) = scope
                .effects
                .effects
                .iter_mut()
                .find(|live| live.number == effect.number && live.priority != 0)
            else {
                return false;
            };
            live.priority = 0;
            true
        });
        if marked_dead {
            let function = format!("Fx{}Stop", effect.name);
            let stop_result = dispatch_effect_fx_callback_fail_safe(
                &effect,
                &function,
                &[
                    object_reference_value(target),
                    Value::Int(effect.number),
                    Value::Int(3),
                ],
            );
            if !object_is_present(target) {
                return Ok(false);
            }
            if stop_result == -1 {
                HOST_CONTEXT.with(|cell| {
                    let mut borrow = cell.borrow_mut();
                    let Some(scope) = borrow
                        .as_mut()
                        .and_then(|context| context.object_scope_mut(target))
                    else {
                        return;
                    };
                    if let Some(live) = scope
                        .effects
                        .effects
                        .iter_mut()
                        .find(|live| live.number == effect.number && live.priority == 0)
                    {
                        live.priority = effect.priority;
                    }
                });
            }
        }
    }

    loop {
        let removed = HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(scope) = borrow
                .as_mut()
                .and_then(|context| context.object_scope_mut(target))
            else {
                return false;
            };
            let Some(number) = scope.effects.effects.first().map(|effect| effect.number) else {
                return false;
            };
            scope
                .effects
                .remove_effect(None, number.max(0) as usize, true)
                .is_some()
        });
        if !removed {
            break;
        }
    }
    Ok(true)
}

/// `C4Object::AssignRemoval` sets Status=0 before killing contents, but it
/// deliberately keeps Info, object references and the solid mask alive until
/// after contents and containment have been cleaned up (C4Object.cpp:276-313).
fn mark_object_status_deleted(context: &mut EffectHostContext, target: ObjectId) -> bool {
    if !context.ensure_object_scope(target) {
        return false;
    }
    if let Some(scope) = context.object_scope_mut(target) {
        scope.mark_destroy_status();
        true
    } else {
        false
    }
}

fn retire_object_info_and_clear_references(
    context: &mut EffectHostContext,
    target: ObjectId,
) {
    let link = context.object_scope(target).and_then(ObjectScopeContext::info_link);
    if let Some(link) = link {
        if retire_host_crew_info(context, link) {
            context.record_player_command(PlayerCommand::RetireCrewInfo {
                object_id: target,
                link,
            });
        }
    }
    if let Some(scope) = context.object_scope_mut(target) {
        scope.clear_info_for_removal();
    }
    context.clear_non_player_script_object_references(target);
}

fn assign_removal_live(target: ObjectId, exit_contents: bool) -> Result<bool, RuntimeError> {
    // C4Object::AssignRemoval gates on raw Status truthiness. Inactive is a
    // live nonzero status and is activated internally before deletion.
    if !object_has_status(target) {
        return Ok(false);
    }
    let container = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .and_then(|object| object.container())
    });
    if let Some(container) = container.filter(|container| object_has_status(*container)) {
        call_object_own_fail_safe(
            container,
            "ContentsDestruction",
            &[object_reference_value(target)],
        );
        if !object_has_status(target) {
            return Ok(true);
        }
    }
    call_object_own_fail_safe(target, "Destruction", &[]);
    if !object_has_status(target) {
        return Ok(true);
    }
    if !clear_effects_for_assign_removal(target)? {
        return Ok(true);
    }

    // Particle lists are cleared before SetAction(ActIdle), while the object
    // is still live (C4Object.cpp:268-274).
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        if let Some(context) = borrow.as_mut() {
            context.register_particle(ParticleCommand::Clear {
                definition_id: None,
                scope: ParticleScope::Object(target),
            });
        }
    });
    let _ = native_set_action_by_name(target, "Idle")?;
    if !object_has_status(target) {
        return Ok(true);
    }

    // AssignRemoval(true) passes the removed container's x/y to every
    // direct child's Exit (C4Object.cpp:285-288).
    let exit_position = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .map(|object| object.position)
    });

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else { return };
        mark_object_status_deleted(context, target);
    });

    loop {
        let child = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(target))
                .and_then(|object| object.contents().first().copied())
        });
        let Some(child) = child else { break };
        if exit_contents {
            let Some(position) = exit_position else { break };
            if !exit_object_at_position(child, position)? {
                break;
            }
            continue;
        }
        HOST_CONTEXT.with(|cell| {
            if let Some(context) = cell.borrow_mut().as_mut() {
                context.unlink_content_for_removal(target, child);
            }
        });
        // AssignRemoval's default `fExitContents=false` unlinks and
        // recursively removes contents without Ejection/Departure calls.
        // The child's Contained pointer remains observable during its own
        // Destruction callback even though the parent is already dead.
        let _ = assign_removal_live(child, false)?;
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else { return };
        let removed_from = context.object_scope(target).and_then(ObjectScopeContext::container);
        if let Some(scope) = context.object_scope_mut(target) {
            scope.set_container(None);
        }
        if let Some(container) = removed_from {
            // AssignRemoval removes the child's link, then UpdateMass and
            // SetOCF on the surviving parent (C4Object.cpp:297-305).
            refresh_container_collection_ocf(context, container);
        }
        retire_object_info_and_clear_references(context, target);
    });
    clear_player_object_pointers_host(target);
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        if let Some(context) = borrow.as_mut() {
            // pSolidMaskData->Remove is the last modeled AssignRemoval side
            // arm, after Game.ClearPointers (C4Object.cpp:309-313).
            context.update_live_solid_mask(target);
        }
    });
    Ok(true)
}

fn can_sell_object_live(target: ObjectId, player: i32) -> bool {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        let player_active = context
            .player_state(player)
            .is_some_and(|state| state.status != crate::PlayerStatus::Eliminated);
        player_active
            && context.get_world_object(target).is_some_and(|object| {
                object.is_present() && object.ocf() & ocf::CREW_MEMBER == 0
            })
    })
}

fn sell_object_to_home_live(target: ObjectId, player: i32) -> Result<bool, RuntimeError> {
    if !can_sell_object_live(target, player) {
        return Ok(false);
    }

    loop {
        let child = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(target))
                .and_then(|object| object.contents().first().copied())
        });
        let Some(child) = child else { break };
        let container = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(target))
                .and_then(|object| object.container())
        });
        let moved = match container {
            Some(container) => enter_object_live(child, container)?,
            None => exit_object_at_current_position(child)?,
        };
        if !moved {
            break;
        }
        let _ = sell_object_to_home_live(child, player)?;
    }

    // Sell2Home prices the object against its live containing base. Direct
    // Sell calls reach this path before Exit, unlike the base-auto-sell path.
    let base = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .and_then(|object| object.container())
    });
    let value = match get_value(&[
        object_reference_value(target),
        Value::Nil,
        base.map(object_reference_value).unwrap_or(Value::Nil),
        Value::Int(player),
    ]) {
        Ok(Value::Int(value)) => value,
        Ok(_) => 0,
        Err(error) => {
            tracing::warn!(%error, "CalcValue failed during home-base sale; using zero");
            0
        }
    };
    // C4Player::DoWealth clamps adjustments to 0..=10000; FnSetWealth's
    // wider 100000 ceiling does not apply to a home-base sale.
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        let updated = {
            let Some(state) = context.player_state_mut(player) else {
                return;
            };
            let updated = (i64::from(state.wealth) + i64::from(value)).clamp(0, 10_000) as i32;
            state.wealth = updated;
            state.view_wealth = 100;
            updated
        };
        context.record_player_command(PlayerCommand::SetWealth {
            player_id: player,
            value: updated,
            show_change: true,
        });
    });

    let original_definition = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_effective_definition_id(target))
    });
    let stock_definition = match call_world_object_own_function(
        target,
        "SellTo",
        &[Value::Int(player)],
    ) {
        Some(Ok(Value::C4Id(id))) if !id.is_empty() && id != "NONE" && id != "0000" => {
            Some(DefinitionId::from(id.as_str()))
        }
        Some(Ok(Value::Int(raw @ 1..=9999))) => {
            Some(DefinitionId::from(format!("{raw:04}").as_str()))
        }
        Some(Ok(_)) => None,
        None => original_definition,
        Some(Err(error)) => {
            tracing::warn!(%error, "SellTo failed during home-base sale; omitting stock");
            None
        }
    };
    if let Some(definition) = stock_definition {
        let should_stock = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let Some(context) = borrow.as_ref() else {
                return false;
            };
            context.world.definition_known(definition.as_str()) != Some(false)
                && (context.world.definition_rebuyable(definition.as_str())
                    || context
                        .player_state(player)
                        .is_some_and(|state| state.home_base_material.contains_key(&definition)))
        });
        if should_stock {
            let _ = do_homebase_material(&[
                Value::Int(player),
                Value::C4Id(definition.as_str().to_owned()),
                Value::Int(1),
            ])?;
        }
    }

    let contained = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(target))
            .is_some_and(|object| object.container().is_some())
    });
    if contained && object_is_present(target) {
        let _ = exit_object_at_position(target, Vector2::ZERO)?;
    }
    if object_is_present(target) {
        call_object_own_fail_safe(target, "Sale", &[Value::Int(player)]);
    }
    if object_is_present(target) {
        let _ = assign_removal_live(target, true)?;
    }
    Ok(true)
}

fn report_buy_error(
    player: i32,
    message: String,
    target: Option<ObjectId>,
) -> Result<(), RuntimeError> {
    let _ = player_message(&[Value::Int(player), Value::String(message)])?;
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            context
                .audio_mut()
                .play_sound("Error", target, 100, false, false, None);
        }
    });
    Ok(())
}

/// FnBuy (C4Script.cpp:3732-3751) plus C4Player::Buy
/// (C4Player.cpp:826-864): synchronously consume the paying player's base
/// stock and wealth, create the item for another player, call Purchase, then
/// enter an explicit target or force-position at the calling object.
fn buy(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 5 {
        return Err(RuntimeError::new(
            "Buy expects at most 5 arguments: definition, for_player, pay_player, target, show_errors",
        ));
    }
    let Some(definition) = parse_definition_argument(args.first(), "Buy")? else {
        return Ok(Value::Nil);
    };
    let for_player = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "Buy",
        "for_player",
    )?;
    let pay_player = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "Buy",
        "pay_player",
    )?;
    let to_base = parse_object_reference_argument(
        args.get(3).unwrap_or(&Value::Nil),
        "Buy",
        "target",
    )?;
    let show_errors = value_to_bool(
        args.get(4).unwrap_or(&Value::Nil),
        "Buy",
        "show_errors",
    )?;
    let caller = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.script_object_context)
    });
    let creator = to_base.or(caller);
    let definition_id = DefinitionId::from(definition.as_str());

    let initial = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return None;
        };
        // ValidPlr accepts eliminated players; C4Player::Buy reports that
        // state separately below.
        context.player_state(for_player)?;
        let payer = context.player_state(pay_player)?;
        let eliminated = matches!(
            payer.status,
            crate::PlayerStatus::Eliminated | crate::PlayerStatus::Surrendered
        ) || payer.surrendered;
        let available = payer
            .exact_home_base_material_entries()
            .into_iter()
            .find_map(|(id, count)| (id == definition_id).then_some(count))
            .unwrap_or(0);
        let crew_member = context
            .definition_metadata(&definition)
            .map(|metadata| metadata.crew_member);
        Some((eliminated, payer.name.clone(), available, crew_member))
    });
    let Some((eliminated, payer_name, available, crew_member)) = initial else {
        return Ok(Value::Nil);
    };
    if eliminated {
        if show_errors {
            report_buy_error(
                pay_player,
                format!("Player {payer_name}|eliminated."),
                creator,
            )?;
        }
        return Ok(Value::Nil);
    }
    // C4Player::Buy checks stock before resolving the definition. Neither an
    // unavailable item nor an unknown definition produces an error message.
    if available <= 0 {
        return Ok(Value::Nil);
    }
    let Some(crew_member) = crew_member else {
        return Ok(Value::Nil);
    };

    let Some(price) = calculated_definition_value(&definition, creator, pay_player)? else {
        return Ok(Value::Nil);
    };

    // CalcDefValue/CalcBuyValue callbacks above can mutate both wealth and
    // stock. C++ compares/decrements the live values after those callbacks,
    // while retaining only the initial availability decision.
    let charged = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let Some(current_wealth) = context.player_state(pay_player).map(|payer| payer.wealth)
        else {
            return false;
        };
        if price > current_wealth {
            return false;
        }

        let (team, updated_material, updated_wealth) = {
            let Some(payer) = context.player_state_mut(pay_player) else {
                return false;
            };
            payer.adjust_home_base_material_entry(definition_id.clone(), -1);
            let updated_wealth = (i64::from(payer.wealth) - i64::from(price))
                .clamp(0, 10_000) as i32;
            payer.wealth = updated_wealth;
            payer.view_wealth = 100;
            (
                payer.team,
                payer.exact_home_base_material_entries(),
                updated_wealth,
            )
        };

        if context.team_home_base_rule() {
            if let Some(team) = team {
                let teammates: Vec<i32> = context
                    .player_ids()
                    .iter()
                    .copied()
                    .filter(|other| {
                        *other != pay_player
                            && context.player_state(*other).and_then(|player| player.team)
                                == Some(team)
                    })
                    .collect();
                for teammate in teammates {
                    if let Some(player) = context.player_state_mut(teammate) {
                        player.set_home_base_material_entries(updated_material.clone());
                    }
                }
            }
        }
        context.record_player_command(PlayerCommand::AdjustHomeBaseMaterial {
            player_id: pay_player,
            definition_id: definition_id.clone(),
            delta: -1,
        });
        context.record_player_command(PlayerCommand::SetWealth {
            player_id: pay_player,
            value: updated_wealth,
            show_change: true,
        });
        true
    });
    if !charged {
        if show_errors {
            report_buy_error(pay_player, "Not enough money!".to_string(), creator)?;
        }
        return Ok(Value::Nil);
    }

    let Some(created) = create_native_object(NativeObjectCreation {
        definition: definition.clone(),
        creator,
        owner: for_player,
        position: Vector2::new(50, 50),
        rotation: 0,
        velocity: FixedVec2::ZERO,
        rotation_velocity: C4Fixed::ZERO,
    })? else {
        return Ok(Value::Nil);
    };

    if crew_member {
        let _ = make_crew_member_live(created, for_player)?;
    }
    if !object_is_present(created) {
        return Ok(Value::Nil);
    }
    call_object_own_fail_safe(
        created,
        "Purchase",
        &[
            Value::Int(pay_player),
            creator.map(object_reference_value).unwrap_or(Value::Nil),
        ],
    );
    if !object_is_present(created) {
        return Ok(Value::Nil);
    }

    if let Some(to_base) = to_base {
        let _ = enter_object_live(created, to_base)?;
    } else if let Some(caller) = caller {
        let caller_position = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(caller))
                .map(|object| object.position())
        });
        if let Some(position) = caller_position {
            let _ = set_position(&[
                Value::Int(position.x),
                Value::Int(position.y),
                object_reference_value(created),
            ])?;
        }
    }
    Ok(object_reference_value(created))
}

/// FnSell (C4Script.cpp:3753-3760): a nil object means the executing
/// script object; a valid player then runs the complete Sell2Home path.
fn sell(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "Sell expects at most 2 arguments: player, object",
        ));
    }
    let player = value_to_i32(args.first().unwrap_or(&Value::Nil), "Sell", "player")?;
    let explicit = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "Sell",
        "object",
    )?;
    let target = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| explicit.or(context.script_object_context))
    });
    let Some(target) = target else {
        return Ok(Value::Bool(false));
    };
    Ok(Value::Bool(sell_object_to_home_live(target, player)?))
}

fn auto_sell_after_enter(entering: ObjectId, original_target: ObjectId) -> Result<(), RuntimeError> {
    let sale = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        if !context.world.base_auto_sell_enabled
            || !context
                .get_world_object(original_target)
                .is_some_and(|object| object.is_present())
        {
            return None;
        }
        let container = context.get_world_object(entering)?.container()?;
        let container_state = context.get_world_object(container)?;
        if !container_state.is_present() {
            return None;
        }
        let base = container_state.full_state()?.base;
        context.player_state(base).map(|_| (container, base))
    });
    let Some((container, player)) = sale else {
        return Ok(());
    };
    let outer = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(container))
            .map(|object| object.contents().to_vec())
            .unwrap_or_default()
    });
    for object in outer {
        let nested = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(object))
                .map(|object| object.contents().to_vec())
                .unwrap_or_default()
        });
        for child in nested {
            let auto_sell = HOST_CONTEXT.with(|cell| {
                let borrow = cell.borrow();
                let Some(context) = borrow.as_ref() else {
                    return false;
                };
                context
                    .object_effective_definition_id(child)
                    .is_some_and(|id| context.world.definition_base_auto_sell(id.as_str()))
            });
            if auto_sell && can_sell_object_live(child, player) {
                let _ = exit_object_at_current_position(child)?;
                let _ = sell_object_to_home_live(child, player)?;
            }
        }
        let auto_sell = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let Some(context) = borrow.as_ref() else {
                return false;
            };
            context
                .object_effective_definition_id(object)
                .is_some_and(|id| context.world.definition_base_auto_sell(id.as_str()))
        });
        if auto_sell && can_sell_object_live(object, player) {
            let _ = exit_object_at_current_position(object)?;
            let _ = sell_object_to_home_live(object, player)?;
        }
    }
    Ok(())
}

/// FnEnter (C4Script.cpp:365-370): pObj (or the scope object) enters the
/// container pTarget through the synchronous C4Object::Enter pipeline.
fn enter(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(target) =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "Enter", "target")?
    else {
        return Ok(Value::Bool(false)); // C4Object::Enter(nullptr)
    };
    let subject =
        parse_object_reference_argument(args.get(1).unwrap_or(&Value::Nil), "Enter", "obj")?;
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    });
    let Some(subject) = subject.or(active) else {
        return Ok(Value::Bool(false));
    };
    Ok(Value::Bool(enter_object_live(subject, target)?))
}

/// FnCollect (C4Script.cpp:391-415) routes through C4Object::Collect:
/// validate the collector's cached OCF, run Enter's two vetoes and callback
/// tail synchronously, then Collection/Hit before the final CopyMotion
/// (C4Object.cpp:1566-1636,5693-5714). This must stay a live host operation,
/// rather than a deferred container assignment: MFBL collects a same-call
/// freshly-created FRBL and branches on the boolean result.
struct CollectDelayRestore {
    collector: ObjectId,
    old_delay: i32,
}

impl Drop for CollectDelayRestore {
    fn drop(&mut self) {
        if self.old_delay == 0 {
            return;
        }
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(scope) = borrow
                .as_mut()
                .and_then(|context| context.object_scope_mut(self.collector))
            else {
                return;
            };
            scope.restore_no_collect_delay(self.old_delay);
        });
    }
}

fn collect(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(item) = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "Collect",
        "item",
    )?
    else {
        return Ok(Value::Bool(false));
    };
    let explicit_collector = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "Collect",
        "collector",
    )?;
    let active = active_object_id();
    let Some(collector) = explicit_collector.or(active) else {
        return Ok(Value::Bool(false));
    };
    if item == collector {
        return Ok(Value::Bool(false));
    }

    let (ready, old_no_collect_delay) = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return (false, 0);
        };
        let item_ready = context
            .get_world_object(item)
            .is_some_and(|object| object.is_present());
        let collector_state = context.get_world_object(collector);
        let collector_present = collector_state
            .as_ref()
            .is_some_and(HostWorldObject::is_present);
        if !collector_present || !context.ensure_object_scope(collector) {
            return (false, 0);
        }
        let old_no_collect_delay = context
            .object_scope(collector)
            .map(ObjectScopeContext::no_collect_delay)
            .unwrap_or(0);
        // FnCollect trusts the existing cached OCF when the delay is already
        // zero. Only a nonzero delay is cleared and followed by UpdateOCF.
        if old_no_collect_delay != 0 {
            if let Some(scope) = context.object_scope_mut(collector) {
                scope.set_no_collect_delay(0);
            }
            let _ = refresh_live_object_ocf(context, collector);
        }
        let collector_ready = collector_present
            && context
                .object_scope(collector)
                .is_some_and(|scope| scope.ocf() & ocf::COLLECTION != 0);
        (item_ready && collector_ready, old_no_collect_delay)
    });
    // Restore on every success, veto, error and early return after the
    // temporary clear. C++ performs this after Collect returns, even when it
    // failed (C4Script.cpp:410-413).
    let _delay_restore = CollectDelayRestore {
        collector,
        old_delay: old_no_collect_delay,
    };
    if !ready {
        return Ok(Value::Bool(false));
    }

    let call_fail_safe = |target, function: &str, pars: &[Value]| -> Value {
        match call_world_object_own_function(target, function, pars) {
            Some(Ok(value)) => value,
            Some(Err(error)) => {
                tracing::warn!(
                    %error,
                    object = target.as_u64(),
                    callback = function,
                    "script error in Collect callback; continuing like C++ fail-safe Call"
                );
                Value::Nil
            }
            None => Value::Nil,
        }
    };

    // Enter first asks the ENTERING object, before cycle detection or any
    // mutation (C4Object.cpp:1575-1581).
    if call_fail_safe(
        item,
        "RejectEntrance",
        &[object_reference_value(collector)],
    )
    .as_bool()
    {
        return Ok(Value::Bool(false));
    }

    let would_cycle = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return true;
        };
        let mut cursor = Some(collector);
        let mut seen = HashSet::new();
        while let Some(container) = cursor {
            if container == item || !seen.insert(container) {
                return true;
            }
            cursor = context
                .get_world_object(container)
                .and_then(|object| object.container());
        }
        false
    });
    if would_cycle {
        return Ok(Value::Bool(false));
    }

    // Collect supplies Enter's non-null pfRejectCollect pointer, so the
    // COLLECTOR sees (entering definition id, entering object) next
    // (C4Object.cpp:1582-1591,5701-5704).
    let item_definition = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(item))
            .map(|object| object.definition_id().to_string())
    });
    let Some(item_definition) = item_definition else {
        return Ok(Value::Bool(false));
    };
    if call_fail_safe(
        collector,
        "RejectCollect",
        &[
            Value::C4Id(item_definition),
            object_reference_value(item),
        ],
    )
    .as_bool()
    {
        return Ok(Value::Bool(false));
    }

    // A transfer performs a real Exit first. Its callbacks observe the
    // already-cleared relation and may re-enter, which aborts the outer Enter
    // (C4Object.cpp:1592-1594; Exit :1559-1563).
    let previous = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return None;
        };
        if !context.ensure_object_scope(item) {
            return None;
        }
        let scope = context.object_scope_mut(item)?;
        let previous = scope.container();
        if previous.is_some() {
            scope.set_container(None);
        }
        Some(previous)
    });
    let Some(previous) = previous else {
        return Ok(Value::Bool(false));
    };
    if let Some(previous) = previous {
        call_fail_safe(
            previous,
            "Ejection",
            &[object_reference_value(item)],
        );
        call_fail_safe(item, "Departure", &[object_reference_value(previous)]);
    }

    let entered = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let item_ready = context.get_world_object(item).is_some_and(|object| {
            object.is_present() && object.container().is_none()
        });
        let collector_state = context.get_world_object(collector).filter(|object| {
            object.is_present()
        });
        let Some(collector_state) = collector_state else {
            return false;
        };
        if !item_ready || !context.ensure_object_scope(item) {
            return false;
        }
        let collector_controller = collector_state.controller();
        let Some(scope) = context.object_scope_mut(item) else {
            return false;
        };
        scope.set_container(Some(collector));
        if !(scope.alive() && scope.category() & crate::CATEGORY_LIVING != 0) {
            scope.set_controller(collector_controller);
        }
        true
    });
    if !entered {
        return Ok(Value::Bool(false));
    }

    // Enter updates the collector's mass and cached OCF immediately after
    // inserting into Contents, before Collection2. Contents can cross the
    // CollectionLimit here and clear OCF_Collection even while the temporary
    // NoCollectDelay override is active (C4Object.cpp:1619-1624;
    // SetOCF :595-600).
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        let Some(collector_state) = context.get_world_object(collector) else {
            return;
        };
        let collection_full = collector_state
            .collection_limit
            .is_some_and(|limit| collector_state.contents().len() >= limit as usize);
        if context.ensure_object_scope(collector) {
            if let Some(scope) = context.object_scope_mut(collector) {
                let mut updated = scope.ocf();
                if collection_full {
                    updated &= !ocf::COLLECTION;
                }
                scope.cached_ocf = Some(updated);
            }
        }
    });

    // The relation is live before both callbacks. Collection2 may move the
    // item; Entrance receives its then-current container, and is skipped when
    // either that container or the original collector died
    // (C4Object.cpp:1625-1630).
    call_fail_safe(
        collector,
        "Collection2",
        &[object_reference_value(item)],
    );
    let entrance_target = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let current = context.get_world_object(item)?.container()?;
        let current_live = context
            .get_world_object(current)
            .is_some_and(|object| object.is_present());
        let original_live = context
            .get_world_object(collector)
            .is_some_and(|object| object.is_present());
        (current_live && original_live).then_some(current)
    });
    if let Some(container) = entrance_target {
        call_fail_safe(item, "Entrance", &[object_reference_value(container)]);
    }

    // C4Object::Collect cancels an ATTACH procedure before Collection. Use
    // ObjectSetAction so Start/Abort calls remain synchronous like C++
    // ObjectComCancelAttach -> SetAction(ActIdle) (C4ObjectCom.cpp:769-774).
    let attached = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        context
            .object_scope(item)
            .map(ObjectScopeContext::effective_action_procedure)
            .or_else(|| {
                context
                    .get_world_object(item)
                    .and_then(|object| object.procedure_name().map(ActionProcedure::from_name))
            })
            == Some(ActionProcedure::Attach)
    });
    if attached {
        let _ = object_set_action(&[
            object_reference_value(item),
            Value::String("Idle".to_string()),
        ])?;
    }

    call_fail_safe(
        collector,
        "Collection",
        &[object_reference_value(item)],
    );
    let hit_flags = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(item))
            .filter(|object| object.is_present())
            .map(|object| object.ocf())
            .unwrap_or(0)
    });
    for (flag, function) in [
        (ocf::HIT_SPEED1, "Hit"),
        (ocf::HIT_SPEED2, "Hit2"),
        (ocf::HIT_SPEED3, "Hit3"),
    ] {
        if hit_flags & flag != 0 {
            call_fail_safe(item, function, &[]);
        }
    }

    // Hit observes the pre-copy item motion. Only afterwards, and only if
    // callbacks left it in this collector, CopyMotion snaps position and
    // fixed dirs to the collector (C4Object.cpp:5711-5713;
    // C4Movement.cpp:518-529).
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        let still_collected = context
            .get_world_object(item)
            .is_some_and(|object| object.is_present() && object.container() == Some(collector));
        if !still_collected {
            return;
        }
        let Some(collector_state) = context.get_world_object(collector) else {
            return;
        };
        let position = context
            .object_scope(collector)
            .map(ObjectScopeContext::effective_position)
            .unwrap_or(collector_state.position);
        let velocity = context
            .object_scope(collector)
            .map(ObjectScopeContext::fixed_velocity)
            .unwrap_or(collector_state.fixed_velocity);
        let Some(scope) = context.object_scope_mut(item) else {
            return;
        };
        scope.set_position(position);
        scope.set_fixed_velocity(velocity);
    });

    // FnCollect restores the old positive NoCollectDelay but deliberately
    // does not call UpdateOCF again (:412-413). Preserve the cache left by
    // the temporary recompute/Enter callbacks after the deferred outcome
    // fold performs its ordinary container refresh.
    if old_no_collect_delay != 0 {
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return;
            };
            if context.ensure_object_scope(collector) {
                if let Some(scope) = context.object_scope_mut(collector) {
                    let ocf = scope.ocf();
                    scope.pending_update.ocf_override = Some(ocf);
                }
            }
        });
    }

    Ok(Value::Bool(true))
}

/// FnGrabContents (C4Script.cpp:320-327) and C4Object::GrabContents
/// (C4Object.cpp:6162-6171): pTo defaults to the calling object, the source
/// list is copied before any moves, and every still-live entry attempts a
/// regular Enter(pTo). Individual failures do not change the true return.
fn grab_contents(args: &[Value]) -> Result<Value, RuntimeError> {
    let from = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "GrabContents",
        "from",
    )?;
    let Some(from) = from else {
        return Ok(Value::Bool(false));
    };
    let explicit_to = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "GrabContents",
        "to",
    )?;
    let active = active_object_id();
    let Some(to) = explicit_to.or(active) else {
        return Ok(Value::Bool(false));
    };
    if to == from {
        return Ok(Value::Bool(false));
    }

    // An explicit foreign destination becomes the call context just like
    // FnGrabContents' pTo default would have been that object. This also
    // lets object-arrow calls operate on freshly created pending objects.
    if Some(to) != active {
        return match call_world_object_function(
            to,
            "GrabContents",
            &[object_reference_value(from)],
        ) {
            Some(result) => result,
            None => Ok(Value::Bool(false)),
        };
    }

    let contents = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return None;
        };
        // A C4Value object reference can only supply live engine objects.
        context.get_world_object(to)?;
        context
            .get_world_object(from)
            .map(|source| source.contents().to_vec())
    });
    let Some(contents) = contents else {
        return Ok(Value::Bool(false));
    };

    let call_fail_safe = |target, function: &str, pars: &[Value]| {
        if let Some(Err(error)) = call_world_object_own_function(target, function, pars) {
            tracing::warn!(
                %error,
                object = target.as_u64(),
                callback = function,
                "script error in container callback; continuing like C++ fail-safe Call"
            );
        }
    };

    for child in contents {
        let live = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(child))
                .is_some_and(|object| object.is_present())
        });
        if !live {
            continue;
        }

        // C4Object::Enter's first gate is the entering object's
        // ~RejectEntrance(pTarget). GrabContents deliberately does not ask
        // the target's ~RejectCollect because it passes no pfRejectCollect.
        let rejected = match call_world_object_own_function(
            child,
            "RejectEntrance",
            &[object_reference_value(to)],
        ) {
            Some(Ok(value)) => value.as_bool(),
            Some(Err(error)) => {
                tracing::warn!(
                    %error,
                    object = child.as_u64(),
                    "script error in RejectEntrance; continuing like C++ fail-safe Call"
                );
                false
            }
            None => false,
        };
        if rejected {
            continue;
        }

        // Reject endless containment before Exit mutates anything
        // (C4Object.cpp:1566-1568).
        let would_cycle = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let Some(context) = borrow.as_ref() else {
                return true;
            };
            let mut cursor = Some(to);
            let mut seen = HashSet::new();
            while let Some(container) = cursor {
                if container == child {
                    return true;
                }
                if !seen.insert(container) {
                    return true;
                }
                cursor = context
                    .get_world_object(container)
                    .and_then(|object| object.container());
            }
            false
        });
        if would_cycle {
            continue;
        }

        // Enter transfers by exiting first. Stage that synchronously so the
        // fail-safe Ejection/Departure callbacks observe the live relation.
        let previous = HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return None;
            };
            if !context.ensure_object_scope(child) {
                return None;
            }
            let scope = context.object_scope_mut(child)?;
            let previous = scope.container();
            if previous.is_some() {
                scope.set_container(None);
            }
            Some(previous)
        });
        let Some(previous) = previous else {
            continue;
        };
        if let Some(previous) = previous {
            call_fail_safe(
                previous,
                "Ejection",
                &[object_reference_value(child)],
            );
            call_fail_safe(
                child,
                "Departure",
                &[object_reference_value(previous)],
            );
        }

        let entered = HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return false;
            };
            let child_ready = context
                .get_world_object(child)
                .is_some_and(|object| object.is_present() && object.container().is_none());
            let target_ready = context
                .get_world_object(to)
                .is_some_and(|object| object.is_present());
            if !child_ready || !target_ready || !context.ensure_object_scope(child) {
                return false;
            }
            context
                .object_scope_mut(child)
                .map(|scope| scope.set_container(Some(to)))
                .is_some()
        });
        if !entered {
            continue;
        }

        call_fail_safe(to, "Collection2", &[object_reference_value(child)]);
        let entrance_target = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow.as_ref()?;
            let child = context.get_world_object(child)?;
            let current = child.container()?;
            let current_live = context
                .get_world_object(current)
                .is_some_and(|object| object.is_present());
            let original_target_live = context
                .get_world_object(to)
                .is_some_and(|object| object.is_present());
            (current_live && original_target_live).then_some(current)
        });
        if let Some(container) = entrance_target {
            call_fail_safe(
                child,
                "Entrance",
                &[object_reference_value(container)],
            );
        }
    }

    Ok(Value::Bool(true))
}

/// FnExit (C4Script.cpp:372-388): pObj (or the scope object) leaves its
/// container via C4Object::Exit. The optional tx/ty are CALLER-relative
/// (`tx += cthr->Obj->x`, :377-381), tr == -1 draws Random(360) (:382),
/// and Exit writes position/rotation/dirs unconditionally — bare Exit()
/// re-places the object at the caller's position with r = 0 and zeroed
/// dirs (C4Object.cpp:1549-1553), the y target offset by the SUBJECT's
/// Shape.y (:385) and rdir scaled `itofix(trdir) / 10` (:388). The
/// BoundsCheck side arm stays unmodeled. ObjectComCancelAttach changes an
/// ATTACH action to Idle (including its AbortCall) before Exit checks
/// containment. Exit dispatches Ejection then Departure synchronously and
/// returns the live post-callback `!Contained` state (C4Object.cpp:1559-1563).
fn exit_container(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 7 {
        return Err(RuntimeError::new(
            "Exit expects at most 7 arguments: obj, x, y, r, xdir, ydir, rdir",
        ));
    }
    let subject =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "Exit", "obj")?;
    let tx = parse_optional_i32(args.get(1), "Exit", "x")?.unwrap_or(0);
    let ty = parse_optional_i32(args.get(2), "Exit", "y")?.unwrap_or(0);
    let tr = parse_optional_i32(args.get(3), "Exit", "r")?.unwrap_or(0);
    let txdir = parse_optional_i32(args.get(4), "Exit", "xdir")?.unwrap_or(0);
    let tydir = parse_optional_i32(args.get(5), "Exit", "ydir")?.unwrap_or(0);
    let trdir = parse_optional_i32(args.get(6), "Exit", "rdir")?.unwrap_or(0);
    let prepared = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(None);
        };
        let active = context.object_context().map(|object| object.id());
        let Some(target) = subject.or(active) else {
            return Ok(None); // no pObj and no scope object
        };
        // Caller-relative offset: the CALLING object, also for foreign
        // subjects (C4Script.cpp:377-381).
        let (mut abs_x, mut abs_y) = (tx, ty);
        if let Some(caller) = context.object_context() {
            let position = caller.effective_position();
            abs_x = abs_x.saturating_add(position.x);
            abs_y = abs_y.saturating_add(position.y);
        }
        // The Random(360) draw happens before the contained check — it
        // runs even when Exit then fails (C4Script.cpp:382).
        let rotation = if tr == -1 {
            draw_context_random(360)?
        } else {
            tr
        };
        Ok(Some((target, abs_x, abs_y, rotation)))
    })?;
    let Some((target, abs_x, abs_y, rotation)) = prepared else {
        return Ok(Value::Bool(false));
    };

    // ObjectComCancelAttach runs after the optional rotation draw but before
    // C4Object::Exit checks Contained. SetAction(ActIdle) is a native call:
    // a script function named SetAction may not intercept it, and the old
    // ATTACH action's AbortCall observes the pre-Exit position/container.
    let attached = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        context
            .object_scope(target)
            .map(ObjectScopeContext::effective_action_procedure)
            .or_else(|| {
                context
                    .get_world_object(target)
                    .and_then(|object| object.procedure_name().map(ActionProcedure::from_name))
            })
            == Some(ActionProcedure::Attach)
    });
    if attached {
        let _ = native_set_action_by_name(target, "Idle")?;
    }

    let exited = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return None;
        };
        // The SUBJECT's live Shape.y (C4Script.cpp:385): a same-call
        // SetShape override wins over the def shape. Read it only after the
        // attach AbortCall, which may change the shape or definition.
        let shape_y = live_object_shape(context, target)
            .map(|shape| shape.y)
            .unwrap_or(0);
        if !context.ensure_object_scope(target) {
            return None;
        }
        let Some(scope) = context.object_scope_mut(target) else {
            return None;
        };
        let Some(previous_container) = scope.container() else {
            return None; // not contained (C4Object.cpp:1539)
        };
        scope.set_container(None);
        scope.set_position(Vector2::new(abs_x, abs_y.saturating_add(shape_y)));
        // Raw r write — C4Object::Exit assigns without SetRotation's
        // normalization (C4Object.cpp:1552).
        scope.current_rotation = rotation;
        scope.pending_update.rotation = Some(rotation);
        scope.set_fixed_velocity(FixedVec2::new(itofix(txdir), itofix(tydir)));
        scope.set_rotation_velocity(itofix(trdir) / 10);
        Some(previous_container)
    });
    let Some(previous_container) = exited else {
        return Ok(Value::Bool(false));
    };

    let call_fail_safe = |callback_target, function: &str, pars: &[Value]| {
        if let Some(Err(error)) =
            call_world_object_own_function(callback_target, function, pars)
        {
            tracing::warn!(
                %error,
                object = callback_target.as_u64(),
                callback = function,
                "script error in Exit callback; continuing like C++ fail-safe Call"
            );
        }
    };
    call_fail_safe(
        previous_container,
        "Ejection",
        &[object_reference_value(target)],
    );
    call_fail_safe(
        target,
        "Departure",
        &[object_reference_value(previous_container)],
    );

    // Ejection may re-enter the object. C++ returns !Contained only after
    // both callbacks (C4Object.cpp:1560-1563).
    let outside = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_scope(target))
            .map(|scope| scope.container().is_none())
            .unwrap_or(true)
    });
    Ok(Value::Bool(outside))
}

/// FnSetComponent (C4Script.cpp:2659-2663): sets the component count on
/// pObj or the scope object (C4IDList::SetIDCount with fAddNewID — the
/// entry persists even at zero). Foreign subjects route through the seam.
fn set_component(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(component) = parse_definition_argument(args.first(), "SetComponent")? else {
        return Ok(Value::Bool(false));
    };
    let count = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "SetComponent", "count")?;
    let target =
        parse_object_reference_argument(args.get(2).unwrap_or(&Value::Nil), "SetComponent", "obj")?;
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    });
    if let Some(target) = target {
        if Some(target) != active {
            return match call_world_object_function(
                target,
                "SetComponent",
                &args[..2.min(args.len())],
            ) {
                Some(result) => result,
                None => Ok(Value::Bool(false)),
            };
        }
    }
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let Some(self_id) = context.object_context().map(|object| object.id()) else {
            return Ok(Value::Bool(false));
        };
        // Read-modify-write: the update replaces the whole map, so seed
        // from pending writes or the object's current components.
        let current = context
            .object_context()
            .and_then(|object| object.pending_update.components.clone())
            .or_else(|| {
                context
                    .get_world_object(self_id)
                    .and_then(|object| object.full_state().map(|state| state.components.clone()))
            })
            .unwrap_or_default();
        let mut order = context
            .object_context()
            .and_then(|object| object.pending_update.component_order.clone())
            .or_else(|| {
                context
                    .get_world_object(self_id)
                    .and_then(|object| {
                        object
                            .full_state()
                            .map(|state| state.component_order.clone())
                    })
            })
            .unwrap_or_default();
        let Some(object) = context.object_context_mut() else {
            return Ok(Value::Bool(false));
        };
        let mut map = current;
        let component = DefinitionId::from(component.as_str());
        if !order.contains(&component) {
            order.push(component.clone());
        }
        map.insert(component, count);
        object.pending_update.components = Some(map);
        object.pending_update.component_order = Some(order);
        Ok(Value::Bool(true))
    })
}

/// FnGetDefinition (C4Script.cpp:2668-2677) indexes runtime `Game.Defs` order;
/// C4DefList::GetDef optionally filters by overlapping category bits without
/// reordering the surviving definitions (C4Def.cpp:1141-1158).
fn get_definition(args: &[Value]) -> Result<Value, RuntimeError> {
    let index = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "GetDefinition",
        "index",
    )?;
    let category = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "GetDefinition",
        "category",
    )?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        Ok(borrow
            .as_ref()
            .and_then(|context| context.world.definition_id_by_index(index, category))
            .map(|id| Value::C4Id(id.as_str().to_string()))
            .unwrap_or(Value::Nil))
    })
}

/// FnValue (C4Script.cpp:1385-1389): the raw DefCore `Value` of a loaded
/// definition. Unlike GetValue this does not run CalcDefValue/CalcBuyValue;
/// an unloaded or zero ID returns null.
fn definition_value(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "Value expects at most 1 argument: definition",
        ));
    }
    let Some(definition) = parse_definition_argument(args.first(), "Value")? else {
        return Ok(Value::Nil);
    };
    HOST_CONTEXT.with(|cell| {
        Ok(cell
            .borrow()
            .as_ref()
            .and_then(|context| {
                context
                    .world
                    .definition_metadata(&DefinitionId::from(definition.as_str()))
            })
            .map_or(Value::Nil, |metadata| Value::Int(metadata.value)))
    })
}

/// `C4Def::GetValue` (C4Def.cpp:839-858): run the definition-owned
/// `CalcDefValue(base, player)` override, then the optional base-owned
/// `CalcBuyValue(definition, value)` adjustment. `None` means the definition
/// is not loaded, matching FnGetValue's null return for an unknown id.
fn calculated_definition_value(
    definition: &str,
    base: Option<ObjectId>,
    player: i32,
) -> Result<Option<i32>, RuntimeError> {
    let (metadata, script) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return (None, None);
        };
        (
            context.definition_metadata(definition).cloned(),
            context.world.definition_script(definition).cloned(),
        )
    });
    let Some(metadata) = metadata else {
        return Ok(None);
    };
    let callback_args = [
        base.map(object_reference_value).unwrap_or(Value::Nil),
        Value::Int(player),
    ];
    let mut value = match script.and_then(|script| {
        call_scoped_definition_function(script, definition, "CalcDefValue", &callback_args)
    }) {
        Some(result) => result?.as_c4_int().unwrap_or(0),
        None => metadata.value,
    };
    if let Some(base) = base {
        if let Some(result) = call_world_object_own_function(
            base,
            "CalcBuyValue",
            &[Value::C4Id(definition.to_string()), Value::Int(value)],
        ) {
            value = result?.as_c4_int().unwrap_or(0);
        }
    }
    Ok(Some(value))
}

/// FnGetValue (C4Script.cpp:1366-1375): with a nonzero definition id, use
/// `C4Def::GetValue`; otherwise use the explicit object or `cthr->Obj` and
/// `C4Object::GetValue` (CalcValue/CalcDefValue, construction percentage,
/// then the containing base's CalcSellValue adjustment).
fn get_value(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 4 {
        return Err(RuntimeError::new(
            "GetValue expects at most 4 arguments: object, definition, base, player",
        ));
    }
    let target = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "GetValue",
        "object",
    )?;
    let definition = parse_definition_argument(args.get(1), "GetValue")?;
    let base = parse_object_reference_argument(
        args.get(2).unwrap_or(&Value::Nil),
        "GetValue",
        "base",
    )?;
    let player = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "GetValue",
        "player",
    )?;

    if let Some(definition) = definition.filter(|id| !id.is_empty()) {
        return Ok(calculated_definition_value(&definition, base, player)?
            .map(Value::Int)
            .unwrap_or(Value::Nil));
    }

    let target = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        target.or_else(|| context.object_context().map(ObjectScopeContext::id))
    });
    let Some(target) = target else {
        return Ok(Value::Nil);
    };
    let Some(definition) = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| effective_definition_id(context, target))
    }) else {
        return Ok(Value::Nil);
    };

    let callback_args = [
        base.map(object_reference_value).unwrap_or(Value::Nil),
        Value::Int(player),
    ];
    let mut value = match call_world_object_own_function(target, "CalcValue", &callback_args) {
        Some(result) => result?.as_c4_int().unwrap_or(0),
        None => calculated_definition_value(&definition, None, player)?.unwrap_or(0),
    };
    let construction = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        context
            .object_scope(target)
            .map(ObjectScopeContext::construction)
            .or_else(|| context.get_world_object(target).map(|object| object.construction()))
    });
    let Some(construction) = construction else {
        return Ok(Value::Nil);
    };
    value = value.wrapping_mul(construction) / crate::FULL_CON;

    if let Some(base) = base {
        if let Some(result) = call_world_object_own_function(
            base,
            "CalcSellValue",
            &[object_reference_value(target), Value::Int(value)],
        ) {
            value = result?.as_c4_int().unwrap_or(0);
        }
    }
    Ok(Value::Int(value))
}

/// FnGetDefCoreVal (C4Script.cpp:4170-4180): DefCore reflection. The hot
/// entries real content reads resolve from the definition metadata
/// (Width/Height/Offset from the Shape rect, Value, Mass); anything else
/// is nil with a debug note (PORT_STATUS).
fn get_def_core_val(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(entry) = parse_optional_string(args.first(), "GetDefCoreVal", "entry")? else {
        return Ok(Value::Nil);
    };
    let section = parse_optional_string(args.get(1), "GetDefCoreVal", "section")?
        .filter(|section| !section.is_empty());
    let requested = parse_definition_argument(args.get(2), "GetDefCoreVal")?;
    let entry_index = parse_optional_i32(args.get(3), "GetDefCoreVal", "entry_nr")?.unwrap_or(0);
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let definition_id = match requested {
            Some(id) => Some(id),
            // `if (!idDef && cthr->Def) idDef = cthr->Def->id` — the
            // executing function's definition, even without an object.
            None => context
                .current_definition_id()
                .map(|definition| definition.to_string()),
        };
        let Some(definition_id) = definition_id else {
            return Ok(Value::Nil);
        };
        let Some(metadata) = context
            .world
            .definition_metadata(&DefinitionId::from(definition_id.as_str()))
        else {
            return Ok(Value::Nil);
        };
        if section.as_deref().is_some_and(|section| section != "DefCore") {
            return Ok(Value::Nil);
        }
        let shape = metadata.shape.unwrap_or(DefinitionRect::new(0, 0, 0, 0));
        if entry == "Offset" {
            return Ok(match entry_index {
                0 => Value::Int(shape.x),
                1 => Value::Int(shape.y),
                _ => Value::Nil,
            });
        }
        if entry_index != 0 {
            return Ok(Value::Nil);
        }
        Ok(match entry.as_str() {
            "Width" => Value::Int(shape.width),
            "Height" => Value::Int(shape.height),
            "CollectionLimit" => Value::Int(metadata.collection_limit),
            "GrabPutGet" => Value::Int(metadata.grab_put_get),
            "FireTop" => Value::Int(metadata.fire.fire_top),
            "LiftTop" => Value::Int(metadata.fire.lift_top),
            "Value" => Value::Int(metadata.value),
            "Mass" => Value::Int(metadata.mass),
            // C4Def::CompileFunc's line bitfields (C4Def.cpp:333-351).
            "Line" => Value::Int(metadata.line),
            "LineConnect" => Value::Int(metadata.line_connect as i32),
            // The blast-chain entries System.c4g reads through the GetXVal
            // wrappers (GetDefGrab/GetDefHorizontalFix/GetDefContainBlast,
            // BlastObjectsShockwaveCheck + DoExplosion).
            "Grab" => Value::Int(metadata.fire.grab),
            "HorizontalFix" => Value::Int(metadata.fire.no_horizontal_move),
            "ContainBlast" => Value::Int(metadata.fire.contain_blast),
            "BlastIncinerate" => Value::Int(metadata.fire.blast_incinerate),
            "ContactIncinerate" => Value::Int(metadata.fire.contact_incinerate),
            other => {
                tracing::debug!(entry = other, "GetDefCoreVal entry not modeled; nil");
                Value::Nil
            }
        })
    })
}

/// FnGetLeague (C4Script.cpp:3562-3568): the indexed league section of
/// Game.Parameters.League — nullptr (nil) when no league is configured,
/// which is every local game. League play itself is not modeled
/// (PORT_STATUS).
fn get_league(args: &[Value]) -> Result<Value, RuntimeError> {
    let _index = value_to_i32(args.first().unwrap_or(&Value::Nil), "GetLeague", "index")?;
    Ok(Value::Nil)
}

/// FnGetScenarioVal (C4Script.cpp:4244-4250): exact StdCompiler reflection
/// over the retained, post-load `Game.C4S`. `entry_nr` counts primitive
/// callbacks inside the matched named value: C4SVal is Std/Rnd/Min/Max and
/// ID lists are ID/count pairs (C4Script.cpp:3997-4006).
fn get_scenario_val(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some(entry) = parse_optional_string(args.first(), "GetScenarioVal", "entry")? else {
        return Ok(Value::Nil);
    };
    let section = parse_optional_string(args.get(1), "GetScenarioVal", "section")?
        .filter(|section| !section.is_empty());
    let entry_index = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "GetScenarioVal",
        "entry_nr",
    )?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        if let Some(value) =
            context
                .world
                .scenario_value(entry.as_str(), section.as_deref(), entry_index)
        {
            return Ok(match value {
                ScenarioValue::Int(value) => Value::Int(*value),
                ScenarioValue::Bool(value) => Value::Bool(*value),
                ScenarioValue::String(value) => Value::String(value.clone()),
                // C4Value(C4ID_None) has C4V_Any type, i.e. nil rather than
                // a typed zero ID (C4Value.h:113,306).
                ScenarioValue::C4Id(value) if value.is_empty() => Value::Nil,
                ScenarioValue::C4Id(value) => Value::C4Id(value.clone()),
            });
        }
        tracing::debug!(
            entry = entry.as_str(),
            section = section.as_deref().unwrap_or(""),
            entry_index,
            "GetScenarioVal entry not found; nil"
        );
        Ok(Value::Nil)
    })
}

/// `FnLoadScenarioSection` (C4Script.cpp:5401-5408): reject a null/empty
/// name, resolve the section case-insensitively, and hand the engine an
/// ordered request. C++ removes every active object but deliberately keeps
/// inactive objects, so their effective identities travel with the request.
fn load_scenario_section(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "LoadScenarioSection expects at most 2 arguments: name, flags",
        ));
    }
    let Some(name) = parse_optional_string(args.first(), "LoadScenarioSection", "name")? else {
        return Ok(Value::Int(0));
    };
    if name.is_empty() {
        return Ok(Value::Int(0));
    }
    let flags = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "LoadScenarioSection",
        "flags",
    )?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Int(0));
        };
        if !context.world.scenario_section_known(&name) {
            return Ok(Value::Int(0));
        }
        let preserve_ids = context
            .world_object_ids()
            .into_iter()
            .filter(|id| {
                context
                    .get_world_object(*id)
                    .is_some_and(|object| object.status() == ObjectStatus::Inactive)
            })
            .collect();
        context.record_player_command(PlayerCommand::LoadScenarioSection {
            name,
            flags,
            preserve_ids,
        });
        Ok(Value::Int(1))
    })
}

fn get_hi_rank(args: &[Value]) -> Result<Value, RuntimeError> {
    // FnGetHiRank (C4Script.cpp:2792-2796) ->
    // C4Player::GetHiRankActiveCrew(false) (C4Player.cpp:1003-1020): walk
    // the crew in order, rank from the linked Info (no info = -1); only a
    // strictly higher rank replaces, so the first of equal ranks wins.
    let player_id = value_to_i32(args.first().unwrap_or(&Value::Nil), "GetHiRank", "player")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(player) = context.player_state(player_id) else {
            return Ok(Value::Nil);
        };
        let mut best: Option<(u64, i32)> = None;
        for crew_id in &player.crew {
            if context.object_crew_disabled(*crew_id).unwrap_or(false) {
                continue;
            }
            let rank = match context.object_scope(*crew_id) {
                Some(scope) => scope.info_rank(),
                None => context.world.crew_rank(crew_id.as_u64()),
            }
            .unwrap_or(-1);
            match best {
                Some((_, best_rank)) if best_rank >= rank => {}
                _ => best = Some((crew_id.as_u64(), rank)),
            }
        }
        Ok(best
            .map(|(id, _)| object_reference_value(ObjectId::new(id)))
            .unwrap_or(Value::Nil))
    })
}

/// FnGetRank (C4Script.cpp:1378-1383): read the linked C4ObjectInfo rank.
/// A null object defaults to the executing object; objects without Info and
/// global calls without an object return nil.
fn get_rank(args: &[Value]) -> Result<Value, RuntimeError> {
    let target = args
        .first()
        .map(|value| parse_object_reference_argument(value, "GetRank", "obj"))
        .transpose()?
        .flatten();
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(target) = target.or_else(|| context.object_context().map(|object| object.id()))
        else {
            return Ok(Value::Nil);
        };
        let rank = match context.object_scope(target) {
            Some(scope) => scope.info_rank(),
            None => context.world.crew_rank(target.as_u64()),
        };
        Ok(rank.map(Value::Int).unwrap_or(Value::Nil))
    })
}

fn get_crew(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "GetCrew expects at most 2 arguments: player and index",
        ));
    }
    // Unfilled iPlr/index slots are nil -> 0 (FnGetCrew, C4Script.cpp:2798);
    // SkiesOfFire's InitializePlayer calls GetCrew(iPlr) with no index.
    let player_id = value_to_i32(args.first().unwrap_or(&Value::Nil), "GetCrew", "player")?;
    let index = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "GetCrew", "index")?;
    if index < 0 {
        return Ok(Value::Nil);
    }
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(player) = context.player_state(player_id) else {
            return Ok(Value::Nil);
        };
        let idx = index as usize;
        let Some(crew_id) = player.crew.get(idx) else {
            return Ok(Value::Nil);
        };
        Ok(object_reference_value(ObjectId::new(crew_id.as_u64())))
    })
}

