#[derive(Debug, Clone, Default, PartialEq, Eq)]
#[doc(hidden)]
pub struct PhysicsDelta {
    pub gravity: Option<i32>,
}

impl PhysicsDelta {
    pub fn is_empty(&self) -> bool {
        self.gravity.is_none()
    }

    pub fn apply(&self, physics: &mut PhysicsSettings) {
        if let Some(gravity) = self.gravity {
            physics.gravity = gravity.clamp(-300, 300);
        }
    }
}

#[derive(Debug)]
struct PhysicsContext {
    settings: RefCell<PhysicsSettings>,
    pending: RefCell<PhysicsDelta>,
}

impl PhysicsContext {
    fn new(settings: PhysicsSettings) -> Self {
        Self {
            settings: RefCell::new(settings),
            pending: RefCell::new(PhysicsDelta::default()),
        }
    }

    fn set_gravity(&self, gravity: i32) {
        let clamped = gravity.clamp(-300, 300);
        self.settings.borrow_mut().gravity = clamped;
        self.pending.borrow_mut().gravity = Some(clamped);
    }

    fn gravity(&self) -> i32 {
        self.settings.borrow().gravity
    }

    fn into_delta(self) -> PhysicsDelta {
        self.pending.into_inner()
    }
}

pub(crate) struct PhysicsContextGuard {
    context: Option<Rc<PhysicsContext>>,
}

impl PhysicsContextGuard {
    pub fn finish(mut self) -> PhysicsDelta {
        let context = self
            .context
            .take()
            .expect("physics context already consumed");
        PHYSICS_CONTEXT.with(|cell| {
            let stored = cell
                .borrow_mut()
                .take()
                .expect("physics context must be present");
            debug_assert!(Rc::ptr_eq(&stored, &context));
        });
        Rc::try_unwrap(context)
            .expect("physics context still referenced")
            .into_delta()
    }
}

impl Drop for PhysicsContextGuard {
    fn drop(&mut self) {
        if self.context.is_some() {
            PHYSICS_CONTEXT.with(|cell| {
                cell.borrow_mut().take();
            });
        }
    }
}

pub(crate) fn enter_physics_context(settings: PhysicsSettings) -> PhysicsContextGuard {
    PHYSICS_CONTEXT.with(|cell| {
        assert!(
            cell.borrow().is_none(),
            "nested physics contexts are not supported",
        );
        let context = Rc::new(PhysicsContext::new(settings));
        *cell.borrow_mut() = Some(context.clone());
        PhysicsContextGuard {
            context: Some(context),
        }
    })
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
#[doc(hidden)]
pub struct EnvironmentDelta {
    pub wind: Option<i32>,
    pub temperature: Option<i32>,
    pub climate: Option<i32>,
    pub season: Option<i32>,
    pub(crate) season_gamma_handled: bool,
}

impl EnvironmentDelta {
    pub(crate) fn is_empty(&self) -> bool {
        self.wind.is_none()
            && self.temperature.is_none()
            && self.climate.is_none()
            && self.season.is_none()
    }

    pub(crate) fn requests_season_gamma_refresh(&self) -> bool {
        !self.season_gamma_handled
            && (self.temperature.is_some() || self.climate.is_some() || self.season.is_some())
    }

    pub fn apply(&self, environment: &mut EnvironmentSettings) {
        if let Some(wind) = self.wind {
            environment.wind = wind.clamp(-100, 100);
        }
        if let Some(temperature) = self.temperature {
            environment.temperature = temperature.clamp(-100, 100);
        }
        if let Some(climate) = self.climate {
            environment.climate = climate.clamp(-50, 50);
        }
        if let Some(season) = self.season {
            // C4Weather::SetSeason (C4Weather.cpp:229-233): BoundBy 0..100.
            environment.season = season.clamp(0, 100);
        }
    }
}

#[derive(Debug)]
struct EnvironmentContext {
    settings: RefCell<EnvironmentSettings>,
    frame: u64,
    pending: RefCell<EnvironmentDelta>,
}

impl EnvironmentContext {
    fn new(settings: EnvironmentSettings, frame: u64) -> Self {
        Self {
            settings: RefCell::new(settings),
            frame,
            pending: RefCell::new(EnvironmentDelta::default()),
        }
    }

    fn set_wind(&self, wind: i32) {
        let clamped = wind.clamp(-100, 100);
        self.settings.borrow_mut().wind = clamped;
        self.pending.borrow_mut().wind = Some(clamped);
    }

    fn wind_force(&self) -> i32 {
        let settings = self.settings.borrow();
        settings.wind_force(self.frame)
    }

    fn set_temperature(&self, temperature: i32) {
        let clamped = temperature.clamp(-100, 100);
        self.settings.borrow_mut().temperature = clamped;
        self.pending.borrow_mut().temperature = Some(clamped);
        self.queue_season_gamma_control();
    }

    /// C4Weather::GetTemperature returns the mutable Weather.Temperature
    /// field verbatim (C4Weather.cpp:173-176). Climate only influences that
    /// field during Init/Execute; it is not added again at script read time.
    fn temperature(&self) -> i32 {
        self.settings.borrow().temperature
    }

    fn set_climate(&self, climate: i32) {
        let clamped = climate.clamp(-50, 50);
        self.settings.borrow_mut().climate = clamped;
        self.pending.borrow_mut().climate = Some(clamped);
        self.queue_season_gamma_control();
    }

    fn climate(&self) -> i32 {
        self.settings.borrow().climate
    }

    /// C4Weather::SetSeason (C4Weather.cpp:229-233): BoundBy(iSeason, 0,
    /// 100), then SetSeasonGamma immediately. Queueing the gamma operation
    /// here preserves its order relative to an explicit SetGamma call in
    /// the same callback.
    fn set_season(&self, season: i32) {
        let clamped = season.clamp(0, 100);
        self.settings.borrow_mut().season = clamped;
        self.pending.borrow_mut().season = Some(clamped);
        self.queue_season_gamma_control();
    }

    fn queue_season_gamma_control(&self) {
        let points = self.settings.borrow().season_gamma_control_points();
        let handled = points.is_none_or(|points| {
            HOST_CONTEXT.with(|cell| {
                cell.borrow_mut().as_mut().is_some_and(|context| {
                    context.register_landscape_operation(LandscapeOperation::GammaRamp {
                        index: 1,
                        points,
                    });
                    true
                })
            })
        });
        self.pending.borrow_mut().season_gamma_handled = handled;
    }

    fn season(&self) -> i32 {
        self.settings.borrow().season
    }

    fn into_delta(self) -> EnvironmentDelta {
        self.pending.into_inner()
    }
}

pub(crate) struct EnvironmentContextGuard {
    context: Option<Rc<EnvironmentContext>>,
}

impl EnvironmentContextGuard {
    pub fn finish(mut self) -> EnvironmentDelta {
        let context = self
            .context
            .take()
            .expect("environment context already consumed");
        ENVIRONMENT_CONTEXT.with(|cell| {
            let stored = cell
                .borrow_mut()
                .take()
                .expect("environment context must be present");
            debug_assert!(Rc::ptr_eq(&stored, &context));
        });
        Rc::try_unwrap(context)
            .expect("environment context still referenced")
            .into_delta()
    }
}

impl Drop for EnvironmentContextGuard {
    fn drop(&mut self) {
        if self.context.is_some() {
            ENVIRONMENT_CONTEXT.with(|cell| {
                cell.borrow_mut().take();
            });
        }
    }
}

pub(crate) fn enter_environment_context(
    settings: EnvironmentSettings,
    frame: u64,
) -> EnvironmentContextGuard {
    ENVIRONMENT_CONTEXT.with(|cell| {
        assert!(
            cell.borrow().is_none(),
            "nested environment contexts are not supported",
        );
        let context = Rc::new(EnvironmentContext::new(settings, frame));
        *cell.borrow_mut() = Some(context.clone());
        EnvironmentContextGuard {
            context: Some(context),
        }
    })
}

#[allow(dead_code)]
pub(crate) fn with_effect_context<F, T, E>(
    object: Option<HostObjectContext<'_>>,
    global_effects: &[EffectState],
    world: HostWorldContext,
    next_object_id: u64,
    func: F,
) -> (Result<T, E>, EffectContextOutcome)
where
    F: FnOnce() -> Result<T, E>,
    E: From<RuntimeError>,
{
    with_effect_context_with_state(object, global_effects, world, next_object_id, false, func)
}

pub(crate) fn with_effect_context_with_state<F, T, E>(
    object: Option<HostObjectContext<'_>>,
    global_effects: &[EffectState],
    world: HostWorldContext,
    next_object_id: u64,
    game_over_triggered: bool,
    func: F,
) -> (Result<T, E>, EffectContextOutcome)
where
    F: FnOnce() -> Result<T, E>,
    E: From<RuntimeError>,
{
    let script_object_context = object.as_ref().map(|object| object.id);
    with_effect_context_with_definition_state(
        object,
        None,
        script_object_context,
        global_effects,
        world,
        next_object_id,
        game_over_triggered,
        func,
    )
}

pub(crate) fn with_effect_context_with_state_and_definition<F, T, E>(
    object: Option<HostObjectContext<'_>>,
    definition_context: Option<DefinitionId>,
    script_object_context: Option<ObjectId>,
    global_effects: &[EffectState],
    world: HostWorldContext,
    next_object_id: u64,
    game_over_triggered: bool,
    func: F,
) -> (Result<T, E>, EffectContextOutcome)
where
    F: FnOnce() -> Result<T, E>,
    E: From<RuntimeError>,
{
    with_effect_context_with_definition_state(
        object,
        definition_context,
        script_object_context,
        global_effects,
        world,
        next_object_id,
        game_over_triggered,
        func,
    )
}

pub(crate) fn with_definition_effect_context_with_state<F, T, E>(
    definition_context: DefinitionId,
    global_effects: &[EffectState],
    world: HostWorldContext,
    next_object_id: u64,
    game_over_triggered: bool,
    func: F,
) -> (Result<T, E>, EffectContextOutcome)
where
    F: FnOnce() -> Result<T, E>,
    E: From<RuntimeError>,
{
    with_effect_context_with_definition_state(
        None,
        Some(definition_context),
        None,
        global_effects,
        world,
        next_object_id,
        game_over_triggered,
        func,
    )
}

fn with_effect_context_with_definition_state<F, T, E>(
    object: Option<HostObjectContext<'_>>,
    definition_context: Option<DefinitionId>,
    script_object_context: Option<ObjectId>,
    global_effects: &[EffectState],
    world: HostWorldContext,
    next_object_id: u64,
    game_over_triggered: bool,
    func: F,
) -> (Result<T, E>, EffectContextOutcome)
where
    F: FnOnce() -> Result<T, E>,
    E: From<RuntimeError>,
{
    let audio_state = AUDIO_CONTEXT
        .with(|cell| cell.borrow_mut().take())
        .unwrap_or_default();
    HOST_CONTEXT.with(|cell| {
        assert!(
            cell.borrow().is_none(),
            "nested effect contexts are not supported"
        );
        *cell.borrow_mut() = Some(EffectHostContext::new(
            object,
            definition_context,
            script_object_context,
            global_effects.to_vec(),
            world,
            next_object_id,
            audio_state,
            game_over_triggered,
        ));
        let mut result = func();
        let context = cell
            .borrow_mut()
            .take()
            .expect("effect context must be present");
        // Nested engine callbacks deliberately use C4Script's fail-safe
        // policy and may turn an ordinary VM error into nil/false. The
        // SetPreSend network path is different: it reached authoritative
        // runtime state that this engine cannot represent. Preserve that
        // fatal marker across every nested warn-and-continue funnel and
        // surface it at the outer script-call boundary.
        if context.runtime_flash_boundary {
            result = Err(RuntimeError::new(SET_PRE_SEND_RUNTIME_BOUNDARY).into());
        }
        let outcome = context.into_commands();
        AUDIO_CONTEXT.with(|cell| {
            *cell.borrow_mut() = Some(outcome.audio.state.clone());
        });
        (result, outcome)
    })
}

#[derive(Debug, Clone)]
#[doc(hidden)]
pub enum LandscapeOperation {
    DigCircle {
        center: Vector2,
        radius: i32,
        requested: bool,
        by_object: Option<ObjectId>,
    },
    DigRect {
        origin: Vector2,
        width: i32,
        height: i32,
        requested: bool,
        by_object: Option<ObjectId>,
    },
    /// FnFreeRect -> Landscape::ClearRect (C4Script.cpp:3125-3131): the
    /// rect clears outright — no dug-out material, no PXS.
    ClearRect {
        origin: Vector2,
        width: i32,
        height: i32,
    },
    /// FnFreeRect's nonzero iFreeDensity arm ->
    /// C4Landscape::ClearRectDensity (C4Script.cpp:3119-3125).
    ClearRectDensity {
        origin: Vector2,
        width: i32,
        height: i32,
        density: i32,
    },
    /// `C4Game::CreateObjectConstruction(..., fTerrain=true)` prepares the
    /// footprint before `NewObject` and its Construction callback
    /// (C4Game.cpp:1191-1230).
    PrepareConstructionTerrain {
        center_x: i32,
        bottom_y: i32,
        width: i32,
        height: i32,
        basement: i32,
    },
    /// FnDrawMaterialQuad -> C4Landscape::DrawQuad
    /// (C4Script.cpp:5111-5115; C4Landscape.cpp:2448-2468).
    DrawMaterialQuad {
        material_texture: String,
        vertices: [Vector2; 4],
        ift: bool,
    },
    /// FnDrawMap -> C4Landscape::DrawMap/MapToLandscape
    /// (C4Script.cpp:4851-4855; C4Landscape.cpp:2636-2668,482-510).
    /// The callback already rendered these exact indexed bytes through the
    /// live synced RNG; the engine fold must not parse or draw RNG again.
    DrawMap {
        origin: Vector2,
        bitmap: lc_resources::bitmap::IndexedBitmap,
        map_width: i32,
        map_height: i32,
        texmap: crate::landscape::RuntimeTexMapState,
    },
    /// DrawMap parsing can allocate a live TextureMap entry before
    /// Render(nullptr) finds no map. C++ retains that allocation despite the
    /// false DrawMap result (C4Landscape.cpp:2659-2663; C4Texture.cpp:319-369).
    SyncRuntimeTexMap {
        texmap: crate::landscape::RuntimeTexMapState,
    },
    BlastCircle {
        center: Vector2,
        radius: i32,
        controller: Option<i32>,
    },
    ShakeCircle {
        center: Vector2,
        radius: i32,
    },
    /// FnInsertMaterial -> Landscape::InsertMaterial
    /// (C4Script.cpp:2207-2211): caller-relative coordinates, material by
    /// number.
    InsertMaterial {
        material: i32,
        position: Vector2,
        velocity: Vector2,
    },
    /// FnExtractLiquid -> Landscape::ExtractMaterial after a GBackLiquid
    /// guard (C4Script.cpp:2194-2199).
    ExtractLiquid { position: Vector2 },
    /// FnCastPXS samples its synced velocities during the script call, then
    /// the engine fold inserts them into the real C4PXSSystem in call order.
    CastPxs {
        material: crate::MaterialId,
        position: Vector2,
        velocities: Vec<FixedVec2>,
    },
    /// FnExtractMaterialAmount (C4Script.cpp:2264-2273): the count was
    /// simulated at call time; the apply reruns the REAL loop.
    ExtractMaterialAmount {
        material: i32,
        position: Vector2,
        amount: i32,
    },
    /// FnSetGamma/FnResetGamma -> C4GraphicsSystem::SetGamma
    /// (C4Script.cpp:4998-5006; C4GraphicsSystem.cpp:772-784). Gamma is
    /// presentation-only, but this existing ordered global-operation channel
    /// preserves callback write order without making it sync-relevant.
    GammaRamp { index: i32, points: [u32; 3] },
    /// FnSetSkyAdjust (C4Script.cpp:4620-4624) -> C4Sky::SetModulation
    /// (C4Sky.cpp:238-244).
    SkyAdjust { modulation: u32, back_color: u32 },
    /// FnSetMatAdjust (C4Script.cpp:4626-4630) ->
    /// C4Landscape::SetModulation.
    MatAdjust { modulation: u32 },
    /// FnSetLandscapePixel (C4Script.cpp:5082-5088): a direct packed-color
    /// write into the presentation-only Surface32.
    SetLandscapePixel { position: Vector2, color: u32 },
    /// FnSetSkyParallax (C4Script.cpp:4955-4970) — Sky is a C4Landscape
    /// member; the raw int args carry the SkyPar_KEEP magic through to
    /// `SkyState::apply_parallax`.
    SkyParallax {
        mode: i32,
        par_x: i32,
        par_y: i32,
        xdir: i32,
        ydir: i32,
        x: i32,
        y: i32,
    },
}

/// Script callbacks run against a copied world view, so construction terrain
/// needs a matching live preview in addition to the operation folded into the
/// real engine afterward. This mirrors the pixel mutations relevant to script
/// queries; instability/mass-mover side effects remain on the authoritative
/// `Engine::prepare_construction_terrain` fold.
fn preview_construction_terrain(
    landscape: &mut Landscape,
    materials: &MaterialSet,
    center_x: i32,
    bottom_y: i32,
    width: i32,
    height: i32,
    basement: i32,
) {
    let x = center_x.saturating_sub(width / 2);
    let y = bottom_y.saturating_sub(height);

    if width.saturating_mul(height) < 12_000 {
        if let Some((grid_width, _)) = landscape.grid_dimensions() {
            for column in x..x.saturating_add(width) {
                for row in y..y.saturating_add(height) {
                    let _ = landscape.dig_free_pix(column, row, materials);
                }
            }
            let start = x.max(0).min(grid_width) as usize;
            let end = x.saturating_add(width).max(0).min(grid_width) as usize;
            landscape.refresh_raster_columns(start..end);
        } else {
            for column in x..x.saturating_add(width) {
                let Some(previous_height) = landscape.surface_height(column) else {
                    continue;
                };
                let Some(material_id) = landscape.solid_material_at(column) else {
                    continue;
                };
                if materials
                    .get_by_id(material_id)
                    .is_none_or(|material| !material.dig_free())
                {
                    continue;
                }
                let clamped_bottom = bottom_y.max(0);
                let desired_bottom = if clamped_bottom <= previous_height {
                    if clamped_bottom.saturating_add(1) <= previous_height {
                        continue;
                    }
                    previous_height.saturating_add(1)
                } else {
                    clamped_bottom
                };
                landscape.ensure_surface_at_least(column, desired_bottom);
            }
        }
    }

    let vehicle = materials.id_of("Vehicle");
    if let Some((grid_width, grid_height)) = landscape.grid_dimensions() {
        for column in x..x.saturating_add(width) {
            let mut target_y = bottom_y;
            while target_y + 1 < grid_height
                && landscape.density_at(column, target_y + 1, materials) < crate::C4M_SOLID
            {
                target_y += 1;
            }
            if target_y + 1 >= grid_height || target_y - bottom_y >= 20 {
                continue;
            }
            let Some(pixel) = landscape.grid_byte_at(column, target_y + 1) else {
                continue;
            };
            if vehicle.is_some_and(|vehicle| {
                landscape.border_material_at(column, target_y + 1) == Some(vehicle)
            }) {
                continue;
            }
            while target_y >= bottom_y {
                landscape.grid_set_byte(column, target_y, pixel);
                target_y -= 1;
            }
        }
        let start = x.max(0).min(grid_width) as usize;
        let end = x.saturating_add(width).max(0).min(grid_width) as usize;
        landscape.refresh_raster_columns(start..end);
    } else {
        for column in x..x.saturating_add(width) {
            let Ok(column_index) = u32::try_from(column) else {
                continue;
            };
            let Some(surface) = landscape.surface_height(column) else {
                continue;
            };
            if surface.saturating_sub(1).saturating_sub(bottom_y) < 20 {
                landscape.set_height(column_index, bottom_y);
            }
        }
    }

    let Some(granite) = materials.id_of("Granite") else {
        return;
    };
    let draw_rect = |landscape: &mut Landscape, x: i32, width: i32| {
        let Some(granite_definition) = materials.get_by_id(granite) else {
            return;
        };
        let granite_density = granite_definition.density();
        let granite_dig_free = i32::from(granite_definition.dig_free());
        for row in bottom_y..bottom_y.saturating_add(8) {
            for column in x..x.saturating_add(width) {
                let current_density = landscape.density_at(column, row, materials);
                let current_dig_free = landscape
                    .border_material_at(column, row)
                    .and_then(|material| materials.get_by_id(material))
                    .map(|material| i32::from(material.dig_free()))
                    .unwrap_or(1);
                if granite_density > current_density
                    || (granite_density == current_density
                        && granite_dig_free <= current_dig_free)
                {
                    let _ = landscape.insert_material_pix(column, row, granite);
                }
            }
        }
    };
    if basement > 1 {
        let border_width = basement.min(width);
        draw_rect(landscape, x, border_width);
        draw_rect(
            landscape,
            x.saturating_add(width).saturating_sub(border_width),
            border_width,
        );
    } else if basement != 0 {
        draw_rect(landscape, x, width);
    }
}

/// Side effects a nested script call (Find_Func/GameCall reentrancy) made to
/// an object other than the outer call's `this`. Folded out of the nested
/// scope in first-call order; the engine applies them after the outer
/// object's update.
#[derive(Debug, Clone)]
pub struct NestedObjectOutcome {
    pub object_id: ObjectId,
    pub effects: Vec<EffectCommand>,
    pub update: Option<ObjectUpdate>,
    pub commands: Vec<QueuedCommand>,
    pub command_operations: Vec<CommandOperation>,
    pub destroy: bool,
    /// A staged C4Object::AssignDeath request from script Kill. `Some(false)`
    /// is distinct from no request; `true` bypasses effect revival.
    pub assign_death: Option<bool>,
}

#[derive(Debug, Clone)]
#[doc(hidden)]
pub struct EffectContextOutcome {
    pub object: Vec<EffectCommand>,
    pub global: Vec<EffectCommand>,
    pub object_update: Option<ObjectUpdate>,
    pub object_commands: Vec<QueuedCommand>,
    pub command_operations: Vec<CommandOperation>,
    /// Events produced by a synchronous FnExecuteCommand step. C++ applies
    /// these before FnExecuteCommand returns (C4Script.cpp:922-929), so the
    /// engine folds them with this callback rather than the next object tick.
    pub command_events: Vec<CommandEvent>,
    pub destroy_object: bool,
    /// Mutations nested script calls made to other objects, in first-call
    /// order. C++ mutates live state during the call; the copy-in/copy-out
    /// architecture applies them when the outer call commits.
    pub other_objects: Vec<NestedObjectOutcome>,
    pub environment: Option<EnvironmentDelta>,
    pub physics: Option<PhysicsDelta>,
    pub spawns: Vec<SpawnConfig>,
    pub landscape: Vec<LandscapeOperation>,
    pub particles: Vec<ParticleCommand>,
    pub transfer_zones: Vec<TransferZoneCommand>,
    pub messages: Vec<MessageCommand>,
    pub player_commands: Vec<PlayerCommand>,
    pub object_order_commands: Vec<ObjectOrderCommand>,
    pub next_mission_commands: Vec<NextMissionCommand>,
    pub menu_requests: Vec<crate::MenuRequest>,
    pub audio: AudioOutcome,
    pub trigger_game_over: bool,
    pub script_go: Option<bool>,
    /// Last synchronous write to `Game.Script.Counter` made during this VM
    /// call. The engine folds it even when the call subsequently errors.
    pub script_counter: Option<i32>,
    pub next_object_id: u64,
    /// VM-final locals of an effect callback that ran in its command
    /// target's own context (pFn->Exec(pCommandTarget, ...),
    /// C4Effect.cpp:129): the dispatch layer records them, the effect
    /// event loop persists them onto the object.
    pub context_locals: Option<HashMap<String, Value>>,
}

impl EffectContextOutcome {
    fn new(
        object: Vec<EffectCommand>,
        global: Vec<EffectCommand>,
        object_update: Option<ObjectUpdate>,
        object_commands: Vec<QueuedCommand>,
        command_operations: Vec<CommandOperation>,
        destroy_object: bool,
        environment: Option<EnvironmentDelta>,
        physics: Option<PhysicsDelta>,
        spawns: Vec<SpawnConfig>,
        landscape: Vec<LandscapeOperation>,
        transfer_zones: Vec<TransferZoneCommand>,
        messages: Vec<MessageCommand>,
        player_commands: Vec<PlayerCommand>,
        object_order_commands: Vec<ObjectOrderCommand>,
        audio: AudioOutcome,
        trigger_game_over: bool,
        script_go: Option<bool>,
        script_counter: Option<i32>,
        next_object_id: u64,
    ) -> Self {
        Self {
            object,
            global,
            object_update,
            object_commands,
            command_operations,
            command_events: Vec::new(),
            destroy_object,
            other_objects: Vec::new(),
            environment,
            physics,
            spawns,
            landscape,
            particles: Vec::new(),
            transfer_zones,
            messages,
            player_commands,
            object_order_commands,
            next_mission_commands: Vec::new(),
            menu_requests: Vec::new(),
            audio,
            trigger_game_over,
            script_go,
            script_counter,
            next_object_id,
            context_locals: None,
        }
    }

    pub(crate) fn empty(next_object_id: u64, audio: AudioRegistry) -> Self {
        Self {
            object: Vec::new(),
            global: Vec::new(),
            object_update: None,
            object_commands: Vec::new(),
            command_operations: Vec::new(),
            command_events: Vec::new(),
            destroy_object: false,
            other_objects: Vec::new(),
            environment: None,
            physics: None,
            spawns: Vec::new(),
            landscape: Vec::new(),
            particles: Vec::new(),
            transfer_zones: Vec::new(),
            messages: Vec::new(),
            player_commands: Vec::new(),
            object_order_commands: Vec::new(),
            next_mission_commands: Vec::new(),
            menu_requests: Vec::new(),
            audio: AudioOutcome {
                state: audio,
                events: Vec::new(),
            },
            trigger_game_over: false,
            script_go: None,
            script_counter: None,
            next_object_id,
            context_locals: None,
        }
    }
}

#[derive(Copy, Clone, Debug, PartialEq, Eq)]
enum EffectScope {
    Object(Option<ObjectId>),
    Global,
}

#[derive(Debug)]
struct RandomContext {
    rng: RefCell<LcgRng>,
}

impl RandomContext {
    fn into_rng(self) -> LcgRng {
        self.rng.into_inner()
    }
}

pub(crate) struct RandomContextGuard {
    context: Option<Rc<RandomContext>>,
}

impl RandomContextGuard {
    pub fn finish(mut self) -> LcgRng {
        let context = self
            .context
            .take()
            .expect("random context already consumed");
        RANDOM_CONTEXT.with(|cell| {
            let stored = cell
                .borrow_mut()
                .take()
                .expect("random context must be present");
            debug_assert!(Rc::ptr_eq(&stored, &context));
        });
        Rc::try_unwrap(context)
            .expect("random context still referenced")
            .into_rng()
    }
}

impl Drop for RandomContextGuard {
    fn drop(&mut self) {
        if self.context.is_some() {
            RANDOM_CONTEXT.with(|cell| {
                cell.borrow_mut().take();
            });
        }
    }
}

/// `SWildcardMatchEx` (C4Strings.cpp:531-562): `*`/`?` wildcard match with
/// backtracking, byte-wise like the C++ char loop.
fn s_wildcard_match_ex(string: &str, wildcard: &str) -> bool {
    let (s, w) = (string.as_bytes(), wildcard.as_bytes());
    let (mut pos, mut wild) = (0usize, 0usize);
    let mut backtrack: Option<(usize, usize)> = None;
    while wild < w.len() || backtrack.is_some() {
        if w.get(wild) == Some(&b'*') {
            wild += 1;
            backtrack = Some((wild, pos));
        } else if pos >= s.len() {
            break;
        } else if w.get(wild) == Some(&b'?') || w.get(wild) == Some(&s[pos]) {
            wild += 1;
            pos += 1;
        } else if let Some((last_wild, last_pos)) = backtrack {
            backtrack = Some((last_wild, last_pos + 1));
            wild = last_wild;
            pos = last_pos + 1;
        } else {
            return false;
        }
    }
    wild >= w.len() && pos >= s.len()
}

/// `FnWildcardMatch` (C4Script.cpp:5606-5609): both params go through
/// `FnStringPar`, which maps nil (and Set0'd falsy pars,
/// C4AulExec.cpp:1370-1374) to `""` (C4Script.cpp:78-81).
fn wildcard_match(args: &[Value]) -> Result<Value, RuntimeError> {
    let string_par = |value: Option<&Value>, par: &str| -> Result<String, RuntimeError> {
        match value {
            Some(Value::String(text)) => Ok(text.clone()),
            Some(Value::Nil) | Some(Value::Int(0)) | Some(Value::Bool(false)) | None => {
                Ok(String::new())
            }
            Some(other) => Err(RuntimeError::new(format!(
                "WildcardMatch: expected string or nil for {par}, got {}",
                other.type_name()
            ))),
        }
    };
    let string = string_par(args.first(), "string")?;
    let wildcard = string_par(args.get(1), "wildcard")?;
    Ok(Value::Int(i32::from(s_wildcard_match_ex(
        &string, &wildcard,
    ))))
}

/// Effect-name parameter shared by AddEffect/RemoveEffect/GetEffect/
/// GetEffectCount: C++ declares it `C4String *`, and pre-#strict-3 callers
/// legally pass falsy values that CheckConvertFunctionParameters Set0()s to
/// nil before conversion (C4AulExec.cpp:1370-1374); the empty string also
/// means "match all" (C4Script.cpp:5561). Truthy non-strings throw in C++.
fn effect_name_filter<'a>(
    function: &str,
    value: &'a Value,
) -> Result<Option<&'a str>, RuntimeError> {
    match value {
        Value::String(name) if !name.is_empty() => Ok(Some(name.as_str())),
        Value::String(_) | Value::Nil | Value::Int(0) | Value::Bool(false) => Ok(None),
        other => Err(RuntimeError::new(format!(
            "{function}: expected string or nil for name, got {}",
            other.type_name()
        ))),
    }
}

/// `SCopy(..., C4MaxName)` in FnChangeEffect copies at most 30 bytes
/// (C4Script.cpp:5534; C4Constants.h:26). Rust strings must remain valid
/// UTF-8, so a split code point retreats to the preceding boundary.
fn truncate_c4_max_name(name: &str) -> String {
    const C4_MAX_NAME: usize = 30;
    let mut end = name.len().min(C4_MAX_NAME);
    while !name.is_char_boundary(end) {
        end -= 1;
    }
    name[..end].to_owned()
}

/// Effect host functions accept ANY object as the state target (the
/// C4Effect operations attach to the GIVEN object, C4Effect.cpp): a
/// foreign target re-dispatches through the reentrancy seam so the
/// effect operation runs in the target's own scope (and folds with its
/// nested outcome). Returns None when the state is not a foreign object
/// — the caller proceeds locally.
fn redirect_foreign_effect_target(
    function: &'static str,
    args: &[Value],
) -> Option<Result<Value, RuntimeError>> {
    let target = match args.get(1) {
        Some(value @ (Value::Object(_) | Value::Proplist(_))) => object_id_from_value(value)?,
        _ => return None,
    };
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    });
    if Some(target) == active {
        return None;
    }
    Some(match call_world_object_function(target, function, args) {
        Some(result) => result,
        None => Ok(Value::Int(0)),
    })
}

/// Runs an effect callback with the fail-safe error policy used by C4Effect's
/// temp/add/stop calls (`fPassErrors=false`). Missing callbacks and script
/// errors both fold to integer zero; the latter are logged.
fn dispatch_effect_fx_callback_fail_safe(
    effect: &EffectState,
    function: &str,
    call_args: &[Value],
) -> i32 {
    match dispatch_effect_fx_callback(
        effect.command_target,
        effect.command_id.as_deref(),
        function,
        call_args,
    ) {
        None => 0,
        Some(Ok(value)) => value_as_i32(&value),
        Some(Err(error)) => {
            tracing::warn!(%error, "script error in {function}; continuing like C++ fail-safe effect dispatch");
            0
        }
    }
}

/// Temp-deactivates an acceptor's active `pNext` effects from high to low,
/// exactly like `C4Effect::TempRemoveUpperEffects` (C4Effect.cpp:473-492).
/// The returned low-to-high list is the matching reactivation order.
fn temp_remove_upper_effects(
    scope: EffectScope,
    target: &Value,
    effects: &[EffectState],
    acceptor_number: i32,
) -> Result<Vec<EffectState>, RuntimeError> {
    let Some(acceptor_index) = effects
        .iter()
        .position(|effect| effect.number == acceptor_number)
    else {
        return Ok(Vec::new());
    };
    if effects[acceptor_index].priority == 1 {
        return Ok(Vec::new());
    }
    let uppers: Vec<EffectState> = effects
        .iter()
        .skip(acceptor_index + 1)
        .filter(|effect| effect.priority > 0 && effect.priority != 1)
        .cloned()
        .collect();
    for upper in uppers.iter().rev() {
        // FlipActive happens before Fx*Stop, so nested effect queries see the
        // temporary negative priority just as they do in C++.
        let flipped = with_context_mut(scope, |ctx| {
            let Some(effect) = ctx
                .effects
                .iter_mut()
                .find(|effect| effect.number == upper.number && effect.priority > 0)
            else {
                return false;
            };
            effect.priority = -effect.priority;
            let updated = effect.clone();
            ctx.commands.push(EffectCommand::update(updated));
            true
        })?;
        if flipped {
            let function = format!("Fx{}Stop", upper.name);
            dispatch_effect_fx_callback_fail_safe(
                upper,
                &function,
                &[
                    target.clone(),
                    Value::Int(upper.number),
                    Value::Int(1),
                    Value::Bool(true),
                ],
            );
        }
    }
    Ok(uppers)
}

fn temp_readd_upper_effects(
    scope: EffectScope,
    target: &Value,
    uppers: &[EffectState],
) -> Result<(), RuntimeError> {
    for upper in uppers {
        // C++ flips the effect active before its temp Start callback.
        let flipped = with_context_mut(scope, |ctx| {
            let Some(effect) = ctx
                .effects
                .iter_mut()
                .find(|effect| effect.number == upper.number && effect.priority < 0)
            else {
                return false;
            };
            effect.priority = -effect.priority;
            let updated = effect.clone();
            ctx.commands.push(EffectCommand::update(updated));
            true
        })?;
        if flipped {
            let function = format!("Fx{}Start", upper.name);
            dispatch_effect_fx_callback_fail_safe(
                upper,
                &function,
                &[target.clone(), Value::Int(upper.number), Value::Int(1)],
            );
        }
    }
    Ok(())
}

/// `C4Effect::Kill` for an effect that was resolved from the live host
/// context (C4Effect.cpp:365-405). The node stays linked and dead while its
/// Stop callback runs, so same-call queries and EffectVar writes see the C++
/// state. An accepted removal is materialized later without dispatching a
/// second Stop; a denial restores this exact node and its callback writes.
fn kill_effect_inline(
    scope: EffectScope,
    target: &Value,
    victim: &EffectState,
) -> Result<(), RuntimeError> {
    let uppers = if victim.priority > 0 {
        let effects = snapshot_effects_from_context(scope).unwrap_or_default();
        temp_remove_upper_effects(scope, target, &effects, victim.number)?
    } else {
        // An inactive victim first receives Fx*Start(iTemp=2) in C++.
        // That distinct legacy case is tracked separately; it never runs
        // the active victim's upper-effect bracket.
        Vec::new()
    };

    let marked_dead = with_context_mut(scope, |ctx| {
        let (previous_priority, updated) = {
            let effect = ctx
                .effects
                .iter_mut()
                .find(|effect| effect.number == victim.number && effect.priority != 0)?;
            let previous_priority = effect.priority;
            effect.priority = 0;
            (previous_priority, effect.clone())
        };
        ctx.commands.push(EffectCommand::update(updated.clone()));
        Some((previous_priority, updated))
    })?;

    if let Some((previous_priority, stopped)) = marked_dead {
        let function = format!("Fx{}Stop", stopped.name);
        let stop_result = dispatch_effect_fx_callback_fail_safe(
            &stopped,
            &function,
            &[target.clone(), Value::Int(stopped.number)],
        );
        if stop_result == -1 {
            with_context_mut(scope, |ctx| {
                let updated = {
                    let Some(effect) = ctx
                        .effects
                        .iter_mut()
                        .find(|effect| effect.number == stopped.number && effect.priority == 0)
                    else {
                        return;
                    };
                    effect.priority = previous_priority;
                    effect.clone()
                };
                // This final update also carries EffectVar writes made by
                // Fx*Stop while the node was dead.
                ctx.commands.push(EffectCommand::update(updated));
            })?;
        } else {
            with_context_mut(scope, |ctx| {
                // Fx*Stop already ran above. Remove by effect number so a
                // callback-added same-name peer cannot be deleted instead.
                ctx.remove_effect(None, stopped.number.max(0) as usize, true);
            })?;
        }
    }

    temp_readd_upper_effects(scope, target, &uppers)
}

/// `FnCheckEffect` / `C4Effect::Check` (C4Script.cpp:5546-5556;
/// C4Effect.cpp:271-317). Unlike AddEffect, this does not create a pending
/// effect: it asks the selected live list synchronously and returns deny,
/// zero, or the accepting effect number.
fn check_effect(args: &[Value]) -> Result<Value, RuntimeError> {
    check_effect_with_policy(args, true, true)
}

/// Shared `C4Effect::Check` core. Script CheckEffect/AddEffect calls
/// propagate checker errors; native constructors such as Incinerate use
/// C4Effect's default fail-safe policy and already select the target scope
/// directly instead of resolving a script function named CheckEffect.
fn check_effect_with_policy(
    args: &[Value],
    redirect_foreign: bool,
    pass_errors: bool,
) -> Result<Value, RuntimeError> {
    if args.len() > 8 {
        return Err(RuntimeError::new("CheckEffect expects at most 8 arguments"));
    }
    let name = match effect_name_filter("CheckEffect", args.first().unwrap_or(&Value::Nil))? {
        Some(name) => name.to_owned(),
        None => return Ok(Value::Nil),
    };
    let target_state = args.get(1).unwrap_or(&Value::Nil);
    let target_id = object_id_from_value(target_state);

    // A typed object pointer whose Status is zero is rejected before its
    // effect list is inspected (FnCheckEffect's safety guard).
    if let Some(target_id) = target_id {
        let (active, status) = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let Some(context) = borrow.as_ref() else {
                return (None, None);
            };
            let active = context.object_context().map(|object| object.id());
            let status = if active == Some(target_id) {
                context.object_context().map(|object| object.status())
            } else {
                context.get_world_object(target_id).map(|object| object.status())
            };
            (active, status)
        });
        if status.is_none_or(|status| status == ObjectStatus::Deleted) {
            return Ok(Value::Nil);
        }
        if redirect_foreign && active != Some(target_id) {
            return call_world_object_function(target_id, "CheckEffect", args)
                .unwrap_or(Ok(Value::Nil));
        }
    }

    let scope = determine_scope_from_state(target_state)?;
    if matches!(scope, EffectScope::Object(_))
        && !matches!(target_state, Value::Object(_) | Value::Proplist(_))
    {
        return Err(RuntimeError::new(format!(
            "CheckEffect: expected object or proplist for object state, got {}",
            target_state.type_name()
        )));
    }
    let priority = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "CheckEffect",
        "priority",
    )?;
    let interval = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "CheckEffect",
        "interval",
    )?;
    let values: Vec<Value> = (4..8)
        .map(|index| args.get(index).cloned().unwrap_or(Value::Nil))
        .collect();
    let effects = match snapshot_effects_from_context(scope) {
        Some(effects) => effects,
        None => match scope {
            EffectScope::Object(_) => extract_effects_from_state(target_state)?,
            EffectScope::Global => Vec::new(),
        },
    };
    // FnCheckEffect returns C4VNull when there is no list head. This is
    // observably distinct from C4Effect::Check's successful integer zero.
    let had_list_head = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.effect_list_had_head(scope))
    });
    if !had_list_head.unwrap_or(!effects.is_empty()) {
        return Ok(Value::Nil);
    }
    if priority == 1 {
        return Ok(Value::Int(0));
    }

    let target = target_id.map(object_reference_value).unwrap_or(Value::Nil);
    let mut acceptor: Option<(EffectState, bool)> = None;
    let checker_numbers: Vec<i32> = effects.iter().map(|effect| effect.number).collect();
    for checker_number in checker_numbers {
        // C++ re-tests IsDead and signed priority as it reaches each linked
        // node. An earlier checker may synchronously remove a later one, so
        // never dispatch from the stale entry snapshot.
        let Some(checker) = snapshot_effects_from_context(scope)
            .unwrap_or_default()
            .into_iter()
            .find(|effect| effect.number == checker_number)
        else {
            continue;
        };
        if checker.priority == 0 || checker.priority < priority {
            continue;
        }
        let function = format!("Fx{}Effect", checker.name);
        let mut call_args = vec![
            Value::String(name.clone()),
            target.clone(),
            Value::Int(checker.number),
            Value::Nil,
        ];
        call_args.extend(values.iter().cloned());
        let result = if pass_errors {
            match dispatch_effect_fx_callback(
                checker.command_target,
                checker.command_id.as_deref(),
                &function,
                &call_args,
            ) {
                None => 0,
                Some(result) => value_as_i32(&result?),
            }
        } else {
            dispatch_effect_fx_callback_fail_safe(&checker, &function, &call_args)
        };
        match result {
            -1 => return Ok(Value::Int(-1)),
            -2 => acceptor = Some((checker.clone(), false)),
            -3 => acceptor = Some((checker.clone(), true)),
            _ => {}
        }
    }

    let Some((acceptor, do_temp_calls)) = acceptor else {
        return Ok(Value::Int(0));
    };
    let uppers = if do_temp_calls {
        temp_remove_upper_effects(scope, &target, &effects, acceptor.number)?
    } else {
        Vec::new()
    };
    let function = format!("Fx{}Add", acceptor.name);
    let mut add_args = vec![
        target.clone(),
        Value::Int(acceptor.number),
        Value::String(name),
        Value::Int(interval),
    ];
    add_args.extend(values);
    let add_result =
        dispatch_effect_fx_callback_fail_safe(&acceptor, &function, &add_args);
    if do_temp_calls {
        temp_readd_upper_effects(scope, &target, &uppers)?;
    }

    if add_result == -1 {
        // Fx*Add returning C4Fx_Start_Deny kills the ACCEPTOR and Check
        // reports Annul. The normal Stop call is fail-safe and may deny that
        // removal, exactly like C4Effect::Kill.
        let current = snapshot_effects_from_context(scope).unwrap_or_default();
        let kill_uppers = temp_remove_upper_effects(scope, &target, &current, acceptor.number)?;
        let previous_priority = with_context_mut(scope, |ctx| {
            let effect = ctx
                .effects
                .iter_mut()
                .find(|effect| effect.number == acceptor.number)?;
            let priority = effect.priority;
            effect.priority = 0;
            Some(priority)
        })?;
        let stop_function = format!("Fx{}Stop", acceptor.name);
        let stop_result = dispatch_effect_fx_callback_fail_safe(
            &acceptor,
            &stop_function,
            &[target.clone(), Value::Int(acceptor.number)],
        );
        if let Some(previous_priority) = previous_priority {
            if stop_result == -1 {
                with_context_mut(scope, |ctx| {
                    if let Some(effect) = ctx
                        .effects
                        .iter_mut()
                        .find(|effect| effect.number == acceptor.number)
                    {
                        effect.priority = previous_priority;
                    }
                })?;
            } else {
                with_context_mut(scope, |ctx| {
                    // The Stop callback already ran synchronously above.
                    // Fold only the identity-keyed deletion, never another
                    // deferred Stop dispatch.
                    ctx.remove_effect(None, acceptor.number as usize, true);
                })?;
            }
        }
        temp_readd_upper_effects(scope, &target, &kill_uppers)?;
        return Ok(Value::Int(-2));
    }
    Ok(Value::Int(acceptor.number))
}

fn add_effect(args: &[Value]) -> Result<Value, RuntimeError> {
    let name = match effect_name_filter("AddEffect", args.first().unwrap_or(&Value::Nil))? {
        Some(name) => name.to_owned(),
        None => return Ok(Value::Int(0)),
    };

    if let Some(result) = redirect_foreign_effect_target("AddEffect", args) {
        return result;
    }

    add_effect_constructor(args, name, true)
}

/// C4Effect constructor core after the script ABI's foreign-target routing.
/// Native callers use it directly so a script function named AddEffect
/// cannot replace the C++ constructor call, and choose the constructor's
/// `passErrors` policy for the Fx*Effect check chain.
fn add_effect_constructor(
    args: &[Value],
    name: String,
    check_pass_errors: bool,
) -> Result<Value, RuntimeError> {
    // An unfilled pTarget slot is nil — a GLOBAL effect (FnAddEffect's
    // C4Object *pTarget = nullptr).
    let target_state = args.get(1).unwrap_or(&Value::Nil);
    let scope = determine_scope_from_state(target_state)?;
    if matches!(scope, EffectScope::Object(_)) {
        match target_state {
            Value::Object(_) | Value::Proplist(_) => {}
            other => {
                return Err(RuntimeError::new(format!(
                    "AddEffect: expected object or proplist for object state, got {}",
                    other.type_name()
                )))
            }
        }
    }

    // `if (... || !iPrio) return 0` (C4Script.cpp:5449) — an unfilled
    // priority nil-fills to 0 like C4AulExec, creating NOTHING.
    let priority = match args.get(2) {
        Some(Value::Int(value)) => *value,
        Some(Value::Nil) | None => 0,
        Some(other) => {
            return Err(RuntimeError::new(format!(
                "AddEffect: expected int for priority, got {}",
                other.type_name()
            )))
        }
    };

    if priority == 0 {
        return Ok(Value::Int(0));
    }

    // C++ FnAddEffect: unpassed iTimerIntervall is 0 - no timer callbacks
    // (C4Effect.cpp:342).
    let interval = match args.get(3) {
        Some(Value::Int(value)) if *value >= 0 => *value,
        Some(Value::Int(_)) => {
            return Err(RuntimeError::new(
                "AddEffect: interval must be >= 0 when provided",
            ))
        }
        Some(Value::Nil) | None => 0,
        Some(other) => {
            return Err(RuntimeError::new(format!(
                "AddEffect: expected int for interval, got {}",
                other.type_name()
            )))
        }
    };

    let len = args.len();
    let mut idx = 4;
    let mut command_target: Option<i32> = None;
    let mut command_target_id: Option<String> = None;
    let mut timer: Option<i32> = None;
    let mut vars: Vec<EffectVarValue> = Vec::new();

    if idx < len {
        match &args[idx] {
            Value::Object(_) | Value::Proplist(_) | Value::Nil => {
                command_target = parse_command_target(&args[idx])?;
                idx += 1;
            }
            Value::Int(value) if *value == 0 && len > idx + 1 => {
                command_target = None;
                idx += 1;
            }
            Value::Int(value) if *value == 0 && len == idx + 1 => {
                timer = Some(parse_timer_from_int(*value)?);
                idx += 1;
            }
            Value::Int(value) if len == idx + 1 => {
                timer = Some(parse_timer_from_int(*value)?);
                idx += 1;
            }
            other => {
                return Err(RuntimeError::new(format!(
                    "AddEffect: expected proplist, nil, or int for command target, got {}",
                    other.type_name()
                )));
            }
        }
    }

    if idx < len {
        match &args[idx] {
            Value::C4Id(_) | Value::String(_) | Value::Nil => {
                command_target_id = parse_command_target_id(&args[idx])?;
                idx += 1;
            }
            Value::Int(value) if *value == 0 && idx < len - 1 => {
                command_target_id = None;
                idx += 1;
            }
            Value::Int(value) if *value == 0 && timer.is_none() && idx == len - 1 => {
                command_target_id = None;
                idx += 1;
            }
            Value::Int(value) if timer.is_none() && idx == len - 1 => {
                timer = Some(parse_timer_from_int(*value)?);
                idx += 1;
            }
            Value::Int(_) => {
                return Err(RuntimeError::new(
                    "AddEffect: command target id must be string, nil, or 0",
                ));
            }
            other => {
                return Err(RuntimeError::new(format!(
                    "AddEffect: expected string or nil for command target id, got {}",
                    other.type_name()
                )));
            }
        }
    }

    // The fixture-DSL keeps an explicit-nil timer slot here; any VALUE is
    // rVal1 — C++ FnAddEffect's vars begin at this position
    // (C4Script.cpp:5444), and `AddEffect("Fire", obj, 100, 1, 0, 0,
    // iCausedBy)` must land the cause in var 0.
    if idx < len && matches!(&args[idx], Value::Nil) {
        idx += 1;
    }

    while idx < len {
        let value = &args[idx];
        vars.push(value_to_effect_var(value));
        idx += 1;
    }

    // C4Effect::AssignCallbackFunctions immediately resolves an object
    // command target and overwrites idCommandTarget with that object's
    // current definition for save/runtime-join safety (C4Effect.cpp:31-57).
    if let Some(target) = command_target {
        if let Some(definition) = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| {
                    context.object_effective_definition_id(ObjectId::new(target as u64))
                })
        }) {
            command_target_id = Some(definition);
        }
    }

    // Priority-1 effects skip C4Effect::Check entirely (C4Effect.cpp:170).
    // Global and live-object additions negotiate and start synchronously,
    // before AddEffect returns (C4Effect.cpp:97-136). Synthetic proplist
    // fixture targets retain the deferred protocol.
    let global_scope = matches!(scope, EffectScope::Global);
    let live_object_scope = matches!(target_state, Value::Object(_));
    let synchronous_start = global_scope || live_object_scope || priority == 1;
    // The engine-internal fire start (FnFxFireStart, AddFunc
    // C4Script.cpp:6994) runs synchronously inside the C4Effect ctor
    // (C4Effect.cpp:118-133) — unless the selected callback script overloads
    // FxFireStart (the generic synchronous dispatch runs the overload), or
    // same/higher-priority effects exist whose Fx*Effect check chain must
    // rule first (C4Effect.cpp:97-116). Live objects run that check above,
    // then invoke the native start immediately.
    let has_checkers = snapshot_effects_from_context(scope)
        .map(|effects| {
            effects
                .iter()
                .any(|existing| existing.priority != 0 && existing.priority >= priority)
        })
        .unwrap_or(false);
    let engine_fire_start = !global_scope
        && name == crate::C4FX_FIRE
        && !effect_script_fx_callback_exists(
            command_target,
            command_target_id.as_deref(),
            "FxFireStart",
        )
        && (live_object_scope || (!synchronous_start && !has_checkers));
    let effect_name = name.clone();
    let call_vars: Vec<Value> = vars.iter().take(4).map(effect_var_to_value).collect();
    let for_object = match args.get(1) {
        Some(value @ Value::Object(_)) => value.clone(),
        _ => Value::Nil,
    };
    let command_id_for_start = command_target_id.clone();
    let identifier = with_context_mut(scope, move |ctx| {
        let mut effect = EffectState::new(name)
            .with_priority(priority)
            .with_interval(interval);
        if let Some(timer) = timer {
            effect = effect.with_timer(timer);
        }
        effect = effect.with_command_target(command_target);
        effect = effect.with_command_id(command_target_id);
        if !vars.is_empty() {
            effect = effect.with_vars(vars);
        }
        effect.start_dispatched = synchronous_start || engine_fire_start;
        ctx.reserve_effect(effect)
    })?;

    if (global_scope || live_object_scope) && priority != 1 {
        let mut check_args = vec![
            Value::String(effect_name.clone()),
            for_object.clone(),
            Value::Int(priority),
            Value::Int(interval),
        ];
        check_args.extend(call_vars.iter().cloned());
        check_args.resize(8, Value::Nil);
        let check_result = match check_effect_with_policy(&check_args, false, check_pass_errors) {
            Ok(result) => result,
            Err(error) => {
                with_context_mut(scope, |ctx| {
                    ctx.abort_reserved_effect(identifier);
                })?;
                return Err(error);
            }
        };
        let stored_number = match check_result {
            Value::Int(0) | Value::Nil => None,
            // C4Effect's pending node remains dead when Check denies it or
            // merges it into an acceptor. FnAddEffect returns zero for a
            // deny, and the acceptor number (or -2 when Fx*Add killed that
            // acceptor) for an annul (C4Effect.cpp:97-115).
            Value::Int(-1) => Some(0),
            Value::Int(result) => Some(result),
            _ => unreachable!("CheckEffect only returns nil or an integer"),
        };
        if let Some(stored_number) = stored_number {
            with_context_mut(scope, |ctx| {
                ctx.discard_reserved_effect(identifier);
            })?;
            return Ok(Value::Int(stored_number));
        }
    }

    let callback = format!("Fx{effect_name}Start");
    let scripted_start = synchronous_start
        && !engine_fire_start
        && effect_fx_callback_exists(
            command_target,
            command_id_for_start.as_deref(),
            &callback,
        );
    let has_start = engine_fire_start || scripted_start;
    let upper_effects = if synchronous_start && priority != 1 && has_start {
        let effects = snapshot_effects_from_context(scope).unwrap_or_default();
        temp_remove_upper_effects(scope, &for_object, &effects, identifier)?
    } else {
        Vec::new()
    };

    // Temp Stop callbacks may delete the carrier. C++ then leaves the
    // pending node invalid, skips Start/readd, and returns stored number 0
    // (C4Effect.cpp:123-126).
    if object_id_from_value(&for_object).is_some_and(|target| !object_is_present(target)) {
        with_context_mut(scope, |ctx| {
            ctx.discard_reserved_effect(identifier);
        })?;
        return Ok(Value::Int(0));
    }
    with_context_mut(scope, |ctx| {
        ctx.validate_reserved_effect(identifier, priority);
    })?;

    let mut start_denied = false;
    let mut start_error = None;
    if engine_fire_start && identifier > 0 {
        // FnFxFireStart parameter mapping: rVal1 = iCausedBy, rVal2 =
        // fBlasted, rVal3 = pIncineratingObject (C4Effect.cpp:560 +
        // pFnStart->Exec args, :129).
        let target = object_id_from_value(&for_object);
        let caused_by = match call_vars.first() {
            Some(Value::Int(value)) => *value,
            Some(Value::Bool(flag)) => i32::from(*flag),
            _ => 0,
        };
        let blasted = call_vars.get(1).map(Value::as_bool).unwrap_or(false);
        let incinerating = call_vars.get(2).and_then(object_id_from_value);
        if let Some(target) = target {
            match fire_effect_start_core(target, identifier, caused_by, blasted, incinerating) {
                Ok(-1) => start_denied = true,
                Ok(_) => {}
                Err(error) => start_error = Some(error),
            }
        }
    } else if scripted_start && identifier > 0 {
        let mut call_args = vec![for_object.clone(), Value::Int(identifier), Value::Int(0)];
        call_args.extend(call_vars);
        call_args.resize(7, Value::Nil);
        // pFnStart->Exec(pCommandTarget, {C4VObj(pForObj), C4VInt(iNumber),
        // C4VInt(0), rVal1..rVal4}, ...) (C4Effect.cpp:128-129); GLOBAL
        // effects resolve like C4Effect::DoCall — command target script,
        // command-id def script, else the engine-global function table
        // (C4Effect.cpp:439-456 via AssignCallbackFunctions :42-57).
        if let Some(result) = dispatch_effect_fx_callback(
            command_target,
            command_id_for_start.as_deref(),
            &callback,
            &call_args,
        ) {
            match result {
                Ok(Value::Int(-1)) => start_denied = true,
                Ok(_) => {}
                Err(error) => start_error = Some(error),
            }
        }
    }
    if let Some(error) = start_error {
        // Constructor exception unwind unlinks only the new node and does
        // not reactivate the temporarily stopped upper effects.
        with_context_mut(scope, |ctx| {
            ctx.abort_reserved_effect(identifier);
        })?;
        return Err(error);
    }
    if start_denied {
        // C4Fx_Start_Deny marks the new node dead without a Stop callback;
        // FnAddEffect still returns its allocated number after reactivating
        // upper effects (C4Effect.cpp:128-136).
        with_context_mut(scope, |ctx| {
            ctx.discard_reserved_effect(identifier);
        })?;
    }
    temp_readd_upper_effects(scope, &for_object, &upper_effects)?;
    if object_id_from_value(&for_object).is_some_and(|target| !object_is_present(target)) {
        return Ok(Value::Int(0));
    }

    Ok(Value::Int(identifier))
}

fn remove_effect(args: &[Value]) -> Result<Value, RuntimeError> {
    if let Some(result) = redirect_foreign_effect_target("RemoveEffect", args) {
        return result;
    }
    let name_filter =
        effect_name_filter("RemoveEffect", args.first().unwrap_or(&Value::Nil))?.map(str::to_owned);

    let target_state = args.get(1).unwrap_or(&Value::Nil);
    let scope = determine_scope_from_state(target_state)?;
    if matches!(scope, EffectScope::Object(_)) {
        match target_state {
            Value::Object(_) | Value::Proplist(_) => {}
            other => {
                return Err(RuntimeError::new(format!(
                    "RemoveEffect: expected object or proplist for object state, got {}",
                    other.type_name()
                )))
            }
        }
    }

    let index = match args.get(2) {
        Some(Value::Int(value)) if *value >= 0 => *value as usize,
        Some(Value::Int(_)) => {
            return Err(RuntimeError::new(
                "RemoveEffect: index must be >= 0 when provided",
            ))
        }
        Some(Value::Nil) | None => 0,
        Some(other) => {
            return Err(RuntimeError::new(format!(
                "RemoveEffect: expected int for index, got {}",
                other.type_name()
            )))
        }
    };

    // `bool fDoNoCalls` (FnRemoveEffect, C4Script.cpp:5493): C4Value
    // converts ints freely - CR content passes 1 (the Talker's movie
    // timer).
    let mut no_callbacks = false;
    if let Some(flag) = args.get(3) {
        match flag {
            Value::Bool(value) => no_callbacks = *value,
            Value::Int(value) => no_callbacks = *value != 0,
            Value::Nil => {}
            other => {
                return Err(RuntimeError::new(format!(
                    "RemoveEffect: expected bool or nil for no-call flag, got {}",
                    other.type_name()
                )))
            }
        }
    }

    // Real object and global effect lists execute C4Effect::Kill inside the
    // host call. Synthetic proplist fixtures retain the deferred command
    // protocol because they have no live callback/world context.
    let synchronous_kill = matches!(scope, EffectScope::Global)
        || matches!(target_state, Value::Object(_));
    if !no_callbacks && synchronous_kill {
        let victim = with_context_mut(scope, |ctx| {
            ctx.find_live_effect(name_filter.as_deref(), index)
        })?;
        let Some(victim) = victim else {
            return Ok(Value::Bool(false));
        };
        let target = match scope {
            EffectScope::Object(_) => target_state.clone(),
            EffectScope::Global => Value::Nil,
        };
        kill_effect_inline(scope, &target, &victim)?;
        return Ok(Value::Bool(true));
    }

    let removed = with_context_mut(scope, |ctx| {
        ctx.remove_live_effect(name_filter.as_deref(), index, no_callbacks)
    })?;
    // Synthetic proplist fixtures have no callback script, but preserve the
    // old engine-Fire projection. fDoNoCalls skips the entire Kill bracket.
    if matches!(scope, EffectScope::Object(_))
        && !no_callbacks
        && removed
            .as_ref()
            .is_some_and(|effect| effect.name == crate::C4FX_FIRE)
        && !script_shadows_engine_fx("FxFireStop")
    {
        HOST_CONTEXT.with(|cell| {
            if let Some(context) = cell.borrow_mut().as_mut() {
                if let Some(object) = context.object_context_mut() {
                    object.pending_update.stage_fire_flag(false);
                }
            }
        });
    }
    Ok(Value::Bool(removed.is_some()))
}

fn change_effect(args: &[Value]) -> Result<Value, RuntimeError> {
    if let Some(result) = redirect_foreign_effect_target("ChangeEffect", args) {
        return result.map(|value| match value {
            // The shared foreign-effect seam uses integer zero when the
            // target vanished. FnChangeEffect's declared return is bool.
            Value::Int(0) => Value::Bool(false),
            other => other,
        });
    }

    let name_filter =
        effect_name_filter("ChangeEffect", args.first().unwrap_or(&Value::Nil))?
            .map(str::to_owned);
    let scope = determine_scope_from_state(args.get(1).unwrap_or(&Value::Nil))?;
    if matches!(scope, EffectScope::Object(_)) {
        match args.get(1).unwrap_or(&Value::Nil) {
            Value::Object(_) | Value::Proplist(_) => {}
            other => {
                return Err(RuntimeError::new(format!(
                    "ChangeEffect: expected object or proplist for object state, got {}",
                    other.type_name()
                )))
            }
        }
    }

    let index = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "ChangeEffect",
        "index",
    )?;
    let Some(new_name) =
        effect_name_filter("ChangeEffect", args.get(3).unwrap_or(&Value::Nil))?
    else {
        return Ok(Value::Bool(false));
    };
    let new_name = truncate_c4_max_name(new_name);
    let new_timer = value_to_i32(
        args.get(4).unwrap_or(&Value::Nil),
        "ChangeEffect",
        "new timer",
    )?;

    let changed = with_context_mut(scope, |ctx| {
        ctx.change_effect(name_filter.as_deref(), index, new_name, new_timer)
    })?;
    Ok(Value::Bool(changed))
}

fn get_effect(args: &[Value]) -> Result<Value, RuntimeError> {
    if let Some(result) = redirect_foreign_effect_target("GetEffect", args) {
        return result;
    }
    let name_filter = effect_name_filter("GetEffect", args.first().unwrap_or(&Value::Nil))?;

    let scope = determine_scope_from_state(args.get(1).unwrap_or(&Value::Nil))?;
    let effects = match snapshot_effects_from_context(scope) {
        Some(effects) => effects,
        None => match scope {
            EffectScope::Object(_) => extract_effects_from_state(&args[1])?,
            EffectScope::Global => Vec::new(),
        },
    };

    let desired_index = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "GetEffect",
        "index",
    )?;

    let query = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "GetEffect",
        "query",
    )?;

    let max_priority = value_to_i32(
        args.get(4).unwrap_or(&Value::Nil),
        "GetEffect",
        "max priority",
    )?;

    let found = match name_filter {
        // Name/wildcard given: find by name and index
        // (C4Script.cpp:5471-5472 -> C4Effect::Get(szName, iIndex,...),
        // wildcard compare at C4Effect.cpp:229).
        Some(filter) => usize::try_from(desired_index).ok().and_then(|index| {
            effects
                .iter()
                .filter(|effect| effect.priority != 0)
                .filter(|effect| s_wildcard_match_ex(&effect.name, filter))
                .filter(|effect| max_priority == 0 || effect.priority <= max_priority)
                .nth(index)
        }),
        // No name: iIndex is the effect NUMBER (C4Script.cpp:5474-5475 ->
        // C4Effect::Get(iNumber, fIncludeDead=true), C4Effect.cpp:240-256).
        None => effects
            .iter()
            .find(|effect| effect.number == desired_index)
            .filter(|effect| max_priority == 0 || effect.priority <= max_priority),
    };

    Ok(found
        .map(|effect| match query {
            // 0: number (C4Script.cpp:5481 `C4VInt(pEffect->iNumber)`)
            0 => Value::Int(effect.number),
            1 => Value::String(effect.name.clone()),
            2 => Value::Int(effect.priority.abs()),
            3 => Value::Int(effect.interval),
            4 => effect
                .command_target
                .map(|target| object_reference_value(ObjectId::new(target as u64)))
                .unwrap_or(Value::Nil),
            5 => {
                let live_id = effect.command_target.and_then(|target| {
                    HOST_CONTEXT.with(|cell| {
                        cell.borrow().as_ref().and_then(|context| {
                            context
                                .object_effective_definition_id(ObjectId::new(target as u64))
                        })
                    })
                });
                live_id
                    .or_else(|| effect.command_id.clone())
                    .map(Value::C4Id)
                    .unwrap_or(Value::Nil)
            }
            6 => Value::Int(effect.timer),
            _ => Value::Nil,
        })
        .unwrap_or(Value::Nil))
}

fn get_effect_count(args: &[Value]) -> Result<Value, RuntimeError> {
    if let Some(result) = redirect_foreign_effect_target("GetEffectCount", args) {
        return result;
    }
    let name_filter = effect_name_filter("GetEffectCount", args.first().unwrap_or(&Value::Nil))?;

    let scope = determine_scope_from_state(args.get(1).unwrap_or(&Value::Nil))?;
    let effects = match snapshot_effects_from_context(scope) {
        Some(effects) => effects,
        None => match scope {
            EffectScope::Object(_) => extract_effects_from_state(&args[1])?,
            EffectScope::Global => Vec::new(),
        },
    };

    let max_priority = match args.get(2) {
        Some(Value::Int(value)) if *value >= 0 => Some(*value),
        Some(Value::Int(_)) => {
            return Err(RuntimeError::new(
                "GetEffectCount: max priority must be >= 0 when provided",
            ))
        }
        Some(Value::Nil) | None => None,
        Some(other) => {
            return Err(RuntimeError::new(format!(
                "GetEffectCount: expected int for max priority, got {}",
                other.type_name()
            )))
        }
    };

    let count = effects
        .iter()
        .filter(|effect| effect.priority != 0)
        .filter(|effect| {
            if let Some(filter) = name_filter {
                // C4Effect::GetCount wildcard-compares names (C4Effect.cpp:263).
                if !s_wildcard_match_ex(&effect.name, filter) {
                    return false;
                }
            }
            if let Some(limit) = max_priority {
                if effect.priority.abs() > limit {
                    return false;
                }
            }
            true
        })
        .count();

    let count = i32::try_from(count).unwrap_or(i32::MAX);
    Ok(Value::Int(count))
}

fn effect_var(args: &[Value]) -> Result<Value, RuntimeError> {
    // FnEffectVar reads/writes the effect list of the GIVEN object
    // (C4Script.cpp:5576-5586) — a foreign target re-dispatches into its
    // own scope like the other effect host functions (Fx callbacks write
    // vars on the effect carrier, not on their command-target context).
    if let Some(result) = redirect_foreign_effect_target("EffectVar", args) {
        return result;
    }
    // Unfilled iVarIndex is nil -> 0 (FnEffectVar, C4Script.cpp:5577).
    let var_index = match args.first().unwrap_or(&Value::Nil) {
        Value::Int(value) if *value >= 0 => *value as usize,
        Value::Nil => 0,
        Value::Int(_) => return Ok(Value::Nil),
        other => {
            return Err(RuntimeError::new(format!(
                "EffectVar: expected int for index, got {}",
                other.type_name()
            )))
        }
    };

    let scope = determine_scope_from_state(args.get(1).unwrap_or(&Value::Nil))?;

    let effect_number = match args.get(2).unwrap_or(&Value::Nil) {
        Value::Int(value) if *value > 0 => *value as usize,
        Value::Int(_) | Value::Nil => return Ok(Value::Nil),
        other => {
            return Err(RuntimeError::new(format!(
                "EffectVar: expected positive int for number, got {}",
                other.type_name()
            )))
        }
    };

    let new_value = args.get(3).map(value_to_effect_var);

    let context_value = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(None);
        };

        match context.scope_mut(scope) {
            Ok(stack) => Ok(stack.effect_var(effect_number, var_index, new_value.clone())),
            Err(_) => Ok(None),
        }
    })?;

    if let Some(value) = context_value {
        return Ok(effect_var_to_value(&value));
    }

    if new_value.is_some() {
        return Err(RuntimeError::new(
            "EffectVar: setting variables requires an active engine context",
        ));
    }

    // FnEffectVar resolves the effect BY NUMBER (C4Effect::Get(iNumber,
    // true), C4Script.cpp:5583); snapshot proplists carry positional
    // stand-in numbers from extract_effects_from_state.
    let effects = extract_effects_from_state(args.get(1).unwrap_or(&Value::Nil))?;
    let number = i32::try_from(effect_number).unwrap_or(i32::MAX);
    Ok(effects
        .iter()
        .find(|effect| effect.number == number)
        .map(|effect| effect_var_to_value(&effect.var(var_index)))
        .unwrap_or(Value::Nil))
}

/// FnEffectCall (C4Script.cpp:5589-5601): `EffectCall(pTarget, iNumber,
/// szCallFn, vVal1..vVal7)` finds the effect BY NUMBER on the target (dead
/// included, `C4Effect::Get(iNumber, true)`, C4Effect.cpp:240-256) and runs
/// `Fx<EffectName><CallFn>` (PSF_FxCustom, C4Script.h:113) through
/// `C4Effect::DoCall` (C4Effect.cpp:439-456): the effect's command target is
/// the call context and its def script the resolution scope (global script
/// functions fall back via GetFuncRecursive); without a live target the
/// command id's def script is used, else Game.ScriptEngine's globals. The
/// callback receives `(pTarget, iNumber, vVal1..vVal7)`; passErrors=true —
/// callback errors abort the calling script like C++.
fn effect_call(args: &[Value]) -> Result<Value, RuntimeError> {
    // Foreign target: run in the target's own scope like the other effect
    // host functions (the C4Effect list lives on the GIVEN object).
    let target = args.first().unwrap_or(&Value::Nil);
    if let Some(foreign) = object_id_from_value(target) {
        let active = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.object_context().map(|object| object.id()))
        });
        if Some(foreign) != active {
            // A vanished/dead target is the FnEffectCall status guard
            // (C4Script.cpp:5593): silent C4VNull.
            return call_world_object_function(foreign, "EffectCall", args)
                .unwrap_or(Ok(Value::Nil));
        }
    }

    // `if (!szCallFn || !*szCallFn) return C4VNull;` (C4Script.cpp:5594) —
    // the same falsy-name conversion the effect name filters use.
    let call_fn = match effect_name_filter("EffectCall", args.get(2).unwrap_or(&Value::Nil))? {
        Some(name) => name.to_owned(),
        None => return Ok(Value::Nil),
    };

    let number = match args.get(1).unwrap_or(&Value::Nil) {
        Value::Int(value) => *value,
        Value::Nil => 0,
        Value::Bool(flag) => i32::from(*flag),
        other => {
            return Err(RuntimeError::new(format!(
                "EffectCall: expected int for effect number, got {}",
                other.type_name()
            )))
        }
    };

    let scope = determine_scope_from_state(target)?;
    let effects = match snapshot_effects_from_context(scope) {
        Some(effects) => effects,
        None => match scope {
            EffectScope::Object(_) => extract_effects_from_state(target)?,
            EffectScope::Global => Vec::new(),
        },
    };
    let Some(effect) = effects.iter().find(|effect| effect.number == number) else {
        return Ok(Value::Nil);
    };

    let function = format!("Fx{}{}", effect.name, call_fn);
    // DoCall argument layout (C4Effect.cpp:455): pObj, iNumber, then the
    // seven forwarded values.
    let mut call_args = Vec::with_capacity(9);
    call_args.push(match scope {
        EffectScope::Object(_) => target.clone(),
        EffectScope::Global => Value::Nil,
    });
    call_args.push(Value::Int(number));
    call_args.extend(args.iter().skip(3).take(7).cloned());
    call_args.resize(9, Value::Nil);

    dispatch_effect_fx_callback(
        effect.command_target,
        effect.command_id.as_deref(),
        &function,
        &call_args,
    )
    .unwrap_or(Ok(Value::Nil))
}

/// Whether the selected callback script supplies a script implementation
/// before the engine-native Fx* fallback.
fn effect_script_fx_callback_exists(
    command_target: Option<i32>,
    command_id: Option<&str>,
    function: &str,
) -> bool {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        if let Some(command_target) = command_target {
            let target = ObjectId::new(command_target as u64);
            if context.get_world_object(target).is_some() {
                return context
                    .object_effective_definition_id(target)
                    .and_then(|id| context.world.definition_script(&id))
                    .is_some_and(|script| script.has_function_or_global(function));
            }
        }
        if let Some(script) = command_id.and_then(|id| context.world.definition_script(id)) {
            return script.has_function_or_global(function);
        }
        context
            .world
            .scenario_script()
            .is_some_and(|script| script.has_global_function(function))
            || context
                .world
                .definition_scripts()
                .any(|script| script.has_global_function(function))
    })
}

/// Whether C4Effect::AssignCallbackFunctions resolves this callback through
/// the command object, command definition, or global script engine. Start's
/// upper-effect temp bracket exists only when pFnStart is non-null.
fn effect_fx_callback_exists(
    command_target: Option<i32>,
    command_id: Option<&str>,
    function: &str,
) -> bool {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        if let Some(command_target) = command_target {
            let target = ObjectId::new(command_target as u64);
            if context.get_world_object(target).is_some() {
                return context
                    .object_effective_definition_id(target)
                    .and_then(|id| context.world.definition_script(&id))
                    .is_some_and(|script| {
                        script.has_function_or_global(function)
                            || script.has_host_function(function)
                    });
            }
        }
        if let Some(script) = command_id.and_then(|id| context.world.definition_script(id)) {
            return script.has_function_or_global(function) || script.has_host_function(function);
        }
        context.world.scenario_script().is_some_and(|script| {
            script.has_global_function(function) || script.has_host_function(function)
        }) || context.world.definition_scripts().any(|script| {
            script.has_global_function(function) || script.has_host_function(function)
        })
    })
}

/// Resolves and executes an Fx callback like C4Effect::DoCall
/// (C4Effect.cpp:439-456): the effect's command target's own script, else
/// the command id's def script (Obj=nullptr, GetFuncRecursive reaches
/// globals), else the engine-global function table. `None` when the
/// function exists nowhere (pFn nullptr) — the caller decides whether
/// that means C4Value() or "leave a chained value untouched".
fn dispatch_effect_fx_callback(
    command_target: Option<i32>,
    command_id: Option<&str>,
    function: &str,
    call_args: &[Value],
) -> Option<Result<Value, RuntimeError>> {
    if let Some(command_target) = command_target {
        // pFn->Exec(pCommandTarget, ...) — the command target is `this`
        // (C4Effect.cpp:443-445,456). GetFuncRecursive also reaches native
        // engine functions (notably FxFireInfo).
        let command_target = ObjectId::new(command_target as u64);
        let target_exists = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .is_some_and(|context| context.get_world_object(command_target).is_some())
        });
        if target_exists {
            return call_world_object_function(command_target, function, call_args);
        }
    }
    let definition_script = command_id.and_then(|id| {
        HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.world.definition_script(id).cloned())
        })
    });
    if let Some(script) = definition_script {
        // idCommandTarget resolves the def script with Obj=nullptr
        // (C4Effect.cpp:446-447); GetFuncRecursive reaches globals.
        return call_scoped_effect_function_or_global(script, function, call_args);
    }
    // No command target at all: Game.ScriptEngine — GLOBAL script
    // functions (C4Effect.cpp:448-449). Any loaded script host shares the
    // engine-global function table.
    let global_carrier = HOST_CONTEXT.with(|cell| {
        cell.borrow().as_ref().and_then(|context| {
            context
                .world
                .scenario_script()
                .filter(|script| {
                    script.has_global_function(function) || script.has_host_function(function)
                })
                .or_else(|| {
                    context
                        .world
                        .definition_scripts()
                        .find(|script| {
                            script.has_global_function(function)
                                || script.has_host_function(function)
                        })
                })
                .cloned()
        })
    });
    global_carrier.and_then(|script| {
        call_scoped_effect_function_or_global(script, function, call_args)
    })
}

/// `C4Object::GetInfoString` effect suffix: query every attached effect in
/// list order through fail-safe `Fx<Name>Info(target, number)` dispatch.
/// Callback side effects remain in the surrounding host context and are
/// folded by the engine after this returns.
pub(crate) fn object_effect_info_lines(
    target: ObjectId,
    effects: &[EffectState],
) -> Vec<String> {
    let target_value = object_reference_value(target);
    let mut lines = Vec::new();
    for effect in effects {
        let function = format!("Fx{}Info", effect.name);
        let call_args = [target_value.clone(), Value::Int(effect.number)];
        let Some(result) = dispatch_effect_fx_callback(
            effect.command_target,
            effect.command_id.as_deref(),
            &function,
            &call_args,
        ) else {
            continue;
        };
        match result {
            Ok(Value::String(line)) if !line.is_empty() => lines.push(line),
            Ok(value) if !value.as_bool() => {}
            Ok(value) => tracing::warn!(
                effect = effect.name,
                number = effect.number,
                returned = value.type_name(),
                "effect Info callback returned a non-string value"
            ),
            Err(error) => tracing::warn!(
                %error,
                effect = effect.name,
                number = effect.number,
                "script error in effect Info callback; continuing like C++ fail-safe dispatch"
            ),
        }
    }
    lines
}

fn legacy_arg_int(args: &[Value], index: usize, function: &str) -> Result<i32, RuntimeError> {
    value_to_i32(
        args.get(index).unwrap_or(&Value::Nil),
        function,
        &format!("argument {}", index + 1),
    )
}

fn legacy_not(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new("Not expects at most 1 argument"));
    }
    Ok(Value::Bool(
        !args.first().unwrap_or(&Value::Nil).as_bool(),
    ))
}

fn legacy_or(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 5 {
        return Err(RuntimeError::new("Or expects at most 5 arguments"));
    }
    Ok(Value::Bool(args.iter().any(Value::as_bool)))
}

fn legacy_and(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new("And expects at most 2 arguments"));
    }
    Ok(Value::Bool(
        (0..2).all(|index| args.get(index).unwrap_or(&Value::Nil).as_bool()),
    ))
}

fn legacy_bit_and(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new("BitAnd expects at most 2 arguments"));
    }
    Ok(Value::Int(
        legacy_arg_int(args, 0, "BitAnd")? & legacy_arg_int(args, 1, "BitAnd")?,
    ))
}

fn legacy_sum(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 4 {
        return Err(RuntimeError::new("Sum expects at most 4 arguments"));
    }
    (0..4)
        .try_fold(0_i32, |sum, index| {
            Ok(sum.wrapping_add(legacy_arg_int(args, index, "Sum")?))
        })
        .map(Value::Int)
}

fn legacy_sub(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 4 {
        return Err(RuntimeError::new("Sub expects at most 4 arguments"));
    }
    let first = legacy_arg_int(args, 0, "Sub")?;
    (1..4)
        .try_fold(first, |difference, index| {
            Ok(difference.wrapping_sub(legacy_arg_int(args, index, "Sub")?))
        })
        .map(Value::Int)
}

fn legacy_mul(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new("Mul expects at most 2 arguments"));
    }
    Ok(Value::Int(
        legacy_arg_int(args, 0, "Mul")?.wrapping_mul(legacy_arg_int(args, 1, "Mul")?),
    ))
}

fn legacy_div(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new("Div expects at most 2 arguments"));
    }
    let dividend = legacy_arg_int(args, 0, "Div")?;
    let divisor = legacy_arg_int(args, 1, "Div")?;
    Ok(Value::Int(if divisor == 0 {
        0
    } else {
        dividend.wrapping_div(divisor)
    }))
}

fn legacy_less_than(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "LessThan expects at most 2 arguments",
        ));
    }
    Ok(Value::Int(i32::from(
        legacy_arg_int(args, 0, "LessThan")? < legacy_arg_int(args, 1, "LessThan")?,
    )))
}

fn legacy_greater_than(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "GreaterThan expects at most 2 arguments",
        ));
    }
    Ok(Value::Int(i32::from(
        legacy_arg_int(args, 0, "GreaterThan")? > legacy_arg_int(args, 1, "GreaterThan")?,
    )))
}

fn legacy_s_equal(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new("SEqual expects at most 2 arguments"));
    }
    let string = |value: &Value, parameter: &str| match value {
        Value::String(value) => Ok(value.clone()),
        Value::Nil => Ok(String::new()),
        other => Err(RuntimeError::new(format!(
            "SEqual: expected string for {parameter}, got {}",
            other.type_name()
        ))),
    };
    let left = string(args.first().unwrap_or(&Value::Nil), "first argument")?;
    let right = string(args.get(1).unwrap_or(&Value::Nil), "second argument")?;
    Ok(Value::Int(i32::from(left == right)))
}

fn set_var(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new("SetVar expects at most 2 arguments"));
    }
    let index = legacy_arg_int(args, 0, "SetVar")?;
    if !(0..AUL_MAX_PAR).contains(&index) {
        return Ok(Value::Nil);
    }
    let value = args.get(1).cloned().unwrap_or(Value::Nil);
    let Some(slots) = lc_script::caller_var_slots() else {
        return Ok(Value::Nil);
    };
    slots.set(index, value.clone());
    Ok(value)
}

fn random(args: &[Value]) -> Result<Value, RuntimeError> {
    if std::env::var("LC_RUST_RNG_TRACE").is_ok() {
        let context = HOST_CONTEXT.with(|cell| {
            cell.borrow().as_ref().and_then(|context| {
                context.object_context().map(|object| {
                    format!("{} {}", object.id().as_u64(), object.effective_action_name())
                })
            })
        });
        let frame = ENVIRONMENT_CONTEXT.with(|cell| {
            cell.borrow().as_ref().map(|context| context.frame).unwrap_or(0)
        });
        if (19..=21).contains(&frame) {
            tracing::warn!(?args, ?context, frame, "RNDCALL");
        }
    }
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "Random expects at most 1 argument: upper exclusive bound",
        ));
    }

    // FnRandom's int parameter follows the C4AulExec conversion rules
    // (C4AulExec.cpp:1364-1396): a missing/nil/bool argument converts —
    // Random(GetActMapVal(...)) with a missing action is Random(0) in
    // C++. The count++ happens even for range 0 (C4Random.h:43), and a
    // negative range goes through the unsigned modulo like C++'s usual
    // arithmetic conversions — both live in LcgRng::random.
    let range = match args.first().unwrap_or(&Value::Nil) {
        Value::Int(value) => *value,
        Value::Nil => 0,
        Value::Bool(flag) => i32::from(*flag),
        other => {
            return Err(RuntimeError::new(format!(
                "Random: expected int for range, got {}",
                other.type_name()
            )))
        }
    };

    RANDOM_CONTEXT.with(|cell| {
        let context = cell
            .borrow()
            .as_ref()
            .ok_or_else(|| RuntimeError::new("Random: host context unavailable"))?
            .clone();
        let mut rng = context.rng.borrow_mut();
        let value = rng.random(range);
        Ok(Value::Int(value))
    })
}

/// FnAsyncRandom (C4Script.cpp:3367-3370): draw from the deliberately
/// unsynchronized SafeRandom stream without touching the lockstep RNG.
fn async_random(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "AsyncRandom expects at most 1 argument: upper exclusive bound",
        ));
    }
    let range = legacy_arg_int(args, 0, "AsyncRandom")?;
    let value = SCRIPT_SAFE_RNG.with(|rng| rng.borrow_mut().random(range));
    Ok(Value::Int(value))
}

fn music(args: &[Value]) -> Result<Value, RuntimeError> {
    let song = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) => Some(name.clone()),
        Value::Nil | Value::Int(0) => None,
        other => {
            return Err(RuntimeError::new(format!(
                "Music: expected string, nil, or 0 for song name, got {}",
                other.type_name()
            )))
        }
    };
    let looped = args.get(1).is_some_and(Value::as_bool);

    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            match song {
                Some(name) => context.audio_mut().play_music(name, looped),
                None => context.audio_mut().stop_music(),
            }
        }
    });
    Ok(Value::Nil)
}

fn music_level(args: &[Value]) -> Result<Value, RuntimeError> {
    let level = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "MusicLevel",
        "level",
    )?;
    let level = HOST_CONTEXT.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .map(|context| context.audio_mut().set_music_level(level))
            .unwrap_or(level.clamp(0, 100) as u8)
    });
    Ok(Value::Int(i32::from(level)))
}

fn sound(args: &[Value]) -> Result<Value, RuntimeError> {
    let name = match args.first().unwrap_or(&Value::Nil) {
        Value::String(value) if !value.is_empty() => value.clone(),
        Value::Nil => return Ok(Value::Bool(true)),
        other => {
            return Err(RuntimeError::new(format!(
                "Sound: expected string for name, got {}",
                other.type_name()
            )))
        }
    };

    let mut index = 1;
    let global = if let Some(arg) = args.get(index) {
        let flag = value_to_bool(arg, "Sound", "global")?;
        index += 1;
        flag
    } else {
        false
    };

    let object_value = if let Some(arg) = args.get(index) {
        index += 1;
        Some(arg)
    } else {
        None
    };

    let level = if let Some(arg) = args.get(index) {
        index += 1;
        value_to_i32(arg, "Sound", "level")?
    } else {
        0
    };

    let at_player = if let Some(arg) = args.get(index) {
        let player = value_to_i32(arg, "Sound", "at_player")?;
        index += 1;
        player
    } else {
        0
    };

    let loop_flag = if let Some(arg) = args.get(index) {
        index += 1;
        value_to_i32(arg, "Sound", "loop")?
    } else {
        0
    };

    let multiple = if let Some(arg) = args.get(index) {
        let flag = value_to_bool(arg, "Sound", "multiple")?;
        index += 1;
        flag
    } else {
        false
    };

    let custom_falloff = if let Some(arg) = args.get(index) {
        Some(value_to_i32(arg, "Sound", "custom_falloff")?).filter(|value| *value > 0)
    } else {
        None
    };

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = match borrow.as_mut() {
            Some(context) => context,
            None => return Ok(Value::Bool(true)),
        };

        if at_player != 0 {
            let player_id = at_player.wrapping_sub(1);
            let Some(player) = context.player_state(player_id) else {
                return Ok(Value::Bool(false));
            };
            if !context.world.local_players.contains(&player_id) && player.viewports.is_empty() {
                return Ok(Value::Bool(true));
            }
        }

        let mut target_id = if let Some(value) = object_value {
            parse_object_reference_argument(value, "Sound", "object")?
        } else {
            None
        };

        if global {
            target_id = None;
        } else if target_id.is_none() {
            target_id = context.object_context().map(|object| object.id());
        }

        if level < 0 {
            return Ok(Value::Bool(true));
        }

        if loop_flag < 0 {
            context.audio_mut().stop_sound(&name, target_id);
            return Ok(Value::Bool(true));
        }

        let mut volume = level;
        if volume == 0 || volume > 100 {
            volume = 100;
        }
        let volume = volume.clamp(0, 100) as u8;
        let looped = loop_flag > 0;
        let custom_falloff = custom_falloff.filter(|value| *value > 0);

        let audio = context.audio_mut();
        if !multiple && audio.is_playing(&name, target_id) {
            return Ok(Value::Bool(true));
        }

        audio.play_sound(&name, target_id, volume, looped, multiple, custom_falloff);
        Ok(Value::Bool(true))
    })
}

fn sound_level(args: &[Value]) -> Result<Value, RuntimeError> {
    let name = match args.first().unwrap_or(&Value::Nil) {
        Value::String(value) if !value.is_empty() => value.clone(),
        Value::Nil => return Ok(Value::Bool(true)),
        other => {
            return Err(RuntimeError::new(format!(
                "SoundLevel: expected string for name, got {}",
                other.type_name()
            )))
        }
    };

    let level = match args.get(1).unwrap_or(&Value::Nil) {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "SoundLevel: expected int for level, got {}",
                other.type_name()
            )))
        }
    };

    let object_arg = args.get(2);

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = match borrow.as_mut() {
            Some(context) => context,
            None => return Ok(Value::Bool(true)),
        };

        let mut target_id = if let Some(value) = object_arg {
            parse_object_reference_argument(value, "SoundLevel", "object")?
        } else {
            None
        };

        if target_id.is_none() {
            target_id = context.object_context().map(|object| object.id());
        }

        let volume = level.clamp(0, 100) as u8;
        context.audio_mut().sound_level(&name, target_id, volume);
        Ok(Value::Bool(true))
    })
}

fn set_gravity(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.is_empty() {
        return Err(RuntimeError::new("SetGravity expects 1 argument: gravity"));
    }

    let gravity = match &args[0] {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "SetGravity: expected int or nil for gravity, got {}",
                other.type_name()
            )))
        }
    };

    PHYSICS_CONTEXT.with(|cell| {
        let context = cell
            .borrow()
            .as_ref()
            .ok_or_else(|| RuntimeError::new("SetGravity requires an active engine context"))?
            .clone();
        context.set_gravity(gravity);
        Ok(Value::Nil)
    })
}

fn get_gravity(args: &[Value]) -> Result<Value, RuntimeError> {
    if !args.is_empty() {
        return Err(RuntimeError::new(
            "GetGravity does not accept any arguments",
        ));
    }

    PHYSICS_CONTEXT.with(|cell| {
        let context = cell
            .borrow()
            .as_ref()
            .ok_or_else(|| RuntimeError::new("GetGravity requires an active engine context"))?
            .clone();
        Ok(Value::Int(context.gravity()))
    })
}

/// FnSimFlight (C4Script.cpp:5309-5330) and SimFlight
/// (C4Movement.cpp:623-653). The first four native C4Value* arguments are
/// nullable references; simulation runs on local fixed-point copies so a
/// bounds/iteration failure leaves every caller variable untouched.
fn sim_flight(args: &[HostCallArg]) -> Result<Value, RuntimeError> {
    if (0..4).any(|index| !args.get(index).is_some_and(HostCallArg::is_reference)) {
        return Err(RuntimeError::new(
            "SimFlight: first four arguments must be variable references",
        ));
    }

    let values = args
        .iter()
        .map(HostCallArg::read)
        .collect::<Result<Vec<_>, _>>()?;
    // FnSimFlight calls getInt() on the referenced C4Values after native
    // dispatch has validated only that they are references. getInt() returns
    // zero when the referenced value cannot convert to Int.
    let read_int = |index: usize| {
        values
            .get(index)
            .and_then(Value::as_c4_int)
            .unwrap_or(0)
    };
    let optional_int = |index: usize, parameter: &str| {
        parse_native_optional_i32(values.get(index), "SimFlight", parameter)
    };
    let density_min = optional_int(4, "density_min")?.unwrap_or(50);
    let density_max = optional_int(5, "density_max")?.unwrap_or(100);
    let mut iterations = optional_int(6, "iterations")?.unwrap_or(-1);
    let precision = optional_int(7, "precision")?.unwrap_or(10);
    if precision == 0 {
        return Err(RuntimeError::new("SimFlight: precision must not be zero"));
    }

    let mut x = itofix(read_int(0));
    let mut y = itofix(read_int(1));
    let xdir = itofix_prec(read_int(2), precision);
    let mut ydir = itofix_prec(read_int(3), precision);
    let gravity = PHYSICS_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .map(|context| fixed100(context.gravity()) / 5)
            .ok_or_else(|| RuntimeError::new("SimFlight requires an active physics context"))
    })?;

    let succeeded = HOST_CONTEXT.with(|cell| -> Result<bool, RuntimeError> {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("SimFlight requires an active engine context"))?;
        let landscape = context
            .world
            .landscape_ref()
            .ok_or_else(|| RuntimeError::new("SimFlight requires an active landscape"))?;
        let width = landscape.width() as i32;
        let height = landscape.estimated_height();
        let mut cx = fixtoi(x);
        let mut cy = fixtoi(y);

        loop {
            if iterations == 0 {
                return Ok(false);
            }
            iterations = iterations.wrapping_sub(1);
            x += xdir;
            y += ydir;
            let target_x = fixtoi(x);
            let target_y = fixtoi(y);
            // Inside(target_x, 0, GBackWdt) is inclusive in both bounds;
            // C++ only rejects the lower landscape vertically.
            if !(0..=width).contains(&target_x) || target_y >= height {
                return Ok(false);
            }

            let contact = loop {
                cx += (target_x - cx).signum();
                cy += (target_y - cy).signum();
                let density = context.world.movement_density_at(cx, cy).unwrap_or(0);
                if (density_min..=density_max).contains(&density) {
                    break true;
                }
                if cx == target_x && cy == target_y {
                    break false;
                }
            };
            // GravAccel is adjusted for every completed movement frame,
            // including the frame that first contacts the density.
            ydir += gravity;
            if contact {
                x = itofix(cx);
                y = itofix(cy);
                return Ok(true);
            }
        }
    })?;

    if !succeeded {
        return Ok(Value::Bool(false));
    }
    let output = [
        Value::Int(fixtoi(x)),
        Value::Int(fixtoi(y)),
        Value::Int(fixtoi(xdir * precision)),
        Value::Int(fixtoi(ydir * precision)),
    ];
    for (index, value) in output.into_iter().enumerate() {
        let wrote = args[index].write(value)?;
        debug_assert!(wrote, "validated SimFlight reference disappeared");
    }
    Ok(Value::Bool(true))
}

fn set_wind(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.is_empty() {
        return Err(RuntimeError::new("SetWind expects 1 argument: wind"));
    }

    let wind = match &args[0] {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "SetWind: expected int or nil for wind, got {}",
                other.type_name()
            )))
        }
    };

    ENVIRONMENT_CONTEXT.with(|cell| {
        let context = cell
            .borrow()
            .as_ref()
            .ok_or_else(|| RuntimeError::new("SetWind requires an active engine context"))?
            .clone();
        context.set_wind(wind);
        Ok(Value::Nil)
    })
}

fn get_wind(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 3 {
        return Err(RuntimeError::new(
            "GetWind expects at most 3 arguments: x, y, global",
        ));
    }

    for (index, arg) in args.iter().enumerate() {
        match arg {
            Value::Int(_) | Value::Nil => {}
            Value::Bool(_) if index == 2 => {}
            other => {
                return Err(RuntimeError::new(format!(
                    "GetWind: unexpected argument type {} at position {}",
                    other.type_name(),
                    index + 1
                )))
            }
        }
    }

    let wind = ENVIRONMENT_CONTEXT.with(|cell| {
        let context = cell
            .borrow()
            .as_ref()
            .ok_or_else(|| RuntimeError::new("GetWind requires an active engine context"))?
            .clone();
        Ok::<i32, RuntimeError>(context.wind_force())
    })?;

    // Global form (FnGetWind, C4Script.cpp:3001-3004).
    let global = match args.get(2) {
        Some(Value::Bool(flag)) => *flag,
        Some(Value::Int(value)) => *value != 0,
        _ => false,
    };
    if global {
        return Ok(Value::Int(wind));
    }

    // Positional form: object-relative GBackWind — zero on tunnel
    // background (C4Script.cpp:3005-3007; C4Wrappers.h:189-192).
    let local_x = match args.first() {
        Some(Value::Int(value)) => *value,
        _ => 0,
    };
    let local_y = match args.get(1) {
        Some(Value::Int(value)) => *value,
        _ => 0,
    };
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Int(wind));
        };
        let mut global_x = local_x;
        let mut global_y = local_y;
        if let Some(object) = context.object_context() {
            let position = object.effective_position();
            global_x = global_x.saturating_add(position.x);
            global_y = global_y.saturating_add(position.y);
        }
        let in_tunnel = context
            .landscape_ref()
            .map(|landscape| landscape.is_tunnel_at(global_x, global_y))
            .unwrap_or(false);
        Ok(Value::Int(if in_tunnel { 0 } else { wind }))
    })
}

// Mathematical host functions

fn abs_func(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() != 1 {
        return Err(RuntimeError::new("Abs expects 1 argument: value"));
    }

    match &args[0] {
        Value::Int(value) => Ok(Value::Int(value.abs())),
        Value::Nil => Ok(Value::Int(0)),
        other => Err(RuntimeError::new(format!(
            "Abs: expected int, got {}",
            other.type_name()
        ))),
    }
}

fn min_func(args: &[Value]) -> Result<Value, RuntimeError> {
    let val1 = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "Min",
        "first argument",
    )?;
    let val2 = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "Min",
        "second argument",
    )?;

    Ok(Value::Int(val1.min(val2)))
}

fn max_func(args: &[Value]) -> Result<Value, RuntimeError> {
    let val1 = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "Max",
        "first argument",
    )?;
    let val2 = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "Max",
        "second argument",
    )?;

    Ok(Value::Int(val1.max(val2)))
}

fn sqrt_func(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() != 1 {
        return Err(RuntimeError::new("Sqrt expects 1 argument: value"));
    }

    let value = match &args[0] {
        Value::Int(v) => *v,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "Sqrt: expected int, got {}",
                other.type_name()
            )))
        }
    };

    // C++ returns 0 for negative values
    if value < 0 {
        return Ok(Value::Int(0));
    }

    // C++ implementation does: sqrt, then adjusts for rounding
    let result = (value as f64).sqrt() as i32;
    Ok(Value::Int(result))
}

fn inverse_trig_func(
    args: &[Value],
    function: &str,
    inverse: fn(f64) -> f64,
) -> Result<Value, RuntimeError> {
    let value = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        function,
        "value",
    )?;
    let radius = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        function,
        "radius",
    )?;
    // FnArcSin/FnArcCos (C4Script.cpp:3276-3298): the comparison is
    // deliberately signed (negative values within the domain remain
    // valid), followed by double-precision libm in degrees and
    // floor(angle + 0.5).
    if radius == 0 || value > radius {
        return Ok(Value::Int(0));
    }
    let angle = inverse(f64::from(value) / f64::from(radius))
        * 180.0
        * std::f64::consts::FRAC_1_PI;
    Ok(Value::Int(round_inverse_angle(angle)))
}

fn round_inverse_angle(angle: f64) -> i32 {
    (angle + 0.5).floor() as i32
}

fn arc_sin_func(args: &[Value]) -> Result<Value, RuntimeError> {
    inverse_trig_func(args, "ArcSin", f64::asin)
}

fn arc_cos_func(args: &[Value]) -> Result<Value, RuntimeError> {
    inverse_trig_func(args, "ArcCos", f64::acos)
}

/// FnAngle (C4Script.cpp:3255-3280): the position-to-position angle in
/// Clonk orientation (0 = up, 90 = right), `iPrec` scaling (default 1).
/// Axis-aligned deltas take the exact shortcuts; the general case is
/// `trunc(180 * prec * atan2(|dy|, |dx|) / pi)` folded into the quadrant.
fn angle_func(args: &[Value]) -> Result<Value, RuntimeError> {
    let x1 = value_to_i32(args.first().unwrap_or(&Value::Nil), "Angle", "x1")?;
    let y1 = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "Angle", "y1")?;
    let x2 = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "Angle", "x2")?;
    let y2 = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "Angle", "y2")?;
    let mut prec = value_to_i32(args.get(4).unwrap_or(&Value::Nil), "Angle", "precision")?;
    if prec == 0 {
        prec = 1;
    }

    let dx = x2.wrapping_sub(x1);
    let dy = y2.wrapping_sub(y1);
    if dx == 0 {
        return Ok(Value::Int(if dy > 0 { 180 * prec } else { 0 }));
    }
    if dy == 0 {
        return Ok(Value::Int(if dx > 0 { 90 * prec } else { 270 * prec }));
    }

    let angle = (180.0
        * f64::from(prec)
        * f64::from(dy.abs()).atan2(f64::from(dx.abs()))
        * std::f64::consts::FRAC_1_PI) as i32;

    Ok(Value::Int(if x2 > x1 {
        if y2 < y1 {
            90 * prec - angle
        } else {
            90 * prec + angle
        }
    } else if y2 < y1 {
        270 * prec + angle
    } else {
        270 * prec - angle
    }))
}

/// FnGetMass (C4Script.cpp:1148-1158): with an id, the DEF mass; else the
/// object's Mass = max(Def->Mass * Con / FullCon, 1)
/// (C4Object.cpp:188; OwnMass/contents mass unmodeled). Nil without both.
fn get_mass(args: &[Value]) -> Result<Value, RuntimeError> {
    if std::env::var("LC_MASSDBG").is_ok() {
        let peek = parse_definition_argument(args.get(1), "GetMass").ok().flatten();
        let mass = peek.as_ref().and_then(|d| {
            HOST_CONTEXT.with(|cell| {
                cell.borrow()
                    .as_ref()
                    .and_then(|c| c.world.definition_metadata(d).map(|m| m.mass))
            })
        });
        eprintln!("MASSDBG GetMass args={args:?} -> {mass:?}");
    }
    let definition = parse_definition_argument(args.get(1), "GetMass")?;
    if let Some(definition) = definition {
        return HOST_CONTEXT.with(|cell| {
            Ok(cell
                .borrow()
                .as_ref()
                .and_then(|context| context.world.definition_metadata(&definition))
                .map(|metadata| Value::Int(metadata.mass))
                .unwrap_or(Value::Nil))
        });
    }
    let target =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "GetMass", "obj")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let id = target.or_else(|| context.object_context().map(|object| object.id()));
        let Some(id) = id else {
            return Ok(Value::Nil);
        };
        // UpdateMass: Mass = max((Def->Mass + OwnMass) * Con / FullCon, 1)
        // (C4Object.cpp:497-500); the active scope has the freshest OwnMass.
        if context.get_world_object(id).is_none() {
            return Ok(Value::Nil);
        }
        Ok(Value::Int(reflected_object_mass(
            context,
            id,
            &mut HashSet::new(),
        )))
    })
}

/// FnGrabObjectInfo (C4Script.cpp:2170-2176) -> C4Object::GrabInfo
/// (C4Object.cpp:5696-5726): `pTo` (default: the caller) takes pFrom's
/// exact info pointer, after both objects are removed from every player crew,
/// then registers the receiver with its unchanged Owner.
fn grab_object_info(args: &[Value]) -> Result<Value, RuntimeError> {
    let from = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "GrabObjectInfo",
        "from",
    )?;
    let Some(from) = from else {
        return Ok(Value::Bool(false));
    };
    let to = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "GrabObjectInfo",
        "to",
    )?;
    let result = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return None;
        };
        let active = context.object_context().map(|object| object.id());
        let Some(to) = to.or(active) else {
            return None;
        };
        if !context.ensure_object_scope(from) || !context.ensure_object_scope(to) {
            return None;
        }
        if !context.object_status_present(from) || !context.object_status_present(to) {
            return None;
        }
        if from == to {
            return Some((to, None));
        }
        let donor_has_info = context
            .object_scope(from)
            .is_some_and(|scope| scope.info_core().is_some() || scope.info_rank().is_some());
        if !donor_has_info {
            return None;
        }

        // Retire and clear the receiver's old Info before either global
        // ClearPointers call.
        let receiver_link = context.object_scope(to).and_then(ObjectScopeContext::info_link);
        if let Some(link) = receiver_link {
            if retire_host_crew_info(context, link) {
                context.record_player_command(PlayerCommand::RetireCrewInfo {
                    object_id: to,
                    link,
                });
            }
        }
        if let Some(scope) = context.object_scope_mut(to) {
            scope.set_info_rank(None);
            scope.set_info_link(None);
            scope.set_info_core(None);
            scope.info_physical = None;
            scope.record_physicals();
        }

        // ClearPointers may synchronously run CrewSelection through cursor
        // replacement. Release the host borrow so those nested callbacks see
        // and mutate the same live context, then re-read donor Info.
        drop(borrow);
        clear_player_object_pointers_host(from);
        clear_player_object_pointers_host(to);
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if !context.ensure_object_scope(from) || !context.ensure_object_scope(to) {
            return None;
        }
        let (donor_core, donor_link, donor_physical) = context
            .object_scope(from)
            .map(|scope| {
                (
                    scope.info_core().cloned().or_else(|| {
                        let rank = scope.info_rank()?;
                        let definition = scope.definition_id.as_deref()?;
                        Some(CrewObjectInfo {
                            definition_id: DefinitionId::from(definition),
                            name: context
                                .definition_metadata(definition)
                                .map(|metadata| metadata.name.clone())
                                .unwrap_or_else(|| "Clonk".to_string()),
                            rank,
                            experience: 0,
                            death_count: 0,
                        })
                    }),
                    scope.info_link(),
                    scope.info_physical,
                )
            })
            .unwrap_or((None, None, None));
        let donor_core = donor_core?;
        let donor_portrait = context
            .get_world_object(from)
            .and_then(|object| {
                object.full_state().and_then(|state| {
                    Some((state.portrait_source.clone()?, state.portrait_name.clone()?))
                })
            })
            .or_else(|| {
                context
                    .get_world_object(from)
                    .map(|object| (object.definition_id().to_string(), "1".to_string()))
            });

        if let Some(scope) = context.object_scope_mut(from) {
            scope.set_crew_status_member(false);
            scope.set_info_rank(None);
            scope.set_info_link(None);
            scope.set_info_core(None);
            scope.info_physical = None;
            scope.record_physicals();
        }

        let target_alive = context
            .object_scope(to)
            .is_some_and(ObjectScopeContext::alive);
        let linked = donor_link.filter(|link| {
            let valid = retire_host_crew_info(context, *link);
            if valid {
                context.record_player_command(PlayerCommand::RetireCrewInfo {
                    object_id: from,
                    link: *link,
                });
                relink_host_crew_info(context, *link, target_alive, !target_alive);
            }
            valid
        });
        if let Some(scope) = context.object_scope_mut(to) {
            scope.set_info_rank(Some(donor_core.rank));
            scope.set_info_link(linked);
            scope.set_info_core(Some(donor_core.clone()));
            scope.info_physical = donor_physical;
            scope.record_physicals();
            if let Some((source, name)) = donor_portrait {
                scope.set_portrait(source, name);
            }
        }
        context.record_player_command(PlayerCommand::LinkCrewInfo {
            object_id: to,
            link: linked,
            info: donor_core,
            created_entry: None,
            recruit: target_alive,
            has_died: !target_alive,
        });

        let owner = context.object_scope(to).map(ObjectScopeContext::owner);
        let callback_owner = owner.filter(|owner| {
            context.player_state(*owner).is_some()
                && context.object_status_present(to)
                && context
                    .object_effective_definition_id(to)
                    .and_then(|definition| context.definition_metadata(&definition))
                    .is_some_and(|metadata| metadata.crew_member)
        });
        if let Some(owner) = callback_owner {
            context.insert_player_crew(owner, to);
            if let Some(scope) = context.object_scope_mut(to) {
                scope.set_controller(owner);
                if scope.plr_view_range() == 0 {
                    scope.set_plr_view_range(500);
                }
            }
        }
        let donor_member = context.object_in_any_crew(from);
        let receiver_member = context.object_in_any_crew(to);
        if let Some(scope) = context.object_scope_mut(from) {
            scope.set_crew_status_member(donor_member);
        }
        if let Some(scope) = context.object_scope_mut(to) {
            scope.set_crew_status_member(receiver_member);
        }
        context.record_crew_rosters();
        Some((to, callback_owner))
    });

    let Some((to, callback_owner)) = result else {
        return Ok(Value::Bool(false));
    };
    if let Some(owner) = callback_owner {
        call_recruitment_callback(to, owner);
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return;
            };
            let donor_member = context.object_in_any_crew(from);
            let receiver_member = context.object_in_any_crew(to);
            if let Some(scope) = context.object_scope_mut(from) {
                scope.set_crew_status_member(donor_member);
            }
            if let Some(scope) = context.object_scope_mut(to) {
                scope.set_crew_status_member(receiver_member);
            }
            context.record_crew_rosters();
        });
    }
    Ok(Value::Bool(true))
}

/// FnMakeCrewMember (C4Script.cpp:2164-2168) -> C4Player::MakeCrewMember
/// (C4Player.cpp:1167-1215): valid player + CrewMember def required; assigns
/// an exact idle/new info, joins the independent roster and calls Recruitment.

/// `pObj->Call(PSF_OnJoinCrew)` where PSF_OnJoinCrew is the fail-safe
/// `~Recruitment` name and C4Object::Call uses fPassError=false.
fn call_recruitment_callback(target: ObjectId, player: i32) {
    if let Some(Err(error)) =
        call_world_object_own_function(target, "Recruitment", &[Value::Int(player)])
    {
        tracing::warn!(
            object = %target,
            error = %error,
            "script error in Recruitment callback; continuing like C++"
        );
    }
}

fn retire_host_crew_info(context: &mut EffectHostContext, link: CrewInfoLink) -> bool {
    let (entry, order) = {
        let mut state = context.world.crew_info_state.borrow_mut();
        let Some(entry) = state.entries.get_mut(&link) else {
            return false;
        };
        entry.in_action = false;
        (
            entry.clone(),
            state.order.get(&link.player_id).cloned().unwrap_or_default(),
        )
    };
    let key = (link.player_id, entry.id.clone());
    let mut state = context.world.crew_info_state.borrow_mut();
    if context.world.definition_metadata(&entry.id).is_none() {
        state.idle.remove(&key);
        return true;
    }
    let rebuilt: Vec<_> = order
        .into_iter()
        .filter_map(|candidate| {
            let info = state.entries.get(&candidate)?;
            (info.id == entry.id
                && info.participation != 0
                && !info.in_action
                && !info.has_died)
                .then(|| (candidate, info.clone()))
        })
        .collect();
    if rebuilt.is_empty() {
        state.idle.remove(&key);
    } else {
        state.idle.insert(key, rebuilt);
    }
    true
}

fn relink_host_crew_info(
    context: &mut EffectHostContext,
    link: CrewInfoLink,
    recruit: bool,
    has_died: bool,
) -> bool {
    let mut state = context.world.crew_info_state.borrow_mut();
    let Some(entry) = state.entries.get_mut(&link) else {
        return false;
    };
    entry.has_died = has_died;
    entry.in_action = recruit;
    let key = (link.player_id, entry.id.clone());
    if let Some(pool) = state.idle.get_mut(&key) {
        pool.retain(|(candidate, _)| *candidate != link);
    }
    true
}

fn recruit_or_create_crew_info(
    context: &mut EffectHostContext,
    player: i32,
    definition_id: &str,
) -> Result<
    Option<(
        CrewInfoLink,
        CrewObjectInfo,
        Option<crate::player_file::CrewInfo>,
    )>,
    RuntimeError,
> {
    let key = (player, definition_id.to_string());
    let idle = {
        let mut state = context.world.crew_info_state.borrow_mut();
        let picked = state.idle.get_mut(&key).and_then(|pool| {
            let best = pool
                .iter()
                .enumerate()
                .fold(None, |best: Option<(usize, i32)>, (index, (_, info))| {
                    match best {
                        Some((_, best_exp)) if best_exp >= info.experience => best,
                        _ => Some((index, info.experience)),
                    }
                })
                .map(|(index, _)| index)?;
            Some(pool.remove(best))
        });
        if let Some((link, _)) = picked.as_ref() {
            if let Some(entry) = state.entries.get_mut(link) {
                entry.in_action = true;
            }
        }
        picked
    };
    if let Some((link, entry)) = idle {
        let info = CrewObjectInfo {
            definition_id: DefinitionId::from(entry.id.as_str()),
            name: entry.name.clone(),
            rank: entry.rank,
            experience: entry.experience,
            death_count: entry.death_count,
        };
        return Ok(Some((link, info, None)));
    }

    let names_source = context
        .world
        .definition_crew_names
        .get(definition_id)
        .cloned()
        .or_else(|| context.world.standard_crew_names.clone());
    const C4_MAX_NAME: usize = 30;
    let mut name = match names_source {
        Some(names) if names.to_ascii_lowercase().contains("names.txt") => {
            draw_context_random(1000)?;
            "Clonk".to_string()
        }
        Some(names) => {
            let newline_count = names.bytes().filter(|&byte| byte == b'\n').count() as i32;
            let segment_index = draw_context_random(newline_count)? as usize;
            let segment = names
                .split('\n')
                .nth(segment_index)
                .unwrap_or_default()
                .replace('\r', "");
            let cleaned: String = segment.trim().chars().take(C4_MAX_NAME).collect();
            if cleaned.is_empty() {
                "Clonk".to_string()
            } else {
                cleaned
            }
        }
        None => "Clonk".to_string(),
    };

    let (link, entry) = {
        let mut state = context.world.crew_info_state.borrow_mut();
        {
            let names = state.roster_names.entry(player).or_default();
            let base = name.clone();
            let mut next_number = 2;
            while names
                .iter()
                .any(|existing| existing.eq_ignore_ascii_case(&name))
            {
                let digits = next_number.to_string();
                let keep = base
                    .chars()
                    .count()
                    .min(C4_MAX_NAME.saturating_sub(digits.len()));
                name = base.chars().take(keep).collect::<String>() + &digits;
                next_number += 1;
            }
            names.push(name.clone());
        }
        let roster_index = *state.next_indices.entry(player).or_insert(0);
        state.next_indices.insert(player, roster_index + 1);
        let link = CrewInfoLink {
            player_id: player,
            roster_index,
        };
        let entry = crate::player_file::CrewInfo {
            id: definition_id.to_string(),
            name,
            rank: 0,
            experience: 0,
            death_count: 0,
            total_playing_time: 0,
            participation: 1,
            in_action: false,
            in_action_time: 0,
            has_died: false,
        };
        state.entries.insert(link, entry.clone());
        state.order.entry(player).or_default().insert(0, link);
        (link, entry)
    };
    let info = CrewObjectInfo {
        definition_id: DefinitionId::from(entry.id.as_str()),
        name: entry.name.clone(),
        rank: entry.rank,
        experience: entry.experience,
        death_count: entry.death_count,
    };
    if let Some(player) = context.player_state_mut(player) {
        player.crew_created = player.crew_created.wrapping_add(1);
    }
    Ok(Some((link, info, Some(entry))))
}

/// Direct C4Player::MakeCrewMember mutation. Native callers such as Buy must
/// not dispatch a definition function named MakeCrewMember on the target.
fn make_crew_member_live(target: ObjectId, player: i32) -> Result<bool, RuntimeError> {
    let joined = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(false);
        };
        if context.player_state(player).is_none() {
            return Ok(false); // ValidPlr (C4Script.cpp:2166)
        }
        if !context.object_status_present(target) || !context.ensure_object_scope(target) {
            return Ok(false); // !pObj->Status (C4Player.cpp:1169)
        }
        let crew_def = context
            .object_effective_definition_id(target)
            .and_then(|definition| context.world.definition_metadata(&definition))
            .map(|metadata| metadata.crew_member)
            .unwrap_or(false);
        if !crew_def {
            return Ok(false); // Def->CrewMember required (C4Player.cpp:1170)
        }
        // C4Player::MakeCrewMember info selection (C4Player.cpp:1180-1199):
        // the gate is `!pObj->Info` — an object that already carries a crew
        // info skips; an idle info skips the New; otherwise
        // C4ObjectInfoList::New draws the name Random over the def's
        // ClonkNames (or the game standard names) — a synced ledger draw
        // that must fire INSIDE this call.
        let already_has_info = context
            .object_scope(target)
            .is_some_and(|object| object.info_rank().is_some());
        let assignment = if already_has_info {
            None
        } else {
            let Some(definition_id) = context.object_effective_definition_id(target) else {
                return Ok(false);
            };
            recruit_or_create_crew_info(context, player, definition_id.as_str())?
        };
        {
            let Some(object) = context.object_scope_mut(target) else {
                return Ok(false);
            };
            object.set_crew_member(true);
            if object.plr_view_range() == 0 {
                object.set_plr_view_range(500);
            }
            if let Some((link, info, _)) = assignment.as_ref() {
                object.set_info_rank(Some(info.rank));
                object.set_info_link(Some(*link));
                object.set_info_core(Some(info.clone()));
                let promoted = crate::crew_info_physical(object.definition_physical, info.rank);
                object.info_physical = Some(promoted);
                object.record_physicals();
            }
            // C4Player::MakeCrewMember changes Controller, never Owner
            // (C4Player.cpp:1202-1204).
            object.set_controller(player);
        }
        if let Some((link, info, created_entry)) = assignment {
            context.record_player_command(PlayerCommand::LinkCrewInfo {
                object_id: target,
                link: Some(link),
                info,
                created_entry,
                recruit: true,
                has_died: false,
            });
        }
        // C4Player::MakeCrewMember inserts into the LIVE C4Player::Crew
        // before Recruitment returns (C4Player.cpp:1194-1209). Later calls
        // in the same scenario callback must therefore see the member via
        // SelectCrew/GetCrew. Crew-member definitions take stMain's ordinary
        // category/id branch: prefer the first equal category+id link, then
        // the first link whose relative category is <= the new one
        // (C4ObjectList.cpp:110-195).
        if !context.insert_player_crew(player, target) {
            return Ok(false);
        }
        context.record_crew_rosters();
        Ok(true)
    })?;
    if joined {
        // PSF_OnJoinCrew resolves to the script function "Recruitment"
        // (C4Script.h:107 `#define PSF_OnJoinCrew "~Recruitment"`), fired
        // inside MakeCrewMember (C4Player.cpp:1206-1209). C4Object::Call's
        // default fPassError=false makes it fail-safe.
        call_recruitment_callback(target, player);
    }
    Ok(joined)
}

fn make_crew_member(args: &[Value]) -> Result<Value, RuntimeError> {
    let explicit = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "MakeCrewMember",
        "obj",
    )?;
    let player = parse_optional_i32(args.get(1), "MakeCrewMember", "player")?.unwrap_or(0);
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    });
    let Some(target) = explicit.or(active) else {
        return Ok(Value::Bool(false));
    };
    Ok(Value::Bool(make_crew_member_live(target, player)?))
}

/// FnSetMass (C4Script.cpp:3620-3626): OwnMass = value - Def->Mass, then
/// UpdateMass; foreign targets mutate in their own scope.
fn set_mass(args: &[Value]) -> Result<Value, RuntimeError> {
    let value = parse_optional_i32(args.first(), "SetMass", "mass")?.unwrap_or(0);
    let target =
        parse_object_reference_argument(args.get(1).unwrap_or(&Value::Nil), "SetMass", "obj")?;
    let active = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_context().map(|object| object.id()))
    });
    if let Some(target) = target {
        if Some(target) != active {
            return match call_world_object_function(target, "SetMass", &[Value::Int(value)]) {
                Some(result) => result,
                None => Ok(Value::Bool(false)),
            };
        }
    }
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let Some(id) = context.object_context().map(|object| object.id()) else {
            return Ok(Value::Bool(false));
        };
        // The scope's own definition id — a synchronous Initialize (the
        // ArrowPack UpdateMass at CreateContents) runs before the object
        // reaches the world/pending views, so get_world_object misses it
        // and OwnMass = iValue - Def->Mass (C4Script.cpp:3627-3631)
        // silently lost the Def->Mass term.
        let def_mass = context
            .object_context()
            .and_then(|object| object.definition_id.clone())
            .and_then(|definition_id| {
                context
                    .world
                    .definition_metadata(&definition_id)
                    .map(|metadata| metadata.mass)
            })
            .or_else(|| {
                context
                    .get_world_object(id)
                    .and_then(|object| context.world.definition_metadata(object.definition_id()))
                    .map(|metadata| metadata.mass)
            })
            .unwrap_or(0);
        let Some(object) = context.object_context_mut() else {
            return Ok(Value::Bool(false));
        };
        object.set_own_mass(value - def_mass);
        Ok(Value::Bool(true))
    })
}

/// FnMod (C4Script.cpp:3219-3223): truncated `%`, zero divisor yields 0.
fn modulo(args: &[Value]) -> Result<Value, RuntimeError> {
    let value = parse_optional_i32(args.first(), "Mod", "value")?.unwrap_or(0);
    let divisor = parse_optional_i32(args.get(1), "Mod", "divisor")?.unwrap_or(0);
    Ok(Value::Int(if divisor == 0 {
        0
    } else {
        value.wrapping_rem(divisor)
    }))
}

/// FnC4Id (C4Script.cpp:2396-2399): string to C4ID; empty/nil is C4ID_None
/// (0 — falsy, like C4Id("") in C++).
fn c4_id(args: &[Value]) -> Result<Value, RuntimeError> {
    let name = parse_optional_string(args.first(), "C4Id", "id")?;
    Ok(match name {
        Some(name) if cast_c4id_payload(&name) != 0 => Value::C4Id(name),
        _ => Value::Nil,
    })
}

/// `C4AulDefCastFunc<C4V_C4ID,C4V_Int>` (C4Script.cpp:6184-6195,
/// :7042): preserve the four-byte C4ID payload and change only its type tag.
fn scoreboard_col(args: &[Value]) -> Result<Value, RuntimeError> {
    let raw = match args.first() {
        None | Some(Value::Nil) | Some(Value::Int(0)) | Some(Value::Bool(false)) => 0,
        Some(Value::C4Id(id)) => definition_id_to_c4id(id).unwrap_or(0),
        Some(Value::Int(raw @ 1..=9999)) => *raw,
        Some(other) => {
            return Err(RuntimeError::new(format!(
                "ScoreboardCol: expected C4ID, got {}",
                other.type_name()
            )))
        }
    };
    Ok(Value::Int(raw))
}

fn pow_func(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() != 2 {
        return Err(RuntimeError::new("Pow expects 2 arguments: base, exponent"));
    }

    let base = match &args[0] {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "Pow: expected int for base, got {}",
                other.type_name()
            )))
        }
    };

    let exponent = match &args[1] {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "Pow: expected int for exponent, got {}",
                other.type_name()
            )))
        }
    };

    if exponent < 0 {
        return Ok(Value::Int(0)); // Match C++ behavior for negative exponents
    }

    Ok(Value::Int(base.pow(exponent as u32)))
}

fn bound_by_func(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() != 3 {
        return Err(RuntimeError::new(
            "BoundBy expects 3 arguments: value, min, max",
        ));
    }

    let value = match &args[0] {
        Value::Int(v) => *v,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "BoundBy: expected int for value, got {}",
                other.type_name()
            )))
        }
    };

    let range1 = match &args[1] {
        Value::Int(v) => *v,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "BoundBy: expected int for range1, got {}",
                other.type_name()
            )))
        }
    };

    let range2 = match &args[2] {
        Value::Int(v) => *v,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "BoundBy: expected int for range2, got {}",
                other.type_name()
            )))
        }
    };

    // BoundBy clamps value between range1 and range2 (order doesn't matter)
    let min = range1.min(range2);
    let max = range1.max(range2);
    Ok(Value::Int(value.clamp(min, max)))
}

pub(crate) fn sin_func(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.is_empty() || args.len() > 3 {
        return Err(RuntimeError::new(
            "Sin expects 1-3 arguments: angle, radius, precision",
        ));
    }

    let angle = match &args[0] {
        Value::Int(v) => *v,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "Sin: expected int for angle, got {}",
                other.type_name()
            )))
        }
    };

    let radius = if args.len() > 1 {
        match &args[1] {
            Value::Int(v) => *v,
            Value::Nil => 0,
            other => {
                return Err(RuntimeError::new(format!(
                    "Sin: expected int for radius, got {}",
                    other.type_name()
                )))
            }
        }
    } else {
        0
    };

    let precision = if args.len() > 2 {
        match &args[2] {
            Value::Int(v) => {
                if *v == 0 {
                    1
                } else {
                    *v
                }
            }
            Value::Nil => 1,
            other => {
                return Err(RuntimeError::new(format!(
                    "Sin: expected int for precision, got {}",
                    other.type_name()
                )))
            }
        }
    } else {
        1
    };

    // FnSin uses C4Fixed's shared SineTable; no floating-point arithmetic is
    // allowed on this lockstep path (C4Script.cpp:3224-3231; Fixed.h:188-202).
    let angle_mod = angle % (360 * precision);
    let result = fixtoi_prec(itofix_prec(angle_mod, precision).sin_deg(), radius);
    Ok(Value::Int(result))
}

pub(crate) fn cos_func(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.is_empty() || args.len() > 3 {
        return Err(RuntimeError::new(
            "Cos expects 1-3 arguments: angle, radius, precision",
        ));
    }

    let angle = match &args[0] {
        Value::Int(v) => *v,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "Cos: expected int for angle, got {}",
                other.type_name()
            )))
        }
    };

    let radius = if args.len() > 1 {
        match &args[1] {
            Value::Int(v) => *v,
            Value::Nil => 0,
            other => {
                return Err(RuntimeError::new(format!(
                    "Cos: expected int for radius, got {}",
                    other.type_name()
                )))
            }
        }
    } else {
        0
    };

    let precision = if args.len() > 2 {
        match &args[2] {
            Value::Int(v) => {
                if *v == 0 {
                    1
                } else {
                    *v
                }
            }
            Value::Nil => 1,
            other => {
                return Err(RuntimeError::new(format!(
                    "Cos: expected int for precision, got {}",
                    other.type_name()
                )))
            }
        }
    } else {
        1
    };

    // FnCos uses the same fixed-point table and scaling path
    // (C4Script.cpp:3233-3238; Fixed.h:204-218).
    let angle_mod = angle % (360 * precision);
    let result = fixtoi_prec(itofix_prec(angle_mod, precision).cos_deg(), radius);
    Ok(Value::Int(result))
}

