// ── C4FindObject / C4SortObject condition trees (C4FindObject.{h,cpp}) ──────

/// C4FO_* constants (C4FindObject.h:27-50) as a parsed condition tree.
/// Known divergences: `Layer` is unmodeled on host objects (never
/// matches); shape tests use the vertices bounding box.
#[derive(Debug, Clone)]
enum FindCondition {
    Not(Box<FindCondition>),
    And(Vec<FindCondition>),
    Or(Vec<FindCondition>),
    Exclude(Option<ObjectId>),
    Id(String),
    InRect(DefinitionRect),
    AtPoint(i32, i32),
    AtRect(DefinitionRect),
    OnLine(i32, i32, i32, i32),
    Distance {
        x: i32,
        y: i32,
        r2: i64,
        /// The enclosing square the C++ constructor precomputes for
        /// GetBounds (C4FindObject.h:253).
        bounds: DefinitionRect,
    },
    Ocf(u32),
    Category(i32),
    Action(String),
    ActionTarget {
        target: Option<ObjectId>,
        index: usize,
    },
    Container(Option<ObjectId>),
    AnyContainer,
    Owner(i32),
    Controller(i32),
    /// C4FindObjectFunc (C4FindObject.cpp:124-136): calls `name` on each
    /// candidate via the nested-call seam.
    Func {
        name: String,
        pars: Vec<Value>,
    },
    /// C4FindObjectLayer (C4FindObject.cpp:671-674): `pObj->pLayer ==
    /// pLayer` — None matches every unlayered object.
    Layer(Option<ObjectId>),
}

/// C4SO_* constants (C4FindObject.h:53-62) as a parsed sort tree.
#[derive(Debug, Clone)]
enum SortCriterion {
    Reverse(Box<SortCriterion>),
    Multiple(Vec<SortCriterion>),
    Distance {
        x: i32,
        y: i32,
    },
    Random,
    Speed,
    Mass,
    Value,
    /// C4SortObjectFunc (C4FindObject.h:521-533). Cached evaluation lands
    /// with the Sort_Func slice; until then all values compare equal.
    Func {
        name: String,
        pars: Vec<Value>,
    },
}

enum ParsedCriterion {
    Condition(FindCondition),
    Sort(SortCriterion),
    None,
}

fn value_as_object_id(value: &Value) -> Option<ObjectId> {
    match value {
        Value::Object(id) => Some(ObjectId::new(*id)),
        _ => object_id_from_value(value),
    }
}

fn value_as_i32(value: &Value) -> i32 {
    match value {
        Value::Int(value) => *value,
        Value::Bool(value) => i32::from(*value),
        _ => 0,
    }
}

impl FindCondition {
    /// `C4FindObject::CreateByValue` (C4FindObject.cpp:37-162): arrays whose
    /// first element is in C4SO_First..=C4SO_Last parse as sort criteria
    /// instead.
    fn parse(value: &Value) -> ParsedCriterion {
        // Must be an array (C4FindObject.cpp:40-41)
        let Value::Array(data) = value else {
            return ParsedCriterion::None;
        };
        let kind = data.first().map(value_as_i32).unwrap_or(0);
        if (100..=200).contains(&kind) {
            return SortCriterion::parse_typed(kind, data)
                .map(ParsedCriterion::Sort)
                .unwrap_or(ParsedCriterion::None);
        }
        let arg_i32 = |index: usize| data.get(index).map(value_as_i32).unwrap_or(0);
        let condition = match kind {
            // C4FO_Not
            1 => match data.get(1).map(Self::parse) {
                Some(ParsedCriterion::Condition(child)) => FindCondition::Not(Box::new(child)),
                _ => return ParsedCriterion::None,
            },
            // C4FO_And / C4FO_Or: trivial single-condition unwrap, dropped
            // null children (C4FindObject.cpp:67-87)
            2 | 3 => {
                let children: Vec<FindCondition> = data[1..]
                    .iter()
                    .filter_map(|entry| match Self::parse(entry) {
                        ParsedCriterion::Condition(child) => Some(child),
                        _ => None,
                    })
                    .collect();
                if data.len() == 2 {
                    match children.into_iter().next() {
                        Some(child) => child,
                        None => return ParsedCriterion::None,
                    }
                } else if kind == 2 {
                    FindCondition::And(children)
                } else {
                    FindCondition::Or(children)
                }
            }
            // C4FO_Exclude
            5 => FindCondition::Exclude(data.get(1).and_then(value_as_object_id)),
            // C4FO_InRect
            10 => FindCondition::InRect(DefinitionRect::new(
                arg_i32(1),
                arg_i32(2),
                arg_i32(3),
                arg_i32(4),
            )),
            // C4FO_AtPoint
            11 => FindCondition::AtPoint(arg_i32(1), arg_i32(2)),
            // C4FO_AtRect
            12 => FindCondition::AtRect(DefinitionRect::new(
                arg_i32(1),
                arg_i32(2),
                arg_i32(3),
                arg_i32(4),
            )),
            // C4FO_OnLine
            13 => FindCondition::OnLine(arg_i32(1), arg_i32(2), arg_i32(3), arg_i32(4)),
            // C4FO_Distance
            14 => {
                let r = arg_i32(3);
                let (x, y) = (arg_i32(1), arg_i32(2));
                FindCondition::Distance {
                    x,
                    y,
                    r2: i64::from(r) * i64::from(r),
                    // (x - r, y - r, 2r + 1, 2r + 1), C4FindObject.h:253 —
                    // wrapping like the C++ int32 arithmetic.
                    bounds: DefinitionRect::new(
                        x.wrapping_sub(r),
                        y.wrapping_sub(r),
                        r.wrapping_mul(2).wrapping_add(1),
                        r.wrapping_mul(2).wrapping_add(1),
                    ),
                }
            }
            // C4FO_ID
            20 => match data.get(1) {
                Some(Value::C4Id(id)) => FindCondition::Id(id.clone()),
                Some(Value::String(id)) => FindCondition::Id(id.clone()),
                _ => return ParsedCriterion::None,
            },
            // C4FO_OCF
            21 => FindCondition::Ocf(arg_i32(1) as u32),
            // C4FO_Category
            22 => FindCondition::Category(arg_i32(1)),
            // C4FO_Action
            30 => match data.get(1) {
                Some(Value::String(name)) => FindCondition::Action(name.clone()),
                _ => return ParsedCriterion::None,
            },
            // C4FO_ActionTarget (index clamped to 0..=1, C4FindObject.cpp:138-144)
            31 => FindCondition::ActionTarget {
                target: data.get(1).and_then(value_as_object_id),
                index: arg_i32(2).clamp(0, 1) as usize,
            },
            // C4FO_Container
            40 => FindCondition::Container(data.get(1).and_then(value_as_object_id)),
            // C4FO_AnyContainer
            41 => FindCondition::AnyContainer,
            // C4FO_Owner
            50 => FindCondition::Owner(arg_i32(1)),
            // C4FO_Controller
            51 => FindCondition::Controller(arg_i32(1)),
            // C4FO_Func: Data[1] must convert to a string, else the whole
            // criterion is dropped (C4FindObject.cpp:127-128); Data[2] →
            // par 0, capped at 10 pars (SetPar, C4FindObject.cpp:645-651)
            60 => match data.get(1) {
                Some(Value::String(name)) => FindCondition::Func {
                    name: name.clone(),
                    pars: data.iter().skip(2).take(10).cloned().collect(),
                },
                _ => return ParsedCriterion::None,
            },
            // C4FO_Layer: Data[1].getObj(), nil = the unlayered world
            // (C4FindObject.cpp:157-159).
            70 => FindCondition::Layer(data.get(1).and_then(value_as_object_id)),
            _ => return ParsedCriterion::None,
        };
        ParsedCriterion::Condition(condition)
    }

    /// Per-condition Check (C4FindObject.cpp:390-679). Fallible because a
    /// `Func` callback error passes through (`fPassErrors=true`,
    /// C4FindObject.cpp:661); And/Or evaluate children in array order with
    /// short-circuit, so Func side effects land in C++ order.
    fn check(
        &self,
        world: &impl WorldAccessor,
        object: &HostWorldObject,
    ) -> Result<bool, RuntimeError> {
        Ok(match self {
            FindCondition::Not(child) => !child.check(world, object)?,
            FindCondition::And(children) => {
                for child in children {
                    if !child.check(world, object)? {
                        return Ok(false);
                    }
                }
                true
            }
            FindCondition::Or(children) => {
                for child in children {
                    if child.check(world, object)? {
                        return Ok(true);
                    }
                }
                false
            }
            FindCondition::Exclude(excluded) => Some(object.id) != *excluded,
            FindCondition::Id(id) => object.definition_id() == id,
            FindCondition::InRect(rect) => {
                // C4FindObjectInRect::Check is a plain point-in-rect on the
                // object CENTER (C4FindObject.cpp) — the old
                // contains_offset(pos - rect.xy) clause double-subtracted
                // the origin and matched far-away objects whose offset
                // happened to land back inside (the 597 NoDmg class).
                let position = object.position();
                position.x >= rect.x
                    && position.x < rect.x + rect.width
                    && position.y >= rect.y
                    && position.y < rect.y + rect.height
            }
            FindCondition::AtPoint(x, y) => {
                let metadata = world.definition_metadata(object.definition_id());
                compute_object_bounds(object, metadata.as_ref())
                    .map(|(left, top, right, bottom)| {
                        *x >= left && *x < right && *y >= top && *y < bottom
                    })
                    .unwrap_or(false)
            }
            FindCondition::AtRect(rect) => {
                let metadata = world.definition_metadata(object.definition_id());
                compute_object_bounds(object, metadata.as_ref())
                    .map(|(left, top, right, bottom)| {
                        rect.x < right
                            && rect.x + rect.width > left
                            && rect.y < bottom
                            && rect.y + rect.height > top
                    })
                    .unwrap_or(false)
            }
            FindCondition::OnLine(x1, y1, x2, y2) => {
                let metadata = world.definition_metadata(object.definition_id());
                compute_object_bounds(object, metadata.as_ref())
                    .map(|bounds| segment_intersects_bounds(*x1, *y1, *x2, *y2, bounds))
                    .unwrap_or(false)
            }
            FindCondition::Distance { x, y, r2, .. } => {
                let position = object.position();
                let dx = i64::from(position.x - x);
                let dy = i64::from(position.y - y);
                dx * dx + dy * dy <= *r2
            }
            FindCondition::Ocf(mask) => object.ocf() & mask != 0,
            FindCondition::Category(category) => object.category() & category != 0,
            FindCondition::Action(name) => object.action_name() == name,
            FindCondition::ActionTarget { target, index } => {
                object.action_target(*index) == *target
            }
            FindCondition::Container(container) => object.container() == *container,
            FindCondition::AnyContainer => object.container().is_some(),
            FindCondition::Owner(owner) => object.owner() == *owner,
            // C4FindObjectController::Check (C4FindObject.cpp:628-631).
            FindCondition::Controller(controller) => object.controller() == *controller,
            // C4FindObjectFunc::Check (C4FindObject.cpp:653-662): no
            // overload visible to the object's def → silently false; the
            // result converts with raw C4Value truthiness, not getBool.
            FindCondition::Func { name, pars } => {
                match call_world_object_function(object.id, name, pars) {
                    None => false,
                    Some(result) => value_raw_truthy(&result?),
                }
            }
            // C4FindObjectLayer::Check (C4FindObject.cpp:671-674).
            FindCondition::Layer(layer) => {
                object.full_state().and_then(|state| state.layer) == *layer
            }
        })
    }

    /// IsImpossible/IsEnsured pruning (C4FindObject.cpp:453-590). `Func` is
    /// impossible only when the name is unknown to every script
    /// (GetFirstFunc miss at construction, C4FindObject.cpp:640-643,
    /// 664-667); Not swaps the two (C4FindObject.h:116-117).
    fn is_impossible(&self, world: &impl WorldAccessor) -> bool {
        match self {
            FindCondition::Not(child) => child.is_ensured(world),
            FindCondition::And(children) => children.iter().any(|child| child.is_impossible(world)),
            FindCondition::Or(children) => {
                !children.iter().any(|child| !child.is_impossible(world))
            }
            FindCondition::InRect(rect) => rect.width == 0 || rect.height == 0,
            FindCondition::Ocf(mask) => *mask == 0,
            FindCondition::Func { name, .. } => !world.script_function_known(name),
            _ => false,
        }
    }

    fn is_ensured(&self, world: &impl WorldAccessor) -> bool {
        match self {
            FindCondition::Not(child) => child.is_impossible(world),
            // C4FindObjectAnd::IsEnsured is `!iCnt` AFTER the constructor
            // filtered ensured children (C4FindObject.h:135) — recursively:
            // ensured iff every child is.
            FindCondition::And(children) => {
                children.iter().all(|child| child.is_ensured(world))
            }
            // C4FindObjectOr::IsEnsured (C4FindObject.cpp:514-520)
            FindCondition::Or(children) => {
                children.iter().any(|child| child.is_ensured(world))
            }
            FindCondition::Category(category) => *category == 0,
            _ => false,
        }
    }

    /// The construction-time pruning of C4FindObjectAnd/Or
    /// (C4FindObject.cpp:400-410, 466-476), bottom-up like CreateByValue:
    /// And drops ensured children (whose Check may still be false —
    /// Category(0), C4FindObject.cpp:582-590), Or drops impossible ones
    /// (which would otherwise kill the sibling bounds). The drivers prune
    /// once before Check/bounds/IsImpossible run, matching the C++ tree.
    fn pruned(self, world: &impl WorldAccessor) -> FindCondition {
        match self {
            FindCondition::Not(child) => FindCondition::Not(Box::new(child.pruned(world))),
            FindCondition::And(children) => FindCondition::And(
                children
                    .into_iter()
                    .map(|child| child.pruned(world))
                    .filter(|child| !child.is_ensured(world))
                    .collect(),
            ),
            FindCondition::Or(children) => FindCondition::Or(
                children
                    .into_iter()
                    .map(|child| child.pruned(world))
                    .filter(|child| !child.is_impossible(world))
                    .collect(),
            ),
            other => other,
        }
    }

    /// GetBounds + UseShapes (C4FindObject.h:93-94): `Some((rect, shapes))`
    /// when the criteria bound the search area — the drivers then walk the
    /// sector lists (shape lists when `shapes`) instead of the master list.
    fn bounds(&self) -> Option<(DefinitionRect, bool)> {
        match self {
            // C4FindObjectAnd constructor (C4FindObject.cpp:411-434): a
            // bounded shapes child wins outright ("some objects might be in
            // an rect and at a point not in that rect"); otherwise all
            // bounded children intersect.
            FindCondition::And(children) => {
                let mut bounds: Option<DefinitionRect> = None;
                for child in children {
                    if let Some((child_bounds, child_shapes)) = child.bounds() {
                        if child_shapes {
                            return Some((child_bounds, true));
                        }
                        bounds = Some(match bounds {
                            Some(rect) => rect_intersect_cpp(rect, child_bounds),
                            None => child_bounds,
                        });
                    }
                }
                bounds.map(|rect| (rect, false))
            }
            // C4FindObjectOr constructor (C4FindObject.cpp:477-496): the
            // union of all child bounds; a boundless or shapes child (which
            // could report an object twice) kills the bounds entirely.
            FindCondition::Or(children) => {
                let mut bounds: Option<DefinitionRect> = None;
                for child in children {
                    match child.bounds() {
                        None | Some((_, true)) => return None,
                        Some((child_bounds, false)) => {
                            bounds = Some(match bounds {
                                Some(rect) => rect_add_cpp(rect, child_bounds),
                                None => child_bounds,
                            });
                        }
                    }
                }
                bounds.map(|rect| (rect, false))
            }
            FindCondition::InRect(rect) => Some((*rect, false)),
            FindCondition::AtPoint(x, y) => Some((DefinitionRect::new(*x, *y, 1, 1), true)),
            FindCondition::AtRect(rect) => Some((*rect, true)),
            // bounds(x, y, 1, 1) + Add((x2, y2, 1, 1)), C4FindObject.h:234-237
            FindCondition::OnLine(x1, y1, x2, y2) => Some((
                rect_add_cpp(
                    DefinitionRect::new(*x1, *y1, 1, 1),
                    DefinitionRect::new(*x2, *y2, 1, 1),
                ),
                true,
            )),
            FindCondition::Distance { bounds, .. } => Some((*bounds, false)),
            _ => None,
        }
    }

    /// Whether any node needs the nested-call seam (drives the borrow-free
    /// snapshot-view evaluation path in the drivers).
    fn uses_func(&self) -> bool {
        match self {
            FindCondition::Not(child) => child.uses_func(),
            FindCondition::And(children) | FindCondition::Or(children) => {
                children.iter().any(FindCondition::uses_func)
            }
            FindCondition::Func { .. } => true,
            _ => false,
        }
    }
}

/// C4Rect::Intersect (C4Rect.cpp:101-133): narrow `a` to the overlap with
/// `b`; a degenerated result clamps to zero size.
fn rect_intersect_cpp(a: DefinitionRect, b: DefinitionRect) -> DefinitionRect {
    let mut result = a;
    if b.x > result.x {
        if b.x + b.width < result.x + result.width {
            result.x = b.x;
            result.width = b.width;
        } else {
            result.width -= b.x - result.x;
            result.x = b.x;
        }
    } else if b.x + b.width < result.x + result.width {
        result.width = b.x + b.width - result.x;
    }
    if b.y > result.y {
        if b.y + b.height < result.y + result.height {
            result.y = b.y;
            result.height = b.height;
        } else {
            result.height -= b.y - result.y;
            result.y = b.y;
        }
    } else if b.y + b.height < result.y + result.height {
        result.height = b.y + b.height - result.y;
    }
    result.width = result.width.max(0);
    result.height = result.height.max(0);
    result
}

/// C4Rect::Add (C4Rect.cpp:153-185): expand `a` to cover `b`; a null rect
/// on either side leaves the other unchanged.
fn rect_add_cpp(a: DefinitionRect, b: DefinitionRect) -> DefinitionRect {
    if b.width == 0 || b.height == 0 {
        return a;
    }
    if a.width == 0 || a.height == 0 {
        return b;
    }
    let mut result = a;
    if b.x < result.x {
        if b.x + b.width > result.x + result.width {
            result.x = b.x;
            result.width = b.width;
        } else {
            result.width += result.x - b.x;
            result.x = b.x;
        }
    } else if b.x + b.width > result.x + result.width {
        result.width = b.x + b.width - result.x;
    }
    if b.y < result.y {
        if b.y + b.height > result.y + result.height {
            result.y = b.y;
            result.height = b.height;
        } else {
            result.height += result.y - b.y;
            result.y = b.y;
        }
    } else if b.y + b.height > result.y + result.height {
        result.height = b.y + b.height - result.y;
    }
    result
}

/// Axis-aligned segment/box intersection for C4FO_OnLine (the C++ uses
/// `Shape.IntersectsLine`; the host shape is its vertices bounding box).
fn segment_intersects_bounds(
    x1: i32,
    y1: i32,
    x2: i32,
    y2: i32,
    bounds: (i32, i32, i32, i32),
) -> bool {
    let (left, top, right, bottom) = bounds;
    let inside = |x: i32, y: i32| x >= left && x < right && y >= top && y < bottom;
    if inside(x1, y1) || inside(x2, y2) {
        return true;
    }
    // sample the segment at integer steps (sufficient for the pixel grid)
    let steps = (x2 - x1).abs().max((y2 - y1).abs());
    for step in 0..=steps {
        let x = x1 + (x2 - x1) * step / steps.max(1);
        let y = y1 + (y2 - y1) * step / steps.max(1);
        if inside(x, y) {
            return true;
        }
    }
    false
}

impl SortCriterion {
    /// `C4SortObject::CreateByValue` (C4FindObject.cpp:683-758).
    fn parse_typed(kind: i32, data: &[Value]) -> Option<SortCriterion> {
        let arg_i32 = |index: usize| data.get(index).map(value_as_i32).unwrap_or(0);
        Some(match kind {
            // C4SO_Reverse
            101 => SortCriterion::Reverse(Box::new(data.get(1).and_then(Self::parse)?)),
            // C4SO_Multiple (trivial single unwrap, C4FindObject.cpp:705-726)
            102 => {
                let children: Vec<SortCriterion> =
                    data[1..].iter().filter_map(Self::parse).collect();
                if data.len() == 2 {
                    children.into_iter().next()?
                } else {
                    SortCriterion::Multiple(children)
                }
            }
            // C4SO_Distance
            110 => SortCriterion::Distance {
                x: arg_i32(1),
                y: arg_i32(2),
            },
            // C4SO_Random
            120 => SortCriterion::Random,
            // C4SO_Speed
            130 => SortCriterion::Speed,
            // C4SO_Mass
            140 => SortCriterion::Mass,
            // C4SO_Value
            150 => SortCriterion::Value,
            // C4SO_Func: string name required, else nullptr
            // (C4FindObject.cpp:743-755); pars capped at 10
            160 => match data.get(1) {
                Some(Value::String(name)) => SortCriterion::Func {
                    name: name.clone(),
                    pars: data.iter().skip(2).take(10).cloned().collect(),
                },
                _ => return None,
            },
            _ => return None,
        })
    }

    /// Whether any node needs the nested-call seam.
    fn uses_func(&self) -> bool {
        match self {
            SortCriterion::Reverse(child) => child.uses_func(),
            SortCriterion::Multiple(children) => children.iter().any(SortCriterion::uses_func),
            // C4SO_Value calls C4Object::GetValue, which may dispatch the
            // definition's CalcValue script just like C4SO_Func.
            SortCriterion::Value | SortCriterion::Func { .. } => true,
            _ => false,
        }
    }

    fn parse(value: &Value) -> Option<SortCriterion> {
        let Value::Array(data) = value else {
            return None;
        };
        Self::parse_typed(data.first().map(value_as_i32).unwrap_or(0), data)
    }

    /// `CompareGetValue` (C4FindObject.cpp:908-956). `Random` draws the
    /// synced `Random(1 << 16)` — exactly once per object, in collection
    /// order, via the cache (C4SortObjectByValue::PrepareCache). `Func`
    /// runs the nested call: no overload → 0 silently, the result converts
    /// with `getInt()` (bools 0/1, pointer types 0), and callback errors
    /// pass through (`fPassErrors=true`, C4FindObject.cpp:947-956).
    fn value_for(
        &self,
        world: &impl WorldAccessor,
        object: &HostWorldObject,
    ) -> Result<i64, RuntimeError> {
        Ok(match self {
            SortCriterion::Distance { x, y } => {
                let position = object.position();
                let dx = position.x.wrapping_sub(*x);
                let dy = position.y.wrapping_sub(*y);
                // int32 wrap like C4SortObjectDistance
                // (C4FindObject.cpp:908-911, CompareGetValue is int32_t).
                i64::from(dx.wrapping_mul(dx).wrapping_add(dy.wrapping_mul(dy)))
            }
            SortCriterion::Random => RANDOM_CONTEXT.with(|cell| {
                cell.borrow()
                    .as_ref()
                    .map(|context| i64::from(context.rng.borrow_mut().random(1 << 16)))
                    .unwrap_or(0)
            }),
            SortCriterion::Speed => {
                // C4SortObjectSpeed's C4Fixed sum reaches int32_t through
                // the IMPLICIT `operator bool` (Fixed.h:117, the only
                // conversion C4Fixed offers): the key is 0/1 "moving at
                // all". The fixed squares truncate (val²/65536), so raw
                // |dir| < 256 keys 0 too. Live fixed dirs come from the
                // script-call snapshot; the int-mirror fallback only
                // misses sub-1/256-px movers.
                let (vx, vy) = object
                    .full_state()
                    .and_then(|state| state.script_fixed_velocity)
                    .map(|fixed| (fixed.x.val(), fixed.y.val()))
                    .unwrap_or_else(|| {
                        let velocity = object.velocity();
                        (
                            velocity.x.wrapping_mul(1 << 16),
                            velocity.y.wrapping_mul(1 << 16),
                        )
                    });
                let square = |v: i32| ((i64::from(v) * i64::from(v)) / (1 << 16)) as i32;
                i64::from(square(vx).wrapping_add(square(vy)) != 0)
            }
            SortCriterion::Mass => {
                // pFor->Mass is the LIVE UpdateMass field, including
                // contents unless NoComponentMass (C4Object.cpp:497-505).
                i64::from(sort_object_mass(world, object.id))
            }
            SortCriterion::Value => i64::from(
                get_value(&[
                    object_reference_value(object.id),
                    Value::Nil,
                    Value::Nil,
                    Value::Int(OWNER_NONE),
                ])?
                .as_c4_int()
                .unwrap_or(0),
            ),
            SortCriterion::Func { name, pars } => {
                match call_world_object_function(object.id, name, pars) {
                    None => 0,
                    Some(result) => i64::from(result?.as_c4_int().unwrap_or(0)),
                }
            }
            SortCriterion::Reverse(_) | SortCriterion::Multiple(_) => 0,
        })
    }

    /// `C4SortObject::SortObjects` (C4FindObject.cpp:784-812): per-criterion
    /// value caches computed in collection order, then a stable sort with
    /// `Compare > 0` ⇒ ascending by value (smallest first).
    fn sort(&self, world: &impl WorldAccessor, ids: &mut [ObjectId]) -> Result<(), RuntimeError> {
        let keys = self.cache_keys(world, ids)?;
        let mut order: Vec<usize> = (0..ids.len()).collect();
        order.sort_by(|&a, &b| Self::compare_keys(&keys[a], &keys[b]));
        let sorted: Vec<ObjectId> = order.iter().map(|&index| ids[index]).collect();
        ids.copy_from_slice(&sorted);
        Ok(())
    }

    /// Per-object key vectors: flattened (criterion, direction) values so
    /// Reverse/Multiple compose like the C++ Compare chain.
    fn cache_keys(
        &self,
        world: &impl WorldAccessor,
        ids: &[ObjectId],
    ) -> Result<Vec<Vec<i64>>, RuntimeError> {
        let mut keys = vec![Vec::new(); ids.len()];
        self.fill_keys(world, ids, &mut keys, false)?;
        Ok(keys)
    }

    fn fill_keys(
        &self,
        world: &impl WorldAccessor,
        ids: &[ObjectId],
        keys: &mut [Vec<i64>],
        reverse: bool,
    ) -> Result<(), RuntimeError> {
        match self {
            SortCriterion::Reverse(child) => child.fill_keys(world, ids, keys, !reverse)?,
            SortCriterion::Multiple(children) => {
                for child in children {
                    child.fill_keys(world, ids, keys, reverse)?;
                }
            }
            _ => {
                let sign = if reverse { -1 } else { 1 };
                for (index, id) in ids.iter().enumerate() {
                    let value = match world.get_object(*id) {
                        Some(object) => self.value_for(world, &object)?,
                        None => 0,
                    };
                    keys[index].push(sign * value);
                }
            }
        }
        Ok(())
    }

    fn compare_keys(a: &[i64], b: &[i64]) -> std::cmp::Ordering {
        for (lhs, rhs) in a.iter().zip(b.iter()) {
            match lhs.cmp(rhs) {
                std::cmp::Ordering::Equal => continue,
                other => return other,
            }
        }
        std::cmp::Ordering::Equal
    }

    /// The UNCACHED `Compare(obj1, obj2)` used by the single-result Find
    /// path (C4FindObject.cpp:834-842): `CompareGetValue` runs for obj1
    /// then obj2 in hardcoded order, returning `value2 - value1` (>0 ⇒
    /// obj1 sorts first). Reverse swaps the arguments
    /// (C4FindObject.cpp:856-859); Multiple returns the first nonzero
    /// child comparison (C4FindObject.cpp:885-895).
    fn compare_uncached(
        &self,
        world: &impl WorldAccessor,
        obj1: &HostWorldObject,
        obj2: &HostWorldObject,
    ) -> Result<i64, RuntimeError> {
        match self {
            SortCriterion::Reverse(child) => child.compare_uncached(world, obj2, obj1),
            SortCriterion::Multiple(children) => {
                for child in children {
                    let result = child.compare_uncached(world, obj1, obj2)?;
                    if result != 0 {
                        return Ok(result);
                    }
                }
                Ok(0)
            }
            _ => {
                let value1 = self.value_for(world, obj1)?;
                let value2 = self.value_for(world, obj2)?;
                Ok(value2 - value1)
            }
        }
    }
}

/// The single-result Find with a sort attached (C4FindObject.cpp:272-308).
/// Bounded criteria walk the per-sector lists: the inner
/// `Find(*pLst)` (C4FindObject.cpp:186-199) keeps a running best PER LIST
/// — replaced when the uncached `Compare(candidate, best)` is positive —
/// and only each list's winner meets the outer running best
/// (C4FindObject.cpp:287-293/299-305). The unbounded walk is the
/// single-list case. No PrepareCache — value functions (and `C4SO_Random`
/// draws) run per comparison, so the pairing is lockstep-relevant. The
/// UseShapes lists carry no Marker: a shape spanning sectors is compared
/// in every list holding it.
fn find_first_with_sort(
    world: &impl WorldAccessor,
    condition: &FindCondition,
    sort: &SortCriterion,
) -> Result<Option<ObjectId>, RuntimeError> {
    if condition.is_impossible(world) {
        return Ok(None);
    }
    let lists = condition
        .bounds()
        .and_then(|(rect, use_shapes)| {
            if use_shapes {
                world.shape_sector_id_lists_in_rect(rect)
            } else {
                world.object_sector_id_lists_in_rect(rect)
            }
        })
        .unwrap_or_else(|| vec![world.object_ids()]);
    let mut best: Option<(ObjectId, HostWorldObject)> = None;
    for ids in lists {
        // inner Find(*pLst): the per-list best
        let mut list_best: Option<(ObjectId, HostWorldObject)> = None;
        for object_id in ids {
            let Some(object) = world.get_object(object_id) else {
                continue;
            };
            if !object.status().is_active() {
                continue;
            }
            if !condition.check(world, &object)? {
                continue;
            }
            list_best = match list_best {
                None => Some((object_id, object)),
                Some((best_id, best_object)) => {
                    if sort.compare_uncached(world, &object, &best_object)? > 0 {
                        Some((object_id, object))
                    } else {
                        Some((best_id, best_object))
                    }
                }
            };
        }
        // outer walk: the list winner vs the running best
        if let Some((list_id, list_object)) = list_best {
            best = match best {
                None => Some((list_id, list_object)),
                Some((best_id, best_object)) => {
                    if sort.compare_uncached(world, &list_object, &best_object)? > 0 {
                        Some((list_id, list_object))
                    } else {
                        Some((best_id, best_object))
                    }
                }
            };
        }
    }
    Ok(best.map(|(id, _)| id))
}

/// `CreateCriterionsFromPars` (C4Script.cpp:1985-2034): each argument array
/// parses as a condition or sort; conditions AND together, sorts merge into
/// a Multiple; no conditions at all is a script error.
fn parse_criterions(args: &[Value]) -> Option<(FindCondition, Option<SortCriterion>)> {
    let mut conditions = Vec::new();
    let mut sorts = Vec::new();
    for arg in args {
        // The first nil parameter ends the criteria list
        // (`if (!Data) break;`, C4Script.cpp:1996).
        if matches!(arg, Value::Nil) {
            break;
        }
        match FindCondition::parse(arg) {
            ParsedCriterion::Condition(condition) => conditions.push(condition),
            ParsedCriterion::Sort(sort) => sorts.push(sort),
            ParsedCriterion::None => {}
        }
    }
    if conditions.is_empty() {
        return None;
    }
    let condition = if conditions.len() == 1 {
        conditions.into_iter().next().expect("one condition")
    } else {
        FindCondition::And(conditions)
    };
    let sort = match sorts.len() {
        0 => None,
        1 => sorts.into_iter().next(),
        _ => Some(SortCriterion::Multiple(sorts)),
    };
    Some((condition, sort))
}

/// The C++ bounded-vs-full walk decision (C4FindObject.cpp:315-328):
/// criteria bounds pick the sector walk — the ObjectShapes lists (with
/// first-encounter dedup standing in for the Marker) when the criteria use
/// shapes, the per-sector point lists otherwise. Boundless criteria — or a
/// world without a sector map (legacy fixture contexts) — walk the master
/// list.
fn find_candidate_ids(world: &impl WorldAccessor, condition: &FindCondition) -> Vec<ObjectId> {
    condition
        .bounds()
        .and_then(|(rect, use_shapes)| {
            if use_shapes {
                world.shape_sector_ids_in_rect(rect)
            } else {
                world.object_sector_ids_in_rect(rect)
            }
        })
        .unwrap_or_else(|| world.object_ids())
}

/// Collect matches in C++ walk order (C4FindObject::FindMany,
/// C4FindObject.cpp:203-226 unbounded, :310-355 sector-bounded).
fn find_condition_matches(
    world: &impl WorldAccessor,
    condition: &FindCondition,
) -> Result<Vec<ObjectId>, RuntimeError> {
    if condition.is_impossible(world) {
        return Ok(Vec::new());
    }
    let mut matches = Vec::new();
    for object_id in find_candidate_ids(world, condition) {
        let Some(object) = world.get_object(object_id) else {
            continue;
        };
        if !object.status().is_active() {
            continue;
        }
        if condition.check(world, &object)? {
            matches.push(object_id);
        }
    }
    Ok(matches)
}

/// Whether the criteria need the borrow-free Func evaluation path.
fn criterions_use_func(condition: &FindCondition, sort: Option<&SortCriterion>) -> bool {
    condition.uses_func() || sort.map(SortCriterion::uses_func).unwrap_or(false)
}

/// FnFindObject2 (C4Script.cpp:2052-2067).
fn find_object2(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some((condition, sort)) = parse_criterions(args) else {
        return Err(RuntimeError::new(
            "FindObject: No valid search criterions supplied!",
        ));
    };
    if criterions_use_func(&condition, sort.as_ref()) {
        let Some(view) = snapshot_func_find_view() else {
            return Ok(Value::Nil);
        };
        let condition = condition.pruned(&view);
        if let Some(sort) = sort {
            return Ok(find_first_with_sort(&view, &condition, &sort)?
                .map(object_reference_value)
                .unwrap_or(Value::Nil));
        }
        let mut matches = find_condition_matches(&view, &condition)?;
        retain_live_nested(&mut matches);
        return Ok(matches
            .first()
            .map(|id| object_reference_value(*id))
            .unwrap_or(Value::Nil));
    }
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let condition = condition.pruned(context);
        if let Some(sort) = sort {
            return Ok(find_first_with_sort(context, &condition, &sort)?
                .map(object_reference_value)
                .unwrap_or(Value::Nil));
        }
        let matches = find_condition_matches(context, &condition)?;
        Ok(matches
            .first()
            .map(|id| object_reference_value(*id))
            .unwrap_or(Value::Nil))
    })
}

/// FnFindObjects array form (C4Script.cpp:2069-2084).
fn find_objects2(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some((condition, sort)) = parse_criterions(args) else {
        return Err(RuntimeError::new(
            "FindObjects: No valid search criterions supplied!",
        ));
    };
    if criterions_use_func(&condition, sort.as_ref()) {
        let Some(view) = snapshot_func_find_view() else {
            return Ok(Value::Array(Vec::new()));
        };
        let condition = condition.pruned(&view);
        let mut matches = find_condition_matches(&view, &condition)?;
        // Pre-sort: erase objects deleted during Check
        // (C4FindObject.cpp:217-218).
        retain_live_nested(&mut matches);
        if let Some(sort) = sort {
            sort.sort(&view, &mut matches)?;
        }
        // Post-sort: objects deleted by sort callbacks keep their slot as
        // nil (CheckObjectStatusAfterSort, C4FindObject.cpp:223,372-375).
        return Ok(Value::Array(HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            matches
                .into_iter()
                .map(|id| {
                    if borrow
                        .as_ref()
                        .map(|context| context.nested_object_destroyed(id))
                        .unwrap_or(false)
                    {
                        Value::Nil
                    } else {
                        object_reference_value(id)
                    }
                })
                .collect()
        })));
    }
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Array(Vec::new()));
        };
        let condition = condition.pruned(context);
        let mut matches = find_condition_matches(context, &condition)?;
        if let Some(sort) = sort {
            sort.sort(context, &mut matches)?;
        }
        Ok(Value::Array(
            matches.into_iter().map(object_reference_value).collect(),
        ))
    })
}

/// FnObjectCount2 (C4Script.cpp:2036-2050).
fn object_count2(args: &[Value]) -> Result<Value, RuntimeError> {
    let Some((condition, _)) = parse_criterions(args) else {
        return Err(RuntimeError::new(
            "ObjectCount: No valid search criterions supplied!",
        ));
    };
    if criterions_use_func(&condition, None) {
        let Some(view) = snapshot_func_find_view() else {
            return Ok(Value::Int(0));
        };
        let condition = condition.pruned(&view);
        if condition.is_ensured(&view) {
            let count = view
                .master_object_ids()
                .into_iter()
                .filter(|id| {
                    view.get_object(*id)
                        .is_some_and(|object| object.status().is_active())
                })
                .count();
            return Ok(Value::Int(truncate_to_i32(count as u64)));
        }
        let matches = find_condition_matches(&view, &condition)?;
        return Ok(Value::Int(truncate_to_i32(matches.len() as u64)));
    }
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Int(0));
        };
        let condition = condition.pruned(context);
        if condition.is_ensured(context) {
            let count = context
                .master_object_ids()
                .into_iter()
                .filter(|id| {
                    context
                        .get_world_object(*id)
                        .is_some_and(|object| object.status().is_active())
                })
                .count();
            return Ok(Value::Int(truncate_to_i32(count as u64)));
        }
        Ok(Value::Int(truncate_to_i32(
            find_condition_matches(context, &condition)?.len() as u64,
        )))
    })
}

fn find_object(args: &[Value]) -> Result<Value, RuntimeError> {
    find_object_cpp(args, "FindObject", None)
}

/// FnFindBase/C4Game::FindBase (C4Script.cpp:1976-1979;
/// C4Game.cpp:3732-3744): validate the player, then walk the active object
/// master list and return the indexed object whose stored Base matches.
fn find_base(args: &[Value]) -> Result<Value, RuntimeError> {
    let player = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "FindBase",
        "player",
    )?;
    let mut index = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "FindBase",
        "index",
    )?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        if context.player_state(player).is_none() || index < 0 {
            return Ok(Value::Nil);
        }
        for object_id in context.master_object_ids() {
            let Some(object) = context.get_world_object(object_id) else {
                continue;
            };
            if !object.status().is_active()
                || object.full_state().map(|state| state.base) != Some(player)
            {
                continue;
            }
            if index == 0 {
                return Ok(object_reference_value(object_id));
            }
            index -= 1;
        }
        Ok(Value::Nil)
    })
}

/// Shared FnFindObject search (C4Script.cpp:2113-2135) with an optional
/// owner filter injected by FindObjectOwner (C4Script.cpp:2137-2161).
fn find_object_cpp(
    args: &[Value],
    function: &str,
    owner_override: Option<i32>,
) -> Result<Value, RuntimeError> {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };
        let mut params = FindObjectParams::parse_cpp_call(args, function, context.caller_scope())?;
        if let Some(owner) = owner_override {
            params.owner = owner;
        }
        let result = if params.is_closest_query() {
            find_object_closest(context, &params)
        } else {
            find_object_linear(context, &params)
        };
        Ok(match result {
            Some(id) => object_reference_value(id),
            None => Value::Nil,
        })
    })
}

fn find_object_owner(args: &[Value]) -> Result<Value, RuntimeError> {
    // FnFindObjectOwner (C4Script.cpp:2137-2161): FindObject with the
    // owner filter as the SECOND parameter; an owner that is neither a
    // valid player nor NO_OWNER returns nil before any search. The
    // remaining arguments shift by one; exclude/container are not
    // script-settable here (C++ passes caller-exclusion and null).
    if args.len() > 10 {
        return Err(RuntimeError::new(
            "FindObjectOwner: expected at most 10 arguments",
        ));
    }
    let owner = parse_optional_i32(args.get(1), "FindObjectOwner", "owner")?.unwrap_or(0);
    let owner_valid = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        borrow
            .as_ref()
            .map(|context| owner == OWNER_NONE || context.player_state(owner).is_some())
            .unwrap_or(false)
    });
    if !owner_valid {
        return Ok(Value::Nil);
    }
    let mut remapped: Vec<Value> = Vec::with_capacity(10);
    remapped.push(args.first().cloned().unwrap_or(Value::Nil)); // id
    for slot in 2..=5 {
        remapped.push(args.get(slot).cloned().unwrap_or(Value::Nil)); // x y wdt hgt
    }
    remapped.push(args.get(6).cloned().unwrap_or(Value::Nil)); // ocf
    remapped.push(args.get(7).cloned().unwrap_or(Value::Nil)); // action
    remapped.push(args.get(8).cloned().unwrap_or(Value::Nil)); // action target
    remapped.push(Value::Nil); // container (not script-settable here)
    remapped.push(args.get(9).cloned().unwrap_or(Value::Nil)); // find next
    find_object_cpp(&remapped, "FindObjectOwner", Some(owner))
}

/// C4Game::FindObject (C4Game.cpp:1334-1424): the legacy single-result
/// search scans the MASTER list for every query form — first master-order
/// match wins; sectors are never consulted (unlike the criteria form).
fn find_object_linear(world: &impl WorldAccessor, params: &FindObjectParams) -> Option<ObjectId> {
    let mut skip_until = params.find_next;
    for object_id in world.master_object_ids() {
        let Some(object) = world.get_object(object_id) else {
            continue;
        };
        if let Some(target) = skip_until {
            if object_id == target {
                skip_until = None;
            }
            continue;
        }
        if !params.matches_object(&object) {
            continue;
        }
        if params.matches_area(world, &object) {
            return Some(object_id);
        }
    }
    None
}

fn find_object_closest(world: &impl WorldAccessor, params: &FindObjectParams) -> Option<ObjectId> {
    let reference = params.reference_distance(world);
    let mut best: Option<(ObjectId, i64)> = None;
    for object_id in params.candidate_ids(world) {
        let Some(object) = world.get_object(object_id) else {
            continue;
        };
        if !params.matches_object(&object) {
            continue;
        }
        let distance = squared_distance(object.position(), params.x, params.y);
        if let Some(reference) = reference {
            if distance <= reference {
                continue;
            }
        }
        match best {
            None => best = Some((object_id, distance)),
            Some((_, best_distance)) if distance < best_distance => {
                best = Some((object_id, distance));
            }
            _ => {}
        }
    }
    best.map(|(id, _)| id)
}

/// C++ `FindObjects` is the array-criteria form (C4Script.cpp:7043); the
/// legacy fixed-parameter form predates it in this port and is kept for the
/// existing fixtures. Array first argument → C++ semantics.
fn find_objects_dispatch(args: &[Value]) -> Result<Value, RuntimeError> {
    if matches!(args.first(), Some(Value::Array(_))) {
        find_objects2(args)
    } else {
        find_objects(args)
    }
}

/// `System.c4g/FindObject.c`'s `Find_AtPoint` wrapper: its coordinates are
/// relative to the calling object, or to the world origin in global context.
fn find_at_point(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "Find_AtPoint",
        "x",
    )?;
    let y = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "Find_AtPoint",
        "y",
    )?;
    let origin = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(EffectHostContext::object_context)
            .map(ObjectScopeContext::effective_position)
            .unwrap_or(Vector2::ZERO)
    });
    Ok(Value::Array(vec![
        Value::Int(11),
        Value::Int(origin.x.wrapping_add(x)),
        Value::Int(origin.y.wrapping_add(y)),
    ]))
}

/// `System.c4g/FindObject.c`'s `Find_Category` wrapper: construct the
/// two-cell C4FO_Category criterion consumed by `FindObjects`.
fn find_category(args: &[Value]) -> Result<Value, RuntimeError> {
    let category = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "Find_Category",
        "category",
    )?;
    Ok(Value::Array(vec![Value::Int(22), Value::Int(category)]))
}

/// `System.c4g/FindObject.c`'s `Find_ID` wrapper: preserve the typed C4ID in
/// the two-cell criterion consumed by `FindObject2`/`FindObjects`.
fn find_id(args: &[Value]) -> Result<Value, RuntimeError> {
    let id = match args.first().unwrap_or(&Value::Nil) {
        Value::C4Id(id) => Value::C4Id(id.clone()),
        Value::Nil => Value::Nil,
        Value::Int(raw @ 0..=9999) => Value::C4Id(render_c4id(*raw)),
        other => {
            return Err(RuntimeError::new(format!(
                "Find_ID: expected id for definition, got {}",
                other.type_name()
            )))
        }
    };
    Ok(Value::Array(vec![Value::Int(20), id]))
}

fn find_objects(args: &[Value]) -> Result<Value, RuntimeError> {
    let params = FindObjectParams::parse(args)?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Array(Vec::new())),
        };
        let ids = if params.is_closest_query() {
            collect_closest_matches(context, &params)
        } else {
            collect_linear_matches(context, &params)
        };
        let values = ids
            .into_iter()
            .map(object_reference_value)
            .collect::<Vec<_>>();
        Ok(Value::Array(values))
    })
}

fn object_count(args: &[Value]) -> Result<Value, RuntimeError> {
    // FnObjectCount (C4Script.cpp:2085-2111): the FindObject layout with
    // iOwner instead of pFindNext as the 10th parameter; an owner of 0
    // becomes ANY_OWNER ("incomplete useless implementation").
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Int(0)),
        };
        let mut params = FindObjectParams::parse_cpp_call(
            &args[..args.len().min(9)],
            "ObjectCount",
            context.caller_scope(),
        )?;
        let owner = parse_optional_i32(args.get(9), "ObjectCount", "owner")?.unwrap_or(0);
        params.owner = if owner == 0 { OWNER_ANY } else { owner };
        let matches_len = if params.is_closest_query() {
            collect_closest_matches(context, &params).len()
        } else {
            collect_linear_matches(context, &params).len()
        };
        Ok(Value::Int(truncate_to_i32(matches_len as u64)))
    })
}

/// FnObjectNumber (C4Script.cpp:3321-3325): return C4Object::Number, defaulting
/// a nil/omitted object to the current script object. Number is the immutable
/// C4Game::ObjectEnumerationIndex allocation, not an index into either object
/// list; therefore object status and list membership do not affect this read.
fn object_number(args: &[Value]) -> Result<Value, RuntimeError> {
    let explicit = match args.first() {
        Some(Value::Object(0)) | Some(Value::Nil) | None => None,
        Some(Value::Object(number)) => Some(*number),
        Some(other) => {
            return Err(RuntimeError::new(format!(
                "ObjectNumber: expected object or nil for object, got {}",
                other.type_name()
            )))
        }
    };
    let number = explicit.or_else(|| {
        HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(EffectHostContext::object_context)
                .map(|object| object.id().as_u64())
        })
    });

    Ok(number.map_or(Value::Nil, |number| {
        Value::Int(truncate_to_i32(number))
    }))
}

/// FnObject (C4Script.cpp:3327-3330): resolve an exact saved object Number.
/// SafeObjectPointer rejects only deleted status; inactive objects remain
/// addressable (C4ObjectList.cpp:544-557, C4GameObjects.cpp:270-276).
fn object_by_number(args: &[Value]) -> Result<Value, RuntimeError> {
    let number = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "Object",
        "number",
    )?;
    let Some(id) = (number > 0).then(|| ObjectId::new(number as u64)) else {
        return Ok(Value::Nil);
    };

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let status = context
            .get_world_object(id)
            .map(|object| object.status())
            .or_else(|| {
                context.object_scope(id).map(|scope| {
                    if scope.destroy {
                        ObjectStatus::Deleted
                    } else {
                        scope.status()
                    }
                })
            });
        Ok(if status.is_some_and(|status| status != ObjectStatus::Deleted) {
            object_reference_value(id)
        } else {
            Value::Nil
        })
    })
}

fn collect_linear_matches(world: &impl WorldAccessor, params: &FindObjectParams) -> Vec<ObjectId> {
    let mut matches = Vec::new();
    let mut skip_until = params.find_next;
    for object_id in params.candidate_ids(world) {
        let Some(object) = world.get_object(object_id) else {
            continue;
        };
        if let Some(target) = skip_until {
            if object_id == target {
                skip_until = None;
            }
            continue;
        }
        if params.matches_object(&object) && params.matches_area(world, &object) {
            matches.push(object_id);
        }
    }
    matches
}

fn collect_closest_matches(world: &impl WorldAccessor, params: &FindObjectParams) -> Vec<ObjectId> {
    let reference = params.reference_distance(world);
    let mut matches = Vec::new();
    for (order_index, object_id) in params.candidate_ids(world).into_iter().enumerate() {
        let Some(object) = world.get_object(object_id) else {
            continue;
        };
        if !params.matches_object(&object) {
            continue;
        }
        let distance = squared_distance(object.position(), params.x, params.y);
        if let Some(reference) = reference {
            if distance <= reference {
                continue;
            }
        }
        matches.push((distance, order_index, object_id));
    }
    matches.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
    matches.into_iter().map(|(_, _, id)| id).collect()
}

fn set_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    if std::env::var("LC_DIRDBG").is_ok() && !matches!(args.first(), Some(Value::Int(_))) {
        eprintln!("DIRDBG SetDir args={args:?}");
    }
    // Unfilled ndir is nil -> 0 = DIR_Left; native int parameters also
    // accept C4Value bools through CheckConvertFunctionParameters
    // (C4AulExec.cpp:1364-1396; C4Value.cpp:514-518).
    let raw_direction = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetDir",
        "direction",
    )?;

    let direction = Direction::from_raw(raw_direction);

    let mut index = 1;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "SetDir", "target")?;

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetDir: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetDir requires an active engine context"))?;
        // FnSetDir works on ANY object (`if (!pObj) pObj = cthr->Obj`) —
        // GoldRush's init calls SetDir(1, pHorse) from the scenario
        // scope. Foreign writes stage into the target's nested scope.
        let active = context.object_context().map(|object| object.id());
        if let Some(target) = target_id {
            if Some(target) != active {
                if !context.nested_objects.contains_key(&target) {
                    let Some(world_object) = context.get_world_object(target) else {
                        return Ok(Value::Bool(false));
                    };
                    let Some((scope, local_vars)) = context.nested_scope_for(&world_object)
                    else {
                        return Ok(Value::Bool(false));
                    };
                    context
                        .nested_objects
                        .insert(target, NestedScopeState { scope, local_vars });
                }
                if !context.nested_order.contains(&target) {
                    context.nested_order.push(target);
                }
                let state = context
                    .nested_objects
                    .get_mut(&target)
                    .expect("scope just ensured");
                let scope = &mut state.scope;
                // The same C4Object::SetDir gates as the self path; the
                // TurnAction fires through the staged action update.
                let action_name = scope.effective_action_name().to_string();
                if scope.action_library.is_idle_action(&action_name) {
                    return Ok(Value::Bool(true));
                }
                let directions = scope.action_library.directions_for(&action_name) as i32;
                if direction.to_script_value() < 0
                    || direction.to_script_value() >= directions
                {
                    return Ok(Value::Bool(true));
                }
                if scope.direction() != direction {
                    if let Some(turn_action) = scope
                        .action_library
                        .turn_action_for(&action_name)
                        .map(str::to_string)
                    {
                        if scope.action_library.contains(&turn_action) {
                            let update = scope
                                .pending_update
                                .action
                                .get_or_insert_with(ActionUpdate::default);
                            update.set_name(turn_action.clone());
                            update.set_force(false);
                            scope.update_effective_action(&turn_action);
                        }
                    }
                }
                scope.set_direction(direction);
                return Ok(Value::Bool(true));
            }
        }
        let object = match context.object_context_mut() {
            Some(object) => object,
            None => return Ok(Value::Bool(false)),
        };

        // C4Object::SetDir (C4Object.cpp:4225-4245): a no-op on idle
        // objects and out-of-range directions (Directions defaults 1 —
        // single-direction actions reject SetDir(1)); a CHANGE fires the
        // action's TurnAction through SetActionByName first.
        let action_name = object.effective_action_name().to_string();
        if object.action_library.is_idle_action(&action_name) {
            return Ok(Value::Bool(true));
        }
        let directions = object.action_library.directions_for(&action_name) as i32;
        if direction.to_script_value() < 0 || direction.to_script_value() >= directions {
            return Ok(Value::Bool(true));
        }
        let turn_action = (object.direction() != direction)
            .then(|| {
                object
                    .action_library
                    .turn_action_for(&action_name)
                    .map(str::to_string)
            })
            .flatten();
        drop(borrow);
        if let Some(turn_action) = turn_action {
            let _ = set_action(&[Value::String(turn_action)])?;
        }
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let context = borrow
                .as_mut()
                .ok_or_else(|| RuntimeError::new("SetDir requires an active engine context"))?;
            if let Some(object) = context.object_context_mut() {
                object.set_direction(direction);
            }
            Ok(Value::Bool(true))
        })
    })
}

fn get_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "GetDir", "target")?;

    if index < args.len() {
        return Err(RuntimeError::new(
            "GetDir: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };
        if let Some(target) = target_id {
            if let Some(object) = context.object_context() {
                if target == object.id() {
                    return Ok(Value::Int(object.direction().to_script_value()));
                }
            }
            // FnGetDir reads ANY pObj's Action.Dir (C4Script.cpp:1118-1122;
            // `if (!pObj) pObj = cthr->Obj` is only the local-call default —
            // an explicit target needs NO object context: GoldRush's
            // WINC->ActualizePhase(pClonk) reads GetDir(pClonk) from a
            // DEFINITION call, Winchester.c4d/Script.c:118-121). The CLNK
            // Riding() PhaseCall does SetDir(GetDir(GetActionTarget()))
            // on the ridden vehicle — a Nil here flipped riders Left.
            return Ok(context
                .get_world_object(target)
                .map(|other| Value::Int(other.direction))
                .unwrap_or(Value::Nil));
        }

        match context.object_context() {
            Some(object) => Ok(Value::Int(object.direction().to_script_value())),
            None => Ok(Value::Nil),
        }
    })
}

fn set_r(args: &[Value]) -> Result<Value, RuntimeError> {
    // Unfilled nr is nil -> 0 (FnSetR, C4Script.cpp:737).
    let rotation = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetR", "rotation")?;

    let mut index = 1;
    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        target_id = parse_object_reference_argument(arg, "SetR", "object")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetR: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetR requires an active engine context"))?;
        let target = target_id.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };

        object.set_rotation(rotation);
        Ok(Value::Bool(true))
    })
}

fn script_rotation(rotation: i32) -> i32 {
    let rotation = rotation % 360;
    if rotation > 180 {
        rotation - 360
    } else if rotation < -180 {
        rotation + 360
    } else {
        rotation
    }
}

fn get_r(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new("GetR expects at most 1 argument: target"));
    }

    let target_id =
        parse_object_reference_argument(args.first().unwrap_or(&Value::Nil), "GetR", "target")?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        if let Some(target) = target_id {
            if let Some(object) = context.object_scope(target) {
                return Ok(Value::Int(script_rotation(object.rotation())));
            }
            if let Some(other) = context.get_world_object(target) {
                return Ok(Value::Int(script_rotation(other.rotation)));
            }
            return Ok(Value::Nil);
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Nil),
        };

        Ok(Value::Int(script_rotation(object.rotation())))
    })
}

fn set_com_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    // Unfilled ncomdir is nil -> 0 = COMD_Stop (FnSetComDir,
    // C4Script.cpp:791, C4Object.h:56-57).
    let raw_direction = match args.first().unwrap_or(&Value::Nil) {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "SetComDir: expected int or nil for command direction, got {}",
                other.type_name()
            )))
        }
    };

    let command_direction = CommandDirection::from_raw(raw_direction);

    let mut index = 1;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "SetComDir", "target")?;

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetComDir: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetComDir requires an active engine context"))?;
        let target = target_id.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };

        object.set_command_direction(command_direction);
        Ok(Value::Bool(true))
    })
}

fn get_com_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "GetComDir", "target")?;

    if index < args.len() {
        return Err(RuntimeError::new(
            "GetComDir: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };
        if let Some(target) = target_id {
            if let Some(object) = context.object_scope(target) {
                return Ok(Value::Int(
                    object.command_direction().to_script_value(),
                ));
            }
            return Ok(context
                .get_world_object(target)
                .map(|object| {
                    Value::Int(
                        object
                            .full_state()
                            .map(|state| state.command_direction)
                            .unwrap_or_default()
                            .to_script_value(),
                    )
                })
                .unwrap_or(Value::Nil));
        }

        match context.object_context() {
            Some(object) => Ok(Value::Int(object.command_direction().to_script_value())),
            None => Ok(Value::Nil),
        }
    })
}

fn command_data_value(data: &CommandData) -> Value {
    match data {
        CommandData::Integer(value) => Value::Int(*value),
        CommandData::Text(value) => Value::String(value.clone()),
        CommandData::None => Value::Nil,
    }
}

/// Host-preview twin of C4Command::Fail's ExecFail tail. ExecuteCommand runs
/// inside a script VM call, so CallFailed/BuildNeedsMaterial and the ComDir
/// stop must be visible before the next script instruction and before
/// ControlCommandFinished.
fn preview_command_failure_feedback(
    actor: ObjectId,
    feedback: CommandFailureFeedback,
) -> Result<(), RuntimeError> {
    let crew = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        context
            .object_scope(actor)
            .map(|scope| scope.ocf() & ocf::CREW_MEMBER != 0)
            .or_else(|| {
                context
                    .get_world_object(actor)
                    .map(|object| object.ocf & ocf::CREW_MEMBER != 0)
            })
            .unwrap_or(false)
    });
    if !crew {
        return Ok(());
    }

    let command = feedback.command;
    match command.name.as_str() {
        "Call" => {
            if let (Some(target), CommandData::Text(text)) =
                (command.target, &command.data)
            {
                if !text.is_empty() {
                    let args = [
                        object_reference_value(actor),
                        command
                            .tx_definition
                            .clone()
                            .map(Value::C4Id)
                            .or_else(|| command.tx.map(Value::Int))
                            .unwrap_or(Value::Nil),
                        Value::Int(command.ty.unwrap_or(0)),
                        command
                            .target2
                            .map(object_reference_value)
                            .unwrap_or(Value::Nil),
                    ];
                    let handled = call_object_own_fail_safe(
                        target,
                        &format!("{text}Failed"),
                        &args,
                    )
                    .as_bool();
                    if handled {
                        return Ok(());
                    }
                }
            }
        }
        "Build" => {
            if let Some(target) = command.target {
                let (component, count) = HOST_CONTEXT.with(|cell| {
                    let borrow = cell.borrow();
                    let Some(context) = borrow.as_ref() else {
                        return (None, 0);
                    };
                    let scope = context.object_scope(target);
                    let state = context
                        .get_world_object(target)
                        .and_then(|object| object.full_state().cloned());
                    let components = scope
                        .and_then(|scope| scope.pending_update.components.as_ref())
                        .or_else(|| state.as_deref().map(|state| &state.components));
                    let order = scope
                        .and_then(|scope| scope.pending_update.component_order.as_ref())
                        .or_else(|| state.as_deref().map(|state| &state.component_order));
                    let Some(id) = order.and_then(|order| order.first()).cloned() else {
                        return (None, 0);
                    };
                    let count = components
                        .and_then(|components| components.get(&id))
                        .copied()
                        .unwrap_or(0);
                    (Some(id), count)
                });
                // A truthy result suppresses only the generated material
                // message; the common Stop still runs.
                let handled = call_object_own_fail_safe(
                    actor,
                    "BuildNeedsMaterial",
                    &[
                        component.map(Value::C4Id).unwrap_or(Value::Nil),
                        Value::Int(count),
                    ],
                )
                .as_bool();
                if !handled {
                    // Even when presentation is deferred, constructing the
                    // message runs target GetCustomComponents synchronously.
                    let _ = get_needed_mat_str(&[object_reference_value(target)])?;
                }
            }
        }
        _ => {}
    }

    if !object_has_status(actor) {
        return Ok(());
    }
    let silent_commands = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return false;
        };
        context
            .object_effective_definition_id(actor)
            .and_then(|id| context.definition_metadata(&id))
            .is_some_and(|metadata| metadata.silent_commands)
    });
    if silent_commands {
        return Ok(());
    }
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        if context.ensure_object_scope(actor) {
            if let Some(scope) = context.object_scope_mut(actor) {
                scope.set_command_direction(CommandDirection::Stop);
            }
        }
    });
    Ok(())
}

/// Host-preview form of ObjectActionJump used by C4Command::Grab's
/// scale/hangle let-go. ExecuteCommand runs inside the VM, so both the
/// OnActionJump hook and Jump action callbacks must complete before the
/// caller's next script instruction (C4ObjectCom.cpp:48-61,310-314).
fn preview_object_action_jump(
    target: ObjectId,
    velocity: FixedVec2,
) -> Result<bool, RuntimeError> {
    let handled = call_object_own_fail_safe(
        target,
        "OnActionJump",
        &[
            Value::Int(fixtoi_prec(velocity.x, 100)),
            Value::Int(fixtoi_prec(velocity.y, 100)),
            Value::Bool(true),
        ],
    );
    if value_raw_truthy(&handled) {
        return Ok(true);
    }
    if !native_set_action_by_name(target, "Jump")? {
        return Ok(false);
    }
    HOST_CONTEXT.with(|cell| {
        if let Some(object) = cell
            .borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(target))
        {
            object.set_fixed_velocity(velocity);
            object.set_mobile(true);
            object.set_t_attach(object.t_attach() & !CNAT_BOTTOM);
        }
    });
    Ok(true)
}

/// Synchronous host twin of ObjectComUnGrab. ObjectComDrop invokes this
/// after its Exit callbacks and NoCollectDelay update, before ExecuteCommand
/// may run ControlCommandFinished (C4ObjectCom.cpp:261-278,640-676).
fn preview_object_com_ungrab(
    actor: ObjectId,
    restore_fight_ready: bool,
) -> Result<bool, RuntimeError> {
    let target = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if !context.ensure_object_scope(actor) {
            return None;
        }
        let scope = context.object_scope_mut(actor)?;
        if scope.effective_action_procedure() != ActionProcedure::Push {
            return None;
        }
        let target = scope.effective_action_target(0);
        scope.set_command_direction(CommandDirection::Stop);
        Some(target)
    });
    let Some(target) = target else {
        return Ok(false);
    };

    // SetActionByName("Walk") performs a full SetOCF before its action
    // callbacks. Preserve the pre-Drop FightReady capability underneath a
    // callback-installed ObjectDisabled Push action so changing to Walk can
    // expose it again; NoCollectDelay still keeps Collection disabled.
    HOST_CONTEXT.with(|cell| {
        if let Some(scope) = cell
            .borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(actor))
        {
            if restore_fight_ready && scope.ocf() & ocf::ALIVE != 0 {
                let cached = scope.cached_ocf.unwrap_or_else(|| scope.ocf());
                scope.cached_ocf = Some(cached | ocf::FIGHT_READY);
            }
        }
    });
    if !native_set_action_by_name(actor, "Walk")? {
        return Ok(false);
    }
    HOST_CONTEXT.with(|cell| {
        if let Some(scope) = cell
            .borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(actor))
        {
            scope.set_fixed_velocity(FixedVec2::ZERO);
        }
    });
    let target_value = target.map(object_reference_value).unwrap_or(Value::Nil);
    let _ = call_object_own_fail_safe(actor, "Grab", &[target_value, Value::Bool(false)]);
    if let Some(target) = target.filter(|target| object_is_present(*target)) {
        let _ = call_object_own_fail_safe(
            target,
            "Grabbed",
            &[object_reference_value(actor), Value::Bool(false)],
        );
    }
    Ok(true)
}

/// Synchronous host preview of ObjectComDrop for script ExecuteCommand.
/// Item/actor state, callbacks, delay and cached OCF are staged here in C++
/// order before the outer script call folds back into the engine.
fn preview_object_com_drop(actor: ObjectId, object: ObjectId) -> Result<bool, RuntimeError> {
    let prepared = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if !context.ensure_object_scope(actor) || !context.ensure_object_scope(object) {
            return None;
        }
        let actor_scope = context.object_scope(actor)?;
        let throw_force = crate::math::val_by_physical(
            400,
            actor_scope.resolved_physical(false).throw,
        );
        let procedure = actor_scope.effective_action_procedure();
        let command_direction = actor_scope.command_direction();
        let actor_xdir = actor_scope.fixed_velocity().x;
        let actor_position = actor_scope.effective_position();
        let actor_shape = live_object_shape(context, actor).unwrap_or_default();
        let object_shape = live_object_shape(context, object).unwrap_or_default();
        let restore_fight_ready = actor_scope.ocf() & ocf::FIGHT_READY != 0;
        Some((
            throw_force,
            procedure,
            command_direction,
            actor_xdir,
            actor_position,
            actor_shape,
            object_shape,
            restore_fight_ready,
        ))
    });
    let Some((
        throw_force,
        procedure,
        command_direction,
        actor_xdir,
        actor_position,
        actor_shape,
        object_shape,
        restore_fight_ready,
    )) = prepared
    else {
        return Ok(false);
    };

    let com_dir_like = |sample: CommandDirection| {
        let com = command_direction.to_script_value();
        let sample = sample.to_script_value();
        com == sample || com % 8 + 1 == sample || com == sample % 8 + 1
    };
    let hangling_or_swimming = matches!(procedure, ActionProcedure::Hang | ActionProcedure::Swim);
    let mut throw_direction = 0;
    let mut right = 0;
    let mut outpos_reduction = 1;
    if procedure != ActionProcedure::Scale {
        if com_dir_like(CommandDirection::Left) {
            throw_direction = -1;
            if actor_xdir < fixed10(15) && !hangling_or_swimming {
                outpos_reduction -= 1;
            }
        }
        if com_dir_like(CommandDirection::Right) {
            throw_direction = 1;
            right = 1;
            if actor_xdir > -fixed10(15) && !hangling_or_swimming {
                outpos_reduction -= 1;
            }
        }
    }
    let edge = actor_shape
        .x
        .wrapping_add(actor_shape.width.wrapping_mul(right));
    let exit_position = Vector2::new(
        actor_position.x.wrapping_add(
            edge.wrapping_mul(i32::from(throw_direction != 0))
                .wrapping_mul(outpos_reduction),
        ),
        actor_position
            .y
            .wrapping_add(actor_shape.y)
            .wrapping_add(actor_shape.height)
            .wrapping_sub(object_shape.y.wrapping_add(object_shape.height)),
    );
    let velocity = FixedVec2::new(throw_force * throw_direction, C4Fixed::ZERO);
    let _ = exit_object_at_position_with_motion_and_calls(
        object,
        exit_position,
        velocity,
        C4Fixed::ZERO,
        true,
    )?;

    // The first SetOCF happened in Exit before Ejection. This explicit
    // ObjectComDrop update happens after Departure and before UnGrab.
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        if !context.ensure_object_scope(actor) {
            return;
        }
        if let Some(scope) = context.object_scope_mut(actor) {
            scope.set_no_collect_delay(2);
        }
        let _ = refresh_live_object_ocf(context, actor);
        if let Some(scope) = context.object_scope_mut(actor) {
            scope.cached_ocf = Some(scope.ocf() & !ocf::COLLECTION);
            scope.record_no_collect_delay_assignment();
            scope.persist_final_ocf = true;
        }
    });
    let _ = preview_object_com_ungrab(actor, restore_fight_ready)?;
    Ok(true)
}

fn preview_object_com_stop_for_grab(actor: ObjectId) -> Result<(), RuntimeError> {
    let _ = native_set_action_by_name(actor, "Idle")?;
    HOST_CONTEXT.with(|cell| {
        if let Some(scope) = cell
            .borrow_mut()
            .as_mut()
            .and_then(|context| context.object_scope_mut(actor))
        {
            scope.set_command_direction(CommandDirection::Stop);
        }
    });
    if native_set_action_by_name(actor, "Walk")? {
        HOST_CONTEXT.with(|cell| {
            if let Some(scope) = cell
                .borrow_mut()
                .as_mut()
                .and_then(|context| context.object_scope_mut(actor))
            {
                scope.set_fixed_velocity(FixedVec2::ZERO);
            }
        });
    }
    Ok(())
}

fn preview_object_com_grab(actor: ObjectId, target: ObjectId) -> Result<bool, RuntimeError> {
    let walking = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_scope(actor))
            .is_some_and(|scope| scope.effective_action_procedure() == ActionProcedure::Walk)
    });
    if !walking
        || !native_set_action_by_name_with_target(actor, "Push", Some(target))?
    {
        return Ok(false);
    }
    if !preview_object_is_present(actor) {
        return Ok(true);
    }
    let _ = call_object_own_fail_safe(
        actor,
        "Grab",
        &[object_reference_value(target), Value::Bool(true)],
    );
    if !preview_object_is_present(actor) || !preview_object_is_present(target) {
        return Ok(true);
    }
    let controller = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_scope(actor))
            .map(ObjectScopeContext::controller)
            .unwrap_or(OWNER_NONE)
    });
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        if let Some(context) = borrow.as_mut() {
            if context.ensure_object_scope(target) {
                if let Some(scope) = context.object_scope_mut(target) {
                    scope.set_controller(controller);
                }
            }
        }
    });
    let _ = call_object_own_fail_safe(
        target,
        "Grabbed",
        &[object_reference_value(actor), Value::Bool(true)],
    );
    Ok(true)
}

/// Synchronous host preview for CommandEvent::AttemptGrab. The regular
/// engine applies the same event before its command-finished tail; this
/// form preserves ObjectComStop, At, MoveTo and callback ordering inside
/// script-level ExecuteCommand too.
fn preview_grab_attempt(actor: ObjectId, target: ObjectId) -> Result<(), RuntimeError> {
    let (initial_procedure, offsets) = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if !context.ensure_object_scope(actor) {
            return None;
        }
        let object = context.object_scope(actor)?;
        Some((
            object.effective_action_procedure(),
            object
                .live_commands
                .pending_grab_offsets(target)
                .unwrap_or((0, 0)),
        ))
    })
    .unwrap_or((ActionProcedure::Undefined, (0, 0)));

    let mut stopped_for_grab = false;
    if matches!(
        initial_procedure,
        ActionProcedure::Build | ActionProcedure::Chop
    ) {
        stopped_for_grab = true;
        preview_object_com_stop_for_grab(actor)?;
    }
    let procedure_after_build_or_chop = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_scope(actor))
            .map(ObjectScopeContext::effective_action_procedure)
            .unwrap_or(ActionProcedure::Undefined)
    });
    if procedure_after_build_or_chop == ActionProcedure::Dig {
        stopped_for_grab = true;
        preview_object_com_stop_for_grab(actor)?;
    }

    let snapshots = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let objects = context.command_runtime_data().0;
        Some((objects.get(&actor)?.clone(), objects.get(&target).cloned()))
    });
    let Some((actor_snapshot, target_snapshot)) = snapshots else {
        return Ok(());
    };

    if actor_snapshot.action_procedure == ActionProcedure::Push {
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return;
            };
            let Some(scope) = context.object_scope_mut(actor) else {
                return;
            };
            let _ = scope.live_commands.resolve_grab_attempt(target, false);
            let _ = scope.live_commands.push_front(
                CommandRequest::new(CommandId::UnGrab)
                    .with_update_interval(50)
                    .with_mode(CommandMode::SilentSub),
            );
            scope.command_stack_replaced = true;
            scope.command_count = scope.live_commands.len();
        });
        return Ok(());
    }

    if stopped_for_grab {
        let failed = HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return false;
            };
            let Some(scope) = context.object_scope_mut(actor) else {
                return false;
            };
            let failed = scope
                .live_commands
                .fail_pending_grab_if_target_cleared(target);
            if failed {
                scope.command_stack_replaced = true;
                scope.command_count = scope.live_commands.len();
            }
            failed
        });
        if failed {
            return Ok(());
        }
    }

    let Some(target_snapshot) = target_snapshot else {
        return Ok(());
    };

    let target_at_actor = actor_snapshot.container.is_none()
        && !target_snapshot.destroyed
        && target_snapshot.status != ObjectStatus::Deleted
        && target_snapshot.container.is_none()
        && target_snapshot.ocf & ocf::ALL != 0
        && target_snapshot.at_point(actor_snapshot.position.x, actor_snapshot.position.y);
    if !target_at_actor {
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return;
            };
            let Some(scope) = context.object_scope_mut(actor) else {
                return;
            };
            let retained = scope
                .live_commands
                .resolve_grab_attempt(target, false)
                .unwrap_or(true);
            if retained {
                let _ = scope.live_commands.push_front(
                    CommandRequest::new(CommandId::MoveTo)
                        .with_tx(Some(target_snapshot.position.x.wrapping_add(offsets.0)))
                        .with_ty(Some(target_snapshot.position.y.wrapping_add(offsets.1)))
                        .with_update_interval(50)
                        .with_mode(CommandMode::SilentSub),
                );
            }
            scope.command_stack_replaced = true;
            scope.command_count = scope.live_commands.len();
        });
        return Ok(());
    }

    let let_go_xdir = matches!(
        actor_snapshot.action_procedure,
        ActionProcedure::Scale | ActionProcedure::Hang
    )
    .then_some(if actor_snapshot.direction == Direction::Left {
        1
    } else {
        -1
    });
    if let Some(xdir) = let_go_xdir {
        let _ = preview_object_action_jump(
            actor,
            FixedVec2::new(itofix(xdir), C4Fixed::ZERO),
        )?;
    }

    let rejected = preview_object_is_present(target)
        && call_object_own_fail_safe(
            target,
            "RejectGrabbed",
            &[object_reference_value(actor)],
        )
        .as_bool();
    if !preview_object_is_present(actor) {
        return Ok(());
    }
    let target_retained = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return true;
        };
        if let Some(object) = context.object_scope_mut(actor) {
            let resolution = object
                .live_commands
                .resolve_grab_attempt(target, rejected);
            if resolution.is_some() {
                object.command_stack_replaced = true;
                object.command_count = object.live_commands.len();
            }
            if rejected {
                return resolution.unwrap_or(true);
            }
            object.set_command_direction(CommandDirection::Stop);
            return resolution.unwrap_or(true);
        }
        true
    });
    if rejected {
        return Ok(());
    }
    if target_retained {
        let _ = preview_object_com_grab(actor, target)?;
    }
    Ok(())
}

fn execute_command(args: &[Value]) -> Result<Value, RuntimeError> {
    let active = active_object_id();
    let target = match args.first() {
        Some(value) => parse_object_reference_argument(value, "ExecuteCommand", "target")?
            .or(active),
        None => active,
    };
    let Some(target) = target else {
        return Ok(Value::Bool(false));
    };
    if active != Some(target) {
        return match call_world_object_function(target, "ExecuteCommand", &[]) {
            Some(result) => result,
            None => Ok(Value::Bool(false)),
        };
    }

    let random = RANDOM_CONTEXT.with(|cell| cell.borrow().clone());
    let preview = HOST_CONTEXT.with(|cell| {
        cell.borrow_mut().as_mut().and_then(|context| {
            context.execute_command_preview(target, random.as_ref().map(|rng| &rng.rng))
        })
    });
    let Some((mut finished, grab_attempts, drop_attempts, failure_feedback)) = preview else {
        return Ok(Value::Bool(false));
    };

    let had_live_attempt = !grab_attempts.is_empty()
        || !drop_attempts.is_empty()
        || !failure_feedback.is_empty();
    for (actor_id, target_id) in grab_attempts {
        preview_grab_attempt(actor_id, target_id)?;
        while let Some(feedback) = HOST_CONTEXT.with(|cell| {
            cell.borrow_mut()
                .as_mut()
                .and_then(|context| context.object_scope_mut(actor_id))
                .and_then(|scope| scope.live_commands.take_failure_feedback())
        }) {
            preview_command_failure_feedback(actor_id, feedback)?;
        }
    }
    for (actor_id, object_id) in drop_attempts {
        let _ = preview_object_com_drop(actor_id, object_id)?;
        HOST_CONTEXT.with(|cell| {
            cell.borrow_mut()
                .as_mut()
                .and_then(|context| context.object_scope_mut(actor_id))
            .map(|scope| scope.live_commands.finish_pending_drop())
        });
    }
    for (actor_id, feedback) in failure_feedback {
        preview_command_failure_feedback(actor_id, feedback)?;
    }
    if had_live_attempt {
        finished = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.object_scope(target))
                .and_then(|scope| scope.live_commands.finished_front_view())
        });
    }

    if let Some(command) = finished {
        let callback_args = [
            Value::String(command.name),
            command
                .target
                .map(object_reference_value)
                .unwrap_or(Value::Nil),
            command
                .tx_definition
                .map(Value::C4Id)
                .or_else(|| command.tx.map(Value::Int))
                .unwrap_or(Value::Nil),
            Value::Int(command.ty.unwrap_or(0)),
            command
                .target2
                .map(object_reference_value)
                .unwrap_or(Value::Nil),
            command_data_value(&command.data),
        ];
        if object_has_status(target) {
            if let Some(Err(error)) = call_world_object_function(
                target,
                "ControlCommandFinished",
                &callback_args,
            ) {
                tracing::warn!(
                    %error,
                    "script error in ControlCommandFinished; continuing like the C++ fail-safe exec"
                );
            }
        }
        HOST_CONTEXT.with(|cell| {
            if let Some(context) = cell.borrow_mut().as_mut() {
                context.clear_finished_command_fronts(target);
            }
        });
    }

    Ok(Value::Bool(true))
}

/// C4Value::getInt as used for FnPlayerObjectCommand's untyped Tx slot.
/// Bool converts directly; conversions from C4ID/string/object fail and
/// therefore yield zero (C4Value.h:159, C4Script.cpp:961-985).
fn player_object_command_tx(value: Option<&Value>) -> i32 {
    match value.unwrap_or(&Value::Nil) {
        Value::Int(value) => *value,
        Value::Bool(value) => i32::from(*value),
        _ => 0,
    }
}

/// C4Value::getIntOrID for FnPlayerObjectCommand's data slot. Unsupported
/// types are deliberately zero rather than script errors.
fn player_object_command_data(value: Option<&Value>) -> i32 {
    match value.unwrap_or(&Value::Nil) {
        Value::Int(value) => *value,
        Value::Bool(value) => i32::from(*value),
        Value::C4Id(id) => definition_id_to_c4id(id).unwrap_or(0),
        _ => 0,
    }
}

/// `C4Player::UpdateSelectionToggleStatus` before ObjectCommand routing
/// (C4Player.cpp:1355-1365). Cursor helpers already provide the synchronous
/// CrewSelection callbacks and copied-player preview; the final record after
/// clearing the two latches makes the authoritative fold retain that state.
fn update_player_selection_toggle_status_host(player_id: i32) {
    let Some((cursor_selection, cursor_toggled)) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let player = context.player_state(player_id)?;
        Some((
            player.control.cursor_selection,
            player.control.cursor_toggled,
        ))
    }) else {
        return;
    };
    if cursor_selection == 0 {
        return;
    }

    if cursor_toggled != 0 {
        adjust_cursor_host(player_id);
    } else {
        // C4Player::SelectSingleByCursor: UnselectCrew, DoSelect(Cursor),
        // SelectFlash=30, then AdjustCursorCommand.
        let _ = unselect_crew_host(&[Value::Int(player_id)]);
        let cursor = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.player_state(player_id))
                .and_then(|player| player.cursor)
        });
        if let Some(cursor) = cursor {
            do_select_host_object(cursor, false);
        }
        HOST_CONTEXT.with(|cell| {
            if let Some(context) = cell.borrow_mut().as_mut() {
                if let Some(player) = context.player_state_mut(player_id) {
                    player.control.select_flash = 30;
                }
            }
        });
        adjust_cursor_host(player_id);
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        if let Some(player) = context.player_state_mut(player_id) {
            player.control.cursor_selection = 0;
            player.control.cursor_toggled = 0;
        }
        record_cursor_state(context, player_id);
    });
}

fn native_set_command_tx(request: &CommandRequest) -> Value {
    request
        .tx_definition
        .as_ref()
        .map(|id| Value::C4Id(id.as_str().to_string()))
        .or_else(|| request.tx.map(Value::Int))
        .unwrap_or(Value::Int(0))
}

fn set_command_callback_args(request: &CommandRequest, tx: Value) -> [Value; 6] {
    let data = match &request.data {
        CommandData::Integer(value) => *value,
        CommandData::Text(_) | CommandData::None => 0,
    };
    [
        Value::String(request.id.to_name().to_string()),
        request
            .target
            .map(object_reference_value)
            .unwrap_or(Value::Nil),
        tx,
        Value::Int(request.ty.unwrap_or(0)),
        request
            .target2
            .map(object_reference_value)
            .unwrap_or(Value::Nil),
        Value::Int(data),
    ]
}

/// `C4Object::Call` is fail-safe and returns nil without executing when the
/// receiver has status zero. Controller transfer happens before this helper.
fn call_control_command_fail_safe(target: ObjectId, args: &[Value]) -> bool {
    let present = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .is_some_and(|context| context.object_status_present(target))
    });
    if !present {
        return false;
    }
    match call_world_object_own_function(target, "ControlCommand", args) {
        Some(Ok(value)) => value_raw_truthy(&value),
        Some(Err(error)) => {
            tracing::warn!(
                object = %target,
                %error,
                "script error in ControlCommand; continuing like the C++ fail-safe exec"
            );
            false
        }
        None => false,
    }
}

fn clear_command_stack_live(target: ObjectId) -> bool {
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        if !context.ensure_object_scope(target) {
            return false;
        }
        let Some(object) = context.object_scope_mut(target) else {
            return false;
        };
        object.clear_command_stack();
        true
    })
}

/// Native C4Object::SetCommand over a live host scope. Only menu closing and
/// the receiver's own ControlCommand are `fControl`-gated; inside/outside
/// vehicle overloads run for script and engine SetCommand calls too
/// (C4Object.cpp:3939-3983).
fn set_command_live(
    target: ObjectId,
    request: CommandRequest,
    f_control: bool,
    callback_tx: Value,
) -> bool {
    let staged = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        // FnSetCommand only checks that pObj is non-null. A status-zero object
        // can still be the in-flight script receiver and SetCommand continues
        // operating on its removal-delay tombstone.
        if !context.ensure_object_scope(target) {
            return false;
        }
        let Some(object) = context.object_scope_mut(target) else {
            return false;
        };
        // SetCommand decrements this delay before clearing the old stack.
        object.decrement_no_collect_delay();
        object.clear_command_stack();
        true
    });
    if !staged {
        return false;
    }

    if f_control {
        // The soft menu close happens after ClearCommands. A denial therefore
        // leaves the stack cleared (plus any command the query callback created).
        if !close_object_menu(target, false) {
            return true;
        }
    }

    let callback_args = set_command_callback_args(&request, callback_tx);
    if f_control && call_control_command_fail_safe(target, &callback_args) {
        return true;
    }

    // The contained vehicle receives a seventh argument naming the command
    // object, and inherits that object's live Controller before its call.
    let inside = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        let (container, controller) = {
            let actor = context.object_scope(target)?;
            (actor.container()?, actor.controller())
        };
        let definition = context.object_effective_definition_id(container)?;
        let enabled = context
            .definition_metadata(definition.as_str())
            .is_some_and(|metadata| {
                metadata.vehicle_control & crate::VEHICLE_CONTROL_INSIDE != 0
            });
        if !enabled || !context.ensure_object_scope(container) {
            return None;
        }
        context.object_scope_mut(container)?.set_controller(controller);
        Some(container)
    });
    if let Some(container) = inside {
        let mut args = callback_args.to_vec();
        args.push(object_reference_value(target));
        if call_control_command_fail_safe(container, &args) {
            return true;
        }
    }

    // Re-read action/procedure/target/controller after the inside callback:
    // it may have redirected the pushed vehicle or changed the actor.
    let outside = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        let (pushed, controller) = {
            let actor = context.object_scope(target)?;
            if actor.effective_action_procedure() != ActionProcedure::Push {
                return None;
            }
            (actor.effective_action_target(0)?, actor.controller())
        };
        let definition = context.object_effective_definition_id(pushed)?;
        let enabled = context
            .definition_metadata(definition.as_str())
            .is_some_and(|metadata| {
                metadata.vehicle_control & crate::VEHICLE_CONTROL_OUTSIDE != 0
            });
        if !enabled || !context.ensure_object_scope(pushed) {
            return None;
        }
        context.object_scope_mut(pushed)?.set_controller(controller);
        Some(pushed)
    });
    if let Some(pushed) = outside {
        if call_control_command_fail_safe(pushed, &callback_args) {
            return true;
        }
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return;
        };
        if let Some(object) = context.object_scope_mut(target) {
            let _ = object.push_command_front(request);
        }
    });
    // FnSetCommand reports success for every recognized command regardless of
    // overload consumption or the final AddCommand stack-limit result.
    true
}

/// C4Object::SetCommand(..., fControl=true) for one recipient of
/// C4Player::ObjectCommand. Command operations live on the target's copied
/// object scope, so GetCommand observes them before this host call returns and
/// the ordinary callback outcome fold persists the exact same stack.
fn set_player_control_command(target: ObjectId, request: CommandRequest) {
    let callback_tx = native_set_command_tx(&request);
    let _ = set_command_live(target, request, true, callback_tx);
}

fn player_object_command_request(
    command: CommandId,
    target: Option<ObjectId>,
    tx: i32,
    ty: i32,
    target2: Option<ObjectId>,
    data: i32,
) -> CommandRequest {
    CommandRequest::new(command)
        .with_target(target)
        .with_target2(target2)
        .with_tx(Some(tx))
        .with_ty(Some(ty))
        .with_data(CommandData::Integer(data))
        .with_mode(CommandMode::Base)
}

/// FnPlayerObjectCommand (C4Script.cpp:961-985) ->
/// C4Player::ObjectCommand(..., C4P_Command_Set) (C4Player.cpp:1397-1451).
fn player_object_command_host(args: &[Value]) -> Result<Value, RuntimeError> {
    let player_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "PlayerObjectCommand",
        "player",
    )?;
    let command_name = parse_optional_string(
        args.get(1),
        "PlayerObjectCommand",
        "command",
    )?;
    let target = parse_object_reference_argument(
        args.get(2).unwrap_or(&Value::Nil),
        "PlayerObjectCommand",
        "target",
    )?;
    let tx = player_object_command_tx(args.get(3));
    let ty = value_to_i32(
        args.get(4).unwrap_or(&Value::Nil),
        "PlayerObjectCommand",
        "y",
    )?;
    let target2 = parse_object_reference_argument(
        args.get(5).unwrap_or(&Value::Nil),
        "PlayerObjectCommand",
        "target2",
    )?;
    let data = player_object_command_data(args.get(6));

    // Native parameter conversion precedes the C++ function body, so only
    // now may player/name/command validation short-circuit. Extra arguments
    // have already been discarded by C4Aul's fixed parameter frame.
    let player_exists = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .is_some_and(|context| context.player_state(player_id).is_some())
    });
    let Some(command_name) = command_name else {
        return Ok(Value::Bool(false));
    };
    if !player_exists {
        return Ok(Value::Bool(false));
    }
    let Some(command) = CommandId::from_name(&command_name) else {
        return Ok(Value::Bool(false));
    };
    if command == CommandId::Call {
        // The value-only host ABI cannot inspect cthr->Caller's strictness.
        // Raise the STRICT3 result unconditionally; crucially this precedes
        // every C4Player/Object command side effect.
        return Err(RuntimeError::new(
            "PlayerObjectCommand: Command \"Call\" not supported",
        ));
    }

    // FnPlayerObjectCommand ignores ObjectCommand's false result and reports
    // true for an existing, but eliminated, player.
    let eliminated = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.player_state(player_id))
            .is_some_and(|player| {
                matches!(
                    player.status,
                    crate::PlayerStatus::Eliminated | crate::PlayerStatus::Surrendered
                )
            })
    });
    if eliminated {
        return Ok(Value::Bool(true));
    }

    update_player_selection_toggle_status_host(player_id);
    let crew = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.player_state(player_id))
            .map(|player| player.crew.clone())
            .unwrap_or_default()
    });

    let mut routed_target = target;
    let mut cursor_processed = false;
    for crew_id in crew {
        let route = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let Some(context) = borrow.as_ref() else {
                return None;
            };
            let cursor = context.player_state(player_id).and_then(|player| player.cursor);
            let object = context.get_world_object(crew_id)?;
            let selected = context
                .object_scope(crew_id)
                .map(ObjectScopeContext::selected)
                .unwrap_or(object.selected);
            Some((
                cursor == Some(crew_id),
                context.object_status_present(crew_id)
                    && selected
                    && Some(crew_id) != routed_target,
            ))
        });
        let Some((is_cursor, should_route)) = route else {
            continue;
        };
        cursor_processed |= is_cursor;
        if !should_route {
            continue;
        }

        let mut object_tx = tx;
        if command == CommandId::Put && target2.is_none() {
            let contents_count = HOST_CONTEXT.with(|cell| {
                let borrow = cell.borrow();
                let Some(context) = borrow.as_ref() else {
                    return 0;
                };
                let Some(object) = context.get_world_object(crew_id) else {
                    return 0;
                };
                let count = object
                    .contents()
                    .iter()
                    .filter(|content_id| {
                        context
                            .get_world_object(**content_id)
                            .is_some_and(|content| {
                                content.is_present()
                                    && (data == 0
                                        || context
                                            .object_effective_definition_id(**content_id)
                                            .and_then(|definition| {
                                                definition_id_to_c4id(&definition)
                                            })
                                            == Some(data))
                            })
                    })
                    .count();
                i32::try_from(count).unwrap_or(i32::MAX)
            });
            if contents_count == 0 {
                continue;
            }
            object_tx = object_tx.min(contents_count);
        }

        set_player_control_command(
            crew_id,
            player_object_command_request(
                command,
                routed_target,
                object_tx,
                ty,
                target2,
                data,
            ),
        );
        if command == CommandId::Construct {
            routed_target = Some(crew_id);
        }
    }

    // Always command a cursor outside Crew; unlike the crew loop this final
    // path deliberately does not apply Put's contents-count workaround.
    let cursor = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.player_state(player_id))
            .and_then(|player| player.cursor)
    });
    if let Some(cursor) = cursor.filter(|cursor| {
        !cursor_processed
            && Some(*cursor) != routed_target
            && HOST_CONTEXT.with(|cell| {
                cell.borrow()
                    .as_ref()
                    .is_some_and(|context| context.object_status_present(*cursor))
            })
    }) {
        set_player_control_command(
            cursor,
            player_object_command_request(command, routed_target, tx, ty, target2, data),
        );
    }

    Ok(Value::Bool(true))
}

fn set_command(args: &[Value]) -> Result<Value, RuntimeError> {
    // C++ FnSetCommand leads with the object slot (pObj, szCommand, ...;
    // C4Script.cpp:840-844); 0/nil means the calling object. The
    // name-first form stays for the command-DSL fixtures.
    let mut args = args;
    let mut leading_target: Option<ObjectId> = None;
    let leads_with_object_slot = matches!(
        (args.first(), args.get(1)),
        (Some(Value::Object(_) | Value::Proplist(_)), _)
            | (Some(Value::Nil | Value::Int(0)), Some(Value::String(_)))
    );
    if leads_with_object_slot {
        leading_target = parse_object_reference_argument(&args[0], "SetCommand", "target")?;
        args = &args[1..];
    }
    if args.is_empty() {
        // C++ FnSetCommand: !szCommand -> false (C4Script.cpp:843-899).
        return Ok(Value::Bool(false));
    }
    let Some(target) = leading_target.or_else(active_object_id) else {
        return Ok(Value::Bool(false));
    };

    let command_name = match &args[0] {
        Value::String(name) if !name.is_empty() => name.clone(),
        Value::String(_) => {
            clear_command_stack_live(target);
            return Ok(Value::Bool(false));
        }
        // FnSetCommand returns before ClearCommands when szCommand is null.
        Value::Nil => return Ok(Value::Bool(false)),
        other => {
            return Err(RuntimeError::new(format!(
                "SetCommand: expected string for command name, got {}",
                other.type_name()
            )))
        }
    };

    let Some(command_id) = CommandId::from_name(&command_name) else {
        clear_command_stack_live(target);
        return Ok(Value::Bool(false));
    };

    // FnSetCommand's ignored ConvertTo(Int) preserves a nil/default Tx value
    // as nil. Retain the callback value separately from the normalized
    // CommandRequest used by the hardcoded command stack.
    let callback_tx = args.get(2).cloned().unwrap_or(Value::Nil);
    let request = parse_command_request(command_id, args, CommandArgLayout::Set, "SetCommand")?;
    Ok(Value::Bool(set_command_live(
        target,
        request,
        false,
        callback_tx,
    )))
}

fn add_command(args: &[Value]) -> Result<Value, RuntimeError> {
    // C++ FnAddCommand leads with the object slot (pObj, szCommand, ...;
    // C4Script.cpp:870-874); 0/nil means the calling object. The
    // name-first form stays for the command-DSL fixtures. A FOREIGN target
    // re-dispatches through the reentrancy seam like SetCommand and
    // AppendCommand so the write folds into that object's command stack.
    let mut args = args;
    let mut leading_target: Option<ObjectId> = None;
    let leads_with_object_slot = matches!(
        (args.first(), args.get(1)),
        (Some(Value::Object(_) | Value::Proplist(_)), _)
            | (Some(Value::Nil | Value::Int(0)), Some(Value::String(_)))
    );
    if leads_with_object_slot {
        leading_target = parse_object_reference_argument(&args[0], "AddCommand", "target")?;
        args = &args[1..];
    }
    if args.is_empty() {
        // C++ FnAddCommand: !szCommand -> false (C4Script.cpp:843-899).
        return Ok(Value::Bool(false));
    }
    if let Some(target) = leading_target {
        if active_object_id() != Some(target) {
            return match call_world_object_function(target, "AddCommand", args) {
                Some(result) => result,
                None => Ok(Value::Bool(false)),
            };
        }
    }

    let command_name = match &args[0] {
        Value::String(name) if !name.is_empty() => name.clone(),
        Value::String(_) | Value::Nil => return Ok(Value::Bool(false)),
        other => {
            return Err(RuntimeError::new(format!(
                "AddCommand: expected string for command name, got {}",
                other.type_name()
            )))
        }
    };

    let command_id = match CommandId::from_name(&command_name) {
        Some(id) => id,
        None => return Ok(Value::Bool(false)),
    };

    let request = parse_command_request(command_id, args, CommandArgLayout::Add, "AddCommand")?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("AddCommand requires an active engine context"))?;
        let object = match context.object_context_mut() {
            Some(object) => object,
            None => return Ok(Value::Bool(false)),
        };
        let success = object.push_command_front(request);
        Ok(Value::Bool(success))
    })
}

fn append_command(args: &[Value]) -> Result<Value, RuntimeError> {
    // C++ FnAppendCommand leads with the object slot (pObj, szCommand, ...;
    // C4Script.cpp:894-916); 0/nil means the calling object. The name-first
    // form stays for the command-DSL fixtures. A FOREIGN target re-dispatches
    // through the reentrancy seam like SetCommand so the queued command lands
    // on the target's own stack.
    let mut args = args;
    let mut leading_target: Option<ObjectId> = None;
    let leads_with_object_slot = matches!(
        (args.first(), args.get(1)),
        (Some(Value::Object(_) | Value::Proplist(_)), _)
            | (Some(Value::Nil | Value::Int(0)), Some(Value::String(_)))
    );
    if leads_with_object_slot {
        leading_target = parse_object_reference_argument(&args[0], "AppendCommand", "target")?;
        args = &args[1..];
    }
    if args.is_empty() {
        // C++ FnAppendCommand: !szCommand -> false (C4Script.cpp:843-899).
        return Ok(Value::Bool(false));
    }
    if let Some(target) = leading_target {
        if active_object_id() != Some(target) {
            return match call_world_object_function(target, "AppendCommand", args) {
                Some(result) => result,
                None => Ok(Value::Bool(false)),
            };
        }
    }

    let command_name = match &args[0] {
        Value::String(name) if !name.is_empty() => name.clone(),
        Value::String(_) | Value::Nil => return Ok(Value::Bool(false)),
        other => {
            return Err(RuntimeError::new(format!(
                "AppendCommand: expected string for command name, got {}",
                other.type_name()
            )))
        }
    };

    let command_id = match CommandId::from_name(&command_name) {
        Some(id) => id,
        None => return Ok(Value::Bool(false)),
    };

    let request = parse_command_request(command_id, args, CommandArgLayout::Add, "AppendCommand")?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("AppendCommand requires an active engine context"))?;
        let object = match context.object_context_mut() {
            Some(object) => object,
            None => return Ok(Value::Bool(false)),
        };

        let success = object.push_command_back(request);
        Ok(Value::Bool(success))
    })
}

enum PositionComponent {
    X,
    Y,
}

impl PositionComponent {
    fn function_name(&self) -> &'static str {
        match self {
            PositionComponent::X => "GetX",
            PositionComponent::Y => "GetY",
        }
    }

    fn extract(&self, position: Vector2) -> i32 {
        match self {
            PositionComponent::X => position.x,
            PositionComponent::Y => position.y,
        }
    }
}

fn get_position_component(
    args: &[Value],
    component: PositionComponent,
) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(format!(
            "{} expects at most 1 argument: target",
            component.function_name()
        )));
    }

    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.first() {
        target_id = parse_object_reference_argument(arg, component.function_name(), "target")?;
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        if let Some(target) = target_id {
            if let Some(object) = context.object_context() {
                if target == object.id() {
                    let position = object.effective_position();
                    return Ok(Value::Int(component.extract(position)));
                }
            }

            if let Some(other) = context.get_world_object(target) {
                let position = other.position();
                return Ok(Value::Int(component.extract(position)));
            }

            return Ok(Value::Nil);
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Nil),
        };

        let position = object.effective_position();
        Ok(Value::Int(component.extract(position)))
    })
}

fn object_distance(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.is_empty() || args.len() > 2 {
        return Err(RuntimeError::new(
            "ObjectDistance expects 1 or 2 arguments: other, object",
        ));
    }

    let other_id = match parse_object_reference_argument(&args[0], "ObjectDistance", "other")? {
        Some(id) => id,
        None => return Ok(Value::Nil),
    };

    let mut reference_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(1) {
        reference_id = parse_object_reference_argument(arg, "ObjectDistance", "object")?;
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        let locate_position = |id: ObjectId| -> Option<Vector2> {
            if let Some(object) = context.object_context() {
                if object.id() == id {
                    return Some(object.effective_position());
                }
            }
            context.get_world_object(id).map(|object| object.position())
        };

        let anchor_position = if let Some(id) = reference_id {
            locate_position(id)
        } else {
            context
                .object_context()
                .map(|object| object.effective_position())
        };

        let anchor_position = match anchor_position {
            Some(position) => position,
            None => return Ok(Value::Nil),
        };

        let other_position = match locate_position(other_id) {
            Some(position) => position,
            None => return Ok(Value::Nil),
        };

        let distance = integer_distance(
            anchor_position.x,
            anchor_position.y,
            other_position.x,
            other_position.y,
        );
        Ok(Value::Int(distance))
    })
}

enum VelocityComponent {
    X,
    Y,
}

impl VelocityComponent {
    fn get_function_name(&self) -> &'static str {
        match self {
            VelocityComponent::X => "GetXDir",
            VelocityComponent::Y => "GetYDir",
        }
    }

    fn set_function_name(&self) -> &'static str {
        match self {
            VelocityComponent::X => "SetXDir",
            VelocityComponent::Y => "SetYDir",
        }
    }

    fn extract_fixed(&self, velocity: FixedVec2) -> C4Fixed {
        match self {
            VelocityComponent::X => velocity.x,
            VelocityComponent::Y => velocity.y,
        }
    }

    fn assign_fixed(&self, velocity: &mut FixedVec2, value: C4Fixed) {
        match self {
            VelocityComponent::X => velocity.x = value,
            VelocityComponent::Y => velocity.y = value,
        }
    }
}

fn get_velocity_component(
    args: &[Value],
    component: VelocityComponent,
) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(format!(
            "{} expects at most 2 arguments: target, precision",
            component.get_function_name()
        )));
    }

    let mut index = 0;
    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        if matches!(
            arg,
            Value::Object(_) | Value::Proplist(_) | Value::Nil | Value::Int(0)
        ) {
            target_id =
                parse_object_reference_argument(arg, component.get_function_name(), "target")?;
            index += 1;
        }
    }

    let mut precision = DEFAULT_VELOCITY_PRECISION;
    if let Some(arg) = args.get(index) {
        precision = value_to_i32(arg, component.get_function_name(), "precision")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(format!(
            "{}: additional arguments are not supported",
            component.get_function_name()
        )));
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        let effective_precision = normalise_precision(precision);
        let fetch_velocity = |fixed_velocity: FixedVec2| {
            // C++ GetXDir/GetYDir return fixtoi(xdir/ydir, prec). `C4Script.cpp:1167`.
            let component_value = component.extract_fixed(fixed_velocity);
            Value::Int(fixtoi_prec(component_value, effective_precision))
        };

        if let Some(target) = target_id {
            if let Some(object) = context.object_context() {
                if target == object.id() {
                    return Ok(fetch_velocity(object.fixed_velocity()));
                }
            }

            if let Some(other) = context.get_world_object(target) {
                return Ok(fetch_velocity(other.fixed_velocity()));
            }

            return Ok(Value::Nil);
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Nil),
        };
        Ok(fetch_velocity(object.fixed_velocity()))
    })
}

fn set_velocity_component(
    args: &[Value],
    component: VelocityComponent,
) -> Result<Value, RuntimeError> {
    // Unfilled parameter slots are nil -> 0 (C4AulExec parameter filling):
    // a bare FnSetXDir()/FnSetYDir() zeroes the dir (C4Script.cpp:697-708).
    let value = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        component.set_function_name(),
        "value",
    )?;
    let mut index = 1;
    let mut target_id: Option<ObjectId> = None;

    if let Some(arg) = args.get(index) {
        if matches!(
            arg,
            Value::Object(_) | Value::Proplist(_) | Value::Nil | Value::Int(0)
        ) {
            target_id =
                parse_object_reference_argument(arg, component.set_function_name(), "target")?;
            index += 1;
        }
    }

    let mut precision = DEFAULT_VELOCITY_PRECISION;
    if let Some(arg) = args.get(index) {
        precision = value_to_i32(arg, component.set_function_name(), "precision")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(format!(
            "{}: additional arguments are not supported",
            component.set_function_name()
        )));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new(format!(
                "{} requires an active engine context",
                component.set_function_name()
            ))
        })?;

        let target = target_id.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };

        // C++ SetXDir/SetYDir set ONLY xdir/ydir = itofix(value, prec)
        // (default precision 10, C4Script.cpp:697-732) — the other
        // component keeps its full sub-pixel value. A whole-vector write
        // here would quantize it through the scope's int-seeded mirror
        // (the GoldRush snake's SetXDir(0) turned ydir 2.6 into 3.0).
        object.set_fixed_velocity_component(
            component,
            itofix_prec(value, normalise_precision(precision)),
        );
        // FnSetXDir/FnSetYDir assign Mobile=1 synchronously after the dir
        // write (C4Script.cpp:697-732). Stage it here so later native
        // Tumble preserves the live value and call order remains observable.
        object.set_mobile(true);
        Ok(Value::Bool(true))
    })
}

fn get_x_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    get_velocity_component(args, VelocityComponent::X)
}

fn get_y_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    get_velocity_component(args, VelocityComponent::Y)
}

fn set_x_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    set_velocity_component(args, VelocityComponent::X)
}

fn set_y_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    set_velocity_component(args, VelocityComponent::Y)
}

/// FnAdjustWalkRotation (C4Script.cpp:5439-5448): bails unless the def is
/// Rotateable, this frame's Action.t_attach carries CNAT_Bottom and the
/// last shape attach hit a material; then C4Object::AdjustWalkRotation
/// (C4Object.cpp:6019-6086) probes the floor around the attach position
/// and steers rdir toward the slope.
fn adjust_walk_rotation(args: &[Value]) -> Result<Value, RuntimeError> {
    let range_x = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "AdjustWalkRotation",
        "range_x",
    )?;
    let range_y = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "AdjustWalkRotation",
        "range_y",
    )?;
    let speed = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "AdjustWalkRotation",
        "speed",
    )?;
    let target_id = args
        .get(3)
        .map(|arg| parse_object_reference_argument(arg, "AdjustWalkRotation", "target"))
        .transpose()?
        .flatten();

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("AdjustWalkRotation requires an active engine context")
        })?;

        let Some(object) = context.object_context() else {
            return Ok(Value::Bool(false));
        };
        if let Some(target) = target_id {
            if target != object.id() {
                // Foreign dispatch is not modeled — the same documented
                // gap as SetRDir's target parameter.
                return Ok(Value::Bool(false));
            }
        }

        let seed = object.walk_rotation;
        let rotation = object.rotation();
        // The LIVE Shape.VtxX for the else-branch (C4Object.cpp:6072).
        let live_vtx_x = usize::try_from(seed.attach.vtx)
            .ok()
            .and_then(|vtx| object.vertices().get(vtx))
            .map(|vertex| vertex.x)
            .unwrap_or(0);

        // Guard: Rotateable + bottom attach + attached material
        // (C4Script.cpp:5443-5446).
        if seed.rotateable == 0 || seed.t_attach & CNAT_BOTTOM == 0 || !seed.attach.mat_valid {
            return Ok(Value::Bool(false));
        }

        let rotation_velocity = {
            let landscape = context.landscape_ref();
            crate::calculate_walk_rotation_velocity(
                rotation,
                seed.attach,
                seed.def_attach_vtx_x,
                live_vtx_x,
                range_x,
                range_y,
                speed,
                |x, y| evaluate_landscape_query(landscape, LandscapeQuery::Solid, x, y),
            )
        };

        let Some(object) = context.object_context_mut() else {
            return Ok(Value::Bool(false));
        };
        // Move to destination angle (C4Object.cpp:6089-6095). C++ writes
        // rdir directly (no Mobile flag); the pending-update path arms
        // mobile, but every caller runs from an attached procedure that
        // has already set it.
        object.set_rotation_velocity(rotation_velocity);
        Ok(Value::Bool(true))
    })
}

fn set_r_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    // C++ FnSetRDir(value, [target], [precision = 10]) sets rdir = itofix(value,
    // precision), a fractional `C4Fixed` angular velocity. `C4Script.cpp:710`.
    // Unfilled parameter slots are nil -> 0 (C4AulExec parameter filling): a
    // bare FnSetRDir() zeroes the spin (the dragon's Jumping/StopFlying).
    let value = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetRDir", "value")?;
    let mut index = 1;
    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        if matches!(
            arg,
            Value::Object(_) | Value::Proplist(_) | Value::Nil | Value::Int(0)
        ) {
            target_id = parse_object_reference_argument(arg, "SetRDir", "target")?;
            index += 1;
        }
    }

    let mut precision = DEFAULT_VELOCITY_PRECISION;
    if let Some(arg) = args.get(index) {
        precision = value_to_i32(arg, "SetRDir", "precision")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetRDir: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetRDir requires an active engine context"))?;
        let target = target_id.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };

        object.set_rotation_velocity(itofix_prec(value, normalise_precision(precision)));
        // FnSetRDir sets Mobile=1 just like the linear dir setters
        // (C4Script.cpp:704-715).
        object.set_mobile(true);
        Ok(Value::Bool(true))
    })
}

fn get_r_dir(args: &[Value]) -> Result<Value, RuntimeError> {
    // C++ FnGetRDir([target], [precision = 10]) returns fixtoi(rdir, precision).
    // `C4Script.cpp` GetRDir.
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "GetRDir expects at most 2 arguments: target, precision",
        ));
    }

    let mut index = 0;
    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        if matches!(
            arg,
            Value::Object(_) | Value::Proplist(_) | Value::Nil | Value::Int(0)
        ) {
            target_id = parse_object_reference_argument(arg, "GetRDir", "target")?;
            index += 1;
        }
    }

    let mut precision = DEFAULT_VELOCITY_PRECISION;
    if let Some(arg) = args.get(index) {
        precision = value_to_i32(arg, "GetRDir", "precision")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "GetRDir: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        let effective_precision = normalise_precision(precision);
        if let Some(target) = target_id {
            if let Some(object) = context.object_scope(target) {
                return Ok(Value::Int(fixtoi_prec(
                    object.rotation_velocity(),
                    effective_precision,
                )));
            }
            return Ok(context
                .get_world_object(target)
                .map(|object| {
                    Value::Int(fixtoi_prec(
                        object.rotation_velocity,
                        effective_precision,
                    ))
                })
                .unwrap_or(Value::Nil));
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Nil),
        };
        Ok(Value::Int(fixtoi_prec(
            object.rotation_velocity(),
            effective_precision,
        )))
    })
}

fn get_x(args: &[Value]) -> Result<Value, RuntimeError> {
    get_position_component(args, PositionComponent::X)
}

fn get_y(args: &[Value]) -> Result<Value, RuntimeError> {
    get_position_component(args, PositionComponent::Y)
}

/// FnGetDefBottom (C4Script.cpp:4445-4449): the object's integer Y plus
/// the untransformed definition-shape bottom. Live Shape changes, Con and
/// rotation do not participate.
fn get_def_bottom(args: &[Value]) -> Result<Value, RuntimeError> {
    let explicit_target = args
        .first()
        .map(|arg| parse_object_reference_argument(arg, "GetDefBottom", "object"))
        .transpose()?
        .flatten();

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let target = explicit_target.or_else(|| context.object_context().map(|object| object.id()));
        let Some(target) = target else {
            return Ok(Value::Nil);
        };
        let position = context
            .object_scope(target)
            .map(ObjectScopeContext::effective_position)
            .or_else(|| {
                context
                    .get_world_object(target)
                    .map(|object| object.position())
            });
        let Some(position) = position else {
            return Ok(Value::Nil);
        };
        let definition = context
            .object_scope(target)
            .and_then(|object| {
                object
                    .pending_update
                    .change_def
                    .clone()
                    .or_else(|| object.definition_id.clone())
            })
            .or_else(|| {
                context
                    .get_world_object(target)
                    .map(|object| object.definition_id().to_string())
            });
        let Some(shape) = definition
            .as_deref()
            .and_then(|definition| context.definition_metadata(definition))
            .map(|metadata| metadata.shape.unwrap_or(DefinitionRect::new(0, 0, 0, 0)))
        else {
            return Ok(Value::Nil);
        };
        Ok(Value::Int(
            position.y.wrapping_add(shape.y).wrapping_add(shape.height),
        ))
    })
}

fn get_id(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetID expects at most 1 argument: target object",
        ));
    }

    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.first() {
        target_id = parse_object_reference_argument(arg, "GetID", "target")?;
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        if let Some(target) = target_id {
            if context.get_world_object(target).is_some() {
                return Ok(context
                    .object_effective_definition_id(target)
                    .map(|id| Value::C4Id(id.as_str().to_string()))
                    .unwrap_or(Value::Nil));
            }
            // If target object not found, return nil
            return Ok(Value::Nil);
        }

        // No argument: cthr->Obj->Def when there is an object, otherwise
        // cthr->Def from the executing function owner.
        if let Some(definition_id) = context.current_definition_id() {
            return Ok(Value::C4Id(definition_id.to_string()));
        }

        Ok(Value::Nil)
    })
}

/// FnGetBase (C4Script.cpp:1406-1410): read C4Object::Base from the
/// explicit object, or from the calling object when the argument is nil;
/// without either object C4ValueInt returns NO_OWNER.
fn get_base(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetBase expects at most 1 argument: target object",
        ));
    }
    let target = args
        .first()
        .map(|arg| parse_object_reference_argument(arg, "GetBase", "target"))
        .transpose()?
        .flatten();

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Int(OWNER_NONE));
        };
        let target = target.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let base = target
            .and_then(|id| context.get_world_object(id))
            .and_then(|object| object.full_state().map(|state| state.base))
            .unwrap_or(OWNER_NONE);
        Ok(Value::Int(base))
    })
}

fn apply_position_bounds(
    desired: Vector2,
    vertices: &[ObjectVertex],
    landscape: Option<&Landscape>,
) -> Vector2 {
    let mut bounded = desired;
    let Some(landscape) = landscape else {
        return bounded;
    };

    let width = landscape.width() as i32;
    if width > 0 {
        let (mut min_allowed, mut max_allowed) = if vertices.is_empty() {
            (0, width.saturating_sub(1))
        } else {
            vertices
                .iter()
                .fold((i32::MIN, i32::MAX), |(min_acc, max_acc), vertex| {
                    (
                        min_acc.max(-vertex.x),
                        max_acc.min(width.saturating_sub(1).saturating_sub(vertex.x)),
                    )
                })
        };

        if min_allowed == i32::MIN {
            min_allowed = 0;
        }
        if max_allowed == i32::MAX {
            max_allowed = width.saturating_sub(1);
        }

        if min_allowed <= max_allowed {
            bounded.x = bounded.x.clamp(min_allowed, max_allowed);
        } else {
            bounded.x = bounded.x.clamp(0, width.saturating_sub(1));
        }
    }

    let min_y_allowed = if vertices.is_empty() {
        0
    } else {
        vertices.iter().map(|vertex| -vertex.y).max().unwrap_or(0)
    };

    let mut max_y_allowed = i32::MAX;
    if vertices.is_empty() {
        if let Some(surface_y) = landscape.surface_height(bounded.x) {
            max_y_allowed = surface_y;
        }
    } else {
        for vertex in vertices {
            let world_x = bounded.x.saturating_add(vertex.x);
            if let Some(surface_y) = landscape.surface_height(world_x) {
                max_y_allowed = max_y_allowed.min(surface_y - vertex.y);
            }
        }
    }

    if max_y_allowed < min_y_allowed {
        max_y_allowed = min_y_allowed;
    }

    bounded.y = bounded.y.clamp(min_y_allowed, max_y_allowed);
    bounded
}

fn set_position(args: &[Value]) -> Result<Value, RuntimeError> {
    // Unfilled iX/iY are nil -> 0 (FnSetPosition, C4Script.cpp:462).
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetPosition", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "SetPosition", "y")?;

    let mut index = 2;
    let mut target_id: Option<ObjectId> = None;

    if let Some(arg) = args.get(index) {
        target_id = parse_object_reference_argument(arg, "SetPosition", "target")?;
        index += 1;
    }

    let mut check_bounds = false;
    if let Some(arg) = args.get(index) {
        check_bounds = match arg {
            Value::Bool(value) => *value,
            Value::Int(value) => *value != 0,
            Value::Nil => false,
            other => {
                return Err(RuntimeError::new(format!(
                    "SetPosition: expected bool for check_bounds, got {}",
                    other.type_name()
                )))
            }
        };
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetPosition: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetPosition requires an active engine context"))?;

        let landscape_snapshot = if check_bounds {
            context.landscape_ref().cloned()
        } else {
            None
        };

        // FnSetPosition (C4Script.cpp:462-477): no pObj means the caller,
        // and ANY object force-positions live (`pObj->ForcePosition`) — the
        // BAS7 MoveOutClonk loop repositions a FOREIGN stuck object and
        // re-reads it within the same call.
        let active = context.object_context().map(|object| object.id());
        let Some(target) = target_id.or(active) else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(scope) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };

        let mut position = Vector2::new(x, y);
        if check_bounds {
            let vertices: Vec<ObjectVertex> = scope.vertices().to_vec();
            position = apply_position_bounds(position, &vertices, landscape_snapshot.as_ref());
        }

        scope.set_position(position);
        Ok(Value::Bool(true))
    })
}

fn create_object(args: &[Value]) -> Result<Value, RuntimeError> {
    // FnCreateObject takes a C4ID (C4Script.cpp:1892); our resources address
    // definitions by their id string, so id values and strings coincide.
    let definition = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) | Value::C4Id(name) if !name.is_empty() => name.clone(),
        Value::String(_) | Value::C4Id(_) | Value::Nil | Value::Int(0) => return Ok(Value::Nil),
        other => {
            return Err(RuntimeError::new(format!(
                "CreateObject: expected id for definition, got {}",
                other.type_name()
            )))
        }
    };

    let mut index = 1;

    let x_offset = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "CreateObject", "x")?;
        index += 1;
        value
    } else {
        0
    };

    let y_offset = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "CreateObject", "y")?;
        index += 1;
        value
    } else {
        0
    };

    let requested_owner = if let Some(arg) = args.get(index) {
        let owner = value_to_i32(arg, "CreateObject", "owner")?;
        index += 1;
        owner
    } else {
        0
    };

    if index < args.len() {
        return Err(RuntimeError::new(
            "CreateObject: additional arguments are not supported",
        ));
    }

    let registration = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("CreateObject requires an active engine context"))?;

        // C4Id2Def failure: no object, silent nullptr (C4Game.cpp:1146).
        if context.world.definition_known(&definition) == Some(false) {
            return Ok(None);
        }

        let metadata = context
            .definition_metadata(&definition)
            .cloned()
            .unwrap_or_else(|| DefinitionMetadata {
                name: String::new(),
                portrait_names: Vec::new(),
                category: context
                    .definition_category(&definition)
                    .unwrap_or(DEFAULT_CATEGORY),
                border_bound: 0,
                contact_function_calls: false,
                blit_mode: 0,
                ocf_base: ocf::NORMAL,
                crew_member: false,
                silent_commands: false,
                vehicle_control: 0,
                action_library: ActionLibrary::default(),
                action_graphics: HashMap::new(),
                value: 0,
                mass: 0,
                no_component_mass: false,
                constructable: false,
                shape: None,
                placement: 0,
                growth: 0,
                construction_offset: 0,
                basement: 0,
                physical: PhysicalInfo::default(),
                components: Vec::new(),
                collection_limit: 0,
                grab_put_get: 0,
                line_connect: 0,
                clonk_name_newlines: None,
                stretch_growth: false,
                rotateable: 0,
                line: 0,
                vertices: Vec::new(),
                contact_density: None,
                fire: DefinitionFireMetadata::default(),
            });
        let definition_category = metadata.category;
        let creator_layer = context
            .object_context()
            .map(ObjectScopeContext::id)
            .and_then(|creator| context.object_layer(creator));

        let base_position = context
            .object_context()
            .map(|object| object.effective_position())
            .unwrap_or(Vector2::ZERO);
        // Typed C4ValueInt conversion makes an omitted/explicit nil owner
        // zero. Local calls replace even an explicit owner when the native
        // has no script caller or its immediate caller is NONSTRICT.
        let substitute_local_owner = matches!(
            lc_script::caller_strictness(),
            lc_script::HostCallerStrictness::NoCaller
                | lc_script::HostCallerStrictness::NonStrict
        );
        let owner = if substitute_local_owner {
            context
                .object_context()
                .map(ObjectScopeContext::owner)
                .unwrap_or(requested_owner)
        } else {
            requested_owner
        };
        let raw_position = Vector2::new(
            base_position.x.saturating_add(x_offset),
            base_position.y.saturating_add(y_offset),
        );

        let id = context.allocate_object_id();

        let mut spawn = SpawnConfig::new(definition.clone())
            .with_position(raw_position)
            .with_owner(owner)
            .with_category(definition_category)
            // C4Object starts at Con=0. C4Game::NewObject exposes that live
            // state to Construction before applying the initial FullCon.
            .with_construction(0)
            .with_id(id);
        if let Some(layer) = creator_layer {
            spawn = spawn.with_layer(layer);
        }
        // "Set initial controller to creating controller, so more
        // complicated cause-effect-chains can be traced back to the
        // causing player" (FnCreateObject, C4Script.cpp:1899-1900).
        let creator_controller = context
            .object_context()
            .map(ObjectScopeContext::controller)
            .filter(|value| *value > OWNER_NONE);
        if let Some(controller) = creator_controller {
            spawn = spawn.with_controller(controller);
        }
        // Creation callbacks and initial DoCon run synchronously below;
        // materialization must repeat neither operation.
        spawn.initialized = true;
        spawn.position_adjusted = true;

        let initial_alive = metadata.category & crate::CATEGORY_LIVING != 0;
        let preview_ocf = ocf::compute(
            metadata.ocf_base,
            metadata.crew_member,
            initial_alive,
            ObjectStatus::Normal,
            false,
            0,
            metadata.category,
        );
        let preview = HostWorldObject::with_category(
            id,
            definition,
            ObjectStatus::Normal,
            "Idle",
            None,
            None,
            None,
            owner,
            definition_category,
            if initial_alive {
                metadata.physical.energy
            } else {
                0
            },
            0,
            0,
            raw_position,
            Vector2::ZERO,
            0,
            metadata.vertices.clone(),
            0,
            0,
            0,
            None,
            None,
        )
        .with_alive(initial_alive)
        .with_ocf(preview_ocf)
        // A callable scope for nested calls on the fresh object — C++
        // creates objects live mid-call (Game.CreateObject), so scripts
        // arrow-call them immediately (GoldRush: pObj->SetAI right after
        // CreateObject). The spawn stays authoritative; nested outcomes
        // fold only touched fields.
        .with_full_state(Rc::new({
            let mut state = crate::preview_spawn_state_with_components(
                raw_position,
                owner,
                owner,
                definition_category,
                0,
                metadata.contact_density(),
                metadata.vertices.clone(),
                metadata.components.as_slice(),
            );
            state.alive = initial_alive;
            state.energy = if initial_alive {
                metadata.physical.energy
            } else {
                0
            };
            state.crew_member = metadata.crew_member;
            state.layer = creator_layer;
            state.blit_mode = metadata.blit_mode;
            state
        }));

        context.register_spawn(spawn, preview);
        Ok(Some((
            id,
            context.object_context().map(ObjectScopeContext::id),
            creator_controller,
            metadata.shape,
            metadata.stretch_growth,
            metadata.line,
            metadata.ocf_base,
            metadata.crew_member,
            metadata.category,
            initial_alive,
        )))
    })?;
    let Some((
        target,
        creator,
        creator_controller,
        shape,
        stretch_growth,
        line,
        ocf_base,
        crew_member,
        category,
        alive,
    )) = registration
    else {
        return Ok(Value::Nil);
    };

    // C4Game::NewObject makes the raw Con=0 object script-visible, then
    // invokes Construction with the creator (C4Game.cpp:1102-1121).
    let creator_arg = creator.map(object_reference_value).unwrap_or(Value::Nil);
    if let Some(Err(error)) =
        call_world_object_own_function(target, "Construction", &[creator_arg])
    {
        tracing::warn!(
            id = target.as_u64(),
            callback = "Construction",
            %error,
            "creation callback failed; continuing like C++ fail-safe Call"
        );
    }
    let removed = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .map(|context| context.nested_object_destroyed(target))
            .unwrap_or(false)
    });
    if removed {
        return Ok(Value::Nil);
    }

    // Construction ran against the raw Con=0 object, before NewObject's
    // initial DoCon. Commit its final action state into the pending spawn at
    // that boundary instead of leaving the ActionUpdate to replay after the
    // spawn has materialized at its post-growth integer position. SetAction
    // synchronizes fix_x/fix_y immediately in C++; replaying it later changed
    // WMPF's raw y=516 fixed coordinate to the intermediate growth y=512.
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            context.commit_creation_action(target);
        }
    });

    // Initial DoCon(FullCon,true) runs only after Construction. Its straight
    // growth keeps the old bottom fixed in integer coordinates and leaves
    // fix_y at the supplied raw center (C4Object.cpp:1428-1515).
    let crossed_full_con = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        if !context.ensure_object_scope(target) {
            return false;
        }
        let was_full = context
            .object_scope(target)
            .is_some_and(|scope| scope.construction() >= FULL_CON);
        let Some(final_construction) = context.adjust_object_construction(target, FULL_CON) else {
            return false;
        };
        let (pre_growth_position, adjusted_position) = {
            let Some(scope) = context.object_scope_mut(target) else {
                return false;
            };
            let pre_growth_position = scope.effective_position();
            let adjusted_position = Vector2::new(
                pre_growth_position.x,
                crate::docon_initial_center_y(
                    shape,
                    stretch_growth,
                    line,
                    final_construction,
                    pre_growth_position.y,
                ),
            );
            scope.pending_update.construction = None;
            scope.current_position = adjusted_position;
            scope.pending_update.position = None;
            scope.cached_ocf = Some(ocf::compute(
                ocf_base,
                crew_member,
                alive,
                ObjectStatus::Normal,
                false,
                final_construction,
                category,
            ));
            (pre_growth_position, adjusted_position)
        };
        if let Some(spawn) = context
            .pending_spawns
            .iter_mut()
            .find(|spawn| spawn.id == Some(target))
        {
            spawn.position = adjusted_position;
            spawn.construction = FULL_CON;
            spawn.fixed_position = (adjusted_position != pre_growth_position)
                .then_some(FixedVec2::from_ints(
                    pre_growth_position.x,
                    pre_growth_position.y,
                ));
        }
        !was_full && final_construction >= FULL_CON
    });

    if crossed_full_con {
        for callback in ["Completion", "Initialize"] {
            if let Some(Err(error)) = call_world_object_own_function(target, callback, &[]) {
                tracing::warn!(
                    id = target.as_u64(),
                    callback,
                    %error,
                    "creation callback failed; continuing like C++ fail-safe Call"
                );
            }
        }
    }

    let removed = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return true;
        };
        if context.nested_object_destroyed(target) {
            return true;
        }
        // FnCreateObject applies the creating controller only after
        // Game.CreateObject (and therefore every lifecycle callback) returns
        // (C4Script.cpp:1886-1902).
        if let Some(controller) = creator_controller {
            if let Some(scope) = context.object_scope_mut(target) {
                scope.set_controller(controller);
            }
            if let Some(preview) = context.pending_objects.get_mut(&target) {
                if let Some(state) = preview.state.as_mut() {
                    Rc::make_mut(state).controller = controller;
                }
            }
        }
        false
    });
    Ok(if removed {
        Value::Nil
    } else {
        object_reference_value(target)
    })
}

fn cast_objects(args: &[Value]) -> Result<Value, RuntimeError> {
    // FnCastObjects -> C4Game::CastObjects (C4Script.cpp:2476-2480,
    // C4Game.cpp:1727-1739): every attempt draws rdir, ydir, xdir and
    // rotation in that order, then creates the object synchronously.
    if args.len() > 5 {
        return Err(RuntimeError::new(
            "CastObjects: additional arguments are not supported",
        ));
    }

    let definition = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) | Value::C4Id(name) if !name.is_empty() => Some(name.clone()),
        Value::String(_) | Value::C4Id(_) | Value::Nil | Value::Int(0) => None,
        other => {
            return Err(RuntimeError::new(format!(
                "CastObjects: expected id for definition, got {}",
                other.type_name()
            )))
        }
    };
    let amount = args
        .get(1)
        .map(|value| value_to_i32(value, "CastObjects", "amount"))
        .transpose()?
        .unwrap_or(0);
    let level = args
        .get(2)
        .map(|value| value_to_i32(value, "CastObjects", "level"))
        .transpose()?
        .unwrap_or(0);
    let x_offset = args
        .get(3)
        .map(|value| value_to_i32(value, "CastObjects", "x"))
        .transpose()?
        .unwrap_or(0);
    let y_offset = args
        .get(4)
        .map(|value| value_to_i32(value, "CastObjects", "y"))
        .transpose()?
        .unwrap_or(0);

    let (creator, base_position, owner, controller) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("CastObjects requires an active engine context"))?;
        let creator = context.object_context().map(ObjectScopeContext::id);
        let base_position = context
            .object_context()
            .map(ObjectScopeContext::effective_position)
            .unwrap_or(Vector2::ZERO);
        let owner = context
            .object_context()
            .map(ObjectScopeContext::owner)
            .unwrap_or(OWNER_NONE);
        let controller = context
            .object_context()
            .map(ObjectScopeContext::controller)
            .unwrap_or(OWNER_NONE);
        Ok((creator, base_position, owner, controller))
    })?;

    let spread = level.wrapping_mul(2).wrapping_add(1);
    for _ in 0..amount {
        // Force the C++ argument-evaluation order. Definition lookup happens
        // only after these draws, so missing ids consume the same ledger.
        let sampled_rdir = itofix(draw_context_random(3)? + 1);
        let ydir = fixed10(draw_context_random(spread)?.wrapping_sub(level));
        let xdir = fixed10(draw_context_random(spread)?.wrapping_sub(level));
        let sampled_rotation = draw_context_random(360)?;

        let Some(definition) = definition.as_ref() else {
            continue;
        };
        let target = HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let context = borrow.as_mut().ok_or_else(|| {
                RuntimeError::new("CastObjects requires an active engine context")
            })?;
            if context.world.definition_known(definition) == Some(false) {
                return Ok(None);
            }

            let metadata = context
                .definition_metadata(definition)
                .cloned()
                .unwrap_or_else(|| DefinitionMetadata {
                    name: String::new(),
                    portrait_names: Vec::new(),
                    category: context
                        .definition_category(definition)
                        .unwrap_or(DEFAULT_CATEGORY),
                    border_bound: 0,
                    contact_function_calls: false,
                    blit_mode: 0,
                    ocf_base: ocf::NORMAL,
                crew_member: false,
                silent_commands: false,
                vehicle_control: 0,
                action_library: ActionLibrary::default(),
                    action_graphics: HashMap::new(),
                    value: 0,
                    mass: 0,
                    no_component_mass: false,
                    constructable: false,
                    shape: None,
                    placement: 0,
                    growth: 0,
                    construction_offset: 0,
                    basement: 0,
                    physical: PhysicalInfo::default(),
                    components: Vec::new(),
                    collection_limit: 0,
                    grab_put_get: 0,
                    line_connect: 0,
                    clonk_name_newlines: None,
                    stretch_growth: false,
                    rotateable: 0,
                    line: 0,
                    vertices: Vec::new(),
                    contact_density: None,
                    fire: DefinitionFireMetadata::default(),
                });
            // C4Object::Init discards sampled rotation/rdir for definitions
            // without Rotateable, after the synced draws already happened.
            let (rotation, rdir) = if metadata.rotateable == 0 {
                (0, C4Fixed::ZERO)
            } else {
                (sampled_rotation, sampled_rdir)
            };
            let fixed_velocity = FixedVec2::new(xdir, ydir);
            let initial_controller = if controller > OWNER_NONE {
                controller
            } else {
                owner
            };
            // Init reads pCreator->pLayer for every object; an earlier
            // synchronous callback may have changed the creator's layer.
            let creator_layer = creator.and_then(|id| context.object_layer(id));
            let raw_position = Vector2::new(
                base_position.x.saturating_add(x_offset),
                base_position.y.saturating_add(y_offset),
            );
            let position = Vector2::new(
                raw_position.x,
                crate::docon_initial_center_y(
                    metadata.shape,
                    metadata.stretch_growth,
                    metadata.line,
                    crate::FULL_CON,
                    raw_position.y,
                ),
            );
            let id = context.allocate_object_id();
            let mut spawn = SpawnConfig::new(definition.clone())
                .with_position(position)
                .with_fixed_velocity(fixed_velocity)
                .with_rotation(rotation)
                .with_rotation_velocity(rdir)
                .with_owner(owner)
                .with_controller(controller)
                .with_category(metadata.category)
                .with_id(id);
            if let Some(layer) = creator_layer {
                spawn = spawn.with_layer(layer);
            }
            // NewObject callbacks run below while this host call is live.
            spawn.initialized = true;
            spawn.position_adjusted = true;
            if position.y != raw_position.y {
                spawn.fixed_position = Some(FixedVec2::from_ints(raw_position.x, raw_position.y));
            }

            let initial_alive = metadata.category & crate::CATEGORY_LIVING != 0;
            let preview_ocf = ocf::compute(
                metadata.ocf_base,
                metadata.crew_member,
                initial_alive,
                ObjectStatus::Normal,
                false,
                0,
                metadata.category,
            );
            let preview_velocity = Vector2::new(fixed_velocity.int_x(), fixed_velocity.int_y());
            let preview = HostWorldObject::with_category(
                id,
                definition.clone(),
                ObjectStatus::Normal,
                "Idle",
                None,
                None,
                None,
                owner,
                metadata.category,
                if initial_alive {
                    metadata.physical.energy
                } else {
                    0
                },
                0,
                0,
                raw_position,
                preview_velocity,
                rotation,
                metadata.vertices.clone(),
                0,
                0,
                0,
                None,
                None,
            )
            .with_rotation_velocity(rdir)
            .with_alive(initial_alive)
            .with_ocf(preview_ocf)
            .with_full_state(Rc::new({
                let mut state = crate::preview_spawn_state_with_components(
                    raw_position,
                    owner,
                    initial_controller,
                    metadata.category,
                    0,
                    metadata.contact_density(),
                    metadata.vertices.clone(),
                    metadata.components.as_slice(),
                );
                state.velocity = preview_velocity;
                state.script_fixed_velocity = Some(fixed_velocity);
                state.script_rotation_velocity = Some(rdir);
                state.rotation = rotation;
                state.alive = initial_alive;
                state.energy = if initial_alive {
                    metadata.physical.energy
                } else {
                    0
                };
                state.crew_member = metadata.crew_member;
                state.layer = creator_layer;
                state.blit_mode = metadata.blit_mode;
                state.mobile = metadata.category != crate::CATEGORY_STATIC_BACK
                    && (fixed_velocity != FixedVec2::ZERO || rdir.is_nonzero());
                state
            }));
            context.register_spawn(spawn, preview);
            // Seed exact fixed dirs into the pending object's live scope so
            // its synchronous callbacks observe the Init values.
            if context.ensure_object_scope(id) {
                if let Some(scope) = context.object_scope_mut(id) {
                    scope.current_fixed_velocity = fixed_velocity;
                    scope.pending_update.rotation_velocity = Some(rdir);
                }
            }
            Ok(Some((
                id,
                metadata.shape,
                metadata.stretch_growth,
                metadata.line,
            )))
        })?;
        let Some((target, shape, stretch_growth, line)) = target else {
            continue;
        };

        let creator_arg = creator.map(object_reference_value).unwrap_or(Value::Nil);
        if let Some(Err(error)) =
            call_world_object_own_function(target, "Construction", &[creator_arg])
        {
            tracing::warn!(
                id = target.as_u64(),
                callback = "Construction",
                %error,
                "creation callback failed; continuing like C++ fail-safe Call"
            );
        }
        let removed = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .map(|context| context.nested_object_destroyed(target))
                .unwrap_or(false)
        });
        if removed {
            continue;
        }

        // NewObject calls Construction while Con is still zero, then its
        // initial DoCon grows to FullCon, moves the straight shape's bottom,
        // and only on that transition calls Completion then Initialize
        // (C4Game.cpp:1117-1127; C4Object.cpp:1506-1511).
        let crossed_full_con = HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let Some(context) = borrow.as_mut() else {
                return false;
            };
            let was_full = context
                .object_scope(target)
                .is_some_and(|scope| scope.construction() >= FULL_CON);
            let Some(final_construction) = context.adjust_object_construction(target, FULL_CON)
            else {
                return false;
            };
            let (pre_growth_position, adjusted_position) = {
                let Some(scope) = context.object_scope_mut(target) else {
                    return false;
                };
                let pre_growth_position = scope.effective_position();
                let adjusted_position = Vector2::new(
                    pre_growth_position.x,
                    crate::docon_initial_center_y(
                        shape,
                        stretch_growth,
                        line,
                        FULL_CON,
                        pre_growth_position.y,
                    ),
                );
                // Fold the pre-insertion Construction writes into the spawn
                // itself. Completion must see the adjusted integer y, but
                // initial DoCon leaves fix_y at the pre-growth center.
                scope.pending_update.construction = None;
                scope.current_position = adjusted_position;
                scope.pending_update.position = None;
                (pre_growth_position, adjusted_position)
            };
            if let Some(spawn) = context
                .pending_spawns
                .iter_mut()
                .find(|spawn| spawn.id == Some(target))
            {
                spawn.position = adjusted_position;
                spawn.construction = final_construction;
                spawn.fixed_position = (adjusted_position != pre_growth_position).then_some(
                    FixedVec2::from_ints(pre_growth_position.x, pre_growth_position.y),
                );
            }
            !was_full && final_construction >= FULL_CON
        });
        if crossed_full_con {
            if let Some(Err(error)) = call_world_object_own_function(target, "Completion", &[]) {
                tracing::warn!(
                    id = target.as_u64(),
                    callback = "Completion",
                    %error,
                    "creation callback failed; continuing like C++ fail-safe Call"
                );
            }
            let removed = HOST_CONTEXT.with(|cell| {
                cell.borrow()
                    .as_ref()
                    .map(|context| context.nested_object_destroyed(target))
                    .unwrap_or(false)
            });
            if !removed {
                if let Some(Err(error)) =
                    call_world_object_own_function(target, "Initialize", &[])
                {
                    tracing::warn!(
                        id = target.as_u64(),
                        callback = "Initialize",
                        %error,
                        "creation callback failed; continuing like C++ fail-safe Call"
                    );
                }
            }
        }
    }

    Ok(Value::Nil)
}

fn cast_pxs(args: &[Value]) -> Result<Value, RuntimeError> {
    // FnCastPXS -> C4PXSSystem::Cast (C4Script.cpp:2470-2474,
    // C4PXS.cpp:309-321): resolve the material once, offset local x/y by
    // the caller, then consume r2/r1 for every attempt even when the
    // material lookup failed. The engine function is void.
    let material_name = parse_optional_string(args.first(), "CastPXS", "material")?
        .unwrap_or_default();
    let amount = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "CastPXS",
        "amount",
    )?;
    let level = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "CastPXS",
        "level",
    )?;
    let x_offset = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "CastPXS", "x")?;
    let y_offset = value_to_i32(args.get(4).unwrap_or(&Value::Nil), "CastPXS", "y")?;

    let (material, position) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("CastPXS requires an active engine context"))?;
        let material = context
            .world
            .materials()
            .and_then(|materials| materials.id_of(&material_name));
        let base = context
            .object_context()
            .map(ObjectScopeContext::effective_position)
            .unwrap_or(Vector2::ZERO);
        Ok((
            material,
            Vector2::new(
                base.x.saturating_add(x_offset),
                base.y.saturating_add(y_offset),
            ),
        ))
    })?;

    let velocities = RANDOM_CONTEXT.with(|cell| {
        let context = cell
            .borrow()
            .as_ref()
            .ok_or_else(|| RuntimeError::new("random context unavailable"))?
            .clone();
        let mut rng = context.rng.borrow_mut();
        Ok::<_, RuntimeError>(
            (0..amount)
                .map(|_| crate::pxs::PxsSystem::sample_cast_velocity(&mut rng, level))
                .collect::<Vec<_>>(),
        )
    })?;

    if let Some(material) = material {
        HOST_CONTEXT.with(|cell| {
            let mut borrow = cell.borrow_mut();
            let context = borrow
                .as_mut()
                .ok_or_else(|| RuntimeError::new("CastPXS requires an active engine context"))?;
            context.register_landscape_operation(LandscapeOperation::CastPxs {
                material,
                position,
                velocities,
            });
            Ok::<_, RuntimeError>(())
        })?;
    }

    Ok(Value::Nil)
}

fn placement_find_liquid_height(
    landscape: &Landscape,
    x: i32,
    y: &mut i32,
    height: i32,
) -> bool {
    let world_height = landscape.estimated_height();
    let (mut cy1, mut cy2) = (*y, *y);
    let (mut rl1, mut rl2) = (0, 0);
    while cy1 >= 0 || cy2 < world_height {
        if cy1 >= 0 {
            if landscape.is_liquid_at(x, cy1) {
                rl1 += 1;
                if rl1 >= height {
                    *y = cy1 + height / 2;
                    return true;
                }
            } else {
                rl1 = 0;
            }
        }
        if cy2 + 1 < world_height {
            if landscape.is_liquid_at(x, cy2) {
                rl2 += 1;
                if rl2 >= height {
                    *y = cy2 - height / 2;
                    return true;
                }
            } else {
                rl2 = 0;
            }
        }
        cy1 -= 1;
        cy2 += 1;
    }
    false
}

fn placement_find_surface_liquid(
    landscape: &Landscape,
    x: &mut i32,
    y: &mut i32,
    width: i32,
    height: i32,
) -> bool {
    let world_width = landscape.width() as i32;
    let (mut cx1, mut cx2) = (*x, *x);
    let (mut cy1, mut cy2) = (*y, *y);
    let (mut rl1, mut rl2) = (0, 0);
    let mut found = false;
    while cx1 > 0 || cx2 < world_width {
        if cx1 > 0 {
            match landscape.above_semi_solid(cx1, cy1) {
                Some(adjusted) => {
                    cy1 = adjusted;
                    if (0..height).all(|offset| landscape.is_liquid_at(cx1, cy1 + 1 + offset)) {
                        rl1 += 1;
                    } else {
                        rl1 = 0;
                    }
                }
                None => cx1 = -1,
            }
        }
        if cx2 < world_width {
            match landscape.above_semi_solid(cx2, cy2) {
                Some(adjusted) => {
                    cy2 = adjusted;
                    if (0..height).all(|offset| landscape.is_liquid_at(cx2, cy2 + 1 + offset)) {
                        rl2 += 1;
                    } else {
                        rl2 = 0;
                    }
                }
                None => cx2 = world_width,
            }
        }
        if rl1 >= width {
            *x = cx1 + rl1 / 2;
            *y = cy1;
            found = true;
            break;
        }
        if rl2 >= width {
            *x = cx2 - rl2 / 2;
            *y = cy2;
            found = true;
            break;
        }
        cx1 -= 1;
        cx2 += 1;
    }
    if found {
        if let Some(adjusted) = landscape.above_semi_solid(*x, *y) {
            *y = adjusted;
        }
    }
    found
}

fn placement_find_liquid(
    landscape: &Landscape,
    x: &mut i32,
    y: &mut i32,
    width: i32,
    height: i32,
) -> bool {
    let world_width = landscape.width() as i32;
    let (mut cx1, mut cx2) = (*x, *x);
    let (mut cy1, mut cy2) = (*y, *y);
    let (mut rl1, mut rl2) = (0, 0);
    while cx1 > 0 || cx2 < world_width {
        if cx1 > 0 {
            if placement_find_liquid_height(landscape, cx1, &mut cy1, height) {
                rl1 += 1;
            } else {
                rl1 = 0;
            }
        }
        if cx2 < world_width {
            if placement_find_liquid_height(landscape, cx2, &mut cy2, height) {
                rl2 += 1;
            } else {
                rl2 = 0;
            }
        }
        if rl1 >= width {
            *x = cx1 + rl1 / 2;
            *y = cy1;
            return true;
        }
        if rl2 >= width {
            *x = cx2 - rl2 / 2;
            *y = cy2;
            return true;
        }
        cx1 -= 1;
        cx2 += 1;
    }
    false
}

struct PlacementObjectRegistration {
    target: ObjectId,
    growth: i32,
    shape: Option<DefinitionRect>,
    stretch_growth: bool,
    line: i32,
}

/// Register the zero-construction object that C4Game::NewObject exposes
/// before PSF_Construction. Runtime placement hosts share this exact preview
/// and pending-spawn setup; the callback/DoCon half lives in
/// [`finish_placement_object_creation`].
fn register_placement_object(
    context: &mut EffectHostContext,
    definition: String,
    metadata: DefinitionMetadata,
    position: Vector2,
    growth: i32,
) -> PlacementObjectRegistration {
    let id = context.allocate_object_id();
    let mut spawn = SpawnConfig::new(definition.clone())
        .with_position(position)
        .with_owner(OWNER_NONE)
        .with_controller(OWNER_NONE)
        .with_category(metadata.category)
        .with_construction(0)
        .with_id(id);
    // NewObject's callbacks and initial DoCon run below while this host
    // call is live. Materialization must not repeat either operation.
    spawn.initialized = true;
    spawn.position_adjusted = true;
    let initial_alive = metadata.category & crate::CATEGORY_LIVING != 0;
    let preview_ocf = ocf::compute(
        metadata.ocf_base,
        metadata.crew_member,
        initial_alive,
        ObjectStatus::Normal,
        false,
        0,
        metadata.category,
    );
    let preview = HostWorldObject::with_category(
        id,
        definition,
        ObjectStatus::Normal,
        "Idle",
        None,
        None,
        None,
        OWNER_NONE,
        metadata.category,
        if initial_alive {
            metadata.physical.energy
        } else {
            0
        },
        0,
        0,
        position,
        Vector2::ZERO,
        0,
        metadata.vertices.clone(),
        0,
        0,
        0,
        None,
        None,
    )
    .with_alive(initial_alive)
    .with_ocf(preview_ocf)
    .with_full_state(Rc::new({
        let mut state = crate::preview_spawn_state_with_components(
            position,
            OWNER_NONE,
            OWNER_NONE,
            metadata.category,
            0,
            metadata.contact_density(),
            metadata.vertices.clone(),
            metadata.components.as_slice(),
        );
        state.alive = initial_alive;
        state.energy = if initial_alive {
            metadata.physical.energy
        } else {
            0
        };
        state.crew_member = metadata.crew_member;
        state.blit_mode = metadata.blit_mode;
        state
    }));
    context.register_spawn(spawn, preview);
    context.ensure_object_scope(id);
    PlacementObjectRegistration {
        target: id,
        growth: growth.clamp(0, FULL_CON),
        shape: metadata.shape,
        stretch_growth: metadata.stretch_growth,
        line: metadata.line,
    }
}

/// Complete C4Game::NewObject after the object has become script-visible:
/// Construction(nil), initial DoCon, Completion/Initialize on the full-con
/// transition, and nullptr if any callback assigned removal.
fn finish_placement_object_creation(
    registration: PlacementObjectRegistration,
) -> Result<Value, RuntimeError> {
    let PlacementObjectRegistration {
        target,
        growth,
        shape,
        stretch_growth,
        line,
    } = registration;

    if let Some(Err(error)) =
        call_world_object_own_function(target, "Construction", &[Value::Nil])
    {
        tracing::warn!(
            id = target.as_u64(),
            callback = "Construction",
            %error,
            "creation callback failed; continuing like C++ fail-safe Call"
        );
    }
    let removed = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .map(|context| context.nested_object_destroyed(target))
            .unwrap_or(false)
    });
    if removed {
        return Ok(Value::Nil);
    }

    let crossed_full_con = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let was_full = context
            .object_scope(target)
            .is_some_and(|scope| scope.construction() >= FULL_CON);
        let Some(final_construction) = context.adjust_object_construction(target, growth) else {
            return false;
        };
        let (pre_growth_position, adjusted_position) = {
            let Some(scope) = context.object_scope_mut(target) else {
                return false;
            };
            let pre_growth_position = scope.effective_position();
            let adjusted_position = Vector2::new(
                pre_growth_position.x,
                crate::docon_initial_center_y(
                    shape,
                    stretch_growth,
                    line,
                    final_construction,
                    pre_growth_position.y,
                ),
            );
            scope.pending_update.construction = None;
            scope.current_position = adjusted_position;
            scope.pending_update.position = None;
            (pre_growth_position, adjusted_position)
        };
        if let Some(spawn) = context
            .pending_spawns
            .iter_mut()
            .find(|spawn| spawn.id == Some(target))
        {
            spawn.position = adjusted_position;
            spawn.construction = final_construction;
            spawn.fixed_position = (adjusted_position != pre_growth_position)
                .then_some(FixedVec2::from_ints(
                    pre_growth_position.x,
                    pre_growth_position.y,
                ));
        }
        !was_full && final_construction >= FULL_CON
    });
    if crossed_full_con {
        if let Some(Err(error)) = call_world_object_own_function(target, "Completion", &[]) {
            tracing::warn!(
                id = target.as_u64(),
                callback = "Completion",
                %error,
                "creation callback failed; continuing like C++ fail-safe Call"
            );
        }
        let removed = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .map(|context| context.nested_object_destroyed(target))
                .unwrap_or(false)
        });
        if !removed {
            if let Some(Err(error)) = call_world_object_own_function(target, "Initialize", &[]) {
                tracing::warn!(
                    id = target.as_u64(),
                    callback = "Initialize",
                    %error,
                    "creation callback failed; continuing like C++ fail-safe Call"
                );
            }
        }
    }

    let removed = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .map(|context| context.nested_object_destroyed(target))
            .unwrap_or(false)
    });
    Ok(if removed {
        Value::Nil
    } else {
        object_reference_value(target)
    })
}

/// FnPlaceAnimal -> C4Game::PlaceAnimal (C4Script.cpp:2495-2499;
/// C4Game.cpp:3028-3061): placement is GLOBAL and creatorless. Definition
/// validation and the Placement switch happen before any synced draw; the
/// three supported arms then use the exact C++ search order.
fn place_animal(args: &[Value]) -> Result<Value, RuntimeError> {
    let definition = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) | Value::C4Id(name) if !name.is_empty() => name.clone(),
        Value::String(_) | Value::C4Id(_) | Value::Nil | Value::Int(0) => {
            return Ok(Value::Nil)
        }
        other => {
            return Err(RuntimeError::new(format!(
                "PlaceAnimal: expected id for definition, got {}",
                other.type_name()
            )))
        }
    };

    let registration = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("PlaceAnimal requires an active engine context"))?;
        let Some(metadata) = context.definition_metadata(&definition).cloned() else {
            // C4Id2Def failure precedes the Placement switch and Random
            // (C4Game.cpp:3028-3035).
            return Ok(None);
        };
        if !matches!(metadata.placement, 0..=2) {
            return Ok(None);
        }
        let (shape_width, shape_height) = metadata
            .shape
            .map(|shape| (shape.width, shape.height))
            .unwrap_or((0, 0));
        let landscape = context.landscape_ref();
        let world_width = landscape.map(|landscape| landscape.width() as i32).unwrap_or(0);
        let world_height = landscape
            .map(Landscape::estimated_height)
            .unwrap_or(0);
        let position = match metadata.placement {
            // Running free: exactly two draws, even when the ground search
            // later fails (C4Game.cpp:3037-3041).
            0 => {
                let x = draw_context_random(world_width)?;
                let y = draw_context_random(world_height)?;
                let Some((x, y)) = landscape
                    .and_then(|landscape| landscape.find_solid_ground(x, y, shape_width))
                else {
                    return Ok(None);
                };
                Vector2::new(x, y)
            }
            // In liquid: surface search first, then the deep fallback. Both
            // consume only the initial x/y draws (C4Game.cpp:3043-3051).
            1 => {
                let mut x = draw_context_random(world_width)?;
                let mut y = draw_context_random(world_height)?;
                let Some(landscape) = landscape else {
                    return Ok(None);
                };
                if !placement_find_surface_liquid(
                    landscape,
                    &mut x,
                    &mut y,
                    shape_width,
                    shape_height,
                ) && !placement_find_liquid(
                    landscape,
                    &mut x,
                    &mut y,
                    shape_width,
                    shape_height,
                ) {
                    return Ok(None);
                }
                Vector2::new(x, y.wrapping_add(shape_height / 2))
            }
            // Air: x draw, top-down first-semisolid scan, then y draw only
            // when the scan result is positive (C4Game.cpp:3053-3060).
            2 => {
                let x = draw_context_random(world_width)?;
                let mut y = 0;
                while y < world_height
                    && landscape.is_some_and(|landscape| !landscape.is_semi_solid_at(x, y))
                {
                    y += 1;
                }
                if y <= 0 {
                    return Ok(None);
                }
                Vector2::new(x, draw_context_random(y)?)
            }
            _ => unreachable!("placement validated above"),
        };
        Ok(Some(register_placement_object(
            context,
            definition,
            metadata,
            position,
            FULL_CON,
        )))
    })?;
    let Some(registration) = registration else {
        return Ok(Value::Nil);
    };
    finish_placement_object_creation(registration)
}

fn place_vegetation(args: &[Value]) -> Result<Value, RuntimeError> {
    let definition = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) | Value::C4Id(name) if !name.is_empty() => name.clone(),
        Value::String(_) | Value::C4Id(_) | Value::Nil | Value::Int(0) => return Ok(Value::Nil),
        other => {
            return Err(RuntimeError::new(format!(
                "PlaceVegetation: expected id for definition, got {}",
                other.type_name()
            )))
        }
    };
    let x = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "PlaceVegetation",
        "x",
    )?;
    let y = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "PlaceVegetation",
        "y",
    )?;
    let width = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "PlaceVegetation",
        "width",
    )?;
    let height = value_to_i32(
        args.get(4).unwrap_or(&Value::Nil),
        "PlaceVegetation",
        "height",
    )?;
    let requested_growth = value_to_i32(
        args.get(5).unwrap_or(&Value::Nil),
        "PlaceVegetation",
        "growth",
    )?;

    let registration = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("PlaceVegetation requires an active engine context")
        })?;
        let Some(metadata) = context.definition_metadata(&definition).cloned() else {
            // C4Id2Def failure happens before the first Random draw
            // (C4Game.cpp:2985-2986).
            return Ok(None);
        };
        let base = context
            .object_context()
            .map(ObjectScopeContext::effective_position)
            .unwrap_or(Vector2::ZERO);
        let area_x = base.x.wrapping_add(x);
        let area_y = base.y.wrapping_add(y);

        let mut growth = requested_growth;
        if growth <= 0 {
            growth = FULL_CON;
            if metadata.growth != 0 && draw_context_random(3)? == 0 {
                growth = draw_context_random(FULL_CON)?.wrapping_add(1);
            }
        }

        let (shape_width, shape_height) = metadata
            .shape
            .map(|shape| (shape.width, shape.height))
            .unwrap_or((0, 0));
        let Some(landscape) = context.landscape_ref() else {
            return Ok(None);
        };
        let bottom = match metadata.placement {
            // C4D_Place_Surface (C4Game.cpp:2998-3024).
            0 => {
                let mut found = None;
                for _ in 0..20 {
                    let tx = area_x.wrapping_add(draw_context_random(width)?);
                    let mut ty = area_y.wrapping_add(draw_context_random(height)?);
                    while ty > 0 && landscape.is_ift_at(tx, ty) {
                        ty -= 1;
                    }
                    let Some(ty) = landscape.above_semi_solid(tx, ty) else {
                        continue;
                    };
                    if !(50..=landscape.estimated_height() - 50).contains(&ty) {
                        continue;
                    }
                    if landscape.is_semi_solid_at(tx, ty - shape_height)
                        || landscape.is_semi_solid_at(tx, ty - shape_height / 2)
                        || landscape.is_semi_solid_at(
                            tx - shape_width / 2,
                            ty - shape_height * 2 / 3,
                        )
                        || landscape.is_semi_solid_at(
                            tx + shape_width / 2,
                            ty - shape_height * 2 / 3,
                        )
                    {
                        continue;
                    }
                    let soil_y = ty.wrapping_add(3);
                    let is_soil = landscape
                        .border_material_at(tx, soil_y)
                        .and_then(|material| {
                            context
                                .world
                                .materials()
                                .and_then(|materials| materials.get_by_id(material))
                        })
                        .and_then(|material| material.definition().int("Soil"))
                        .is_some_and(|soil| soil != 0);
                    if !is_soil {
                        continue;
                    }
                    if metadata.growth == 0 {
                        growth = FULL_CON;
                    }
                    found = Some(Vector2::new(tx, soil_y.wrapping_add(5)));
                    break;
                }
                let Some(found) = found else {
                    return Ok(None);
                };
                found
            }
            // C4D_Place_Liquid (C4Game.cpp:3027-3039).
            1 => {
                let mut tx = area_x.wrapping_add(draw_context_random(width)?);
                let mut ty = area_y.wrapping_add(draw_context_random(height)?);
                if !placement_find_surface_liquid(
                    landscape,
                    &mut tx,
                    &mut ty,
                    shape_width,
                    shape_height,
                ) && !placement_find_liquid(
                    landscape,
                    &mut tx,
                    &mut ty,
                    shape_width,
                    shape_height,
                ) {
                    return Ok(None);
                }
                let Some(ty) = landscape.semi_above_solid(tx, ty) else {
                    return Ok(None);
                };
                Vector2::new(tx, ty.wrapping_add(3))
            }
            _ => return Ok(None),
        };

        Ok(Some(register_placement_object(
            context,
            definition,
            metadata,
            bottom,
            growth,
        )))
    })?;
    let Some(registration) = registration else {
        return Ok(Value::Nil);
    };
    finish_placement_object_creation(registration)
}

fn create_construction(args: &[Value]) -> Result<Value, RuntimeError> {
    // FnCreateConstruction takes a C4ID (C4Script.cpp:1911-1912); our
    // resources address definitions by their id string, so id values and
    // strings coincide.
    let definition = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) | Value::C4Id(name) if !name.is_empty() => name.clone(),
        Value::String(_) | Value::C4Id(_) | Value::Nil | Value::Int(0) => return Ok(Value::Nil),
        other => {
            return Err(RuntimeError::new(format!(
                "CreateConstruction: expected id for definition, got {}",
                other.type_name()
            )))
        }
    };

    let mut index = 1;

    let x_offset = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "CreateConstruction", "x")?;
        index += 1;
        value
    } else {
        0
    };

    let y_offset = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "CreateConstruction", "y")?;
        index += 1;
        value
    } else {
        0
    };

    let requested_owner = if let Some(arg) = args.get(index) {
        let owner = value_to_i32(arg, "CreateConstruction", "owner")?;
        index += 1;
        owner
    } else {
        0
    };

    let completion_percent = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "CreateConstruction", "completion")?;
        index += 1;
        value
    } else {
        0
    };

    let terrain_flag = if let Some(arg) = args.get(index) {
        let flag = value_to_bool(arg, "CreateConstruction", "terrain")?;
        index += 1;
        flag
    } else {
        false
    };

    let check_site = if let Some(arg) = args.get(index) {
        let flag = value_to_bool(arg, "CreateConstruction", "check_site")?;
        index += 1;
        flag
    } else {
        false
    };

    if index < args.len() {
        return Err(RuntimeError::new(
            "CreateConstruction: additional arguments are not supported",
        ));
    }

    let registration = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("CreateConstruction requires an active engine context")
        })?;

        // C4Id2Def failure: no site, silent nullptr (C4Game.cpp:1183).
        if context.world.definition_known(&definition) == Some(false) {
            return Ok(None);
        }

        let metadata = context
            .definition_metadata(&definition)
            .cloned()
            .unwrap_or_else(|| DefinitionMetadata {
                name: String::new(),
                portrait_names: Vec::new(),
                category: context
                    .definition_category(&definition)
                    .unwrap_or(DEFAULT_CATEGORY),
                border_bound: 0,
                contact_function_calls: false,
                blit_mode: 0,
                ocf_base: ocf::NORMAL,
                crew_member: false,
                silent_commands: false,
                vehicle_control: 0,
                action_library: ActionLibrary::default(),
                action_graphics: HashMap::new(),
                value: 0,
                mass: 0,
                no_component_mass: false,
                constructable: true,
                shape: None,
                placement: 0,
                growth: 0,
                construction_offset: 0,
                basement: 0,
                physical: PhysicalInfo::default(),
                components: Vec::new(),
                collection_limit: 0,
                grab_put_get: 0,
                line_connect: 0,
                clonk_name_newlines: None,
                stretch_growth: false,
                rotateable: 0,
                line: 0,
                vertices: Vec::new(),
                contact_density: None,
                fire: DefinitionFireMetadata::default(),
            });
        let definition_category = metadata.category;
        let creator = context.object_context().map(ObjectScopeContext::id);
        let creator_layer = creator.and_then(|creator| context.object_layer(creator));

        let base_position = context
            .object_context()
            .map(|object| object.effective_position())
            .unwrap_or(Vector2::ZERO);
        let substitute_local_owner = matches!(
            lc_script::caller_strictness(),
            lc_script::HostCallerStrictness::NoCaller
                | lc_script::HostCallerStrictness::NonStrict
        );
        let owner = if substitute_local_owner {
            context
                .object_context()
                .map(ObjectScopeContext::owner)
                .unwrap_or(requested_owner)
        } else {
            requested_owner
        };
        let position = Vector2::new(
            base_position.x.saturating_add(x_offset),
            base_position.y.saturating_add(y_offset),
        );

        let completion = completion_percent.clamp(0, 100);
        let construction_value = ((i64::from(completion) * i64::from(FULL_CON)) / 100)
            .clamp(0, i64::from(FULL_CON)) as i32;

        if check_site && !construction_check(context, &definition, &metadata, position)? {
            return Ok(None);
        }

        if terrain_flag {
            let (width, height) = metadata
                .shape
                .map(|shape| (shape.width, shape.height))
                .unwrap_or_default();
            context.prepare_construction_terrain(
                position.x,
                position.y,
                width,
                height,
                metadata.basement,
            );
        }

        let id = context.allocate_object_id();

        let mut spawn = SpawnConfig::new(definition.clone())
            .with_position(position)
            .with_owner(owner)
            .with_category(definition_category)
            // C4Game::NewObject inserts the object at Con=0, calls
            // Construction, and only then applies the requested iCon.
            .with_construction(0)
            .with_id(id);
        if let Some(layer) = creator_layer {
            spawn = spawn.with_layer(layer);
        }
        // The creating controller rides onto the site (FnCreateConstruction,
        // C4Script.cpp:1932-1933).
        let creator_controller = context
            .object_context()
            .map(ObjectScopeContext::controller)
            .filter(|value| *value > OWNER_NONE);
        if let Some(controller) = creator_controller {
            spawn = spawn.with_controller(controller);
        }
        // The lifecycle below runs while this host call is live; the later
        // copy-out spawn must not repeat callbacks or the initial DoCon.
        spawn.initialized = true;
        spawn.position_adjusted = true;

        let initial_alive = metadata.category & crate::CATEGORY_LIVING != 0;
        let preview_ocf = ocf::compute(
            metadata.ocf_base,
            metadata.crew_member,
            initial_alive,
            ObjectStatus::Normal,
            false,
            0,
            metadata.category,
        );
        let preview = HostWorldObject::with_category(
            id,
            definition,
            ObjectStatus::Normal,
            "Idle",
            None,
            None,
            None,
            owner,
            definition_category,
            if initial_alive {
                metadata.physical.energy
            } else {
                0
            },
            0,
            0,
            position,
            Vector2::ZERO,
            0,
            Vec::new(),
            0,
            0,
            0,
            None,
            None,
        )
        .with_alive(initial_alive)
        .with_ocf(preview_ocf)
        .with_full_state(Rc::new({
            let mut state = crate::preview_spawn_state_with_components(
                position,
                owner,
                creator_controller.unwrap_or(owner),
                definition_category,
                0,
                metadata.contact_density(),
                metadata.vertices.clone(),
                metadata.components.as_slice(),
            );
            state.alive = initial_alive;
            state.energy = if initial_alive {
                metadata.physical.energy
            } else {
                0
            };
            state.crew_member = metadata.crew_member;
            state.layer = creator_layer;
            state.blit_mode = metadata.blit_mode;
            state
        }));

        context.register_spawn(spawn, preview);
        Ok(Some((
            id,
            creator,
            construction_value,
            metadata.shape,
            metadata.stretch_growth,
            metadata.line,
            metadata.ocf_base,
            metadata.crew_member,
            metadata.category,
            initial_alive,
        )))
    })?;
    let Some((
        target,
        creator,
        construction_value,
        shape,
        stretch_growth,
        line,
        ocf_base,
        crew_member,
        category,
        alive,
    )) = registration
    else {
        return Ok(Value::Nil);
    };

    // C4Game::NewObject exposes the inserted object to scripts before
    // running PSF_Construction, passing the creator as its sole argument
    // (C4Game.cpp:1110-1121).
    let creator_arg = creator.map(object_reference_value).unwrap_or(Value::Nil);
    if let Some(Err(error)) =
        call_world_object_own_function(target, "Construction", &[creator_arg])
    {
        tracing::warn!(
            id = target.as_u64(),
            callback = "Construction",
            %error,
            "creation callback failed; continuing like C++ fail-safe Call"
        );
    }
    let removed = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .map(|context| context.nested_object_destroyed(target))
            .unwrap_or(false)
    });
    if removed {
        return Ok(Value::Nil);
    }

    // Initial DoCon adds iCon to whatever Construction left behind, keeps
    // the old shape bottom fixed in integer coordinates, and leaves fix_y
    // at the pre-growth position (C4Object.cpp:1432-1500).
    let (crossed_full_con, final_construction) = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return (false, 0);
        };
        if !context.ensure_object_scope(target) {
            return (false, 0);
        }
        let was_full = context
            .object_scope(target)
            .is_some_and(|scope| scope.construction() >= FULL_CON);
        let Some(final_construction) =
            context.adjust_object_construction(target, construction_value)
        else {
            return (false, 0);
        };
        let (pre_growth_position, adjusted_position) = {
            let Some(scope) = context.object_scope_mut(target) else {
                return (false, 0);
            };
            let pre_growth_position = scope.effective_position();
            let adjusted_position = Vector2::new(
                pre_growth_position.x,
                crate::docon_initial_center_y(
                    shape,
                    stretch_growth,
                    line,
                    final_construction,
                    pre_growth_position.y,
                ),
            );
            scope.pending_update.construction = None;
            scope.current_position = adjusted_position;
            scope.pending_update.position = None;
            scope.cached_ocf = Some(ocf::compute(
                ocf_base,
                crew_member,
                alive,
                ObjectStatus::Normal,
                false,
                final_construction,
                category,
            ));
            (pre_growth_position, adjusted_position)
        };
        if let Some(spawn) = context
            .pending_spawns
            .iter_mut()
            .find(|spawn| spawn.id == Some(target))
        {
            spawn.position = adjusted_position;
            spawn.construction = final_construction;
            spawn.fixed_position = (adjusted_position != pre_growth_position)
                .then_some(FixedVec2::from_ints(
                    pre_growth_position.x,
                    pre_growth_position.y,
                ));
        }
        (!was_full && final_construction >= FULL_CON, final_construction)
    });

    // DoCon(0) removes a zero-construction object, and NewObject returns
    // nullptr after its status re-check (C4Object.cpp:1513-1517;
    // C4Game.cpp:1122-1128).
    if final_construction <= 0 {
        HOST_CONTEXT.with(|cell| {
            if let Some(context) = cell.borrow_mut().as_mut() {
                context.cancel_pending_spawn(target);
                context.nested_objects.remove(&target);
                context.nested_order.retain(|id| *id != target);
            }
        });
        return Ok(Value::Nil);
    }

    if crossed_full_con {
        for callback in ["Completion", "Initialize"] {
            if let Some(Err(error)) = call_world_object_own_function(target, callback, &[]) {
                tracing::warn!(
                    id = target.as_u64(),
                    callback,
                    %error,
                    "creation callback failed; continuing like C++ fail-safe Call"
                );
            }
        }
    }

    let removed = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .map(|context| context.nested_object_destroyed(target))
            .unwrap_or(false)
    });
    Ok(if removed {
        Value::Nil
    } else {
        object_reference_value(target)
    })
}

fn construction_check(
    context: &EffectHostContext,
    definition_id: &str,
    metadata: &DefinitionMetadata,
    position: Vector2,
) -> Result<bool, RuntimeError> {
    if !metadata.constructable {
        return Ok(false);
    }

    let (raw_width, raw_height) = metadata
        .shape
        .map(|rect| (rect.width, rect.height))
        .unwrap_or((20, 40));
    let width = raw_width.max(1);
    let height = raw_height.max(1);
    let effective_height = height.saturating_sub(metadata.construction_offset).max(1);

    let rect_left = position.x - width / 2;
    let rect_right = rect_left + width;
    let rect_top = position.y - effective_height;
    let rect_bottom = position.y;

    let Some(landscape) = context.landscape_ref() else {
        return Ok(true);
    };

    let landscape_width = landscape.width() as i32;
    if rect_left < 0 || rect_right > landscape_width {
        return Ok(false);
    }

    // ConstructionCheck uses AreaSolidCount over the actual pixel plane;
    // column surface heights are not equivalent in caves or below a closed
    // roof (C4Landscape.cpp:1090-1098,2125-2158).
    let solid_count = (rect_top..rect_bottom)
        .flat_map(|y| (rect_left..rect_right).map(move |x| (x, y)))
        .filter(|&(x, y)| landscape.is_solid_at(x, y))
        .count()
        .min(i32::MAX as usize) as i32;
    let support_count = (rect_bottom..rect_bottom.saturating_add(5))
        .flat_map(|y| (rect_left..rect_right).map(move |x| (x, y)))
        .filter(|&(x, y)| landscape.is_solid_at(x, y))
        .count()
        .min(i32::MAX as usize) as i32;

    let area_threshold = ((i64::from(width) * i64::from(effective_height)) / 20)
        .clamp(0, i64::from(i32::MAX)) as i32;
    if solid_count > area_threshold {
        return Ok(false);
    }

    if support_count < width.saturating_mul(2) {
        return Ok(false);
    }

    let overlap_mask = metadata.category & CATEGORY_SORT_LIMIT;
    if overlap_mask == 0 {
        return Ok(true);
    }

    let current_object_id = context.object_context().map(|object| object.id());
    for object_id in context.world_object_ids() {
        let Some(other) = context.get_world_object(object_id) else {
            continue;
        };
        if Some(other.id) == current_object_id {
            continue;
        }
        if !other.is_present() || !other.status().is_active() {
            continue;
        }
        if other.container().is_some() {
            continue;
        }
        if other.category() & overlap_mask & CATEGORY_SORT_LIMIT == 0 {
            continue;
        }
        let other_metadata = if other.definition_id() == definition_id {
            Some(metadata)
        } else {
            context.definition_metadata(other.definition_id())
        };
        if let Some(bounds) = compute_object_bounds(&other, other_metadata) {
            if rectangles_overlap((rect_left, rect_top, rect_right, rect_bottom), bounds) {
                return Ok(false);
            }
        }
    }

    Ok(true)
}

/// `C4AUL_MAX_Par` (C4Aul.h:54): the NumVars/Par slot count that bounds
/// FindConstructionSite's var indices.
const AUL_MAX_PAR: i32 = 10;

/// `C4Value::getInt` tolerance on the staged Var slots: non-numeric
/// values read as 0.
fn value_as_int(value: &Value) -> i32 {
    match value {
        Value::Int(int) => *int,
        Value::Bool(flag) => i32::from(*flag),
        _ => 0,
    }
}

/// `Game.OverlapObject` (C4Game.cpp:1298-1313) over the host world: any
/// active, uncontained object whose category intersects `category` within
/// C4D_SortLimit and whose shape rect overlaps the given rect
/// (C4Rect::Overlap, C4Rect.cpp:92-99).
fn host_overlap_object(
    context: &EffectHostContext,
    x: i32,
    y: i32,
    wdt: i32,
    hgt: i32,
    category: i32,
) -> bool {
    context.world_object_ids().into_iter().any(|id| {
        let Some(object) = context.get_world_object(id) else {
            return false;
        };
        if !object.is_present() || !object.status().is_active() {
            return false;
        }
        if object.container().is_some() {
            return false;
        }
        if object.category() & category & CATEGORY_SORT_LIMIT == 0 {
            return false;
        }
        let metadata = context.definition_metadata(object.definition_id());
        let Some((left, top, right, bottom)) = compute_object_bounds(&object, metadata) else {
            return false;
        };
        x < right && left < x + wdt && y < bottom && top < y + hgt
    })
}

/// `FnFindConstructionSite` (C4Script.cpp:1958-1981): stages coordinates
/// through the CALLER's Var slots — reads the start position from
/// `Caller->NumVars[iVarX/iVarY]`, accepts it when ConstructionCheck
/// passes, else runs the FindConSiteSpot landscape probe
/// (C4Landscape.cpp:1987-2043, hrange 20) with the Game.OverlapObject
/// veto and writes the coordinates back into the caller's slots. The
/// planet System.c4g FindConstructionSiteX wrapper (Commits.c:384-390)
/// drives it — 10x DLAR Initialize in SkiesOfFire.
fn find_construction_site(args: &[Value]) -> Result<Value, RuntimeError> {
    // C4Id2Def failure yields the empty optional (:1962).
    let definition = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) | Value::C4Id(name) if !name.is_empty() => name.clone(),
        _ => return Ok(Value::Nil),
    };
    let var_x = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "FindConstructionSite",
        "iVarX",
    )?;
    let var_y = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "FindConstructionSite",
        "iVarY",
    )?;
    // Var indices out of range (:1964).
    if !(0..AUL_MAX_PAR).contains(&var_x) || !(0..AUL_MAX_PAR).contains(&var_y) {
        return Ok(Value::Nil);
    }
    // `if (!cthr->Caller) return {}` (:1966).
    let Some(slots) = lc_script::caller_var_slots() else {
        return Ok(Value::Nil);
    };
    let v1 = value_as_int(&slots.get(var_x));
    let v2 = value_as_int(&slots.get(var_y));

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref().ok_or_else(|| {
            RuntimeError::new("FindConstructionSite requires an active engine context")
        })?;
        let Some(metadata) = context.definition_metadata(&definition) else {
            return Ok(Value::Nil);
        };
        // Construction check at the starting position (:1970-1971): the
        // caller's vars stay untouched on an immediate hit.
        if construction_check(context, &definition, metadata, Vector2::new(v1, v2))? {
            return Ok(Value::Bool(true));
        }
        // Search for real (:1973-1977) with pDef->Shape.Wdt/Hgt and
        // Category.
        let (wdt, hgt) = metadata
            .shape
            .map(|rect| (rect.width, rect.height))
            .unwrap_or((0, 0));
        let category = metadata.category;
        let found = context.landscape_ref().and_then(|landscape| {
            landscape.find_con_site_spot(v1, v2, wdt, hgt, 20, |x, y, w, h| {
                host_overlap_object(context, x, y, w, h, category)
            })
        });
        // V1 = C4VInt(v1); V2 = C4VInt(v2) — written back even when the
        // probe found nothing (:1978).
        let (out_x, out_y) = found.unwrap_or((v1, v2));
        slots.set(var_x, Value::Int(out_x));
        slots.set(var_y, Value::Int(out_y));
        Ok(Value::Bool(found.is_some()))
    })
}

fn compute_object_bounds(
    object: &HostWorldObject,
    metadata: Option<&DefinitionMetadata>,
) -> Option<(i32, i32, i32, i32)> {
    if let Some(meta) = metadata {
        if let Some(shape) = meta.shape {
            let position = object.position();
            let left = position.x + shape.x;
            let top = position.y + shape.y;
            let right = left + shape.width;
            let bottom = top + shape.height;
            return Some((left, top, right, bottom));
        }
    }

    let vertices = object.vertices();
    if vertices.is_empty() {
        return None;
    }

    let mut min_x = vertices[0].x;
    let mut max_x = min_x;
    let mut min_y = vertices[0].y;
    let mut max_y = min_y;
    for vertex in vertices.iter().skip(1) {
        if vertex.x < min_x {
            min_x = vertex.x;
        }
        if vertex.x > max_x {
            max_x = vertex.x;
        }
        if vertex.y < min_y {
            min_y = vertex.y;
        }
        if vertex.y > max_y {
            max_y = vertex.y;
        }
    }

    let position = object.position();
    Some((
        position.x + min_x,
        position.y + min_y,
        position.x + max_x,
        position.y + max_y,
    ))
}

fn rectangles_overlap(a: (i32, i32, i32, i32), b: (i32, i32, i32, i32)) -> bool {
    let (a_left, a_top, a_right, a_bottom) = a;
    let (b_left, b_top, b_right, b_bottom) = b;
    a_left < b_right && a_right > b_left && a_top < b_bottom && a_bottom > b_top
}

fn create_particle(args: &[Value]) -> Result<Value, RuntimeError> {
    let definition = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) if !name.is_empty() => name.clone(),
        Value::String(_) | Value::Nil => return Ok(Value::Bool(false)),
        other => {
            return Err(RuntimeError::new(format!(
                "CreateParticle: expected string for name, got {}",
                other.type_name()
            )))
        }
    };

    let mut index = 1;

    let x = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "CreateParticle", "x")?;
        index += 1;
        value
    } else {
        0
    };

    let y = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "CreateParticle", "y")?;
        index += 1;
        value
    } else {
        0
    };

    let x_dir = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "CreateParticle", "xdir")?;
        index += 1;
        value
    } else {
        0
    };

    let y_dir = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "CreateParticle", "ydir")?;
        index += 1;
        value
    } else {
        0
    };

    let parameter_a = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "CreateParticle", "a")?;
        index += 1;
        value
    } else {
        0
    };

    let life_raw = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "CreateParticle", "b")?;
        index += 1;
        value
    } else {
        0
    };

    let mut target_object: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        target_object = parse_object_reference_argument(arg, "CreateParticle", "object")?;
        index += 1;
    }

    let mut back = false;
    if let Some(arg) = args.get(index) {
        back = value_to_bool(arg, "CreateParticle", "back")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "CreateParticle: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("CreateParticle requires an active engine context"))?;

        let base_position = context
            .object_context()
            .map(|object| object.effective_position())
            .unwrap_or(Vector2::ZERO);

        let world_x = base_position.x.saturating_add(x);
        let world_y = base_position.y.saturating_add(y);

        let layer = if let Some(target) = target_object {
            let world_object = match context.get_world_object(target) {
                Some(object) => object,
                None => return Ok(Value::Bool(false)),
            };
            if !world_object.status().is_active() {
                return Ok(Value::Bool(false));
            }
            if back {
                ParticleLayer::ObjectBack(target)
            } else {
                ParticleLayer::ObjectFront(target)
            }
        } else {
            ParticleLayer::Global
        };

        // GetDef failure → false (C4Script.cpp:4874)
        if context.particle_def_known(&definition) == Some(false) {
            return Ok(Value::Bool(false));
        }

        let config = ParticleConfig {
            definition_id: definition,
            position: FloatVector2::new(world_x as f32, world_y as f32),
            velocity: FloatVector2::new(x_dir as f32 / 10.0, y_dir as f32 / 10.0),
            life: life_raw.max(0),
            parameter_a: parameter_a as f32 / 10.0,
            parameter_b: life_raw,
            layer,
        };

        context.register_particle(ParticleCommand::Create(config));
        Ok(Value::Bool(true))
    })
}

/// FnCastAParticles (C4Script.cpp:4881-4898), shared by CastParticles and
/// CastBackParticles. Args: name, amount, level, x, y, a0, a1, b0, b1, obj.
fn cast_a_particles(args: &[Value], back: bool, fn_name: &str) -> Result<Value, RuntimeError> {
    let definition = match args.first() {
        Some(Value::String(name)) if !name.is_empty() => name.clone(),
        Some(Value::String(_)) | Some(Value::Nil) | None => return Ok(Value::Bool(false)),
        Some(other) => {
            return Err(RuntimeError::new(format!(
                "{fn_name}: expected string for name, got {}",
                other.type_name()
            )))
        }
    };

    let int_arg = |index: usize, label: &str| -> Result<i32, RuntimeError> {
        args.get(index)
            .map(|arg| value_to_i32(arg, fn_name, label))
            .transpose()
            .map(|value| value.unwrap_or(0))
    };
    let amount = int_arg(1, "amount")?;
    let level = int_arg(2, "level")?;
    let x = int_arg(3, "x")?;
    let y = int_arg(4, "y")?;
    let a0 = int_arg(5, "a0")?;
    let a1 = int_arg(6, "a1")?;
    let b0 = int_arg(7, "b0")? as u32;
    let b1 = int_arg(8, "b1")? as u32;

    let target_object = args
        .get(9)
        .map(|arg| parse_object_reference_argument(arg, fn_name, "object"))
        .transpose()?
        .flatten();

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new(format!("{fn_name} requires an active engine context"))
        })?;

        // safety: pObj && !pObj->Status → false (C4Script.cpp:4884)
        let layer = if let Some(target) = target_object {
            let world_object = match context.get_world_object(target) {
                Some(object) => object,
                None => return Ok(Value::Bool(false)),
            };
            if !world_object.status().is_active() {
                return Ok(Value::Bool(false));
            }
            if back {
                ParticleLayer::ObjectBack(target)
            } else {
                ParticleLayer::ObjectFront(target)
            }
        } else {
            ParticleLayer::Global
        };

        // GetDef failure → false (C4Script.cpp:4893)
        if context.particle_def_known(&definition) == Some(false) {
            return Ok(Value::Bool(false));
        }

        // local offset (C4Script.cpp:4886-4890)
        let base_position = context
            .object_context()
            .map(|object| object.effective_position())
            .unwrap_or(Vector2::ZERO);

        context.register_particle(ParticleCommand::Cast {
            definition_id: definition,
            amount,
            x: base_position.x.saturating_add(x) as f32,
            y: base_position.y.saturating_add(y) as f32,
            level,
            a0: a0 as f32 / 10.0,
            b0,
            a1: a1 as f32 / 10.0,
            b1,
            layer,
        });
        Ok(Value::Bool(true))
    })
}

fn cast_particles(args: &[Value]) -> Result<Value, RuntimeError> {
    cast_a_particles(args, false, "CastParticles")
}

fn cast_back_particles(args: &[Value]) -> Result<Value, RuntimeError> {
    cast_a_particles(args, true, "CastBackParticles")
}

/// FnPushParticles (C4Script.cpp:4910-4923): name nil → push all particles;
/// a named def that is not loaded → false.
fn push_particles(args: &[Value]) -> Result<Value, RuntimeError> {
    let definition = match args.first() {
        Some(Value::String(name)) if !name.is_empty() => Some(name.clone()),
        Some(Value::String(_)) | Some(Value::Nil) | None => None,
        Some(other) => {
            return Err(RuntimeError::new(format!(
                "PushParticles: expected string or nil for name, got {}",
                other.type_name()
            )))
        }
    };
    let ax = args
        .get(1)
        .map(|arg| value_to_i32(arg, "PushParticles", "xdir"))
        .transpose()?
        .unwrap_or(0);
    let ay = args
        .get(2)
        .map(|arg| value_to_i32(arg, "PushParticles", "ydir"))
        .transpose()?
        .unwrap_or(0);

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("PushParticles requires an active engine context"))?;
        if let Some(name) = &definition {
            if context.particle_def_known(name) == Some(false) {
                return Ok(Value::Bool(false));
            }
        }
        context.register_particle(ParticleCommand::Push {
            definition_id: definition,
            dxdir: ax as f32 / 10.0,
            dydir: ay as f32 / 10.0,
        });
        Ok(Value::Bool(true))
    })
}

fn clear_particles(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let mut definition: Option<String> = None;

    if let Some(arg) = args.get(index) {
        match arg {
            Value::String(name) if !name.is_empty() => definition = Some(name.clone()),
            Value::String(_) | Value::Nil => definition = None,
            other => {
                return Err(RuntimeError::new(format!(
                    "ClearParticles: expected string or nil for name, got {}",
                    other.type_name()
                )))
            }
        }
        index += 1;
    }

    let mut target_object: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        target_object = parse_object_reference_argument(arg, "ClearParticles", "object")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "ClearParticles: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = match borrow.as_mut() {
            Some(context) => context,
            None => return Ok(Value::Bool(false)),
        };

        // a named def that is not loaded → false (C4Script.cpp:4932)
        if let Some(name) = &definition {
            if context.particle_def_known(name) == Some(false) {
                return Ok(Value::Bool(false));
            }
        }

        let scope = if let Some(target) = target_object {
            if context.get_world_object(target).is_none() {
                return Ok(Value::Bool(false));
            }
            ParticleScope::Object(target)
        } else {
            ParticleScope::Global
        };

        context.register_particle(ParticleCommand::Clear {
            definition_id: definition.clone(),
            scope,
        });
        Ok(Value::Bool(true))
    })
}

/// FnIsNewgfx (C4Script.cpp:4947): the compatibility probe is always true.
fn is_newgfx(_args: &[Value]) -> Result<Value, RuntimeError> {
    Ok(Value::Bool(true))
}

fn contained(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "Contained expects at most 1 argument: target",
        ));
    }

    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.first() {
        target_id = parse_object_reference_argument(arg, "Contained", "target")?;
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        let to_value = |container: Option<ObjectId>| {
            container.map(object_reference_value).unwrap_or(Value::Nil)
        };

        if let Some(target) = target_id {
            if let Some(object) = context.object_context() {
                if target == object.id() {
                    return Ok(to_value(object.container()));
                }
            }
            if let Some(other) = context.get_world_object(target) {
                return Ok(to_value(other.container()));
            }
            return Ok(Value::Nil);
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Nil),
        };

        Ok(to_value(object.container()))
    })
}

fn contents(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 3 {
        return Err(RuntimeError::new(
            "Contents expects at most 3 arguments: index, object, include_attached",
        ));
    }

    let index = match args.first() {
        None | Some(Value::Nil) => 0,
        Some(value) => value_to_i32(value, "Contents", "index")?,
    };
    if index < 0 {
        return Ok(Value::Nil);
    }

    let target_id =
        parse_object_reference_argument(args.get(1).unwrap_or(&Value::Nil), "Contents", "object")?;
    let include_attached = if let Some(value) = args.get(2) {
        value_to_bool(value, "Contents", "include_attached")?
    } else {
        false
    };

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        let container_id = if let Some(id) = target_id {
            id
        } else {
            match context.object_context() {
                Some(object) => object.id(),
                None => return Ok(Value::Nil),
            }
        };

        let container = match context.get_world_object(container_id) {
            Some(object) if !context.removed_object_references.contains(&container_id) => object,
            _ => return Ok(Value::Nil),
        };

        // C4ObjectList::GetObject applies the Status filter before indexing.
        // FnContents then advances that raw index only while the selected
        // entry uses DFA_ATTACH. Filtering attached entries up front would
        // shift every later index and lose C++'s duplicate-return quirk.
        let mut entries = Vec::new();
        for child_id in container.contents() {
            if let Some(child) = context.get_world_object(*child_id) {
                if !child.is_present() {
                    continue;
                }
                entries.push(child);
            }
        }

        let mut raw_index = index as usize;
        while let Some(selected) = entries.get(raw_index) {
            let attached = selected
                .procedure_name()
                .is_some_and(|procedure| procedure.eq_ignore_ascii_case("attach"));
            if include_attached || !attached {
                return Ok(object_reference_value(selected.id));
            }
            raw_index += 1;
        }
        Ok(Value::Nil)
    })
}

fn contents_count(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "ContentsCount expects at most 2 arguments: definition, object",
        ));
    }

    let definition = parse_definition_argument(args.first(), "ContentsCount")?;
    let target_id = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "ContentsCount",
        "object",
    )?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Int(0)),
        };

        let container_id = if let Some(id) = target_id {
            id
        } else {
            match context.object_context() {
                Some(object) => object.id(),
                None => return Ok(Value::Int(0)),
            }
        };

        let container = match context.get_world_object(container_id) {
            Some(object) if !context.removed_object_references.contains(&container_id) => object,
            _ => return Ok(Value::Int(0)),
        };

        let mut count = 0;
        for child_id in container.contents() {
            if let Some(child) = context.get_world_object(*child_id) {
                if !child.is_present() {
                    continue;
                }
                if let Some(definition_id) = definition.as_ref() {
                    if context
                        .object_effective_definition_id(*child_id)
                        .is_none_or(|id| id.as_str() != definition_id)
                    {
                        continue;
                    }
                }
                count += 1;
            }
        }

        Ok(Value::Int(count))
    })
}

fn find_contents(args: &[Value]) -> Result<Value, RuntimeError> {
    let definition =
        parse_definition_argument(Some(args.first().unwrap_or(&Value::Nil)), "FindContents")?;
    let Some(definition) = definition else {
        return Ok(Value::Nil);
    };

    let target_id = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "FindContents",
        "object",
    )?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        let container_id = if let Some(id) = target_id {
            id
        } else {
            match context.object_context() {
                Some(object) => object.id(),
                None => return Ok(Value::Nil),
            }
        };

        let container = match context.get_world_object(container_id) {
            Some(object) if !context.removed_object_references.contains(&container_id) => object,
            _ => return Ok(Value::Nil),
        };

        for child_id in container.contents() {
            if let Some(child) = context.get_world_object(*child_id) {
                if !child.is_present() {
                    continue;
                }
                if context
                    .object_effective_definition_id(*child_id)
                    .is_some_and(|id| id.as_str() == definition)
                {
                    return Ok(object_reference_value(child.id));
                }
            }
        }

        Ok(Value::Nil)
    })
}

fn find_other_contents(args: &[Value]) -> Result<Value, RuntimeError> {
    let definition = parse_definition_argument(
        Some(args.first().unwrap_or(&Value::Nil)),
        "FindOtherContents",
    )?;
    let target_id = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "FindOtherContents",
        "object",
    )?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        let container_id = if let Some(id) = target_id {
            id
        } else {
            match context.object_context() {
                Some(object) => object.id(),
                None => return Ok(Value::Nil),
            }
        };

        let container = match context.get_world_object(container_id) {
            Some(object) if object.is_present() => object,
            _ => return Ok(Value::Nil),
        };

        for child_id in container.contents() {
            if let Some(child) = context.get_world_object(*child_id) {
                if !child.is_present() {
                    continue;
                }
                let matches = match definition.as_ref() {
                    Some(definition_id) => child.definition_id() != definition_id,
                    None => true,
                };
                if matches {
                    return Ok(object_reference_value(child.id));
                }
            }
        }

        Ok(Value::Nil)
    })
}

fn get_ocf(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetOCF expects at most 1 argument: target",
        ));
    }

    let target_value = args.first().unwrap_or(&Value::Nil);
    let target_id = parse_object_reference_argument(target_value, "GetOCF", "target")?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        let ocf_value = |mask: u32| Value::Int(mask as i32);

        if let Some(target) = target_id {
            if let Some(object) = context.object_context() {
                if object.id() == target {
                    return Ok(ocf_value(object.ocf()));
                }
            }
            if let Some(other) = context.get_world_object(target) {
                return Ok(ocf_value(other.ocf()));
            }
            return Ok(Value::Nil);
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Nil),
        };

        Ok(ocf_value(object.ocf()))
    })
}

/// FnGetUnusedOverlayID (C4Script.cpp:5942-5951): search away from a
/// nonzero base index until the target object has no overlay in that slot.
fn get_unused_overlay_id(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut overlay_id = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "GetUnusedOverlayID",
        "base index",
    )?;
    let target = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "GetUnusedOverlayID",
        "object",
    )?;
    if overlay_id == 0 {
        return Ok(Value::Nil);
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let target = target.or(context.script_object_context);
        let Some(target) = target else {
            return Ok(Value::Nil);
        };
        if context.object_scope(target).is_none() && context.get_world_object(target).is_none() {
            return Ok(Value::Nil);
        }

        let search_step = if overlay_id < 0 { -1 } else { 1 };
        while context.object_has_graphics_overlay(target, overlay_id) {
            overlay_id = overlay_id.wrapping_add(search_step);
        }
        Ok(Value::Int(overlay_id))
    })
}

fn set_graphics(args: &[Value]) -> Result<Value, RuntimeError> {
    // A null pGfxName restores the DEFAULT graphics (FnSetGraphics,
    // C4Script.cpp:4378).
    let graphics_name = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) if !name.is_empty() => Some(name.clone()),
        Value::String(_) | Value::Nil => None,
        // Falsy parameters reset to nil before the type check
        // (C4AulExec.cpp:1372): SetGraphics(0) selects the default graphics.
        Value::Int(0) | Value::Bool(false) => None,
        other => {
            return Err(RuntimeError::new(format!(
                "SetGraphics: expected string or nil for graphics name, got {}",
                other.type_name()
            )))
        }
    };

    let mut index = 1;

    let target_id = if let Some(arg) = args.get(index) {
        index += 1;
        parse_object_reference_argument(arg, "SetGraphics", "object")?
    } else {
        None
    };

    let definition = if let Some(arg) = args.get(index) {
        index += 1;
        parse_definition_argument(Some(arg), "SetGraphics")?
    } else {
        None
    };

    let overlay_id = if let Some(arg) = args.get(index) {
        index += 1;
        match arg {
            Value::Int(value) => *value,
            Value::Nil => 0,
            other => {
                return Err(RuntimeError::new(format!(
                    "SetGraphics: expected int or nil for overlay id, got {}",
                    other.type_name()
                )))
            }
        }
    } else {
        0
    };

    let mode_value = if let Some(arg) = args.get(index) {
        index += 1;
        match arg {
            Value::Int(value) => *value,
            Value::Nil => 0,
            other => {
                return Err(RuntimeError::new(format!(
                    "SetGraphics: expected int or nil for overlay mode, got {}",
                    other.type_name()
                )))
            }
        }
    } else {
        0
    };

    let action_name = if let Some(arg) = args.get(index) {
        index += 1;
        match arg {
            Value::String(name) if !name.is_empty() => Some(name.clone()),
            Value::String(_) | Value::Nil | Value::Int(0) | Value::Bool(false) => None,
            other => {
                return Err(RuntimeError::new(format!(
                    "SetGraphics: expected string or nil for action, got {}",
                    other.type_name()
                )))
            }
        }
    } else {
        None
    };

    let blit_mode = if let Some(arg) = args.get(index) {
        index += 1;
        match arg {
            Value::Int(value) => (*value).max(0) as u32,
            Value::Nil => 0,
            other => {
                return Err(RuntimeError::new(format!(
                    "SetGraphics: expected int or nil for blit mode, got {}",
                    other.type_name()
                )))
            }
        }
    } else {
        0
    };

    let overlay_object = if let Some(arg) = args.get(index) {
        index += 1;
        parse_object_reference_argument(arg, "SetGraphics", "overlay_object")?
    } else {
        None
    };

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetGraphics: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetGraphics requires an active engine context"))?;

        let object_id = if let Some(target) = target_id {
            target
        } else {
            match context.object_context() {
                Some(object) => object.id(),
                None => return Ok(Value::Bool(false)),
            }
        };
        if !context.ensure_object_scope(object_id)
            || context
                .object_scope(object_id)
                .is_none_or(|object| object.status() == ObjectStatus::Deleted)
        {
            return Ok(Value::Bool(false));
        }

        let mut resolved_definition = definition.clone();
        if overlay_id <= 0 && resolved_definition.is_none() {
            resolved_definition = context.object_effective_definition_id(object_id);
            if resolved_definition.is_none() {
                return Ok(Value::Bool(false));
            }
        }

        if overlay_id <= 0 {
            let definition_id = resolved_definition.expect("resolved definition present");

            if context.definition_metadata(&definition_id).is_none() {
                return Ok(Value::Bool(false));
            }
            let color_by_owner = context.world.definition_color_by_owner(&definition_id);
            let target_definition = context.object_effective_definition_id(object_id);

            let base_graphics = if graphics_name.is_none()
                && target_definition.as_deref() == Some(definition_id.as_str())
            {
                None
            } else {
                Some(ObjectBaseGraphics {
                    definition: definition_id,
                    graphics_name: graphics_name.clone(),
                    blit_mode,
                })
            };
            let Some(object) = context.object_scope_mut(object_id) else {
                return Ok(Value::Bool(false));
            };
            let changed = object.set_base_graphics(base_graphics);
            if changed && !color_by_owner {
                object.pending_update.color = Some(0);
            }
            return Ok(Value::Bool(true));
        }

        let Some(object) = context.object_scope_mut(object_id) else {
            return Ok(Value::Bool(false));
        };

        if overlay_id < 0 {
            return Ok(Value::Bool(false));
        }

        let mode = if mode_value == 0 {
            GraphicsOverlayMode::Base
        } else {
            match GraphicsOverlayMode::from_script_value(mode_value) {
                Some(mode) => mode,
                None => return Ok(Value::Bool(false)),
            }
        };

        if mode == GraphicsOverlayMode::Object && overlay_object.is_none() {
            let removed = object.remove_graphics_overlay(overlay_id);
            return Ok(Value::Bool(removed));
        }

        if mode != GraphicsOverlayMode::Object && definition.is_none() {
            let removed = object.remove_graphics_overlay(overlay_id);
            return Ok(Value::Bool(removed));
        }

        let overlay = ObjectGraphicsOverlay::new(overlay_id, mode)
            .with_definition(if mode == GraphicsOverlayMode::Object {
                None
            } else {
                definition.clone()
            })
            .with_graphics_name(graphics_name.clone())
            .with_action(action_name)
            .with_blit_mode(blit_mode)
            .with_overlay_object(overlay_object);

        let changed = object.set_graphics_overlay(overlay);
        Ok(Value::Bool(changed))
    })
}

fn parse_draw_transform_components(
    args: &[Value],
    function: &str,
) -> Result<[i32; 6], RuntimeError> {
    Ok([
        value_to_i32(args.first().unwrap_or(&Value::Nil), function, "a")?,
        value_to_i32(args.get(1).unwrap_or(&Value::Nil), function, "b")?,
        value_to_i32(args.get(2).unwrap_or(&Value::Nil), function, "c")?,
        value_to_i32(args.get(3).unwrap_or(&Value::Nil), function, "d")?,
        value_to_i32(args.get(4).unwrap_or(&Value::Nil), function, "e")?,
        value_to_i32(args.get(5).unwrap_or(&Value::Nil), function, "f")?,
    ])
}

fn parse_draw_transform_matrix(args: &[Value], function: &str) -> Result<[i32; 9], RuntimeError> {
    Ok([
        value_to_i32(args.first().unwrap_or(&Value::Nil), function, "a")?,
        value_to_i32(args.get(1).unwrap_or(&Value::Nil), function, "b")?,
        value_to_i32(args.get(2).unwrap_or(&Value::Nil), function, "c")?,
        value_to_i32(args.get(3).unwrap_or(&Value::Nil), function, "d")?,
        value_to_i32(args.get(4).unwrap_or(&Value::Nil), function, "e")?,
        value_to_i32(args.get(5).unwrap_or(&Value::Nil), function, "f")?,
        value_to_i32(args.get(6).unwrap_or(&Value::Nil), function, "g")?,
        value_to_i32(args.get(7).unwrap_or(&Value::Nil), function, "h")?,
        value_to_i32(args.get(8).unwrap_or(&Value::Nil), function, "i")?,
    ])
}

fn set_obj_draw_transform(args: &[Value]) -> Result<Value, RuntimeError> {
    let components = parse_draw_transform_components(args, "SetObjDrawTransform")?;
    let mut index = 6;
    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        target_id = parse_object_reference_argument(arg, "SetObjDrawTransform", "object")?;
        index += 1;
    }
    let overlay_id = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "SetObjDrawTransform", "overlay")?;
        index += 1;
        value
    } else {
        0
    };

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetObjDrawTransform: additional arguments are not supported",
        ));
    }

    let transform = DrawTransform::from_matrix([
        components[0] as f32 / 1000.0,
        components[1] as f32 / 1000.0,
        components[2] as f32 / 1000.0,
        components[3] as f32 / 1000.0,
        components[4] as f32 / 1000.0,
        components[5] as f32 / 1000.0,
        0.0,
        0.0,
        1.0,
    ]);
    let resets_base = components[1] == 0
        && components[2] == 0
        && components[3] == 0
        && components[5] == 0
        && components[0] == components[4]
        && matches!(components[0], 0 | 1000);

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("SetObjDrawTransform requires an active engine context")
        })?;
        let object_id = match target_id.or_else(|| context.object_context().map(|object| object.id()))
        {
            Some(object) => object,
            None => return Ok(Value::Bool(false)),
        };
        if !context.ensure_object_scope(object_id) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(object_id) else {
            return Ok(Value::Bool(false));
        };

        if overlay_id == 0 {
            object.set_draw_transform(if resets_base { None } else { Some(transform) });
            Ok(Value::Bool(true))
        } else {
            let changed = object.set_overlay_transform(overlay_id, Some(transform));
            Ok(Value::Bool(changed))
        }
    })
}

fn set_obj_draw_transform2(args: &[Value]) -> Result<Value, RuntimeError> {
    let matrix = parse_draw_transform_matrix(args, "SetObjDrawTransform2")?;
    let mut index = 9;
    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        target_id = parse_object_reference_argument(arg, "SetObjDrawTransform2", "object")?;
        index += 1;
    }
    let overlay_id = if let Some(arg) = args.get(index) {
        let value = value_to_i32(arg, "SetObjDrawTransform2", "overlay")?;
        index += 1;
        value
    } else {
        0
    };

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetObjDrawTransform2: additional arguments are not supported",
        ));
    }

    let delta = DrawTransform::from_matrix([
        matrix[0] as f32 / 1000.0,
        matrix[1] as f32 / 1000.0,
        matrix[2] as f32 / 1000.0,
        matrix[3] as f32 / 1000.0,
        matrix[4] as f32 / 1000.0,
        matrix[5] as f32 / 1000.0,
        matrix[6] as f32 / 1000.0,
        matrix[7] as f32 / 1000.0,
        matrix[8] as f32 / 1000.0,
    ]);

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("SetObjDrawTransform2 requires an active engine context")
        })?;
        let object_id = match target_id.or_else(|| context.object_context().map(|object| object.id()))
        {
            Some(object) => object,
            None => return Ok(Value::Bool(false)),
        };
        if !context.ensure_object_scope(object_id) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(object_id) else {
            return Ok(Value::Bool(false));
        };

        if overlay_id == 0 {
            let current = object.draw_transform().unwrap_or(DrawTransform::identity());
            let combined = current.combined(delta);
            object.set_draw_transform(Some(combined));
            Ok(Value::Bool(true))
        } else {
            let existing = match object.overlay_transform(overlay_id) {
                Some(transform) => transform.unwrap_or(DrawTransform::identity()),
                None => return Ok(Value::Bool(false)),
            };
            let combined = existing.combined(delta);
            let changed = object.set_overlay_transform(overlay_id, Some(combined));
            Ok(Value::Bool(changed))
        }
    })
}

fn get_category(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "GetCategory expects at most 2 arguments: target, definition",
        ));
    }

    let target_value = args.first().unwrap_or(&Value::Nil);
    let target_id = parse_object_reference_argument(target_value, "GetCategory", "target")?;
    let definition = parse_definition_argument(args.get(1), "GetCategory")?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        if let Some(definition_id) = definition {
            if let Some(category) = context.definition_category(&definition_id) {
                return Ok(Value::Int(category));
            }
            return Ok(Value::Nil);
        }

        if let Some(target) = target_id {
            if let Some(object) = context.object_context() {
                if object.id() == target {
                    return Ok(Value::Int(object.category()));
                }
            }
            if let Some(other) = context.get_world_object(target) {
                return Ok(Value::Int(other.category()));
            }
            return Ok(Value::Nil);
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Nil),
        };

        Ok(Value::Int(object.category()))
    })
}
struct NativeObjectCreation {
    definition: String,
    creator: Option<ObjectId>,
    owner: i32,
    position: Vector2,
    rotation: i32,
    velocity: FixedVec2,
    rotation_velocity: C4Fixed,
}

/// Synchronous `C4Game::CreateObject` for native engine operations whose
/// exact initial position and fixed motion are not expressible through the
/// script `CreateObject` wrapper. The pending spawn is only storage: every
/// NewObject lifecycle callback runs here before this function returns.
fn create_native_object(request: NativeObjectCreation) -> Result<Option<ObjectId>, RuntimeError> {
    let registration = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut().ok_or_else(|| {
            RuntimeError::new("native object creation requires an active engine context")
        })?;
        if context.world.definition_known(&request.definition) == Some(false) {
            return Ok(None);
        }
        let metadata = context
            .definition_metadata(&request.definition)
            .cloned()
            .unwrap_or_else(|| DefinitionMetadata {
                category: context
                    .definition_category(&request.definition)
                    .unwrap_or(DEFAULT_CATEGORY),
                ..DefinitionMetadata::default()
            });
        // C4Object::Init discards initial r/rdir for non-rotateable defs,
        // after their callers have already consumed every random draw.
        let (rotation, rotation_velocity) = if metadata.rotateable == 0 {
            (0, C4Fixed::ZERO)
        } else {
            (request.rotation, request.rotation_velocity)
        };
        let creator_layer = request
            .creator
            .and_then(|creator| context.object_layer(creator));
        let id = context.allocate_object_id();
        let mut spawn = SpawnConfig::new(request.definition.clone())
            .with_position(request.position)
            .with_fixed_velocity(request.velocity)
            .with_rotation(rotation)
            .with_rotation_velocity(rotation_velocity)
            .with_owner(request.owner)
            .with_category(metadata.category)
            .with_construction(0)
            .with_id(id);
        if let Some(layer) = creator_layer {
            spawn = spawn.with_layer(layer);
        }
        spawn.initialized = true;
        spawn.position_adjusted = true;

        let alive = metadata.category & crate::CATEGORY_LIVING != 0;
        let preview_ocf = ocf::compute(
            metadata.ocf_base,
            metadata.crew_member,
            alive,
            ObjectStatus::Normal,
            false,
            0,
            metadata.category,
        );
        let preview_velocity = Vector2::new(request.velocity.int_x(), request.velocity.int_y());
        let preview = HostWorldObject::with_category(
            id,
            request.definition.clone(),
            ObjectStatus::Normal,
            "Idle",
            None,
            None,
            None,
            request.owner,
            metadata.category,
            if alive { metadata.physical.energy } else { 0 },
            0,
            0,
            request.position,
            preview_velocity,
            rotation,
            metadata.vertices.clone(),
            0,
            0,
            0,
            None,
            None,
        )
        .with_fixed_motion(FixedVec2::from_ints(request.position.x, request.position.y), request.velocity)
        .with_rotation_velocity(rotation_velocity)
        .with_alive(alive)
        .with_ocf(preview_ocf)
        .with_full_state(Rc::new({
            let mut state = crate::preview_spawn_state_with_components(
                request.position,
                request.owner,
                request.owner,
                metadata.category,
                0,
                metadata.contact_density(),
                metadata.vertices.clone(),
                metadata.components.as_slice(),
            );
            state.velocity = preview_velocity;
            state.script_fixed_velocity = Some(request.velocity);
            state.script_rotation_velocity = Some(rotation_velocity);
            state.rotation = rotation;
            state.alive = alive;
            state.energy = if alive { metadata.physical.energy } else { 0 };
            state.breath = metadata.physical.breath;
            state.crew_member = metadata.crew_member;
            state.layer = creator_layer;
            state.blit_mode = metadata.blit_mode;
            if context.world.definition_color_by_owner(&request.definition) {
                state.color = context
                    .player_state(request.owner)
                    .and_then(|player| player.color)
                    .map(|color| {
                        u32::from(color.r) << 16
                            | u32::from(color.g) << 8
                            | u32::from(color.b)
                    })
                    .unwrap_or(0);
            }
            state.mobile = metadata.category != crate::CATEGORY_STATIC_BACK
                && (request.velocity != FixedVec2::ZERO || rotation_velocity.is_nonzero());
            state
        }));
        context.register_spawn(spawn, preview);
        if context.ensure_object_scope(id) {
            if let Some(scope) = context.object_scope_mut(id) {
                scope.current_fixed_velocity = request.velocity;
                scope.current_rotation_velocity = rotation_velocity;
            }
        }
        Ok(Some((id, metadata, rotation)))
    })?;
    let Some((target, metadata, initial_rotation)) = registration else {
        return Ok(None);
    };

    let creator_arg = request
        .creator
        .map(object_reference_value)
        .unwrap_or(Value::Nil);
    call_object_own_fail_safe(target, "Construction", &[creator_arg]);
    if !object_is_present(target) {
        return Ok(None);
    }
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            context.commit_creation_action(target);
        }
    });

    // Construction may ChangeDef synchronously. Initial DoCon and the
    // Completion/Initialize lookup use the object's live definition in C++.
    let metadata = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow.as_ref()?;
        let definition = context.object_effective_definition_id(target)?;
        context.definition_metadata(definition.as_str()).cloned()
    })
    .unwrap_or(metadata);

    let crossed_full_con = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return false;
        };
        let was_full = context
            .object_scope(target)
            .is_some_and(|scope| scope.construction() >= FULL_CON);
        let Some(final_construction) = context.adjust_object_construction(target, FULL_CON) else {
            return false;
        };
        let (raw_position, adjusted_position) = {
            let Some(scope) = context.object_scope_mut(target) else {
                return false;
            };
            let raw_position = scope.effective_position();
            let rotation = scope.rotation();
            let adjusted_position = Vector2::new(
                raw_position.x,
                crate::docon_initial_center_y_with_rotation(
                    metadata.shape,
                    metadata.stretch_growth,
                    metadata.line,
                    metadata.rotateable,
                    rotation,
                    final_construction,
                    raw_position.y,
                ),
            );
            scope.pending_update.construction = None;
            scope.current_position = adjusted_position;
            scope.pending_update.position = None;
            scope.cached_ocf = Some(ocf::compute(
                metadata.ocf_base,
                metadata.crew_member,
                scope.alive(),
                ObjectStatus::Normal,
                false,
                final_construction,
                metadata.category,
            ));
            (raw_position, adjusted_position)
        };
        if let Some(spawn) = context
            .pending_spawns
            .iter_mut()
            .find(|spawn| spawn.id == Some(target))
        {
            spawn.position = adjusted_position;
            spawn.construction = final_construction;
            spawn.fixed_position = (adjusted_position != raw_position)
                .then_some(FixedVec2::from_ints(raw_position.x, raw_position.y));
            // Construction may have changed r. The nested update remains
            // authoritative, but seed the spawn for the no-write case.
            spawn.rotation = initial_rotation;
        }
        !was_full && final_construction >= FULL_CON
    });
    if crossed_full_con {
        call_object_own_fail_safe(target, "Completion", &[]);
        if object_is_present(target) {
            call_object_own_fail_safe(target, "Initialize", &[]);
        }
    }
    Ok(object_is_present(target).then_some(target))
}

/// FnCreateContents (C4Script.cpp:1938-1951): create `count` (default 1)
/// objects of `c_id` inside the container, returning the last one. C++
/// routes through pObj->CreateContents -> CreateObject + Enter, with the
/// container's owner.
fn create_contents(args: &[Value]) -> Result<Value, RuntimeError> {
    let definition = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) | Value::C4Id(name) if !name.is_empty() => name.clone(),
        Value::String(_) | Value::C4Id(_) | Value::Nil | Value::Int(0) => return Ok(Value::Nil),
        other => {
            return Err(RuntimeError::new(format!(
                "CreateContents: expected id for definition, got {}",
                other.type_name()
            )))
        }
    };

    let mut index = 1;
    let target_id = consume_optional_object_reference_argument(
        args,
        &mut index,
        "CreateContents",
        "container",
    )?;
    let count = match args.get(index) {
        // C++: `if (!iCount) ++iCount;`
        Some(arg) => match value_to_i32(arg, "CreateContents", "count")? {
            0 => 1,
            value => value,
        },
        None => 1,
    };

    let container = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = borrow
            .as_ref()
            .ok_or_else(|| RuntimeError::new("CreateContents requires an active engine context"))?;
        Ok::<_, RuntimeError>(target_id.or(context.script_object_context))
    })?;
    let Some(container) = container else {
        return Ok(Value::Nil);
    };
    if !object_is_present(container) {
        return Ok(Value::Nil);
    }

    let mut last = Value::Nil;
    for _ in 0..count {
        let owner = HOST_CONTEXT.with(|cell| {
            let borrow = cell.borrow();
            let context = borrow.as_ref()?;
            context
                .object_scope(container)
                .map(ObjectScopeContext::owner)
                .or_else(|| context.get_world_object(container).map(|object| object.owner))
        });
        let Some(owner) = owner else {
            last = Value::Nil;
            continue;
        };
        // C4Game::CreateObject's omitted coordinates are (50,50). Only the
        // subsequent Enter copies the container's current motion.
        let Some(created) = create_native_object(NativeObjectCreation {
            definition: definition.clone(),
            creator: Some(container),
            owner,
            position: Vector2::new(50, 50),
            rotation: 0,
            velocity: FixedVec2::ZERO,
            rotation_velocity: C4Fixed::ZERO,
        })? else {
            last = Value::Nil;
            continue;
        };
        if enter_object_live(created, container)? {
            last = object_reference_value(created);
        } else {
            let _ = assign_removal_live(created, false)?;
            last = Value::Nil;
        }
    }
    Ok(last)
}

fn resolve_component_list(
    definition: &str,
    instance: Option<ObjectId>,
    builder: Option<ObjectId>,
) -> Result<Vec<(String, i32)>, RuntimeError> {
    let (script, static_components) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return (None, Vec::new());
        };
        (
            context.world.definition_script(definition).cloned(),
            context
                .definition_metadata(definition)
                .map(|metadata| metadata.components.clone())
                .unwrap_or_default(),
        )
    });
    let builder = builder
        .map(object_reference_value)
        .unwrap_or(Value::Nil);
    let custom = script
        .filter(|script| script.has_function("GetCustomComponents"))
        .and_then(|script| {
            match instance {
                Some(instance) => call_world_object_function_in_scope(
                    instance,
                    script,
                    "GetCustomComponents",
                    &[builder.clone()],
                ),
                None => call_scoped_definition_function(
                    script,
                    definition,
                    "GetCustomComponents",
                    &[builder.clone()],
                ),
            }
            .and_then(|result| match result {
                Ok(value) => Some(value),
                Err(error) => {
                    tracing::warn!(
                        %error,
                        definition,
                        "GetCustomComponents failed; using stored components like C++"
                    );
                    None
                }
            })
        });
    if let Some(Value::Array(values)) = custom {
        return Ok(component_list_from_custom_array(&values));
    }
    let Some(instance) = instance else {
        return Ok(static_components);
    };

    Ok(HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Vec::new();
        };
        let object = context.get_world_object(instance);
        let components = context
            .object_scope(instance)
            .and_then(|scope| scope.pending_update.components.clone())
            .or_else(|| {
                object
                    .as_ref()
                    .and_then(|object| object.full_state().map(|state| state.components.clone()))
            })
            .unwrap_or_else(|| {
                static_components
                    .iter()
                    .map(|(id, count)| (DefinitionId::from(id.as_str()), *count))
                    .collect()
            });
        let order = context
            .object_scope(instance)
            .and_then(|scope| scope.pending_update.component_order.clone())
            .or_else(|| {
                object.as_ref().and_then(|object| {
                    object
                        .full_state()
                        .map(|state| state.component_order.clone())
                })
            })
            .unwrap_or_else(|| {
                static_components
                    .iter()
                    .map(|(id, _)| DefinitionId::from(id.as_str()))
                    .collect()
            });
        order
            .into_iter()
            .map(|id| {
                let count = components.get(&id).copied().unwrap_or(0);
                (id.as_str().to_owned(), count)
            })
            .collect()
    }))
}

fn live_contents_matching(container: ObjectId, definition: &str) -> Vec<ObjectId> {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Vec::new();
        };
        context
            .get_world_object(container)
            .map(|container| {
                container
                    .contents()
                    .iter()
                    .copied()
                    .filter(|child| {
                        context.get_world_object(*child).is_some_and(|object| {
                            object.is_present()
                                && context
                                    .object_effective_definition_id(*child)
                                    .is_some_and(|id| id.as_str() == definition)
                        })
                    })
                    .collect()
            })
            .unwrap_or_default()
    })
}

/// FnComposeContents -> C4Object::ComposeContents
/// (C4Script.cpp:1946-1950; C4Object.cpp:3764-3806).
fn compose_contents(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 2 {
        return Err(RuntimeError::new(
            "ComposeContents expects at most 2 arguments: definition and container",
        ));
    }
    let Some(definition) = parse_definition_argument(args.first(), "ComposeContents")? else {
        return Ok(Value::Nil);
    };
    let explicit = parse_object_reference_argument(
        args.get(1).unwrap_or(&Value::Nil),
        "ComposeContents",
        "container",
    )?;
    let container = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| explicit.or(context.script_object_context))
    });
    let Some(container) = container.filter(|container| object_is_present(*container)) else {
        return Ok(Value::Nil);
    };
    let definition_known = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.world.definition_known(&definition))
    });
    if definition_known == Some(false) {
        return Ok(Value::Nil);
    }

    let components = resolve_component_list(&definition, None, Some(container))?;
    let mut missing = Vec::<(String, i32)>::new();
    for (component, needed) in &components {
        let available =
            i32::try_from(live_contents_matching(container, component).len()).unwrap_or(i32::MAX);
        if *needed > available {
            missing.push((component.clone(), needed - available));
        }
    }
    if let Some((first_id, first_count)) = missing.first() {
        let handled = call_object_own_fail_safe(
            container,
            "BuildNeedsMaterial",
            &[Value::C4Id(first_id.clone()), Value::Int(*first_count)],
        )
        .as_bool();
        if !handled {
            let text = HOST_CONTEXT.with(|cell| {
                let borrow = cell.borrow();
                let context = borrow.as_ref();
                let display_name = |id: &str| {
                    context
                        .and_then(|context| context.definition_metadata(id))
                        .map(|metadata| metadata.name.as_str())
                        .filter(|name| !name.is_empty())
                        .unwrap_or(id)
                        .to_owned()
                };
                let mut text = format!("{}|needs", display_name(&definition));
                for (component, count) in &missing {
                    text.push_str(&format!("|{count}x {}", display_name(component)));
                }
                text
            });
            HOST_CONTEXT.with(|cell| {
                if let Some(context) = cell.borrow_mut().as_mut() {
                    context.register_message(MessageCommand::Add(MessageSpec {
                        kind: MessageKind::Target,
                        text,
                        target: Some(container),
                        player: None,
                        offset: Vector2::ZERO,
                        color: invert_rgba_alpha(LEGACY_DEFAULT_MESSAGE_COLOR),
                        flags: 0,
                        width: None,
                        decoration: None,
                        frame_decoration: None,
                        portrait: None,
                    }));
                }
            });
        }
        return Ok(Value::Nil);
    }

    for (component, count) in components {
        for _ in 0..count {
            let Some(item) = live_contents_matching(container, &component)
                .into_iter()
                .next()
            else {
                return Ok(Value::Nil);
            };
            let _ = assign_removal_live(item, false)?;
        }
    }
    create_contents(&[
        Value::C4Id(definition),
        object_reference_value(container),
        Value::Int(1),
    ])
}

/// FnSplit2Components (C4Script.cpp:415-454): transfer contents, resolve
/// the source's live/custom recipe, create every piece with exact random
/// draw order, then remove the source.
fn split_to_components(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "Split2Components expects at most 1 argument: object",
        ));
    }
    let explicit = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "Split2Components",
        "object",
    )?;
    let (source, builder) = HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return (None, None);
        };
        (
            explicit.or(context.script_object_context),
            context.script_object_context,
        )
    });
    let Some(source) = source.filter(|source| object_is_present(*source)) else {
        return Ok(Value::Bool(false));
    };
    let original_container = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(source))
            .and_then(|object| object.container())
    });

    loop {
        let child = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .and_then(|context| context.get_world_object(source))
                .and_then(|object| object.contents().first().copied())
        });
        let Some(child) = child else { break };
        let moved = match original_container {
            Some(container) => enter_object_live(child, container)?,
            None => exit_object_at_current_position(child)?,
        };
        if !moved {
            break;
        }
    }

    let definition = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.object_effective_definition_id(source))
    });
    let Some(definition) = definition else {
        return Ok(Value::Bool(false));
    };
    let components = resolve_component_list(&definition, Some(source), builder)?;
    let still_contained = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| context.get_world_object(source))
            .is_some_and(|object| object.container().is_some())
    });
    if still_contained {
        let _ = exit_object_at_current_position(source)?;
    }

    for (component, count) in components {
        for _ in 0..count {
            let rdir = draw_context_rnd3()?;
            let ydir = draw_context_rnd3()?;
            let xdir = draw_context_rnd3()?;
            let rotation = draw_context_random(360)?;
            let creation = HOST_CONTEXT.with(|cell| {
                let borrow = cell.borrow();
                let context = borrow.as_ref()?;
                let source_state = context.get_world_object(source)?;
                let owner = context
                    .object_scope(source)
                    .map(ObjectScopeContext::owner)
                    .unwrap_or(source_state.owner);
                let position = context
                    .object_scope(source)
                    .map(ObjectScopeContext::effective_position)
                    .unwrap_or(source_state.position);
                Some((owner, position))
            });
            let Some((owner, position)) = creation else {
                continue;
            };
            let Some(created) = create_native_object(NativeObjectCreation {
                definition: component.clone(),
                creator: Some(source),
                owner,
                position,
                rotation,
                velocity: FixedVec2::new(itofix(xdir), itofix(ydir)),
                rotation_velocity: itofix(rdir),
            })? else {
                continue;
            };
            let (burning, fire_owner) = HOST_CONTEXT.with(|cell| {
                let borrow = cell.borrow();
                let Some(context) = borrow.as_ref() else {
                    return (false, OWNER_NONE);
                };
                let Some(source_state) = context.get_world_object(source) else {
                    return (false, OWNER_NONE);
                };
                let owner = context
                    .object_scope(source)
                    .map(ObjectScopeContext::owner)
                    .unwrap_or(source_state.owner);
                let burning = context
                    .object_scope(source)
                    .and_then(|scope| scope.pending_update.staged_on_fire())
                    .or_else(|| source_state.full_state().map(|state| state.on_fire))
                    .unwrap_or(false);
                (burning, owner)
            });
            if burning {
                let _ = incinerate_target(created, fire_owner, false, None)?;
            }
            if let Some(container) = original_container {
                let _ = enter_object_live(created, container)?;
            }
        }
    }
    let _ = assign_removal_live(source, false)?;
    Ok(Value::Bool(true))
}

/// FnGetActMapVal (C4Script.cpp:4216-4241): one entry of one action in a
/// definition's ActMap, addressed by its serialization name
/// (C4ActionDef::CompileFunc, C4Def.cpp). Unknown definition, action or
/// entry -> nil. C4ActionDef compile defaults: Length 1, Delay 0, strings "".
fn get_act_map_val(args: &[Value]) -> Result<Value, RuntimeError> {
    let entry = match args.first().unwrap_or(&Value::Nil) {
        Value::String(name) => name.clone(),
        Value::Nil => return Ok(Value::Nil),
        other => {
            return Err(RuntimeError::new(format!(
                "GetActMapVal: expected string for entry, got {}",
                other.type_name()
            )))
        }
    };
    let action = match args.get(1).unwrap_or(&Value::Nil) {
        Value::String(name) => name.clone(),
        Value::Nil => return Ok(Value::Nil),
        other => {
            return Err(RuntimeError::new(format!(
                "GetActMapVal: expected string for action, got {}",
                other.type_name()
            )))
        }
    };
    let definition = match args.get(2).unwrap_or(&Value::Nil) {
        Value::String(name) | Value::C4Id(name) if !name.is_empty() => Some(name.clone()),
        _ => None,
    };

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        // `idDef` defaults to the executing definition (cthr->Def).
        let library = match definition {
            Some(id) => match context.definition_metadata(&id) {
                Some(metadata) => metadata.action_library.clone(),
                None => return Ok(Value::Nil),
            },
            None => match context.object_context() {
                Some(object) => object.action_library.clone(),
                None => {
                    let Some(definition) = context.current_definition_id() else {
                        return Ok(Value::Nil);
                    };
                    let Some(metadata) = context.definition_metadata(definition.as_str()) else {
                        return Ok(Value::Nil);
                    };
                    metadata.action_library.clone()
                }
            },
        };
        let Some(spec) = library.specs().get(&action) else {
            return Ok(Value::Nil);
        };

        Ok(match entry.as_str() {
            "Name" => Value::String(action.clone()),
            "Procedure" => Value::String(spec.procedure.clone().unwrap_or_default()),
            "Length" => Value::Int(spec.length.unwrap_or(1) as i32),
            "Delay" => Value::Int(spec.delay.unwrap_or(0) as i32),
            "Attach" => Value::Int(spec.attach as i32),
            "NextAction" => Value::String(spec.next.clone().unwrap_or_default()),
            "StartCall" => Value::String(spec.start_call.clone().unwrap_or_default()),
            "EndCall" => Value::String(spec.end_call.clone().unwrap_or_default()),
            "AbortCall" => Value::String(spec.abort_call.clone().unwrap_or_default()),
            "PhaseCall" => Value::String(spec.phase_call.clone().unwrap_or_default()),
            "NoOtherAction" => Value::Int(i32::from(spec.no_other_action)),
            "DigFree" => Value::Int(spec.dig_free.unwrap_or(0)),
            _ => Value::Nil,
        })
    })
}

#[derive(Default)]
struct ObjectValueReflection {
    primitives: Vec<(Vec<&'static str>, Value)>,
}

impl ObjectValueReflection {
    fn push(&mut self, path: &[&'static str], value: Value) {
        self.primitives.push((path.to_vec(), value));
    }

    fn push_ints(&mut self, path: &[&'static str], values: impl IntoIterator<Item = i32>) {
        for value in values {
            self.push(path, Value::Int(value));
        }
    }

    /// StdArrayDefaultAdapt removes only the trailing default-valued slots.
    fn push_trimmed_ints(&mut self, path: &[&'static str], mut values: Vec<i32>) {
        while values.last() == Some(&0) {
            values.pop();
        }
        self.push_ints(path, values);
    }

    fn push_fixed(&mut self, path: &[&'static str], value: C4Fixed) {
        // C4Fixed::CompileFunc emits its format character before the raw
        // signed 16.16 payload (Fixed.h:248-265).
        self.push(path, Value::String("F".to_string()));
        self.push(path, Value::Int(value.val()));
    }

    fn get(&self, entry: &str, section: Option<&str>, entry_nr: i32) -> Option<Value> {
        let mut remaining = usize::try_from(entry_nr).ok()?;
        for (path, value) in &self.primitives {
            let matches = match section {
                Some(section) => {
                    path.len() >= 2
                        && path[path.len() - 2] == section
                        && path[path.len() - 1] == entry
                }
                None => path.last().is_some_and(|name| *name == entry),
            };
            if !matches {
                continue;
            }
            if remaining == 0 {
                return Some(value.clone());
            }
            remaining -= 1;
        }
        None
    }
}

fn push_reflected_c4value(
    reflection: &mut ObjectValueReflection,
    path: &[&'static str],
    value: &Value,
) {
    let (kind, payload) = match value {
        Value::Nil => ("A", 0),
        Value::Int(value) => ("i", *value),
        Value::Bool(value) => ("b", i32::from(*value)),
        Value::C4Id(value) if value.is_empty() => ("A", 0),
        Value::C4Id(value) => ("I", definition_id_to_c4id(value).unwrap_or(0)),
        Value::Object(value) if *value == 0 => ("A", 0),
        Value::Object(value) => ("O", *value as i32),
        Value::String(_) => {
            // C4Value persists the script string-table enumeration number,
            // not its text. Rust values do not retain that identity/cache;
            // -1 is C4String's runtime value before EnumStrings. Loaded
            // string-table IDs require a future identity-bearing value model.
            ("S", -1)
        }
        Value::Array(values) => {
            reflection.push(path, Value::String("a".to_string()));
            reflection.push(path, Value::Int(values.len() as i32));
            for value in values {
                push_reflected_c4value(reflection, path, value);
            }
            return;
        }
        Value::Proplist(values) => {
            reflection.push(path, Value::String("m".to_string()));
            reflection.push(path, Value::Int(values.len() as i32));
            for (key, value) in values {
                push_reflected_c4value(reflection, path, key);
                push_reflected_c4value(reflection, path, value);
            }
            return;
        }
    };
    reflection.push(path, Value::String(kind.to_string()));
    reflection.push(path, Value::Int(payload));
}

fn reflected_object_mass(
    context: &EffectHostContext,
    target: ObjectId,
    visited: &mut HashSet<ObjectId>,
) -> i32 {
    if !visited.insert(target) {
        return 0;
    }
    let scope = context.object_scope(target);
    let Some(object) = context.get_world_object(target) else {
        visited.remove(&target);
        return 1;
    };
    let state = object.full_state().map(Rc::as_ref);
    let definition = scope
        .and_then(|scope| {
            scope
                .pending_update
                .change_def
                .as_deref()
                .or(scope.definition_id.as_deref())
        })
        .unwrap_or_else(|| object.definition_id());
    let Some(metadata) = context.definition_metadata(definition) else {
        visited.remove(&target);
        return 1;
    };
    let own_mass = scope
        .map(ObjectScopeContext::own_mass)
        .or_else(|| state.map(|state| state.own_mass))
        .unwrap_or(0);
    let construction = scope
        .map(ObjectScopeContext::construction)
        .or_else(|| state.map(|state| state.construction))
        .unwrap_or(FULL_CON);
    let mut mass = metadata
        .mass
        .saturating_add(own_mass)
        .saturating_mul(construction)
        / FULL_CON;
    mass = mass.max(1);
    if !metadata.no_component_mass {
        for content in object.contents() {
            mass = mass.saturating_add(reflected_object_mass(context, *content, visited));
        }
    }
    visited.remove(&target);
    mass
}

fn reflected_object_locals(
    context: &EffectHostContext,
    target: ObjectId,
    state: Option<&ObjectState>,
    scope: Option<&ObjectScopeContext>,
) -> HashMap<String, Value> {
    let mut locals = state
        .map(|state| state.local_vars.clone())
        .unwrap_or_default();
    if let Some(nested) = context.nested_objects.get(&target) {
        locals.extend(nested.local_vars.clone());
    }
    if let Some(update) = scope.and_then(|scope| scope.pending_update.local_vars.as_ref()) {
        locals.extend(update.clone());
    }
    if let Some(cells) = context.session_local_cells.get(&target) {
        locals.extend(cells.snapshot());
    }
    context.overlay_foreign_cells(target, &mut locals);
    locals
}

fn reflect_object_values(
    context: &EffectHostContext,
    target: ObjectId,
) -> Option<ObjectValueReflection> {
    let scope = context.object_scope(target);
    let world_object = context.get_world_object(target);
    if scope.is_none() && world_object.is_none() {
        return None;
    }
    let state = world_object
        .as_ref()
        .and_then(HostWorldObject::full_state)
        .map(Rc::as_ref);
    let definition_id = scope
        .and_then(|scope| {
            scope
                .pending_update
                .change_def
                .clone()
                .or_else(|| scope.definition_id.clone())
        })
        .or_else(|| {
            world_object
                .as_ref()
                .map(|object| object.definition_id().to_string())
        });
    let metadata = definition_id
        .as_deref()
        .and_then(|definition| context.definition_metadata(definition));
    let position = scope
        .map(ObjectScopeContext::effective_position)
        .or_else(|| world_object.as_ref().map(HostWorldObject::position))
        .unwrap_or_default();
    let fixed_position = scope
        .map(ObjectScopeContext::fixed_position)
        .or_else(|| world_object.as_ref().map(|object| object.fixed_position))
        .unwrap_or_else(|| FixedVec2::from_ints(position.x, position.y));
    let fixed_velocity = scope
        .map(ObjectScopeContext::fixed_velocity)
        .or_else(|| world_object.as_ref().map(|object| object.fixed_velocity))
        .unwrap_or_default();
    let rotation = scope
        .map(ObjectScopeContext::rotation)
        .or_else(|| world_object.as_ref().map(|object| object.rotation))
        .unwrap_or(0);
    let fixed_rotation = scope
        .map(ObjectScopeContext::fixed_rotation)
        .or_else(|| world_object.as_ref().map(|object| object.fixed_rotation))
        .unwrap_or_else(|| itofix(rotation));
    let rotation_velocity = scope
        .map(ObjectScopeContext::rotation_velocity)
        .or_else(|| world_object.as_ref().map(|object| object.rotation_velocity))
        .unwrap_or_default();
    let shape = live_object_shape(context, target).unwrap_or_default();
    let shape_vertices = scope
        .map(ObjectScopeContext::shape_vertex_buffer)
        .or_else(|| state.map(|state| state.shape_vertices.clone()))
        .unwrap_or_default();
    let local_vars = reflected_object_locals(context, target, state, scope);

    let mut reflection = ObjectValueReflection::default();
    let object_path = |name| ["Object", name];
    reflection.push(
        &object_path("id"),
        definition_id
            .clone()
            .filter(|id| !id.is_empty())
            .map(Value::C4Id)
            .unwrap_or(Value::Nil),
    );
    if let Some(name) = context.object_custom_name(target) {
        reflection.push(&object_path("Name"), Value::String(name));
    }
    reflection.push(&object_path("Number"), Value::Int(target.as_u64() as i32));
    reflection.push(
        &object_path("Status"),
        Value::Int(
            scope
                .map(ObjectScopeContext::status)
                .or_else(|| world_object.as_ref().map(HostWorldObject::status))
                .unwrap_or(ObjectStatus::Deleted)
                .to_script_value(),
        ),
    );
    // `Info` serializes the stale nInfo cache refreshed only by
    // EnumeratePointers; the live crew-info name is not an equivalent value.
    reflection.push(
        &object_path("Owner"),
        Value::Int(
            scope
                .map(ObjectScopeContext::owner)
                .or_else(|| state.map(|state| state.owner))
                .or_else(|| world_object.as_ref().map(HostWorldObject::owner))
                .unwrap_or(OWNER_NONE),
        ),
    );
    reflection.push(
        &object_path("Timer"),
        Value::Int(state.map(|state| state.timer).unwrap_or(0)),
    );
    reflection.push(
        &object_path("Controller"),
        Value::Int(
            scope
                .map(ObjectScopeContext::controller)
                .or_else(|| state.map(|state| state.controller))
                .or_else(|| world_object.as_ref().map(HostWorldObject::controller))
                .unwrap_or(OWNER_NONE),
        ),
    );
    reflection.push(
        &object_path("LastEngLossPlr"),
        Value::Int(
            scope
                .and_then(|scope| scope.pending_update.energy_loss_cause)
                .or_else(|| {
                    world_object
                        .as_ref()
                        .map(|object| object.last_energy_loss_cause)
                })
                .unwrap_or(OWNER_NONE),
        ),
    );
    reflection.push(
        &object_path("Category"),
        Value::Int(
            scope
                .map(ObjectScopeContext::category)
                .or_else(|| state.map(|state| state.category))
                .or_else(|| world_object.as_ref().map(HostWorldObject::category))
                .unwrap_or(0),
        ),
    );
    reflection.push(&object_path("X"), Value::Int(position.x));
    reflection.push(&object_path("Y"), Value::Int(position.y));
    reflection.push(&object_path("Rotation"), Value::Int(rotation));
    // MotionX/MotionY and iLastAttachMovementFrame are serialized engine
    // caches that ObjectState does not retain. Omit them instead of exposing
    // plausible-looking defaults that differ after movement.
    reflection.push(
        &object_path("NoCollectDelay"),
        Value::Int(
            scope
                .map(ObjectScopeContext::no_collect_delay)
                .or_else(|| state.map(|state| state.no_collect_delay))
                .or_else(|| world_object.as_ref().map(|object| object.no_collect_delay))
                .unwrap_or(0),
        ),
    );
    reflection.push(
        &object_path("Base"),
        Value::Int(state.map(|state| state.base).unwrap_or(OWNER_NONE)),
    );
    let construction = scope
        .map(ObjectScopeContext::construction)
        .or_else(|| state.map(|state| state.construction))
        .or_else(|| world_object.as_ref().map(HostWorldObject::construction))
        .unwrap_or(0);
    reflection.push(&object_path("Size"), Value::Int(construction));
    reflection.push(
        &object_path("OwnMass"),
        Value::Int(
            scope
                .map(ObjectScopeContext::own_mass)
                .or_else(|| state.map(|state| state.own_mass))
                .unwrap_or(0),
        ),
    );
    reflection.push(
        &object_path("Mass"),
        Value::Int(reflected_object_mass(context, target, &mut HashSet::new())),
    );
    reflection.push(
        &object_path("Damage"),
        Value::Int(
            scope
                .map(ObjectScopeContext::damage)
                .or_else(|| state.map(|state| state.damage))
                .or_else(|| world_object.as_ref().map(HostWorldObject::damage))
                .unwrap_or(0),
        ),
    );
    reflection.push(
        &object_path("Energy"),
        Value::Int(
            scope
                .map(ObjectScopeContext::energy)
                .or_else(|| state.map(|state| state.energy))
                .or_else(|| world_object.as_ref().map(HostWorldObject::energy))
                .unwrap_or(0),
        ),
    );
    reflection.push(
        &object_path("MagicEnergy"),
        Value::Int(
            scope
                .map(ObjectScopeContext::magic_energy)
                .or_else(|| state.map(|state| state.magic_energy))
                .unwrap_or(0),
        ),
    );
    reflection.push(
        &object_path("Alive"),
        Value::Bool(
            scope
                .map(ObjectScopeContext::alive)
                .or_else(|| state.map(|state| state.alive))
                .or_else(|| world_object.as_ref().map(HostWorldObject::alive))
                .unwrap_or(false),
        ),
    );
    reflection.push(
        &object_path("Breath"),
        Value::Int(
            scope
                .map(ObjectScopeContext::breath)
                .or_else(|| state.map(|state| state.breath))
                .unwrap_or(0),
        ),
    );
    let fire_phase = scope
        .and_then(|scope| scope.pending_update.fire.map(|(_, phase)| phase))
        .or_else(|| state.map(|state| state.fire_phase))
        .unwrap_or(0);
    reflection.push(&object_path("FirePhase"), Value::Int(fire_phase));
    let color = scope
        .and_then(|scope| scope.pending_update.color)
        .or_else(|| state.map(|state| state.color))
        .unwrap_or(0);
    reflection.push(&object_path("Color"), Value::Int(color as i32));
    reflection.push(&object_path("ColorDw"), Value::Int(color as i32));

    let numbered_size = local_vars
        .keys()
        .filter_map(|name| name.strip_prefix("__local_")?.parse::<usize>().ok())
        .max()
        .map_or(0, |index| index.saturating_add(1));
    reflection.push(&object_path("Locals"), Value::Int(numbered_size as i32));
    for index in 0..numbered_size {
        let value = local_vars
            .get(&format!("__local_{index}"))
            .unwrap_or(&Value::Nil);
        push_reflected_c4value(&mut reflection, &object_path("Locals"), value);
    }

    reflection.push_fixed(&object_path("FixX"), fixed_position.x);
    reflection.push_fixed(&object_path("FixY"), fixed_position.y);
    reflection.push_fixed(&object_path("FixR"), fixed_rotation);
    reflection.push_fixed(&object_path("XDir"), fixed_velocity.x);
    reflection.push_fixed(&object_path("YDir"), fixed_velocity.y);
    reflection.push_fixed(&object_path("RDir"), rotation_velocity);

    reflection.push(&object_path("Width"), Value::Int(shape.width));
    reflection.push(&object_path("Height"), Value::Int(shape.height));
    reflection.push_trimmed_ints(&object_path("Offset"), vec![shape.x, shape.y]);
    reflection.push(
        &object_path("Vertices"),
        Value::Int(shape_vertices.active_count() as i32),
    );
    reflection.push_trimmed_ints(
        &object_path("VertexX"),
        shape_vertices.slots.iter().map(|vertex| vertex.x).collect(),
    );
    reflection.push_trimmed_ints(
        &object_path("VertexY"),
        shape_vertices.slots.iter().map(|vertex| vertex.y).collect(),
    );
    reflection.push_trimmed_ints(
        &object_path("VertexCNAT"),
        shape_vertices
            .slots
            .iter()
            .map(|vertex| vertex.cnat as i32)
            .collect(),
    );
    reflection.push_trimmed_ints(
        &object_path("VertexFriction"),
        shape_vertices
            .slots
            .iter()
            .map(|vertex| vertex.friction)
            .collect(),
    );
    reflection.push(
        &object_path("ContactDensity"),
        Value::Int(
            scope
                .map(ObjectScopeContext::contact_density)
                .or_else(|| state.map(|state| state.contact_density))
                .or_else(|| world_object.as_ref().map(HostWorldObject::contact_density))
                .unwrap_or(crate::CONTACT_DENSITY_SOLID),
        ),
    );
    let fire_top = metadata.map_or(0, |metadata| {
        if metadata.line != 0 || construction == FULL_CON {
            metadata.fire.fire_top
        } else {
            let percent = construction.saturating_mul(100) / FULL_CON;
            metadata.fire.fire_top.saturating_mul(percent) / 100
        }
    });
    reflection.push(&object_path("FireTop"), Value::Int(fire_top));
    let attach = scope
        .map(|scope| scope.walk_rotation.attach)
        .or_else(|| state.map(|state| state.shape_attach))
        .unwrap_or_default();
    reflection.push(&object_path("AttachX"), Value::Int(attach.x));
    reflection.push(&object_path("AttachY"), Value::Int(attach.y));
    reflection.push(&object_path("AttachVtx"), Value::Int(attach.vtx));

    reflection.push(
        &object_path("OwnVertices"),
        Value::Bool(
            scope.is_some_and(|scope| scope.staged_own_vertices)
                || world_object
                    .as_ref()
                    .is_some_and(|object| object.own_vertices),
        ),
    );
    let solid_mask = scope
        .and_then(|scope| scope.pending_update.solid_mask_override)
        .or_else(|| state.and_then(|state| state.solid_mask_override))
        .or_else(|| {
            definition_id.as_ref().and_then(|definition| {
                context
                    .world
                    .solid_mask_metadata
                    .get(definition)
                    .and_then(|metadata| metadata.default_mask)
            })
        })
        .unwrap_or_else(|| crate::DefinitionTargetRect::new(0, 0, 0, 0, 0, 0));
    reflection.push_ints(
        &object_path("SolidMask"),
        [
            solid_mask.x,
            solid_mask.y,
            solid_mask.width,
            solid_mask.height,
            solid_mask.target_x,
            solid_mask.target_y,
        ],
    );
    let picture = scope
        .and_then(|scope| scope.pending_update.picture_rect)
        .or_else(|| state.map(|state| state.picture_rect))
        .unwrap_or_default();
    reflection.push_ints(
        &object_path("Picture"),
        [picture.x, picture.y, picture.width, picture.height],
    );
    reflection.push(
        &object_path("Mobile"),
        Value::Bool(
            scope
                .map(ObjectScopeContext::mobile)
                .or_else(|| state.map(|state| state.mobile))
                .unwrap_or(false),
        ),
    );
    reflection.push(
        &object_path("Selected"),
        Value::Bool(
            scope
                .map(ObjectScopeContext::selected)
                .or_else(|| state.map(|state| state.selected))
                .unwrap_or(false),
        ),
    );
    reflection.push(
        &object_path("OnFire"),
        Value::Bool(
            scope
                .and_then(|scope| scope.pending_update.staged_on_fire())
                .or_else(|| state.map(|state| state.on_fire))
                .unwrap_or(false),
        ),
    );
    reflection.push(
        &object_path("InLiquid"),
        Value::Bool(
            scope
                .map(ObjectScopeContext::in_liquid)
                .or_else(|| state.map(|state| state.in_liquid))
                .or_else(|| world_object.as_ref().map(HostWorldObject::in_liquid))
                .unwrap_or(false),
        ),
    );
    reflection.push(
        &object_path("EntranceStatus"),
        Value::Bool(
            scope
                .and_then(|scope| scope.pending_update.entrance_status)
                .or_else(|| state.map(|state| state.entrance_status))
                .unwrap_or(false),
        ),
    );
    reflection.push(
        &object_path("PhysicalTemporary"),
        Value::Bool(
            scope
                .map(|scope| scope.temporary_physical.is_some())
                .or_else(|| state.map(|state| state.temporary_physical.is_some()))
                .unwrap_or(false),
        ),
    );
    reflection.push(
        &object_path("NeedEnergy"),
        Value::Bool(
            scope
                .map(ObjectScopeContext::need_energy)
                .or_else(|| state.map(|state| state.need_energy))
                .or_else(|| world_object.as_ref().map(|object| object.need_energy))
                .unwrap_or(false),
        ),
    );
    reflection.push(
        &object_path("OCF"),
        Value::Int(
            scope
                .map(|scope| scope.staged_ocf(scope.ocf()))
                .or_else(|| world_object.as_ref().map(HostWorldObject::ocf))
                .unwrap_or(0) as i32,
        ),
    );

    let action_name = scope
        .map(|scope| scope.effective_action_name().to_string())
        .or_else(|| state.map(|state| state.action.name.clone()))
        .or_else(|| world_object.as_ref().map(|object| object.action_name.clone()))
        .unwrap_or_default();
    reflection.push(&object_path("Action"), Value::String(action_name));
    reflection.push(
        &object_path("Dir"),
        Value::Int(
            scope
                .map(ObjectScopeContext::direction)
                .or_else(|| state.map(|state| state.direction))
                .unwrap_or_default()
                .to_script_value(),
        ),
    );
    reflection.push(
        &object_path("ComDir"),
        Value::Int(
            scope
                .map(ObjectScopeContext::command_direction)
                .or_else(|| state.map(|state| state.command_direction))
                .unwrap_or_default()
                .to_script_value(),
        ),
    );
    reflection.push(
        &object_path("ActionTime"),
        Value::Int(
            scope
                .map(|scope| scope.current_action_ticks.min(i32::MAX as u32) as i32)
                .or_else(|| state.map(|state| state.action.time.min(i32::MAX as u32) as i32))
                .unwrap_or(0),
        ),
    );
    reflection.push(
        &object_path("ActionData"),
        Value::Int(
            scope
                .map(ObjectScopeContext::effective_action_data)
                .or_else(|| state.map(|state| state.action.data))
                .unwrap_or(0),
        ),
    );
    reflection.push(
        &object_path("Phase"),
        Value::Int(
            scope
                .map(ObjectScopeContext::action_phase)
                .or_else(|| state.map(|state| state.action.phase))
                .unwrap_or(0),
        ),
    );
    let phase_delay = scope
        .and_then(|scope| {
            scope.pending_update.action.as_ref().and_then(|action| {
                action
                    .ticks
                    .map(|ticks| ticks.min(i32::MAX as u32) as i32)
                    .or_else(|| action.name.as_ref().map(|_| 0))
            })
        })
        .or_else(|| state.map(|state| state.action.ticks.min(i32::MAX as u32) as i32))
        .unwrap_or(0);
    reflection.push(&object_path("PhaseDelay"), Value::Int(phase_delay));

    // Contained, ActionTarget1/2 and Layer compile their independent
    // C4EnumeratedObjectPtr::number caches, not the live ObjectId. Rust does
    // not yet retain those raw cache values, so live IDs would be incorrect.

    let components = scope
        .and_then(|scope| scope.pending_update.components.as_ref())
        .or_else(|| state.map(|state| &state.components));
    let component_order = scope
        .and_then(|scope| scope.pending_update.component_order.as_ref())
        .or_else(|| state.map(|state| &state.component_order));
    if let (Some(components), Some(order)) = (components, component_order) {
        for id in order {
            reflection.push(
                &object_path("Component"),
                if id.as_str().is_empty() {
                    Value::Nil
                } else {
                    Value::C4Id(id.as_str().to_string())
                },
            );
            reflection.push(
                &object_path("Component"),
                Value::Int(components.get(id).copied().unwrap_or(0)),
            );
        }
    }
    if let Some(object) = world_object.as_ref() {
        for content in object.contents() {
            reflection.push(
                &object_path("Contents"),
                Value::Int(content.as_u64() as i32),
            );
        }
    }
    reflection.push(
        &object_path("PlrViewRange"),
        Value::Int(
            scope
                .map(ObjectScopeContext::plr_view_range)
                .or_else(|| state.map(|state| state.plr_view_range))
                .unwrap_or(0),
        ),
    );
    reflection.push(
        &object_path("Visibility"),
        Value::Int(
            scope
                .and_then(|scope| scope.pending_update.visibility)
                .or_else(|| state.map(|state| state.visibility))
                .unwrap_or(0),
        ),
    );
    let local_names = definition_id
        .as_deref()
        .and_then(|definition| context.world.definition_script(definition))
        .map(|script| {
            script
                .local_variable_names()
                .map(str::to_string)
                .collect::<Vec<_>>()
        })
        .unwrap_or_else(|| {
            let mut names = local_vars
                .keys()
                .filter(|name| !name.starts_with("__local_"))
                .cloned()
                .collect::<Vec<_>>();
            names.sort();
            names
        });
    reflection.push(
        &object_path("LocalNamed"),
        Value::Int(local_names.len() as i32),
    );
    for name in &local_names {
        reflection.push(&object_path("LocalNamed"), Value::String(name.clone()));
        push_reflected_c4value(
            &mut reflection,
            &object_path("LocalNamed"),
            local_vars.get(name).unwrap_or(&Value::Nil),
        );
    }
    reflection.push(
        &object_path("ColorMod"),
        Value::Int(
            scope
                .and_then(|scope| scope.pending_update.color_modulation)
                .or_else(|| state.map(|state| state.color_modulation))
                .unwrap_or(0) as i32,
        ),
    );
    reflection.push(
        &object_path("BlitMode"),
        Value::Int(
            context
                .object_blit_mode(target)
                .or_else(|| state.map(|state| state.blit_mode))
                .unwrap_or(0) as i32,
        ),
    );
    reflection.push(
        &object_path("CrewDisabled"),
        Value::Bool(
            context
                .object_crew_disabled(target)
                .or_else(|| state.map(|state| state.crew_disabled))
                .unwrap_or(false),
        ),
    );
    let base_graphics = match scope {
        Some(scope) => scope.base_graphics.as_ref(),
        None => state.and_then(|state| state.base_graphics.as_ref()),
    };
    let graphics_definition = base_graphics
        .map(|graphics| graphics.definition.as_str())
        .or(definition_id.as_deref())
        .unwrap_or_default();
    let graphics_name = base_graphics
        .and_then(|graphics| graphics.graphics_name.as_deref())
        .unwrap_or_default();
    reflection.push(
        &object_path("Graphics"),
        Value::C4Id(graphics_definition.to_string()),
    );
    reflection.push(
        &object_path("Graphics"),
        Value::String(graphics_name.to_string()),
    );

    // PhysicalTemporary follows the Object root as a sibling section.
    let physical = match scope {
        Some(scope) => scope.temporary_physical,
        None => state.and_then(|state| state.temporary_physical),
    };
    if let Some(physical) = physical {
        for (name, value) in [
            ("Energy", physical.energy),
            ("Breath", physical.breath),
            ("Walk", physical.walk),
            ("Jump", physical.jump),
            ("Scale", physical.scale),
            ("Hangle", physical.hangle),
            ("Dig", physical.dig),
            ("Swim", physical.swim),
            ("Throw", physical.throw),
            ("Push", physical.push),
            ("Fight", physical.fight),
            ("Magic", physical.magic),
            ("Float", physical.float),
            ("CanScale", physical.can_scale),
            ("CanHangle", physical.can_hangle),
            ("CanDig", physical.can_dig),
            ("CanConstruct", physical.can_construct),
            ("CanChop", physical.can_chop),
            ("CanFly", physical.can_fly),
            ("CorrosionResist", physical.corrosion_resist),
            ("BreatheWater", physical.breathe_water),
        ] {
            reflection.push(&["Physical", name], Value::Int(value));
        }
    }

    Some(reflection)
}

/// FnGetObjectVal (C4Script.cpp:4184-4195): reflect the modeled live portion
/// of C4Object::CompileFunc's named primitive stream. Shape, Action and
/// Graphics fields are inline under Object; Physical is a sibling section.
fn get_object_val(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 4 {
        return Err(RuntimeError::new(
            "GetObjectVal expects at most 4 arguments",
        ));
    }
    let Some(entry) = parse_optional_string(args.first(), "GetObjectVal", "entry")? else {
        return Ok(Value::Nil);
    };
    let section = parse_optional_string(args.get(1), "GetObjectVal", "section")?
        .filter(|section| !section.is_empty());
    let target_arg = args.get(2).unwrap_or(&Value::Nil);
    let target = if matches!(target_arg, Value::Bool(false)) {
        None
    } else {
        parse_object_reference_argument(target_arg, "GetObjectVal", "target")?
    };
    let entry_nr = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "GetObjectVal",
        "entry_nr",
    )?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let target = target.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(Value::Nil);
        };
        // These shipped hot paths run from movement callbacks every frame.
        // Their compiler paths are unique and inline directly under Object,
        // so avoid materializing the complete reflection stream (including
        // locals and recursive contents mass) just to read one shape scalar.
        if section.as_deref().is_none_or(|section| section == "Object") {
            if let Some(shape) = live_object_shape(context, target) {
                let value = match entry.as_str() {
                    "Width" if entry_nr == 0 => Some(Value::Int(shape.width)),
                    "Height" if entry_nr == 0 => Some(Value::Int(shape.height)),
                    "Offset" => {
                        let mut values = vec![shape.x, shape.y];
                        while values.last() == Some(&0) {
                            values.pop();
                        }
                        usize::try_from(entry_nr)
                            .ok()
                            .and_then(|index| values.get(index).copied())
                            .map(Value::Int)
                    }
                    _ => None,
                };
                if matches!(entry.as_str(), "Width" | "Height" | "Offset") {
                    return Ok(value.unwrap_or(Value::Nil));
                }
            }
        }
        Ok(reflect_object_values(context, target)
            .and_then(|reflection| reflection.get(&entry, section.as_deref(), entry_nr))
            .unwrap_or(Value::Nil))
    })
}

/// FnGetObjectInfoCoreVal (C4Script.cpp:4197-4214): reflect the linked
/// C4ObjectInfoCore rather than the object's current definition. In
/// particular, `id` remains the recruited crew's source definition across a
/// ChangeDef; System.c4g/Magic.c uses that value for physical-training caps.
fn get_object_info_core_val(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 4 {
        return Err(RuntimeError::new(
            "GetObjectInfoCoreVal expects at most 4 arguments",
        ));
    }
    let Some(entry) = parse_optional_string(args.first(), "GetObjectInfoCoreVal", "entry")?
    else {
        return Ok(Value::Nil);
    };
    let section = parse_optional_string(args.get(1), "GetObjectInfoCoreVal", "section")?;
    let target = parse_object_reference_argument(
        args.get(2).unwrap_or(&Value::Nil),
        "GetObjectInfoCoreVal",
        "target",
    )?;
    let _entry_number = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "GetObjectInfoCoreVal",
        "entry number",
    )?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let target = target.or_else(|| context.object_context().map(|object| object.id()));
        let Some(target) = target else {
            return Ok(Value::Nil);
        };
        let info = match context.object_scope(target) {
            Some(scope) => scope.info_core(),
            None => context.world.crew_infos.get(&target),
        };
        let Some(info) = info else {
            return Ok(Value::Nil);
        };
        if section
            .as_deref()
            .is_some_and(|section| section != "ObjectInfo")
        {
            tracing::debug!(?section, %entry, "GetObjectInfoCoreVal section not modeled; nil");
            return Ok(Value::Nil);
        }
        Ok(match entry.as_str() {
            "id" => Value::C4Id(info.definition_id.as_str().to_string()),
            "Name" => Value::String(info.name.clone()),
            "Rank" => Value::Int(info.rank),
            "Experience" => Value::Int(info.experience),
            "DeathCount" => Value::Int(info.death_count),
            other => {
                tracing::debug!(entry = other, "GetObjectInfoCoreVal entry not modeled; nil");
                Value::Nil
            }
        })
    })
}

/// The live `C4Object::Shape` reflected by GetObjectVal. Same-call SetShape
/// and persisted shape overrides win over the definition-derived shape.
fn live_object_shape(context: &EffectHostContext, target: ObjectId) -> Option<DefinitionRect> {
    let pending_override = context
        .object_scope(target)
        .and_then(|scope| scope.pending_update.shape_override);
    match pending_override {
        Some(Some(shape)) => return Some(shape),
        Some(None) => {}
        None => {
            if let Some(shape) = context
                .get_world_object(target)
                .and_then(|object| object.full_state().and_then(|state| state.shape_override))
            {
                return Some(shape);
            }
        }
    }

    let scope = context.object_scope(target);
    let world_object = context.get_world_object(target);
    let definition = scope
        .and_then(|scope| {
            scope
                .pending_update
                .change_def
                .clone()
                .or_else(|| scope.definition_id.clone())
        })
        .or_else(|| {
            world_object
                .as_ref()
                .map(|object| object.definition_id().to_string())
        })?;
    let metadata = context.definition_metadata(&definition)?;
    if metadata.line != 0 {
        return metadata.shape;
    }
    let construction = scope
        .map(ObjectScopeContext::construction)
        .or_else(|| world_object.as_ref().map(HostWorldObject::construction))
        .unwrap_or(FULL_CON);
    let rotation = scope
        .map(ObjectScopeContext::rotation)
        .or_else(|| world_object.as_ref().map(|object| object.rotation))
        .unwrap_or(0);
    crate::transformed_shape_rect(
        metadata.shape,
        construction,
        metadata.stretch_growth,
        metadata.rotateable,
        rotation,
    )
}

/// Engine System.c4g wrappers (GetXVal.c:78-79). Nil forwards into
/// FnGetObjectVal and therefore defaults to the calling object.
fn get_obj_width(args: &[Value]) -> Result<Value, RuntimeError> {
    get_obj_dimension(args.first(), "Width")
}

fn get_obj_height(args: &[Value]) -> Result<Value, RuntimeError> {
    get_obj_dimension(args.first(), "Height")
}

fn get_obj_dimension(target: Option<&Value>, entry: &str) -> Result<Value, RuntimeError> {
    get_object_val(&[
        Value::String(entry.to_string()),
        Value::Nil,
        target.cloned().unwrap_or(Value::Nil),
    ])
}

/// FnGetEntrance (C4Script.cpp:1125-1129): read the object's live
/// EntranceStatus as an integer, defaulting a nil target to cthr->Obj.
fn get_entrance(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetEntrance expects at most 1 argument: target",
        ));
    }

    let target_id = parse_object_reference_argument(
        args.first().unwrap_or(&Value::Nil),
        "GetEntrance",
        "target",
    )?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Nil);
        };
        let Some(target) = target_id.or(context.script_object_context) else {
            return Ok(Value::Nil);
        };

        let scope = context.object_scope(target);
        let world_object = context.get_world_object(target);
        if scope.is_none() && world_object.is_none() {
            return Ok(Value::Nil);
        }

        let enabled = scope
            .and_then(|scope| scope.pending_update.entrance_status)
            .or_else(|| {
                world_object
                    .as_ref()
                    .and_then(|object| object.full_state())
                    .map(|state| state.entrance_status)
            })
            .unwrap_or(false);
        Ok(Value::Int(i32::from(enabled)))
    })
}

/// FnSetEntrance (C4Script.cpp:690-695): toggle the object's EntranceStatus.
fn set_entrance(args: &[Value]) -> Result<Value, RuntimeError> {
    let enabled = args.first().unwrap_or(&Value::Nil).as_bool();
    let mut index = 1;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "SetEntrance", "target")?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetEntrance requires an active engine context"))?;
        let object = match context.object_context_mut() {
            Some(object) => object,
            None => return Ok(Value::Bool(false)),
        };
        if let Some(target) = target_id {
            if target != object.id() {
                return Ok(Value::Bool(false));
            }
        }
        object.pending_update.entrance_status = Some(enabled);
        Ok(Value::Bool(true))
    })
}

/// FnSetColorDw (C4Script.cpp:3661-3668): set the object's 32-bit color.
fn set_color_dw(args: &[Value]) -> Result<Value, RuntimeError> {
    let value = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetColorDw", "value")?;
    let mut index = 1;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "SetColorDw", "target")?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let target = target_id.or_else(|| context.object_context().map(|object| object.id()));
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        Ok(Value::Bool(
            context
                .object_scope_mut(target)
                .map(|object| object.pending_update.color = Some(value as u32))
                .is_some(),
        ))
    })
}

/// FnSetPicture (C4Script.cpp:3708-3715): write the object's raw picture
/// rectangle. A null explicit target falls back to the calling object; unlike
/// SetShape, C++ accepts any live object pointer supplied by script.
fn set_picture(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetPicture", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "SetPicture", "y")?;
    let width = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "SetPicture", "wdt")?;
    let height = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "SetPicture", "hgt")?;
    let mut index = 4;
    let explicit_target =
        consume_optional_object_reference_argument(args, &mut index, "SetPicture", "target")?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let target = explicit_target.or_else(|| context.object_context().map(|object| object.id()));
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let changed = context
            .object_scope_mut(target)
            .map(|object| {
                object.set_picture_rect(DefinitionRect::new(x, y, width, height));
            })
            .is_some();
        Ok(Value::Bool(changed))
    })
}

/// FnSetShape (C4Script.cpp:5182-5196): overwrite the object's shape rect.
fn set_shape(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetShape", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "SetShape", "y")?;
    let width = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "SetShape", "wdt")?;
    let height = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "SetShape", "hgt")?;
    let mut index = 4;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "SetShape", "target")?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetShape requires an active engine context"))?;
        let target = target_id.or_else(|| context.object_context().map(ObjectScopeContext::id));
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        Ok(Value::Bool(
            context
                .object_scope_mut(target)
                .map(|object| {
                    object.pending_update.shape_override =
                        Some(Some(DefinitionRect::new(x, y, width, height)));
                })
                .is_some(),
        ))
    })
}

/// FnSetContactDensity (C4Script.cpp:1286-1291): overwrite the live
/// C4Shape field on the explicit object, or on the calling object when the
/// optional pointer is nil. This is per object rather than a definition
/// mutation; later host calls in this same VM call observe the write.
fn set_contact_density(args: &[Value]) -> Result<Value, RuntimeError> {
    let density = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "SetContactDensity",
        "density",
    )?;
    let mut index = 1;
    let explicit_target = consume_optional_object_reference_argument(
        args,
        &mut index,
        "SetContactDensity",
        "target",
    )?;

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let target = explicit_target.or_else(|| context.object_context().map(|object| object.id()));
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };
        object.set_contact_density(density);
        Ok(Value::Bool(true))
    })
}

/// FnAddVertex (C4Script.cpp:1274-1278): append one raw X/Y pair to the
/// current live shape. C4Shape::AddVertex rejects the 31st vertex without
/// enabling C4Object::fOwnVertices (C4Shape.cpp:26-32).
fn add_vertex(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "AddVertex", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "AddVertex", "y")?;
    let explicit_target = args
        .get(2)
        .map(|arg| parse_object_reference_argument(arg, "AddVertex", "object"))
        .transpose()?
        .flatten();

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let target = explicit_target.or_else(|| context.object_context().map(|object| object.id()));
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };
        let mut vertices = object.shape_vertex_buffer();
        if !vertices.add(x, y) {
            return Ok(Value::Bool(false));
        }
        object.set_shape_vertex_buffer(vertices);
        Ok(Value::Bool(true))
    })
}

