/// FnSetVertex (C4Script.cpp:1237-1271): set one vertex attribute (VTX_X=0,
/// VTX_Y=1, VTX_CNAT=2, VTX_Friction=3); unknown attributes fall back to
/// VtxY like the old-style C++ behaviour. Own-vertex mode offsets the index
/// by C4D_VertexCpyPos = C4D_MaxVertex/2 = 15 (C4Shape.h:27).
fn set_vertex(args: &[Value]) -> Result<Value, RuntimeError> {
    const MAX_VERTEX: usize = 30;
    let index_arg = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetVertex", "index")?;
    let kind = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "SetVertex", "attribute")?;
    let value = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "SetVertex", "value")?;
    let mut arg_index = 3;
    let target_id =
        consume_optional_object_reference_argument(args, &mut arg_index, "SetVertex", "target")?;
    let own_vertex_mode = match args.get(arg_index) {
        Some(arg) => value_to_i32(arg, "SetVertex", "own vertex mode")?,
        None => 0,
    };

    let mut vertex_index = index_arg;
    if own_vertex_mode != 0 {
        vertex_index += 15;
    }
    let Ok(vertex_index) = usize::try_from(vertex_index) else {
        return Ok(Value::Bool(false));
    };
    if vertex_index >= MAX_VERTEX {
        return Ok(Value::Bool(false));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetVertex requires an active engine context"))?;
        let active = context.object_context().map(|object| object.id());
        let write = |vertices_base: &[ObjectVertex], pending: &mut Option<Vec<ObjectVertex>>| {
            let mut vertices = pending.clone().unwrap_or_else(|| vertices_base.to_vec());
            if vertices.len() <= vertex_index {
                vertices.resize(vertex_index + 1, ObjectVertex::default());
            }
            match kind {
                0 => vertices[vertex_index].x = value,
                2 => vertices[vertex_index].cnat = value as u32,
                3 => vertices[vertex_index].friction = value,
                // VTX_Y and the old-style fallback for any other attribute.
                _ => vertices[vertex_index].y = value,
            }
            *pending = Some(vertices);
        };

        // FnSetVertex works on ANY object (`if (!pObj) pObj = cthr->Obj`,
        // C4Script.cpp) — the Gatling aims its crosshair with
        // SetVertex(0, .., pCrosshair). Foreign writes stage into the
        // target's nested scope like every other cross-object fold.
        match target_id {
            Some(target) if Some(target) != active => {
                if !context.nested_objects.contains_key(&target) {
                    let Some(world_object) = context.get_world_object(target) else {
                        return Ok(Value::Bool(false));
                    };
                    let Some((scope, local_vars)) = context.nested_scope_for(&world_object) else {
                        return Ok(Value::Bool(false));
                    };
                    context
                        .nested_objects
                        .insert(target, NestedScopeState { scope, local_vars });
                }
                if !context.nested_order.contains(&target) {
                    context.nested_order.push(target);
                }
                let state = context
                    .nested_objects
                    .get_mut(&target)
                    .expect("scope just ensured");
                let base = state.scope.vertices().to_vec();
                write(&base, &mut state.scope.pending_update.vertices);
                state.scope.staged_own_vertices |= own_vertex_mode != 0;
                Ok(Value::Bool(true))
            }
            _ => {
                let object = match context.object_context_mut() {
                    Some(object) => object,
                    None => return Ok(Value::Bool(false)),
                };
                let base = object.vertices().to_vec();
                write(&base, &mut object.pending_update.vertices);
                object.staged_own_vertices |= own_vertex_mode != 0;
                Ok(Value::Bool(true))
            }
        }
    })
}

/// FindObject container sentinels (C4Object.h:83-84): `NoContainer()` = 124,
/// `AnyContainer()` = 123 (FnNoContainer/FnAnyContainer,
/// C4Script.cpp:6731-6732).
/// FnInsertMaterial (C4Script.cpp:2207-2211): insert one material pixel
/// at caller-relative coordinates. The authoritative fold runs the full
/// landscape/PXS/reaction path with vx/vy converted through FIXED10.
fn insert_material(args: &[Value]) -> Result<Value, RuntimeError> {
    let material = value_to_i32(args.first().unwrap_or(&Value::Nil), "InsertMaterial", "mat")?;
    let x = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "InsertMaterial", "x")?;
    let y = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "InsertMaterial", "y")?;
    // FnInsertMaterial (C4Script.cpp:2207-2211): vx/vy ride into
    // C4Landscape::InsertMaterial (FIXED10 there).
    let vx = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "InsertMaterial", "vx")?;
    let vy = value_to_i32(args.get(4).unwrap_or(&Value::Nil), "InsertMaterial", "vy")?;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = match borrow.as_mut() {
            Some(context) => context,
            None => return Ok(Value::Bool(false)),
        };
        let valid_material = usize::try_from(material)
            .ok()
            .and_then(crate::material::MaterialId::new)
            .is_some_and(|material| {
                context
                    .world
                    .materials()
                    .and_then(|materials| materials.get_by_id(material))
                    .is_some()
            });
        if !valid_material {
            return Ok(Value::Bool(false));
        }
        let position = context.caller_scope().map_or(Vector2::new(x, y), |(_, base)| {
            Vector2::new(base.x.saturating_add(x), base.y.saturating_add(y))
        });
        context.register_landscape_operation(LandscapeOperation::InsertMaterial {
            material,
            position,
            velocity: Vector2::new(vx, vy),
        });
        Ok(Value::Bool(true))
    })
}

/// FnExtractLiquid (C4Script.cpp:2194-2199): caller-relative coordinates,
/// MNone for a non-liquid pixel, otherwise the material number returned by
/// C4Landscape::ExtractMaterial. A callback-local COW preview supplies C++'s
/// synchronous visibility; the matching authoritative mutation folds after
/// the callback and runs instability side effects exactly once.
fn extract_liquid(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "ExtractLiquid", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "ExtractLiquid", "y")?;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = match borrow.as_mut() {
            Some(context) => context,
            None => return Ok(Value::Int(MATERIAL_NONE)),
        };
        let position = context.caller_scope().map_or(Vector2::new(x, y), |(_, base)| {
            Vector2::new(base.x.saturating_add(x), base.y.saturating_add(y))
        });
        let Some(material) = context.preview_extract_liquid(position) else {
            return Ok(Value::Int(MATERIAL_NONE));
        };
        Ok(Value::Int(material.index() as i32))
    })
}

/// FnFlameConsumeMaterial (C4Script.cpp:2172-2180): consume one
/// caller-relative landscape pixel only when its material is inflammable.
/// The synchronous return value is computed from the current landscape and
/// the matching real ExtractMaterial mutation is folded after the callback.
fn flame_consume_material(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "FlameConsumeMaterial",
        "x",
    )?;
    let y = value_to_i32(
        args.get(1).unwrap_or(&Value::Nil),
        "FlameConsumeMaterial",
        "y",
    )?;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        let mut position = Vector2::new(x, y);
        if let Some(object) = context.object_context() {
            let base = object.effective_position();
            position = Vector2::new(base.x.saturating_add(x), base.y.saturating_add(y));
        }

        let extracted = match (context.landscape_ref(), context.world.materials()) {
            (Some(landscape), Some(materials)) => landscape
                .material_at(position.x, position.y)
                .filter(|&material| {
                    materials
                        .get_by_id(material)
                        .is_some_and(|entry| entry.inflammable() != 0)
                })
                .is_some_and(|material| {
                    landscape.simulate_extract_material_amount(
                        materials,
                        position.x,
                        position.y,
                        material,
                        1,
                    ) == 1
                }),
            _ => false,
        };
        if extracted {
            let material = context
                .landscape_ref()
                .and_then(|landscape| landscape.material_at(position.x, position.y))
                .expect("successful material extraction keeps its source material");
            context.register_landscape_operation(LandscapeOperation::ExtractMaterialAmount {
                material: material.index() as i32,
                position,
                amount: 1,
            });
        }
        Ok(Value::Bool(extracted))
    })
}

/// FnExtractMaterialAmount (C4Script.cpp:2264-2273): extract up to
/// `amount` pixels while `GBackMat(x,y) == mat`, each through
/// ExtractMaterial (FindMatTop + clear). The count is computed by an
/// overlay simulation on the read view and the mutation staged as an
/// operation applied on the same state.
fn extract_material_amount(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "ExtractMaterialAmount", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "ExtractMaterialAmount", "y")?;
    let material = value_to_i32(
        args.get(2).unwrap_or(&Value::Nil),
        "ExtractMaterialAmount",
        "mat",
    )?;
    let amount = value_to_i32(
        args.get(3).unwrap_or(&Value::Nil),
        "ExtractMaterialAmount",
        "amount",
    )?;
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = match borrow.as_mut() {
            Some(context) => context,
            None => return Ok(Value::Int(0)),
        };
        let mut position = Vector2::new(x, y);
        if let Some(object) = context.object_context() {
            let base = object.current_position;
            position = Vector2::new(base.x + x, base.y + y);
        }
        let Some(material_id) = usize::try_from(material).ok().and_then(crate::material::MaterialId::new)
        else {
            return Ok(Value::Int(0));
        };
        let Some(materials) = context.world.materials() else {
            return Ok(Value::Int(0));
        };
        let extracted = context
            .world
            .landscape_ref()
            .map(|landscape| {
                landscape.simulate_extract_material_amount(
                    materials,
                    position.x,
                    position.y,
                    material_id,
                    amount,
                )
            })
            .unwrap_or(0);
        if extracted > 0 {
            context.register_landscape_operation(LandscapeOperation::ExtractMaterialAmount {
                material,
                position,
                amount: extracted,
            });
        }
        Ok(Value::Int(extracted))
    })
}

/// FnOnFire (C4Script.cpp:1866-1877): burning when the OnFire flag is set
/// or any *Fire* effect (C4Fx_AnyFire) sits on the object; nil without one.
/// Staged same-call writes (Incinerate/Extinguish/RemoveEffect) win over
/// the world snapshot like C++'s live flag.
fn on_fire(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "OnFire", "target")?;
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };
        let target = target_id.or_else(|| context.object_context().map(|object| object.id()));
        let Some(target) = target else {
            return Ok(Value::Nil);
        };
        let world_flag = || {
            context
                .get_world_object(target)
                .and_then(|object| object.full_state().map(|state| state.on_fire))
                .unwrap_or(false)
        };
        if let Some(scope) = context.object_scope(target) {
            let flag = scope
                .pending_update
                .staged_on_fire()
                .unwrap_or_else(world_flag);
            let burning = flag
                || scope
                    .effects
                    .snapshot()
                    .iter()
                    .any(|effect| effect.name.contains("Fire"));
            return Ok(Value::Bool(burning));
        }
        match context.get_world_object(target) {
            Some(other) => Ok(Value::Bool(other.full_state().is_some_and(|state| {
                state.on_fire
                    || state
                        .effects
                        .iter()
                        .any(|effect| effect.name.contains("Fire"))
            }))),
            None => Ok(Value::Nil),
        }
    })
}

fn no_container(_args: &[Value]) -> Result<Value, RuntimeError> {
    Ok(Value::Int(124))
}

fn any_container(_args: &[Value]) -> Result<Value, RuntimeError> {
    Ok(Value::Int(123))
}

/// FnActIdle (C4Script.cpp:1831-1836): true when the object has no action
/// (C++ Act == ActIdle; our engine stores that as an empty or "Idle" name),
/// nil without an object.
fn act_idle(args: &[Value]) -> Result<Value, RuntimeError> {
    let mut index = 0;
    let target_id =
        consume_optional_object_reference_argument(args, &mut index, "ActIdle", "target")?;

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Nil),
        };

        let action_name = if let Some(target) = target_id {
            match context.object_context() {
                Some(object) if target == object.id() => {
                    Some(object.effective_action_name().to_string())
                }
                _ => context
                    .get_world_object(target)
                    .map(|other| other.action_name.clone()),
            }
        } else {
            context
                .object_context()
                .map(|object| object.effective_action_name().to_string())
        };

        Ok(action_name
            .map(|name| Value::Bool(name.is_empty() || name == "Idle"))
            .unwrap_or(Value::Nil))
    })
}

fn set_category(args: &[Value]) -> Result<Value, RuntimeError> {
    // Unfilled iCategory is nil -> 0 (FnSetCategory, C4Script.cpp:805).
    let category = value_to_i32(args.first().unwrap_or(&Value::Nil), "SetCategory", "category")?;

    let mut index = 1;
    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        target_id = parse_object_reference_argument(arg, "SetCategory", "target")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetCategory: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetCategory requires an active engine context"))?;
        let target = target_id.or(context.script_object_context);
        let Some(target) = target else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };

        object.set_category(category);
        object.unsorted = true;
        // C4Object::SetCategory immediately calls Resort(), which leaves the
        // link in place but arms the post-CrossCheck global unsorted sweep.
        context.record_object_order_command(ObjectOrderCommand::ResortObject(target));
        Ok(Value::Bool(true))
    })
}

/// Live host-side `C4Object::SetOwner`. The callback must run before the
/// outer VM resumes, so this cannot be deferred to ObjectUpdate folding.
fn set_owner_live(target: ObjectId, new_owner: i32) -> bool {
    let staged: Option<Option<i32>> = HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow.as_mut()?;
        if new_owner != OWNER_NONE && context.player_state(new_owner).is_none() {
            return None;
        }
        if !context.ensure_object_scope(target) {
            return None;
        }

        // Bare host fixtures and a handful of legacy definition-less scopes
        // still carry a valid C4Object owner slot.
        let definition_id = context
            .object_effective_definition_id(target)
            .unwrap_or_default();
        let graphics_definition_id = context
            .object_scope(target)
            .and_then(|scope| {
                scope
                    .base_graphics
                    .as_ref()
                    .map(|graphics| graphics.definition.as_str().to_string())
            })
            .unwrap_or_else(|| definition_id.clone());
        let owner_color = (new_owner != OWNER_NONE
            && context
                .world
                .definition_color_by_owner(&graphics_definition_id))
        .then(|| {
            context
                .player_state(new_owner)
                .and_then(|player| player.color)
                .map(|color| {
                    u32::from(color.r) << 16
                        | u32::from(color.g) << 8
                        | u32::from(color.b)
                })
                .unwrap_or(0)
        });

        let (old_owner, flag_base_target) = {
            let object = context.object_scope_mut(target)?;
            // C++ refreshes the currently selected ColorByOwner graphics
            // before its same-owner early return.
            if let Some(color) = owner_color {
                object.pending_update.color = Some(color);
            }
            let old_owner = object.owner();
            if old_owner == new_owner {
                return Some(None);
            }
            let flag_base_target = (definition_id == "FLAG"
                && object.effective_action_name() == "FlyBase")
                .then(|| object.effective_action_target(0))
                .flatten();
            object.set_owner(new_owner);
            (old_owner, flag_base_target)
        };

        // A flying flag transfers only a still-present base that belongs to
        // the old owner. Inactive targets have nonzero C++ Status and count.
        if let Some(base_target) = flag_base_target {
            let base = context
                .object_scope(base_target)
                .and_then(|scope| scope.pending_update.base)
                .or_else(|| {
                    context
                        .get_world_object(base_target)
                        .and_then(|object| object.full_state().map(|state| state.base))
                });
            if context.object_status_present(base_target)
                && base == Some(old_owner)
                && context.ensure_object_scope(base_target)
            {
                if let Some(base) = context.object_scope_mut(base_target) {
                    base.pending_update.base = Some(new_owner);
                }
            }
        }
        Some(Some(old_owner))
    });

    let Some(old_owner) = staged else {
        return false;
    };
    if let Some(old_owner) = old_owner {
        let present = HOST_CONTEXT.with(|cell| {
            cell.borrow()
                .as_ref()
                .is_some_and(|context| context.object_status_present(target))
        });
        if present {
            let _ = call_inflight_object_own_fail_safe(
                target,
                "OnOwnerChanged",
                &[Value::Int(new_owner), Value::Int(old_owner)],
            );
        }
    }
    true
}

fn set_owner(args: &[Value]) -> Result<Value, RuntimeError> {
    // Unfilled iOwner is nil -> 0 (FnSetOwner, C4Script.cpp:820).
    let owner = match args.first().unwrap_or(&Value::Nil) {
        Value::Int(value) => *value,
        Value::Nil => 0,
        other => {
            return Err(RuntimeError::new(format!(
                "SetOwner: expected int for owner, got {}",
                other.type_name()
            )))
        }
    };

    let mut index = 1;
    let mut target_id: Option<ObjectId> = None;

    if let Some(arg) = args.get(index) {
        target_id = parse_object_reference_argument(arg, "SetOwner", "target")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetOwner: additional arguments are not supported",
        ));
    }

    let target = HOST_CONTEXT.with(|cell| {
        cell.borrow()
            .as_ref()
            .and_then(|context| target_id.or(context.script_object_context))
    });
    Ok(Value::Bool(
        target.is_some_and(|target| set_owner_live(target, owner)),
    ))
}

fn set_alive(args: &[Value]) -> Result<Value, RuntimeError> {
    // Unfilled nalv is nil -> false (FnSetAlive, C4Script.cpp:813).
    let alive = match args.first().unwrap_or(&Value::Nil) {
        Value::Bool(flag) => *flag,
        Value::Int(value) => *value != 0,
        Value::Nil => false,
        other => {
            return Err(RuntimeError::new(format!(
                "SetAlive: expected bool, int, or nil for alive, got {}",
                other.type_name()
            )))
        }
    };

    let mut index = 1;
    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.get(index) {
        target_id = parse_object_reference_argument(arg, "SetAlive", "target")?;
        index += 1;
    }

    if index < args.len() {
        return Err(RuntimeError::new(
            "SetAlive: additional arguments are not supported",
        ));
    }

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let context = borrow
            .as_mut()
            .ok_or_else(|| RuntimeError::new("SetAlive requires an active engine context"))?;
        let Some(target) = target_id.or_else(|| context.object_context().map(|object| object.id()))
        else {
            return Ok(Value::Bool(false));
        };
        if !context.ensure_object_scope(target) {
            return Ok(Value::Bool(false));
        }
        let Some(object) = context.object_scope_mut(target) else {
            return Ok(Value::Bool(false));
        };

        object.set_alive(alive);
        Ok(Value::Bool(true))
    })
}

fn get_owner(args: &[Value]) -> Result<Value, RuntimeError> {
    if args.len() > 1 {
        return Err(RuntimeError::new(
            "GetOwner expects at most 1 argument: target",
        ));
    }

    let mut target_id: Option<ObjectId> = None;
    if let Some(arg) = args.first() {
        target_id = parse_object_reference_argument(arg, "GetOwner", "target")?;
    }

    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let context = match borrow.as_ref() {
            Some(context) => context,
            None => return Ok(Value::Int(OWNER_NONE)),
        };

        if let Some(target) = target_id {
            if let Some(object) = context.object_context() {
                if target == object.id() {
                    return Ok(Value::Int(object.owner()));
                }
            }
            if let Some(other) = context.get_world_object(target) {
                return Ok(Value::Int(other.owner()));
            }
            return Ok(Value::Int(OWNER_NONE));
        }

        let object = match context.object_context() {
            Some(object) => object,
            None => return Ok(Value::Int(OWNER_NONE)),
        };

        Ok(Value::Int(object.owner()))
    })
}

