    #[test]
    fn buy_host_rejects_invalid_players_and_honors_silent_errors() {
        let (mut engine, caller, base) = buy_host_fixture();
        let caller_index = engine.find_object_index(caller).expect("caller index");
        let initial_objects = engine.snapshot().objects.len();

        for (for_player, pay_player) in [(99, 2), (1, 99)] {
            let rejected = engine
                .call_object_function(
                    caller_index,
                    "BuyAt",
                    vec![
                        Value::Int(for_player),
                        Value::Int(pay_player),
                        object_reference_value(base),
                        Value::Bool(true),
                    ],
                )
                .expect("invalid-player Buy returns normally");
            assert_eq!(rejected, Value::Nil);
        }
        assert_eq!(engine.snapshot().objects.len(), initial_objects);
        assert_eq!(engine.player(2).expect("payer remains").wealth(), 100);
        assert_eq!(
            engine
                .player(2)
                .expect("payer remains")
                .home_base_material()
                .get(&DefinitionId::from("ITEM")),
            Some(&2)
        );
        assert!(engine.snapshot().hud.messages.is_empty());
        assert!(engine.pending_audio.is_empty());

        engine
            .set_player_home_base_material(2, HashMap::new())
            .expect("empty stock installs");
        let unavailable = engine
            .call_object_function(
                caller_index,
                "BuyAt",
                vec![
                    Value::Int(1),
                    Value::Int(2),
                    object_reference_value(base),
                    Value::Bool(false),
                ],
            )
            .expect("silent unavailable-item Buy returns normally");
        assert_eq!(unavailable, Value::Nil);
        assert_eq!(engine.snapshot().objects.len(), initial_objects);
        assert!(engine.snapshot().hud.messages.is_empty());
        assert!(engine.pending_audio.is_empty());
        engine
            .set_player_home_base_material(
                2,
                HashMap::from([(DefinitionId::from("ITEM"), 2)]),
            )
            .expect("stock restores");

        engine
            .set_player_wealth(2, 24)
            .expect("insufficient wealth installs");
        let rejected = engine
            .call_object_function(
                caller_index,
                "BuyAt",
                vec![
                    Value::Int(1),
                    Value::Int(2),
                    object_reference_value(base),
                    Value::Bool(false),
                ],
            )
            .expect("silent insufficient-wealth Buy returns normally");
        assert_eq!(rejected, Value::Nil);
        assert_eq!(engine.snapshot().objects.len(), initial_objects);
        assert_eq!(engine.player(2).expect("payer remains").wealth(), 24);
        assert_eq!(
            engine
                .player(2)
                .expect("payer remains")
                .home_base_material()
                .get(&DefinitionId::from("ITEM")),
            Some(&2)
        );
        assert!(engine.snapshot().hud.messages.is_empty());
        assert!(engine.pending_audio.is_empty());

        let rejected = engine
            .call_object_function(
                caller_index,
                "BuyAt",
                vec![
                    Value::Int(1),
                    Value::Int(2),
                    object_reference_value(base),
                    Value::Bool(true),
                ],
            )
            .expect("visible insufficient-wealth Buy returns normally");
        assert_eq!(rejected, Value::Nil);
        let messages = engine.snapshot().hud.messages;
        assert_eq!(messages.len(), 1);
        assert_eq!(messages[0].kind, MessageKind::GlobalPlayer);
        assert_eq!(messages[0].player, Some(2));
        assert_eq!(messages[0].lines, vec!["Not enough money!"]);
        assert!(matches!(
            engine.pending_audio.as_slice(),
            [AudioCommand::PlaySound { name, target, .. }]
                if name == "Error" && *target == Some(base)
        ));
    }

    #[test]
    fn sell_host_runs_the_cpp_homebase_transaction_and_defaults_target() {
        let caller_script = r#"#strict
public func SellTarget(int player, object target) { return Sell(player, target); }
"#;
        let item_script = r#"#strict
local sale_base;
public func CalcValue(object base, int player)
{
    sale_base = base;
    if (!base) return(-1000);
    return(20 + player);
}
public func Sale(int player)
{
    if (!Contained())
        sale_base->RecordSale(GetWealth(player), GetHomebaseMaterial(player, VALU));
}
public func SellSelf(int player) { return Sell(player); }
"#;
        let base_script = r#"#strict
local sales, sale_wealth, sale_stock;
public func CalcSellValue(object item, int value) { return(value + 3); }
public func RecordSale(int wealth, int stock)
{
    sales++;
    sale_wealth = wealth;
    sale_stock = stock;
}
"#;

        let mut engine = crate::Engine::with_seed(32);
        engine
            .register_player(crate::PlayerConfig::new(0, "Player"))
            .expect("player registers");
        engine
            .register_definition(
                crate::Definition::from_script("CALL", "Caller", caller_script)
                    .expect("caller compiles"),
            )
            .expect("caller registers");
        engine
            .register_definition(
                crate::Definition::from_script("BASE", "Base", base_script)
                    .expect("base compiles"),
            )
            .expect("base registers");
        let mut item = crate::Definition::from_script("VALU", "Valuable", item_script)
            .expect("item compiles");
        item.set_value(99);
        item.set_rebuyable(true);
        engine.register_definition(item).expect("item registers");

        let base = engine
            .spawn_object(SpawnConfig::new("BASE"))
            .expect("base spawns");
        let caller = engine
            .spawn_object(SpawnConfig::new("CALL"))
            .expect("caller spawns");
        let caller_index = engine.find_object_index(caller).expect("caller index");

        let explicit = engine
            .spawn_object(SpawnConfig::new("VALU").with_container(base))
            .expect("explicit target spawns");
        let sold = engine
            .call_object_function(
                caller_index,
                "SellTarget",
                vec![Value::Int(0), object_reference_value(explicit)],
            )
            .expect("explicit Sell runs");
        assert_eq!(sold, Value::Bool(true));
        assert!(
            engine
                .object_snapshot(explicit)
                .is_none_or(|object| !object.status.is_active()),
            "the explicitly sold object is removed"
        );
        assert_eq!(engine.player(0).expect("player remains").wealth(), 23);
        assert_eq!(
            engine
                .player(0)
                .expect("player remains")
                .home_base_material()
                .get(&DefinitionId::from("VALU")),
            Some(&1)
        );
        let base_snapshot = engine.object_snapshot(base).expect("base remains");
        assert_eq!(base_snapshot.local_vars.get("sales"), Some(&Value::Int(1)));
        assert_eq!(
            base_snapshot.local_vars.get("sale_wealth"),
            Some(&Value::Int(23))
        );
        assert_eq!(
            base_snapshot.local_vars.get("sale_stock"),
            Some(&Value::Int(1))
        );

        let invalid = engine
            .spawn_object(SpawnConfig::new("VALU").with_container(base))
            .expect("invalid-player target spawns");
        let rejected = engine
            .call_object_function(
                caller_index,
                "SellTarget",
                vec![Value::Int(99), object_reference_value(invalid)],
            )
            .expect("invalid-player Sell returns normally");
        assert_eq!(rejected, Value::Bool(false));
        let invalid_snapshot = engine
            .object_snapshot(invalid)
            .expect("rejected object remains");
        assert!(invalid_snapshot.status.is_active());
        assert_eq!(invalid_snapshot.container, Some(base));
        assert_eq!(engine.player(0).expect("player remains").wealth(), 23);
        assert_eq!(
            engine
                .player(0)
                .expect("player remains")
                .home_base_material()
                .get(&DefinitionId::from("VALU")),
            Some(&1)
        );
        assert_eq!(
            engine
                .object_snapshot(base)
                .expect("base remains")
                .local_vars
                .get("sales"),
            Some(&Value::Int(1))
        );

        engine
            .set_player_wealth(0, 9_990)
            .expect("near-cap wealth installs");
        let implicit = engine
            .spawn_object(SpawnConfig::new("VALU").with_container(base))
            .expect("implicit target spawns");
        let implicit_index = engine.find_object_index(implicit).expect("implicit index");
        let sold = engine
            .call_object_function(implicit_index, "SellSelf", vec![Value::Int(0)])
            .expect("implicit Sell runs");
        assert_eq!(sold, Value::Bool(true));
        assert!(
            engine
                .object_snapshot(implicit)
                .is_none_or(|object| !object.status.is_active()),
            "the calling object is removed"
        );
        assert_eq!(engine.player(0).expect("player remains").wealth(), 10_000);
        assert_eq!(
            engine
                .player(0)
                .expect("player remains")
                .home_base_material()
                .get(&DefinitionId::from("VALU")),
            Some(&2)
        );
        let base_snapshot = engine.object_snapshot(base).expect("base remains");
        assert_eq!(base_snapshot.local_vars.get("sales"), Some(&Value::Int(2)));
        assert_eq!(
            base_snapshot.local_vars.get("sale_wealth"),
            Some(&Value::Int(10_000))
        );
        assert_eq!(
            base_snapshot.local_vars.get("sale_stock"),
            Some(&Value::Int(2))
        );
    }

    fn place_animal_world(
        id: &str,
        placement: i32,
        landscape: Landscape,
    ) -> HostWorldContext {
        HostWorldContext::with_landscape(
            Vec::<HostWorldObject>::new(),
            Some(landscape),
            HashMap::from([(
                DefinitionId::from(id),
                DefinitionMetadata {
                    category: crate::CATEGORY_LIVING,
                    shape: Some(DefinitionRect::new(-2, -3, 4, 6)),
                    placement,
                    physical: PhysicalInfo {
                        energy: 50_000,
                        ..PhysicalInfo::default()
                    },
                    ..DefinitionMetadata::default()
                },
            )]),
            Vec::new(),
            HashMap::new(),
            HashMap::new(),
            1,
            false,
        )
    }

    #[test]
    fn place_animal_surface_uses_two_draws_and_find_solid_ground() {
        // C4D_Place_Surface draws global x then y, runs FindSolidGround with
        // Shape.Wdt, and calls creatorless CreateObject at the returned point
        // (C4Game.cpp:3028-3043; C4Landscape.cpp:1830-1857).
        let mut landscape = Landscape::flat(100, 60);
        landscape.set_world_height(100);
        let mut expected_rng = LcgRng::new(17);
        let start_x = expected_rng.random(100);
        let start_y = expected_rng.random(100);
        let raw = landscape
            .find_solid_ground(start_x, start_y, 4)
            .map(|(x, y)| Vector2::new(x, y))
            .expect("flat world has solid ground");
        let final_position = Vector2::new(
            raw.x,
            crate::docon_initial_center_y(
                Some(DefinitionRect::new(-2, -3, 4, 6)),
                false,
                0,
                FULL_CON,
                raw.y,
            ),
        );
        let guard = enter_random_context(LcgRng::new(17));
        let (result, outcome) = with_effect_context(
            None,
            &[],
            place_animal_world("SURF", 0, landscape),
            1,
            || place_animal(&[Value::C4Id("SURF".into())]),
        );
        let final_rng = guard.finish();

        assert_eq!(final_rng, expected_rng);
        assert_eq!(
            result.expect("PlaceAnimal surface succeeds"),
            object_reference_value(ObjectId::new(1))
        );
        let spawn = &outcome.spawns[0];
        assert_eq!(spawn.position, final_position);
        assert_eq!(spawn.fixed_position, Some(FixedVec2::from_ints(raw.x, raw.y)));
        assert_eq!(spawn.owner, OWNER_NONE);
        assert_eq!(spawn.controller, Some(OWNER_NONE));
        assert_eq!(spawn.construction, FULL_CON);
    }

    #[test]
    fn place_animal_liquid_uses_surface_then_deep_fallback_search() {
        // C4D_Place_Liquid draws global x/y, tries FindSurfaceLiquid before
        // FindLiquid, then adds Shape.Hgt/2 before creatorless CreateObject
        // (C4Game.cpp:3044-3052; C4Landscape.cpp:1860-1915).
        let mut landscape = Landscape::flat(100, 80);
        landscape.set_world_height(100);
        let water = crate::MaterialId::new(1).expect("water id");
        for x in 20..80 {
            for y in 40..80 {
                assert!(landscape.insert_liquid_at(x, y, Some(water)));
            }
        }
        let mut expected_rng = LcgRng::new(23);
        let mut expected_x = expected_rng.random(100);
        let mut expected_y = expected_rng.random(100);
        assert!(
            placement_find_surface_liquid(&landscape, &mut expected_x, &mut expected_y, 4, 6)
                || placement_find_liquid(&landscape, &mut expected_x, &mut expected_y, 4, 6)
        );
        let raw = Vector2::new(expected_x, expected_y + 3);
        let final_position = Vector2::new(
            raw.x,
            crate::docon_initial_center_y(
                Some(DefinitionRect::new(-2, -3, 4, 6)),
                false,
                0,
                FULL_CON,
                raw.y,
            ),
        );
        let guard = enter_random_context(LcgRng::new(23));
        let (result, outcome) = with_effect_context(
            None,
            &[],
            place_animal_world("FISH", 1, landscape),
            1,
            || place_animal(&[Value::C4Id("FISH".into())]),
        );
        let final_rng = guard.finish();

        assert_eq!(final_rng, expected_rng);
        assert_eq!(
            result.expect("PlaceAnimal liquid succeeds"),
            object_reference_value(ObjectId::new(1))
        );
        assert_eq!(outcome.spawns[0].position, final_position);
        assert_eq!(
            outcome.spawns[0].fixed_position,
            Some(FixedVec2::from_ints(raw.x, raw.y))
        );
    }

    #[test]
    fn place_animal_air_scans_first_semisolid_then_draws_height() {
        // C4D_Place_Air draws global x, scans down to the first semi-solid
        // row, then draws Random(y) (C4Game.cpp:3053-3060).
        let mut landscape = Landscape::flat(100, 60);
        landscape.set_world_height(100);
        let mut expected_rng = LcgRng::new(31);
        let expected_x = expected_rng.random(100);
        let ceiling = (0..100)
            .find(|&y| landscape.is_semi_solid_at(expected_x, y))
            .expect("flat ground is semi-solid");
        let raw = Vector2::new(expected_x, expected_rng.random(ceiling));
        let final_position = Vector2::new(
            raw.x,
            crate::docon_initial_center_y(
                Some(DefinitionRect::new(-2, -3, 4, 6)),
                false,
                0,
                FULL_CON,
                raw.y,
            ),
        );
        let guard = enter_random_context(LcgRng::new(31));
        let (result, outcome) = with_effect_context(
            None,
            &[],
            place_animal_world("BIRD", 2, landscape),
            1,
            || place_animal(&[Value::C4Id("BIRD".into())]),
        );
        let final_rng = guard.finish();

        assert_eq!(final_rng, expected_rng);
        assert_eq!(
            result.expect("PlaceAnimal air succeeds"),
            object_reference_value(ObjectId::new(1))
        );
        assert_eq!(outcome.spawns[0].position, final_position);
        assert_eq!(
            outcome.spawns[0].fixed_position,
            Some(FixedVec2::from_ints(raw.x, raw.y))
        );
    }

    #[test]
    fn place_animal_air_without_semisolid_uses_world_height() {
        // If the column contains no semi-solid pixel, the C++ scan reaches
        // GBackHgt and still calls Random(GBackHgt) before creating the
        // animal (C4Game.cpp:3053-3060).
        let mut landscape = Landscape::flat(100, 100);
        landscape.set_world_height(100);
        let mut expected_rng = LcgRng::new(37);
        let raw = Vector2::new(expected_rng.random(100), expected_rng.random(100));
        let guard = enter_random_context(LcgRng::new(37));
        let (result, outcome) = with_effect_context(
            None,
            &[],
            place_animal_world("BIRD", 2, landscape),
            1,
            || place_animal(&[Value::C4Id("BIRD".into())]),
        );
        let final_rng = guard.finish();

        assert_eq!(final_rng, expected_rng);
        assert_eq!(
            result.expect("PlaceAnimal sky-only air succeeds"),
            object_reference_value(ObjectId::new(1))
        );
        assert_eq!(
            outcome.spawns[0].fixed_position,
            Some(FixedVec2::from_ints(raw.x, raw.y))
        );
    }

    #[test]
    fn place_animal_invalid_modes_draw_nothing_and_air_row_zero_draws_once() {
        // C4Id2Def and unsupported Placement return before Random; the Air
        // arm draws x, then fails without Random(y) when row zero is already
        // semi-solid (C4Game.cpp:3028-3061).
        let mut landscape = Landscape::flat(20, 0);
        landscape.set_world_height(20);
        let definitions = HashMap::from([
            (
                DefinitionId::from("UNSP"),
                DefinitionMetadata {
                    placement: 9,
                    ..DefinitionMetadata::default()
                },
            ),
            (
                DefinitionId::from("AIR0"),
                DefinitionMetadata {
                    placement: 2,
                    shape: Some(DefinitionRect::new(-2, -3, 4, 6)),
                    ..DefinitionMetadata::default()
                },
            ),
            (
                DefinitionId::from("SURF0"),
                DefinitionMetadata {
                    placement: 0,
                    shape: Some(DefinitionRect::new(-2, -3, 4, 6)),
                    ..DefinitionMetadata::default()
                },
            ),
        ]);
        let world = HostWorldContext::with_landscape(
            Vec::<HostWorldObject>::new(),
            Some(landscape),
            definitions,
            Vec::new(),
            HashMap::new(),
            HashMap::new(),
            1,
            false,
        );
        let mut expected_rng = LcgRng::new(41);
        let _ = expected_rng.random(20);
        let _ = expected_rng.random(20);
        let _ = expected_rng.random(20);
        let expected_after = expected_rng.random(1_000);
        let guard = enter_random_context(LcgRng::new(41));
        let (result, outcome) = with_effect_context(None, &[], world, 1, || {
            Ok::<_, RuntimeError>(Value::Array(vec![
                place_animal(&[Value::C4Id("NONE".into())])?,
                place_animal(&[Value::C4Id("UNSP".into())])?,
                place_animal(&[Value::C4Id("AIR0".into())])?,
                place_animal(&[Value::C4Id("SURF0".into())])?,
                random(&[Value::Int(1_000)])?,
            ]))
        });
        let final_rng = guard.finish();

        assert_eq!(final_rng, expected_rng);
        assert_eq!(
            result.expect("PlaceAnimal failure paths succeed"),
            Value::Array(vec![
                Value::Nil,
                Value::Nil,
                Value::Nil,
                Value::Nil,
                Value::Int(expected_after),
            ])
        );
        assert!(outcome.spawns.is_empty());
    }

    #[test]
    fn place_animal_callbacks_are_synchronous_and_removal_returns_nil() {
        // CreateObject inserts the animal before Construction(nil) at Con=0,
        // then DoCon(FullCon,true) calls Completion and Initialize; removal
        // in Construction makes PlaceAnimal return null while consuming the
        // object number (C4Game.cpp:1102-1146,3028-3061;
        // C4Object.cpp:1428-1515).
        let animal_script = r#"#strict
local iConstructionCon, iConstructionY, iOrder;
protected func Construction() { iConstructionCon=GetCon(); iConstructionY=GetY(); iOrder=1; }
protected func Completion() { iOrder=iOrder*10+2; }
protected func Initialize() { iOrder=iOrder*10+3; }
public func ConstructionCon() { return(iConstructionCon); }
"#;
        let caller_script = r#"#strict
local iObservedCon;
public func Seed() { var child=PlaceAnimal(ANML); iObservedCon=child->ConstructionCon(); return(child); }
public func SeedRemoved() { return(PlaceAnimal(DIEA)); }
"#;
        let mut engine = crate::Engine::with_seed(53);
        let mut landscape = Landscape::flat(100, 60);
        landscape.set_world_height(100);
        engine.set_landscape(landscape);
        let mut animal = crate::Definition::from_script("ANML", "Animal", animal_script)
            .expect("animal script compiles");
        animal.set_category(crate::CATEGORY_LIVING);
        animal.set_shape_rect(Some(DefinitionRect::new(-2, -3, 4, 6)));
        animal.set_placement(2);
        engine.register_definition(animal).expect("animal registers");
        let mut removed = crate::Definition::from_script(
            "DIEA",
            "Removed animal",
            "#strict\nprotected func Construction() { RemoveObject(); }",
        )
        .expect("removed animal script compiles");
        removed.set_category(crate::CATEGORY_LIVING);
        removed.set_shape_rect(Some(DefinitionRect::new(-2, -3, 4, 6)));
        removed.set_placement(2);
        engine.register_definition(removed).expect("removed animal registers");
        let caller = crate::Definition::from_script("CALL", "Caller", caller_script)
            .expect("caller script compiles");
        engine.register_definition(caller).expect("caller registers");
        let caller_id = engine
            .spawn_object(SpawnConfig::new("CALL").with_position(Vector2::new(1_000, 1_000)))
            .expect("caller spawns");
        let caller_index = engine.find_object_index(caller_id).expect("caller exists");

        let value = engine
            .call_object_function(caller_index, "Seed", Vec::new())
            .expect("Seed runs");
        let animal_id = object_id_from_value(&value).expect("Seed returns live animal");
        let animal_index = engine.find_object_index(animal_id).expect("animal exists");
        let animal = &engine.objects[animal_index].state;
        assert_eq!(animal.owner, OWNER_NONE);
        assert_eq!(animal.controller, OWNER_NONE);
        assert_eq!(animal.construction, FULL_CON);
        assert!((0..100).contains(&animal.position.x), "placement is global");
        assert_eq!(animal.local_vars.get("iConstructionCon"), Some(&Value::Int(0)));
        assert_eq!(animal.local_vars.get("iOrder"), Some(&Value::Int(123)));
        assert_eq!(
            animal.local_vars.get("iConstructionY"),
            Some(&Value::Int(animal.position.y + 3)),
            "Construction sees the raw pre-DoCon y"
        );
        let caller_index = engine.find_object_index(caller_id).expect("caller remains");
        assert_eq!(
            engine.objects[caller_index].state.local_vars.get("iObservedCon"),
            Some(&Value::Int(0)),
            "Construction writes are visible before PlaceAnimal returns"
        );

        let before_next_id = engine.capture_state().next_object_id;
        let value = engine
            .call_object_function(caller_index, "SeedRemoved", Vec::new())
            .expect("SeedRemoved runs");
        assert_eq!(value, Value::Nil);
        assert!(engine
            .snapshot()
            .objects
            .iter()
            .all(|object| object.definition_id != "DIEA"));
        assert_eq!(engine.capture_state().next_object_id, before_next_id + 1);
    }

    #[test]
    fn place_vegetation_uses_relative_surface_area_and_raw_growth_like_cpp() {
        // FnPlaceVegetation makes x/y caller-relative (C4Script.cpp:2487-2492),
        // then the surface arm draws x/y, applies AboveSemiSolid, checks Soil,
        // and passes the raw growth value to CreateObjectConstruction with
        // NO_OWNER (C4Game.cpp:2980-3022).
        let library = lc_resources::MaterialLibrary::parse(
            "[Material]\nName=Earth\nDensity=100\nSoil=1\n",
        )
        .expect("earth material parses");
        let materials = MaterialSet::from_resource_library(&library);
        let earth = materials.id_of("Earth").expect("earth material exists");
        let mut landscape = Landscape::flat_with_material(400, 160, Some(earth));
        landscape.set_world_height(300);
        let definitions = HashMap::from([(
            DefinitionId::from("TREE"),
            DefinitionMetadata {
                category: crate::CATEGORY_STATIC_BACK,
                shape: Some(DefinitionRect::new(-20, -28, 40, 56)),
                placement: 0,
                growth: 2,
                stretch_growth: true,
                ..DefinitionMetadata::default()
            },
        )]);
        let world = HostWorldContext::with_landscape(
            Vec::<HostWorldObject>::new(),
            Some(landscape),
            definitions,
            Vec::new(),
            HashMap::new(),
            HashMap::new(),
            2,
            false,
        )
        .with_materials(Some(Rc::new(materials)));
        let caller = HostObjectContext::new(
            ObjectId::new(1),
            None,
            ObjectStatus::Normal,
            100,
            OWNER_NONE,
            Vector2::new(200, 150),
            Vector2::ZERO,
            &[],
            "Idle",
            0,
            0,
            ActionLibrary::default(),
            Direction::Left,
            CommandDirection::Stop,
            0,
            None,
            None,
            &[],
            FULL_CON,
        );
        let mut expected_rng = LcgRng::new(17);
        assert_eq!(expected_rng.random(200), 94);
        assert_eq!(expected_rng.random(200), 2);
        let guard = enter_random_context(LcgRng::new(17));
        let (result, outcome) = with_effect_context(Some(caller), &[], world, 2, || {
            place_vegetation(&[
                Value::C4Id("TREE".into()),
                Value::Int(-100),
                Value::Int(-100),
                Value::Int(200),
                Value::Int(200),
                Value::Int(10),
            ])
        });
        let rng_after = guard.finish();

        assert_eq!(rng_after, expected_rng, "exactly the x/y draws are consumed");
        assert_eq!(
            result.expect("PlaceVegetation succeeds"),
            object_reference_value(ObjectId::new(2))
        );
        assert_eq!(outcome.spawns.len(), 1);
        let spawn = &outcome.spawns[0];
        assert_eq!(spawn.definition_id, "TREE");
        assert_eq!(spawn.position, Vector2::new(194, 168));
        assert_eq!(spawn.construction, 10, "growth is FullCon scale, not percent");
        assert_eq!(spawn.owner, OWNER_NONE);
        assert_eq!(spawn.controller, Some(OWNER_NONE));
    }

    #[test]
    fn place_vegetation_runs_construction_before_partial_growth_like_cpp() {
        // NewObject inserts the object, calls Construction at Con=0, then
        // DoCon(iGrowth, true); Completion+Initialize only run when that
        // transition reaches FullCon (C4Game.cpp:1135-1144;
        // C4Object.cpp:1428-1515). FnPlaceVegetation returns that live object.
        let script = r#"#strict
local iConstructionCon, iCompletion, iInitialized, iObservedCon, iCompletionRock;

protected func Construction()
{
    iConstructionCon = GetCon();
    SetComponent(ROCK, 0);
    DoCon(1);
    return(1);
}

protected func Completion()
{
    iCompletion = 1;
    iCompletionRock = GetComponent(ROCK);
    return(1);
}

protected func Initialize()
{
    iInitialized = 1;
    return(1);
}

public func ConstructionCon()
{
    return(iConstructionCon);
}

public func Seed()
{
    var child = PlaceVegetation(TREE, -100, -100, 200, 200, 10);
    iObservedCon = child->ConstructionCon();
    return(child);
}

public func SeedFull()
{
    return(PlaceVegetation(TREE, -100, -100, 200, 200, 100000));
}
"#;
        let library = lc_resources::MaterialLibrary::parse(
            "[Material]\nName=Earth\nDensity=100\nSoil=1\n",
        )
        .expect("earth material parses");
        let mut engine = crate::Engine::with_seed(17);
        engine.configure_materials_from_library(&library);
        let earth = engine
            .materials()
            .id_of("Earth")
            .expect("earth material exists");
        let mut landscape = Landscape::flat_with_material(400, 160, Some(earth));
        landscape.set_world_height(300);
        engine.set_landscape(landscape);

        let mut tree = crate::Definition::from_script("TREE", "Tree", script)
            .expect("tree script compiles");
        tree.set_category(crate::CATEGORY_STATIC_BACK);
        tree.set_shape_rect(Some(DefinitionRect::new(-20, -28, 40, 56)));
        tree.set_placement(0);
        tree.set_growth(2);
        tree.set_stretch_growth(true);
        tree.set_components(vec![crate::DefinitionComponent {
            id: "ROCK".to_owned(),
            count: 100,
        }]);
        engine.register_definition(tree).expect("tree registers");
        let caller = engine
            .spawn_object(
                SpawnConfig::new("TREE")
                    .with_position(Vector2::new(200, 160))
                    .with_category(crate::CATEGORY_STATIC_BACK),
            )
            .expect("caller tree spawns");
        let caller_index = engine.find_object_index(caller).expect("caller exists");
        let value = engine
            .call_object_function(caller_index, "Seed", Vec::new())
            .expect("Seed runs");
        let child_id = object_id_from_value(&value).expect("Seed returns child");
        let child_index = engine.find_object_index(child_id).expect("child exists");
        let child = &engine.objects[child_index].state;

        assert_eq!(
            child.construction, 1_010,
            "the initial DoCon adds raw growth after Construction's change"
        );
        assert_eq!(
            child.local_vars.get("iConstructionCon"),
            Some(&Value::Int(0)),
            "Construction observes the pre-growth Con=0 state"
        );
        assert_eq!(child.local_vars.get("iCompletion"), Some(&Value::Nil));
        assert_eq!(child.local_vars.get("iInitialized"), Some(&Value::Nil));
        assert_eq!(child.components.get("ROCK"), Some(&1));
        let caller_index = engine.find_object_index(caller).expect("caller remains");
        assert_eq!(
            engine.objects[caller_index]
                .state
                .local_vars
                .get("iObservedCon"),
            Some(&Value::Int(0)),
            "the Construction write is visible before PlaceVegetation returns"
        );

        let value = engine
            .call_object_function(caller_index, "SeedFull", Vec::new())
            .expect("SeedFull runs");
        let full_child = object_id_from_value(&value).expect("SeedFull returns child");
        let full_index = engine
            .find_object_index(full_child)
            .expect("full child exists");
        let full = &engine.objects[full_index].state;
        assert_eq!(full.construction, FULL_CON);
        assert_eq!(
            full.local_vars.get("iConstructionCon"),
            Some(&Value::Int(0))
        );
        assert_eq!(full.local_vars.get("iCompletion"), Some(&Value::Int(1)));
        assert_eq!(
            full.local_vars.get("iCompletionRock"),
            Some(&Value::Int(100))
        );
        assert_eq!(full.local_vars.get("iInitialized"), Some(&Value::Int(1)));
        assert_eq!(full.components.get("ROCK"), Some(&100));
    }

    #[test]
    fn place_vegetation_finds_liquid_bottom_like_cpp() {
        // C4D_Place_Liquid takes one random point, tries FindSurfaceLiquid
        // then FindLiquid, settles via SemiAboveSolid, and creates three
        // pixels into the bottom (C4Game.cpp:3027-3039;
        // C4Landscape.cpp:1860-1915,1772-1796).
        let library = lc_resources::MaterialLibrary::parse(
            r#"
            [Material Rock]
            Name=Rock
            Density=100

            [Material Water]
            Name=Water
            Density=25
            "#,
        )
        .expect("materials parse");
        let materials = MaterialSet::from_resource_library(&library);
        let rock = materials.id_of("Rock").expect("rock exists");
        let water = materials.id_of("Water").expect("water exists");
        let mut landscape = Landscape::flat_with_material(100, 200, Some(rock));
        landscape.set_world_height(300);
        for x in 20..80 {
            for y in 100..200 {
                assert!(landscape.insert_liquid_at(x, y, Some(water)));
            }
        }
        let definitions = HashMap::from([(
            DefinitionId::from("PLNT"),
            DefinitionMetadata {
                shape: Some(DefinitionRect::new(-2, -3, 4, 6)),
                placement: 1,
                ..DefinitionMetadata::default()
            },
        )]);
        let world = HostWorldContext::with_landscape(
            Vec::<HostWorldObject>::new(),
            Some(landscape),
            definitions,
            Vec::new(),
            HashMap::new(),
            HashMap::new(),
            1,
            false,
        )
        .with_materials(Some(Rc::new(materials)));
        let mut expected_rng = LcgRng::new(23);
        assert_eq!(expected_rng.random(1), 0);
        assert_eq!(expected_rng.random(1), 0);
        let guard = enter_random_context(LcgRng::new(23));
        let (result, outcome) = with_effect_context(None, &[], world, 1, || {
            place_vegetation(&[
                Value::C4Id("PLNT".into()),
                Value::Int(50),
                Value::Int(120),
                Value::Int(1),
                Value::Int(1),
                Value::Int(500),
            ])
        });
        let rng_after = guard.finish();

        assert_eq!(rng_after, expected_rng, "the point costs exactly two draws");
        assert_eq!(
            result.expect("PlaceVegetation succeeds"),
            object_reference_value(ObjectId::new(1))
        );
        assert_eq!(outcome.spawns.len(), 1);
        assert_eq!(outcome.spawns[0].position, Vector2::new(49, 202));
        assert_eq!(outcome.spawns[0].construction, 500);
    }

    #[test]
    fn place_vegetation_default_growth_uses_cpp_random_gate() {
        // iGrowth<=0 first becomes FullCon; a definition with Growth then
        // has a 1-in-3 gate followed by Random(FullCon)+1
        // (C4Game.cpp:2988-2992), before the placement-point draws.
        let library = lc_resources::MaterialLibrary::parse(
            "[Material]\nName=Earth\nDensity=100\nSoil=1\n",
        )
        .expect("earth material parses");
        let materials = MaterialSet::from_resource_library(&library);
        let earth = materials.id_of("Earth").expect("earth exists");
        let mut landscape = Landscape::flat_with_material(400, 160, Some(earth));
        landscape.set_world_height(300);
        let definitions = HashMap::from([(
            DefinitionId::from("TREE"),
            DefinitionMetadata {
                shape: Some(DefinitionRect::new(-20, -28, 40, 56)),
                placement: 0,
                growth: 2,
                stretch_growth: true,
                ..DefinitionMetadata::default()
            },
        )]);
        let world = HostWorldContext::with_landscape(
            Vec::<HostWorldObject>::new(),
            Some(landscape),
            definitions,
            Vec::new(),
            HashMap::new(),
            HashMap::new(),
            1,
            false,
        )
        .with_materials(Some(Rc::new(materials)));
        let mut expected_rng = LcgRng::new(2);
        assert_eq!(expected_rng.random(3), 0);
        let expected_growth = expected_rng.random(FULL_CON) + 1;
        assert_eq!(expected_growth, 29_217);
        assert_eq!(expected_rng.random(1), 0);
        assert_eq!(expected_rng.random(1), 0);
        let guard = enter_random_context(LcgRng::new(2));
        let (result, outcome) = with_effect_context(None, &[], world, 1, || {
            place_vegetation(&[
                Value::C4Id("TREE".into()),
                Value::Int(200),
                Value::Int(50),
                Value::Int(1),
                Value::Int(1),
                Value::Int(0),
            ])
        });
        let rng_after = guard.finish();

        assert_eq!(rng_after, expected_rng);
        assert_eq!(
            result.expect("PlaceVegetation succeeds"),
            object_reference_value(ObjectId::new(1))
        );
        assert_eq!(outcome.spawns[0].construction, expected_growth);
    }

    #[test]
    fn create_contents_consumes_explicit_zero_container_before_count() {
        // Tutorial06 calls HUT3->CreateContents(METL, 0, 2) and WOOD with
        // count 4. The typed object slot converts integer zero to nullptr;
        // iCount remains the following argument (C4Script.cpp:1938-1951).
        // Object number 1 belongs to the active container; C++'s global
        // allocator therefore starts the first created content at 2.
        let (result, outcome) = with_object_host_context_with_world_and_next_id(
            HostWorldContext::default(),
            2,
            || {
            create_contents(&[
                Value::C4Id("WOOD".into()),
                Value::Int(0),
                Value::Int(4),
            ])
            },
        );

        assert_eq!(
            result.expect("CreateContents accepts the null object slot"),
            object_reference_value(ObjectId::new(5))
        );
        assert_eq!(outcome.spawns.len(), 4);
        assert!(outcome.spawns.iter().all(|spawn| {
            spawn.definition_id == "WOOD" && spawn.container == Some(ObjectId::new(1))
        }));
    }

    #[test]
    fn create_construction_counts_tutorial06_cave_pixels_not_roof_surface() {
        // Tutorial06 is TopOpen=0: the valid ELEV site at (332,148) has a
        // solid cave roof above it and floor support below it. C++ counts
        // the actual pixels in the construction rectangle and its five-row
        // support strip (C4Landscape.cpp:1090-1098,2125-2158); it does not
        // treat the first solid surface in each column as solid forever.
        const WIDTH: u32 = 64;
        const HEIGHT: u32 = 200;
        let mut pixels = vec![0; WIDTH as usize * HEIGHT as usize];
        for y in 0..25 {
            pixels[y * WIDTH as usize..(y + 1) * WIDTH as usize].fill(1);
        }
        for y in 150..HEIGHT as usize {
            pixels[y * WIDTH as usize..(y + 1) * WIDTH as usize].fill(1);
        }
        let mut densities = vec![0; 2];
        densities[1] = 100;
        let mut landscape = Landscape::new(WIDTH, vec![0; WIDTH as usize])
            .expect("Tutorial06 cave fixture builds");
        landscape.set_world_height(HEIGHT as i32);
        landscape.set_pixel_grid(crate::landscape::PixelGrid::new(
            WIDTH,
            HEIGHT,
            pixels,
            densities,
            vec![None; 2],
            vec![None; 2],
        ));
        landscape.refresh_all_raster_columns();
        assert_eq!(landscape.surface_height(32), Some(0), "the roof is first");

        let definitions = HashMap::from([(
            DefinitionId::from("ELEV"),
            DefinitionMetadata {
                category: crate::CATEGORY_STRUCTURE,
                constructable: true,
                shape: Some(DefinitionRect::new(-14, -28, 28, 56)),
                ..DefinitionMetadata::default()
            },
        )]);
        let world = HostWorldContext::with_landscape(
            Vec::new(),
            Some(landscape),
            definitions,
            Vec::new(),
            HashMap::new(),
            HashMap::new(),
            1,
            false,
        );
        let args = [
            Value::C4Id("ELEV".into()),
            Value::Int(32),
            Value::Int(148),
            Value::Int(1),
            Value::Int(1),
            Value::Bool(true),
            Value::Bool(true),
        ];

        let (result, outcome) =
            with_effect_context(None, &[], world, 1, || create_construction(&args));

        assert_eq!(
            result.expect("CreateConstruction checks the cave site"),
            object_reference_value(ObjectId::new(1))
        );
        assert_eq!(outcome.spawns.len(), 1);
        assert!(matches!(
            outcome.landscape.as_slice(),
            [LandscapeOperation::PrepareConstructionTerrain {
                center_x: 32,
                bottom_y: 148,
                width: 28,
                height: 56,
                basement: 0,
            }]
        ));
    }

